// V1.27.158 — ChatGPT/ProseMirror can render the same multiline draft with
// different block-newline spacing (for example one input newline becomes two
// innerText newlines). UI verification must compare semantic text, not raw DOM
// whitespace, while still requiring every non-whitespace character in order.
function normalizeChatgptUiComparable(value = '') {
  return normalizeChatgptText(value).replace(/\s+/g, ' ').trim();
}
function chatgptUiTextEquivalent(a = '', b = '') {
  const aa = normalizeChatgptUiComparable(a);
  const bb = normalizeChatgptUiComparable(b);
  return !!aa && !!bb && aa === bb;
}
function chatgptUiTextStartsWith(full = '', partial = '') {
  const ff = normalizeChatgptUiComparable(full);
  const pp = normalizeChatgptUiComparable(partial);
  return !!ff && !!pp && ff.startsWith(pp);
}
function chatgptUiComparableFingerprint(value = '') {
  return chatgptPromptFingerprint(normalizeChatgptUiComparable(value));
}
