// V1.15.27: keep BOTH application data and Chromium session data on stable,
// version-independent paths. Electron stores cookies/localStorage/IndexedDB under
// sessionData; fixing only userData can still make LINE look like a new browser.
// This must run before app.ready and before any Session is created.
const YOKO_BOOT_PATHS = (() => {
  try {
    const appData = app.getPath('appData');
    const originalUserData = app.getPath('userData');
    const originalSessionData = app.getPath('sessionData');
    const stableUserData = path.join(appData, 'Yoko SCRM');
    const stableSessionData = path.join(stableUserData, 'Chromium');

    fs.mkdirSync(stableUserData, { recursive: true });
    fs.mkdirSync(stableSessionData, { recursive: true });

    const legacyCandidates = [
      originalUserData,
      path.join(appData, 'yoko-scrm')
    ].filter((value, index, list) => value && list.indexOf(value) === index);

    const hasYokoState = dir => {
      try {
        return fs.existsSync(path.join(dir, 'config.json')) ||
          fs.existsSync(path.join(dir, 'Partitions')) ||
          fs.existsSync(path.join(dir, 'secure-store'));
      } catch { return false; }
    };

    if (!hasYokoState(stableUserData)) {
      const legacy = legacyCandidates.find(dir =>
        path.resolve(dir) !== path.resolve(stableUserData) && hasYokoState(dir)
      );
      if (legacy) {
        for (const name of [
          'config.json', 'config.json.bak', 'Partitions', 'secure-store',
          'aggregate-cache.json', 'aggregate-cache.json.bak',
          'aggregate-customer-avatar-cache.json', 'aggregate-customer-avatars',
          'avatar-cache', 'translation-cache.json', 'restored-line-drafts.json'
        ]) {
          const src = path.join(legacy, name);
          const dst = path.join(stableUserData, name);
          try {
            if (!fs.existsSync(src) || fs.existsSync(dst)) continue;
            fs.cpSync(src, dst, { recursive: true, force: false, errorOnExist: false });
          } catch {}
        }
      }
    }

    app.setPath('userData', stableUserData);
    app.setPath('sessionData', stableSessionData);
    return { appData, originalUserData, originalSessionData, stableUserData, stableSessionData };
  } catch (error) {
    console.debug('[Yoko stable data bootstrap skipped]', error?.message || error);
    return null;
  }
})();

