// V1.24.5 — conversion diagnostics trace core.
// This ring buffer records only conversion-routing metadata and short snippets
// around explicit LINE conversion evidence. It intentionally does not record
// ordinary chat history, credentials, proxy passwords or API keys.
const conversionDiagnosticTrace = [];
const conversionDiagnosticLast = new Map();
function conversionDiagClean(value, limit = 240) {
  return String(value == null ? '' : value).replace(/\u0000/g, '').replace(/\s+/g, ' ').trim().slice(0, limit);
}
function conversionDiagSafe(value, depth = 0) {
  if (depth > 4) return '[depth-limit]';
  if (value == null || typeof value === 'boolean' || typeof value === 'number') return value;
  if (typeof value === 'string') return conversionDiagClean(value, 500);
  if (Array.isArray(value)) return value.slice(0, 24).map(v => conversionDiagSafe(v, depth + 1));
  if (typeof value === 'object') {
    const out = {};
    for (const [key, raw] of Object.entries(value).slice(0, 40)) {
      if (/password|secret|token|api.?key|proxy.?pass|cookie|authorization/i.test(key)) { out[key] = '[redacted]'; continue; }
      out[key] = conversionDiagSafe(raw, depth + 1);
    }
    return out;
  }
  return conversionDiagClean(value, 240);
}
function traceConversion(event, data = {}, { dedupeMs = 1200 } = {}) {
  try {
    const safe = conversionDiagSafe(data);
    const sig = `${event}|${JSON.stringify(safe)}`;
    const now = Date.now();
    const last = conversionDiagnosticLast.get(sig) || 0;
    if (dedupeMs > 0 && now - last < dedupeMs) return;
    conversionDiagnosticLast.set(sig, now);
    conversionDiagnosticTrace.push({ at:new Date(now).toISOString(), event:String(event || 'event'), data:safe });
    if (conversionDiagnosticTrace.length > 500) conversionDiagnosticTrace.splice(0, conversionDiagnosticTrace.length - 500);
    if (conversionDiagnosticLast.size > 1000) {
      for (const [key, at] of conversionDiagnosticLast) if (now - at > 120000) conversionDiagnosticLast.delete(key);
    }
  } catch {}
}
function conversionDiagnosticSnapshot(limit = 160) {
  return conversionDiagnosticTrace.slice(-Math.max(1, Math.min(500, Number(limit) || 160)));
}
function conversionDiagnosticContact(contact = {}) {
  return {
    stage:conversionDiagClean(contact?.stage, 60),
    lineProgress:conversionDiagClean(contact?.lineProgress, 60),
    lineIntent:conversionDiagClean(contact?.lineIntent, 60),
    lineIntentScore:Number(contact?.lineIntentScore || 0) || 0,
    tags:conversionDiagClean(contact?.tags, 220),
    serviceStatus:conversionDiagClean(contact?.serviceStatus, 60),
    targetLineAccountId:conversionDiagClean(contact?.targetLineAccountId, 100),
    updatedAt:conversionDiagClean(contact?.updatedAt, 80)
  };
}
