function ensureNativeApiRealtimeStream({restart=false}={}){
  if(!nativeApiInboxEnabled()){stopNativeApiRealtimeStream();return false;}
  const settings=teamSyncSettings();
  const base=String(settings.cloudflarePublicUrl||settings.serverUrl||'').trim().replace(/\/+$/,'');
  const sessionToken=String(settings.sessionToken||settings.officialApiSessionToken||'').trim();
  const teamId=String(settings.teamId||'').trim(),apiKey=String(settings.apiKey||'').trim();
  if(!base||(!sessionToken&&(!teamId||!apiKey))){stopNativeApiRealtimeStream();return false;}
  const authSignature=sessionToken?`bearer:${crypto.createHash('sha256').update(sessionToken).digest('hex').slice(0,12)}`:`team:${teamId}|${crypto.createHash('sha256').update(apiKey).digest('hex').slice(0,12)}`;
  const signature=`${base}|${authSignature}`;
  if(!restart&&nativeApiRealtimeClient&&nativeApiRealtimeSignature===signature)return true;
  stopNativeApiRealtimeStream();nativeApiRealtimeSignature=signature;
  try{
    nativeApiRealtimeClient=createNativeApiDbDeltaClient(settings,{
      onEvent:event=>{
        nativeApiRealtimeState.state='connected';nativeApiRealtimeState.events+=1;nativeApiRealtimeState.lastEventAt=Date.now();nativeApiRealtimeState.lastError='';
        try{sendUI('team-sync-updated',{__nativeApiRealtime:{...event,receivedByDesktopAt:Date.now(),stream:'v127227-sqlite-delta'}});}catch{}
      },
      onStatus:status=>{
        const state=String(status?.state||'');if(state)nativeApiRealtimeState.state=state;
        if(state==='connected'){
          if(!nativeApiRealtimeState.connectedAt)nativeApiRealtimeState.connectedAt=Date.now();
          nativeApiRealtimeState.lastPollAt=Date.now();
          nativeApiRealtimeState.lastError='';
          nativeApiRealtimeState.recoveryWatchdog=status?.payload?.recoveryWatchdog||nativeApiRealtimeState.recoveryWatchdog;
        }
        if(state==='reconnecting')nativeApiRealtimeState.reconnects=Number(status?.reconnects||nativeApiRealtimeState.reconnects||0);
        if(state==='error')nativeApiRealtimeState.lastError=String(status?.error||status?.statusCode||'realtime-error').slice(0,300);
      }
    });
    nativeApiRealtimeState.state='connecting';return true;
  }catch(error){nativeApiRealtimeState.state='error';nativeApiRealtimeState.lastError=String(error?.message||error).slice(0,300);nativeApiRealtimeClient=null;return false;}
}
