// diagnostics/UI. It never contains chat text or credentials.
const lineOperationalState = new Map(); // accountId -> { status, lastLoadedAt, lastErrorAt, lastError, unresponsiveAt }

function updateLineOperationalState(accountId, patch = {}) {
  accountId = String(accountId || '').trim();
  if (!accountId) return {};
  const previous = lineOperationalState.get(accountId) || {};
  const next = { ...previous, ...patch, updatedAt: Date.now() };
  lineOperationalState.set(accountId, next);
  return next;
}

