// V1.10.14 full-offline local AI support. A full-offline build can include
// both the Ollama Windows runtime and the qwen3:4b model. On first use the
// bundled model is hard-linked (or copied when hard-linking is unavailable)
// into the current user's standard Ollama model store, then a bundled Ollama
// server is started automatically if no system Ollama server is already up.
let bundledOllamaProcess = null;
let bundledOllamaStartPromise = null;
let bundledQwen4bProvisioned = false;
let ollamaManagerTask = null;
let systemOllamaProcess = null;

function localOllamaModelStore() {
  const custom = String(process.env.OLLAMA_MODELS || '').trim();
  if (custom) return path.resolve(custom);
  return path.join(process.env.USERPROFILE || app.getPath('home'), '.ollama', 'models');
}

function bundledOllamaRuntimeRoot() {
  return app.isPackaged
    ? path.join(process.resourcesPath, 'ollama-runtime')
    : path.join(app.getAppPath(), 'vendor', 'ollama-runtime');
}

function bundledOllamaExePath() {
  const root = bundledOllamaRuntimeRoot();
  const candidates = [
    path.join(root, 'ollama.exe'),
    path.join(root, 'bin', 'ollama.exe')
  ];
  return candidates.find(candidate => fs.existsSync(candidate)) || '';
}

function bundledOllamaModelsRoot() {
  return app.isPackaged
    ? path.join(process.resourcesPath, 'ollama-models')
    : path.join(app.getAppPath(), 'vendor', 'ollama-models');
}

function bundledQwen4bManifestPath(root = bundledOllamaModelsRoot()) {
  return path.join(root, 'manifests', 'registry.ollama.ai', 'library', 'qwen3', '4b');
}

function bundledLocalAiAvailable() {
  return !!bundledOllamaExePath() && fs.existsSync(bundledQwen4bManifestPath());
}

function sameFileSize(a, b) {
  try {
    return fs.statSync(a).size === fs.statSync(b).size;
  } catch {
    return false;
  }
}

function linkOrCopyBundledFile(source, target) {
  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (fs.existsSync(target) && sameFileSize(source, target)) return;
  try { fs.rmSync(target, { force: true }); } catch {}

  // Most installations and user profiles are on the same NTFS volume. A hard
  // link makes first-run provisioning almost instant and avoids another ~2.5GB
  // copy. If the app is installed on another drive, fall back to a normal copy.
  try {
    fs.linkSync(source, target);
  } catch {
    fs.copyFileSync(source, target);
  }
}

function provisionBundledQwen4b() {
  if (bundledQwen4bProvisioned) return true;
  const sourceRoot = bundledOllamaModelsRoot();
  const sourceManifest = bundledQwen4bManifestPath(sourceRoot);
  if (!fs.existsSync(sourceManifest)) return false;

  const targetRoot = localOllamaModelStore();
  const copyTree = current => {
    const rel = path.relative(sourceRoot, current);
    const target = path.join(targetRoot, rel);
    const stat = fs.statSync(current);
    if (stat.isDirectory()) {
      fs.mkdirSync(target, { recursive: true });
      for (const entry of fs.readdirSync(current)) copyTree(path.join(current, entry));
    } else if (stat.isFile()) {
      linkOrCopyBundledFile(current, target);
    }
  };

  copyTree(sourceRoot);
  bundledQwen4bProvisioned = true;
  return true;
}

function isDefaultLocalOllamaUrl(baseUrl) {
  try {
    const u = new URL(normalizeOllamaBaseUrl(baseUrl));
    return ['127.0.0.1', 'localhost', '::1'].includes(u.hostname) && Number(u.port || 80) === 11434;
  } catch {
    return false;
  }
}

async function probeOllama(baseUrl) {
  try {
    await requestJson(`${normalizeOllamaBaseUrl(baseUrl)}/api/tags`, { method: 'GET', timeout: 1800 });
    return true;
  } catch {
    return false;
  }
}

async function waitForOllama(baseUrl, timeoutMs = 30000) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (await probeOllama(baseUrl)) return true;
    await new Promise(resolve => setTimeout(resolve, 500));
  }
  return false;
}

async function ensureBundledOllamaReady(settings = {}) {
  const baseUrl = normalizeOllamaBaseUrl(settings?.ollamaUrl || OLLAMA_DEFAULT_URL);
  if (!isDefaultLocalOllamaUrl(baseUrl)) return false;

  // Install the embedded model into the standard Ollama store first. This also
  // makes it visible to a system-installed Ollama that may already be running.
  try { provisionBundledQwen4b(); } catch (error) {
    console.debug('[Yoko bundled qwen4b provision skipped]', error?.message || error);
  }

  if (await probeOllama(baseUrl)) return true;
  if (!bundledLocalAiAvailable()) return false;
  if (bundledOllamaStartPromise) return bundledOllamaStartPromise;

  bundledOllamaStartPromise = (async () => {
    const exe = bundledOllamaExePath();
    const modelStore = localOllamaModelStore();
    fs.mkdirSync(modelStore, { recursive: true });

    try {
      bundledOllamaProcess = spawn(exe, ['serve'], {
        cwd: bundledOllamaRuntimeRoot(),
        windowsHide: true,
        stdio: 'ignore',
        env: {
          ...process.env,
          OLLAMA_HOST: '127.0.0.1:11434',
          OLLAMA_MODELS: modelStore
        }
      });
      bundledOllamaProcess.on('error', error => {
        console.debug('[Yoko bundled Ollama start error]', error?.message || error);
      });
      bundledOllamaProcess.on('exit', () => {
        bundledOllamaProcess = null;
      });
      const ready = await waitForOllama(baseUrl, 30000);
      if (!ready) throw new Error('内置 Ollama 启动超时。');
      return true;
    } finally {
      bundledOllamaStartPromise = null;
    }
  })();

  return bundledOllamaStartPromise;
}

function stopBundledOllama() {
  const child = bundledOllamaProcess;
  bundledOllamaProcess = null;
  if (!child || child.killed) return;
  try {
    if (process.platform === 'win32' && child.pid) {
      spawn('taskkill.exe', ['/pid', String(child.pid), '/t', '/f'], {
        windowsHide: true,
        stdio: 'ignore'
      });
    } else {
      child.kill('SIGTERM');
    }
  } catch {}
}

// V1.23.19: in-app Ollama/Qwen manager. The normal Yoko installer stays
// lightweight; Ollama and model weights are downloaded only when the operator
// explicitly asks for them from Translation Settings.
function findExecutableOnPath(fileName) {
  try {
    const pathValue = String(process.env.PATH || '');
    for (const folder of pathValue.split(path.delimiter).filter(Boolean)) {
      const candidate = path.join(folder.replace(/^"|"$/g, ''), fileName);
      if (fs.existsSync(candidate)) return candidate;
    }
  } catch {}
  return '';
}

function systemOllamaExePath() {
  const candidates = [
    process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, 'Programs', 'Ollama', 'ollama.exe') : '',
    process.env.ProgramFiles ? path.join(process.env.ProgramFiles, 'Ollama', 'ollama.exe') : '',
    findExecutableOnPath('ollama.exe')
  ].filter(Boolean);
  return candidates.find(candidate => fs.existsSync(candidate)) || '';
}


let ollamaLatestVersionCache = { at: 0, version: '', error: '' };

function normalizeVersionNumber(value = '') {
  const match = String(value || '').match(/(?:^|[^0-9])(\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?)/);
  return match ? match[1] : '';
}

function compareVersionNumbers(a = '', b = '') {
  const parse = value => String(value || '').replace(/^v/i, '').split(/[.+-]/).slice(0, 3).map(part => Number.parseInt(part, 10) || 0);
  const av = parse(a), bv = parse(b);
  for (let i = 0; i < 3; i++) {
    if ((av[i] || 0) > (bv[i] || 0)) return 1;
    if ((av[i] || 0) < (bv[i] || 0)) return -1;
  }
  return 0;
}

function captureProcessOutput(command, args = [], { timeoutMs = 12000 } = {}) {
  return new Promise((resolve, reject) => {
    let child;
    try { child = spawn(command, args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] }); }
    catch (error) { reject(error); return; }
    let stdout = '', stderr = '';
    child.stdout?.on('data', chunk => { stdout = (stdout + String(chunk || '')).slice(-12000); });
    child.stderr?.on('data', chunk => { stderr = (stderr + String(chunk || '')).slice(-12000); });
    const timer = setTimeout(() => {
      try { child.kill(); } catch {}
      reject(new Error('版本检测超时'));
    }, timeoutMs);
    child.once('error', error => { clearTimeout(timer); reject(error); });
    child.once('exit', code => {
      clearTimeout(timer);
      if (Number(code) === 0) resolve(`${stdout}\n${stderr}`.trim());
      else reject(new Error((stderr || stdout || `命令退出代码 ${code}`).trim()));
    });
  });
}

async function getInstalledOllamaVersion({ serverOnline = false, exe = '' } = {}) {
  if (exe) {
    try {
      const output = await captureProcessOutput(exe, ['--version'], { timeoutMs: 10000 });
      const parsed = normalizeVersionNumber(output);
      if (parsed) return parsed;
    } catch {}
  }
  if (serverOnline) {
    try {
      const data = await requestJson(`${OLLAMA_DEFAULT_URL}/api/version`, { method: 'GET', timeout: 6000 });
      const parsed = normalizeVersionNumber(data?.version || '');
      if (parsed) return parsed;
    } catch {}
  }
  return '';
}

async function getLatestOllamaVersion({ force = false } = {}) {
  const now = Date.now();
  if (!force && now - ollamaLatestVersionCache.at < 30 * 60 * 1000) return { ...ollamaLatestVersionCache };
  try {
    const data = await requestJson(OLLAMA_LATEST_RELEASE_API, {
      method: 'GET', timeout: 7000,
      headers: {
        'user-agent': `YokoSCRM/${APP_VERSION}`,
        'accept': 'application/vnd.github+json'
      }
    });
    const version = normalizeVersionNumber(data?.tag_name || data?.name || '');
    if (!version) throw new Error('无法识别 Ollama 最新版本号');
    ollamaLatestVersionCache = { at: now, version, error: '' };
  } catch (error) {
    ollamaLatestVersionCache = { at: now, version: '', error: String(error?.message || error) };
  }
  return { ...ollamaLatestVersionCache };
}

function sendOllamaManagerProgress(payload = {}) {
  try {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('ollama-manager-progress', {
        phase: String(payload.phase || ''),
        status: String(payload.status || ''),
        model: String(payload.model || ''),
        percent: Number.isFinite(Number(payload.percent)) ? Math.max(0, Math.min(100, Number(payload.percent))) : 0,
        completed: Number(payload.completed || 0),
        total: Number(payload.total || 0),
        detail: String(payload.detail || ''),
        indeterminate: payload.indeterminate === true
      });
    }
  } catch {}
}

function runHiddenProcess(command, args = [], { timeoutMs = 15 * 60 * 1000, onOutput = null } = {}) {
  return new Promise((resolve, reject) => {
    let child;
    try {
      child = spawn(command, args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    } catch (error) {
      reject(error);
      return;
    }
    let stderr = '';
    const consume = chunk => {
      const text = String(chunk || '').trim();
      if (text && typeof onOutput === 'function') onOutput(text);
    };
    child.stdout?.on('data', consume);
    child.stderr?.on('data', chunk => {
      const text = String(chunk || '');
      stderr = (stderr + text).slice(-5000);
      consume(text);
    });
    const timer = setTimeout(() => {
      try { child.kill(); } catch {}
      reject(new Error('安装过程超时。请检查网络后重试。'));
    }, timeoutMs);
    child.once('error', error => {
      clearTimeout(timer);
      reject(error);
    });
    child.once('exit', code => {
      clearTimeout(timer);
      if (Number(code) === 0) resolve(true);
      else reject(new Error(`Ollama 安装程序退出，代码 ${code}${stderr ? `：${stderr.trim().slice(-800)}` : ''}`));
    });
  });
}

async function installOfficialOllamaRuntime({ forceUpdate = false } = {}) {
  if (process.platform !== 'win32') throw new Error('Yoko 的一键 Ollama 环境安装目前仅支持 Windows。');
  const onlineBefore = await probeOllama(OLLAMA_DEFAULT_URL);
  if (onlineBefore && !forceUpdate) return true;
  const existingExe = systemOllamaExePath();
  if (existingExe && !forceUpdate) {
    sendOllamaManagerProgress({ phase: 'runtime', status: '正在启动已安装的 Ollama…', percent: 82 });
    const ready = await startSystemOllamaServer(existingExe);
    if (!ready) throw new Error('已检测到 Ollama，但本地服务启动失败。');
    return true;
  }

  sendOllamaManagerProgress({
    phase: 'runtime',
    status: forceUpdate ? '正在准备更新官方 Ollama 环境…' : '正在准备安装官方 Ollama 环境…',
    percent: 8,
    detail: forceUpdate ? '已确认存在可更新版本，正在启动官方更新流程。' : '正在启动官方安装流程。',
    indeterminate: true
  });
  const psCommand = `& { $ErrorActionPreference='Stop'; $ProgressPreference='SilentlyContinue'; irm '${OLLAMA_OFFICIAL_INSTALL_SCRIPT}' | iex }`;
  await runHiddenProcess('powershell.exe', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', psCommand], {
    timeoutMs: 20 * 60 * 1000,
    onOutput: text => {
      const compact = String(text || '').replace(/\s+/g, ' ').trim();
      if (!compact) return;
      const lower = compact.toLowerCase();
      const percent = lower.includes('install') ? 68 : lower.includes('download') ? 36 : 18;
      sendOllamaManagerProgress({ phase: 'runtime', status: forceUpdate ? '正在更新 Ollama 环境…' : '正在安装 Ollama 环境…', percent, detail: compact.slice(-220), indeterminate: true });
    }
  });

  sendOllamaManagerProgress({ phase: 'runtime', status: forceUpdate ? 'Ollama 更新完成，正在确认环境…' : 'Ollama 已安装，正在启动本地服务…', percent: 88, indeterminate: true });
  const started = Date.now();
  let exe = '';
  while (Date.now() - started < 45000) {
    exe = systemOllamaExePath();
    if (exe) break;
    await new Promise(resolve => setTimeout(resolve, 700));
  }
  if (!exe) throw new Error('Ollama 安装完成，但没有找到 ollama.exe。请重新打开 Yoko 后再试。');
  const ready = await startSystemOllamaServer(exe);
  if (!ready) throw new Error('Ollama 已安装，但本地服务没有在规定时间内启动。');
  sendOllamaManagerProgress({ phase: 'runtime', status: 'Ollama 环境已就绪', percent: 100 });
  return true;
}

async function startSystemOllamaServer(exe = systemOllamaExePath()) {
  if (await probeOllama(OLLAMA_DEFAULT_URL)) return true;
  if (!exe) return false;
  if (!systemOllamaProcess || systemOllamaProcess.killed) {
    try {
      systemOllamaProcess = spawn(exe, ['serve'], {
        windowsHide: true,
        stdio: 'ignore',
        env: { ...process.env, OLLAMA_HOST: '127.0.0.1:11434' }
      });
      systemOllamaProcess.on('error', error => console.debug('[Yoko system Ollama start error]', error?.message || error));
      systemOllamaProcess.on('exit', () => { systemOllamaProcess = null; });
    } catch (error) {
      console.debug('[Yoko system Ollama spawn skipped]', error?.message || error);
    }
  }
  return waitForOllama(OLLAMA_DEFAULT_URL, 45000);
}

async function ensureLocalOllamaServerForManager({ installIfMissing = false } = {}) {
  if (await probeOllama(OLLAMA_DEFAULT_URL)) return true;
  try {
    if (await ensureBundledOllamaReady({ ollamaUrl: OLLAMA_DEFAULT_URL, ollamaModel: 'qwen3:4b' })) return true;
  } catch {}
  const exe = systemOllamaExePath();
  if (exe && await startSystemOllamaServer(exe)) return true;
  if (installIfMissing) return installOfficialOllamaRuntime({ forceUpdate: false });
  return false;
}

async function localOllamaTagList() {
  if (!await probeOllama(OLLAMA_DEFAULT_URL)) return [];
  try {
    const data = await requestJson(`${OLLAMA_DEFAULT_URL}/api/tags`, { method: 'GET', timeout: 6000 });
    return Array.isArray(data?.models)
      ? data.models.map(item => String(item?.name || item?.model || '').trim()).filter(Boolean)
      : [];
  } catch {
    return [];
  }
}

function modelNameInstalled(installed, model) {
  const wanted = String(model || '').trim().toLowerCase();
  if (!wanted) return false;
  return installed.some(name => {
    const normalized = String(name || '').trim().toLowerCase();
    return normalized === wanted || normalized === `${wanted}:latest` || `${normalized}:latest` === wanted;
  });
}


function normalizeOllamaModelMode(value = '') {
  const normalized = String(value || '').trim();
  if (normalized === 'fixed') return 'fixed';
  // V1.23.22 migrates the old accuracy-first automatic mode to the balanced
  // router. Fixed mode remains fully manual.
  return 'auto_balanced';
}

let ollamaAutoInstalledCache = { at: 0, baseUrl: '', models: [] };
let ollamaLastRouteDecision = null;

async function cachedOllamaInstalledModels(settings = {}, { force = false } = {}) {
  const baseUrl = normalizeOllamaBaseUrl(settings?.ollamaUrl || OLLAMA_DEFAULT_URL);
  const now = Date.now();
  if (!force && ollamaAutoInstalledCache.baseUrl === baseUrl && now - ollamaAutoInstalledCache.at < 20000) {
    return [...ollamaAutoInstalledCache.models];
  }
  await ensureBundledOllamaReady(settings).catch(() => false);
  const data = await requestJson(`${baseUrl}/api/tags`, { method: 'GET', timeout: 6000 });
  const models = Array.isArray(data?.models)
    ? data.models.map(item => String(item?.name || item?.model || '').trim()).filter(Boolean)
    : [];
  ollamaAutoInstalledCache = { at: now, baseUrl, models };
  return [...models];
}

function ollamaDifficultySignals(text = '', source = 'auto', target = 'zh', context = []) {
  const raw = String(text || '').trim();
  const length = [...raw].length;
  const recent = sanitizeAiContext(context, 4);
  let score = 0;
  const reasons = [];
  const add = (points, reason) => { score += points; if (reason && !reasons.includes(reason)) reasons.push(reason); };

  const stripped = raw.replace(/[\s。！？!?、,.，…~〜～❤️❤😊☺️🙂😄😂🤣🥰😍✨🌸👍🙏]+/g, '');
  const veryTrivial = length <= 14 && /^(?:はい|うん|ううん|そう|そうです|そうだね|そうですね|了解|わかった|ありがとう|ありがとうございます|おはよう|こんにちは|こんばんは|おやすみ|お疲れ様|おつかれさま|いいね|大丈夫|頑張って|はいそうです|嗯|好的|是的|不是|谢谢|早上好|晚安|你好|没问题|好呀|可以|OK|ok)$/i.test(stripped);
  if (veryTrivial) return { score: 0, level: 'trivial', reasons: ['极短且语义明确'], contextMessages: 0, targetRank: 1 };

  if (length > 20) add(5, '句子较长');
  if (length > 48) add(7, '多信息句');
  if (length > 100) add(10, '长句');
  if (length > 220) add(12, '长段落');
  if (length > 520) add(12, '超长内容');

  const clauseCount = (raw.match(/[、,，;；:：。！？!?]|けど|けれど|が、|ので|から|のに|なら|たら|ても|一方|しかし|でも|だから/g) || []).length;
  if (clauseCount >= 3) add(7, '多从句');
  if (clauseCount >= 6) add(8, '复杂句式');

  const hasContextAmbiguity = /(?:これ|それ|あれ|そう|そんな|こんな|その人|あの人|彼|彼女|例の|さっき|前に|それで|だから|という|っていう|わけ|こと|ところ|まま|みたい|らしい|っぽい|かな|かも|んです|んだけど|なんて|せっかく|やっぱり|別に|どうせ|一応|むしろ)/.test(raw);
  if (hasContextAmbiguity) add(10, '存在上下文指代或省略');
  if (/(?:ない|ません|じゃない|ではない|なくて|なかった|わけでは|とは限ら|必ずしも|むしろ|逆に|にもかかわらず|のに)/.test(raw)) add(5, '否定或转折语义');
  if (/(?:気持ち|嬉し|寂し|悲し|不安|心配|好き|嫌い|大切|信頼|付き合|恋愛|結婚|離婚|会いたい|寂しい|幸せ|残念|申し訳|遠慮|気まず|微妙)/.test(raw)) add(6, '情绪与关系语气');
  const hasProfessionalTerms = /(?:投資|金融|経済|経営|会社|契約|保険|税金|法律|医療|不動産|資産|為替|暗号|ビットコイン|株|金利|利益|損失|製造|農業|会計|顧客|取引|市場|責任|条件|技術|システム|AI|API)/i.test(raw);
  if (hasProfessionalTerms) add(9, '专业或商务词汇');
  if (/\([^)]{8,}\)|（[^）]{8,}）|「[^」]{8,}」|『[^』]{8,}』|“[^”]{8,}”/.test(raw)) add(4, '引用或补充说明');
  if (/(?:[A-Za-z]{3,}.*[ぁ-んァ-ヶ一-龯]|[ぁ-んァ-ヶ一-龯].*[A-Za-z]{3,})/.test(raw)) add(4, '混合语言');
  if (recent.length >= 2 && hasContextAmbiguity) add(6, '需要结合最近上下文');
  if (recent.length >= 3 && /(?:これ|それ|そう|彼|彼女|前|さっき|だから|でも|けど|んです)/.test(raw)) add(5, '强上下文依赖');

  // Balanced routing: 1.7B handles short/simple chat, 4B is the normal quality
  // tier, 8B is reserved for genuinely complex content. 14B is not selected by
  // difficulty alone because its cold-load/inference cost can make chat feel stuck.
  let targetRank = 1;
  let level = 'simple';
  if (score >= 5 || length > 26) { targetRank = 2; level = 'normal'; }
  if (score >= 32 || length > 180 || (hasProfessionalTerms && length > 60)) { targetRank = 3; level = 'complex'; }
  if (score >= 72 && length > 320) { targetRank = 4; level = 'very_complex'; }

  const contextMessages = targetRank >= 4 ? Math.min(4, recent.length)
    : targetRank >= 3 ? Math.min(3, recent.length)
      : targetRank >= 2 && hasContextAmbiguity ? Math.min(2, recent.length)
        : 0;
  return { score, level, reasons: reasons.slice(0, 5), contextMessages, targetRank };
}

const ollamaModelPerformance = new Map();
let ollamaRecentModel = { model: '', at: 0 };

function ollamaModelRank(model = '') {
  return Math.max(0, OLLAMA_MODEL_CATALOG.findIndex(item => item.id === String(model || '').trim()));
}

function ollamaDefaultLatencyMs(rank = 0) {
  return [2500, 3500, 6500, 13000, 24000][Math.max(0, Math.min(4, Number(rank) || 0))];
}

function ollamaModelEstimatedLatencyMs(model = '') {
  const rank = ollamaModelRank(model);
  const perf = ollamaModelPerformance.get(String(model || '').trim());
  return perf?.emaMs > 0 ? perf.emaMs : ollamaDefaultLatencyMs(rank);
}

function recordOllamaModelPerformance(model = '', elapsedMs = 0, ok = true) {
  const id = String(model || '').trim();
  if (!id) return;
  const elapsed = Math.max(1, Number(elapsedMs) || 1);
  const previous = ollamaModelPerformance.get(id) || { emaMs: 0, samples: 0, failures: 0, lastSuccessAt: 0 };
  const emaMs = previous.emaMs > 0 ? Math.round(previous.emaMs * 0.72 + elapsed * 0.28) : elapsed;
  const next = {
    emaMs,
    samples: previous.samples + 1,
    failures: ok ? Math.max(0, previous.failures - 1) : previous.failures + 1,
    lastSuccessAt: ok ? Date.now() : previous.lastSuccessAt
  };
  ollamaModelPerformance.set(id, next);
  if (ok) ollamaRecentModel = { model: id, at: Date.now() };
}

function ollamaModelRecentlyWarm(model = '', now = Date.now()) {
  const id = String(model || '').trim();
  if (!id) return false;
  if (ollamaRecentModel.model === id && now - ollamaRecentModel.at < 8 * 60 * 1000) return true;
  const perf = ollamaModelPerformance.get(id);
  return !!perf?.lastSuccessAt && now - perf.lastSuccessAt < 8 * 60 * 1000;
}

function selectBalancedInstalledModel(installed = [], signals = {}) {
  const available = OLLAMA_MODEL_CATALOG
    .map((item, rank) => ({ ...item, rank }))
    .filter(item => modelNameInstalled(installed, item.id));
  if (!available.length) return null;

  let requested = Math.max(1, Math.min(4, Number(signals?.targetRank) || 1));
  const now = Date.now();

  // Automatic 14B is allowed only when it has already proven reasonably fast on
  // this computer and is still warm. Otherwise cap automatic work at 8B.
  if (requested >= 4) {
    const fourteen = available.find(item => item.rank === 4);
    const fourteenFast = fourteen && ollamaModelRecentlyWarm(fourteen.id, now) && ollamaModelEstimatedLatencyMs(fourteen.id) <= 14000;
    if (!fourteenFast) requested = 3;
  }

  // Hysteresis: reusing a recently warm model avoids multi-GB model swapping. A
  // warm 4B can cover a 1.7B request without losing accuracy; a warm 8B is kept
  // only if this machine has shown it can answer quickly enough.
  const recent = available.find(item => item.id === ollamaRecentModel.model && now - ollamaRecentModel.at < 8 * 60 * 1000);
  if (recent) {
    const estimated = ollamaModelEstimatedLatencyMs(recent.id);
    if (recent.rank === 2 && requested <= 2 && estimated <= 10000) return recent;
    if (recent.rank === 3 && requested >= 2 && requested <= 3 && estimated <= 12000) return recent;
    if (recent.rank === 1 && requested === 1 && estimated <= 7000) return recent;
  }

  const exact = available.find(item => item.rank === requested);
  if (exact) return exact;

  // In balanced mode avoid jumping to a much larger cold model just because an
  // exact tier is missing. Prefer the nearest lower tier first; if none exists,
  // use the nearest higher installed model.
  const lower = [...available].filter(item => item.rank < requested).sort((a, b) => b.rank - a.rank)[0];
  if (lower) return lower;
  return available.find(item => item.rank > requested) || available[0];
}

function ollamaFallbackModel(installed = [], selectedModel = '') {
  const selectedRank = ollamaModelRank(selectedModel);
  const available = OLLAMA_MODEL_CATALOG
    .map((item, rank) => ({ ...item, rank }))
    .filter(item => modelNameInstalled(installed, item.id) && item.rank < selectedRank)
    .sort((a, b) => b.rank - a.rank);
  return available[0]?.id || '';
}

async function resolveOllamaTranslationRoute(settings = {}, text = '', source = 'auto', target = 'zh', context = []) {
  const mode = normalizeOllamaModelMode(settings?.ollamaModelMode);
  if (mode === 'fixed') {
    const model = String(settings?.ollamaModel || '').trim();
    if (!model) throw new Error('固定模型模式下，请先选择一个已安装的 Qwen 模型。');
    // V1.27.57: fixed mode is allowed a realistic cold-start budget again.
    // V1.27.55 shortened qwen3:1.7b from 30s to 9s. On CPU-only machines the
    // model can legitimately need >9s while loading, so healthy translations
    // were being classified as failures. Backpressure now prevents request
    // storms, so a single fixed-model request can safely wait for completion.
    const rank = ollamaModelRank(model);
    const warm = ollamaModelRecentlyWarm(model);
    const estimated = Math.max(1000, Number(ollamaModelEstimatedLatencyMs(model)) || 0);
    const floorMs = rank <= 1 ? (warm ? 12000 : 24000) : rank === 2 ? (warm ? 16000 : 30000) : rank === 3 ? (warm ? 24000 : 42000) : 52000;
    const capMs = rank <= 1 ? 30000 : rank === 2 ? 38000 : rank === 3 ? 50000 : 65000;
    const deadlineMs = Math.min(capMs, Math.max(floorMs, Math.ceil(estimated * 2.2 + 2500)));
    const decision = { mode, model, score: null, level: 'fixed', reasons: ['固定模型','V1.27.57自适应冷启动预算'], contextMessages: 0, targetModel: model, fallbackModel: '', deadlineMs };
    ollamaLastRouteDecision = { ...decision, at: Date.now(), textLength: [...String(text || '')].length };
    return decision;
  }

  const installed = await cachedOllamaInstalledModels(settings);
  const signals = ollamaDifficultySignals(text, source, target, context);
  const selected = selectBalancedInstalledModel(installed, signals);
  if (!selected) throw new Error('智能自动模式没有发现已安装的 Qwen 模型。请先在“本地 Qwen 环境 / 模型管理”中至少下载一个模型。');
  const targetModel = OLLAMA_MODEL_CATALOG[Math.max(0, Math.min(OLLAMA_MODEL_CATALOG.length - 1, signals.targetRank))]?.id || 'qwen3:4b';
  const estimatedMs = ollamaModelEstimatedLatencyMs(selected.id);
  const deadlineMs = selected.rank <= 1 ? 9000 : selected.rank === 2 ? 12000 : selected.rank === 3 ? 18000 : 24000;
  const decision = {
    mode,
    model: selected.id,
    score: signals.score,
    level: signals.level,
    reasons: signals.reasons,
    contextMessages: signals.contextMessages,
    targetModel,
    estimatedMs,
    deadlineMs,
    fallbackModel: ollamaFallbackModel(installed, selected.id)
  };
  ollamaLastRouteDecision = { ...decision, at: Date.now(), textLength: [...String(text || '')].length };
  return decision;
}

async function getOllamaManagerStatus({ checkLatest = false, forceLatest = false } = {}) {
  const systemExe = systemOllamaExePath();
  const bundledAvailable = bundledLocalAiAvailable();
  let serverOnline = await probeOllama(OLLAMA_DEFAULT_URL);
  if (!serverOnline && (systemExe || bundledAvailable)) {
    serverOnline = await ensureLocalOllamaServerForManager({ installIfMissing: false }).catch(() => false);
  }
  const installed = serverOnline ? await localOllamaTagList() : [];
  const runtimeInstalled = !!systemExe || bundledAvailable || serverOnline;
  const runtimeType = bundledAvailable ? 'bundled' : systemExe ? 'system' : serverOnline ? 'external' : 'none';
  const runtimeVersion = runtimeInstalled ? await getInstalledOllamaVersion({ serverOnline, exe: systemExe }) : '';
  let latestInfo = { ...ollamaLatestVersionCache };
  if (checkLatest && runtimeType !== 'bundled') latestInfo = await getLatestOllamaVersion({ force: forceLatest });
  const latestVersion = String(latestInfo?.version || '');
  const updateAvailable = !!(runtimeVersion && latestVersion && compareVersionNumbers(runtimeVersion, latestVersion) < 0);
  const isLatest = !!(runtimeVersion && latestVersion && !updateAvailable);
  return {
    runtimeInstalled,
    runtimeType,
    serverOnline,
    runtimeVersion,
    latestVersion,
    latestCheckError: String(latestInfo?.error || ''),
    updateAvailable,
    isLatest,
    currentModel: String(config?.translation?.ollamaModel || ''),
    modelMode: normalizeOllamaModelMode(config?.translation?.ollamaModelMode),
    lastRoute: ollamaLastRouteDecision ? { ...ollamaLastRouteDecision } : null,
    models: OLLAMA_MODEL_CATALOG.map(item => ({ ...item, installed: modelNameInstalled(installed, item.id) })),
    installedModels: installed
  };
}

async function detectOllamaEnvironment() {
  sendOllamaManagerProgress({ phase: 'detect', status: '正在检测 Ollama 环境与版本…', percent: 15 });
  const status = await getOllamaManagerStatus({ checkLatest: true, forceLatest: true });
  sendOllamaManagerProgress({
    phase: 'detect',
    status: status.runtimeInstalled ? 'Ollama 环境检测完成' : '未检测到 Ollama 环境',
    percent: 100,
    detail: status.runtimeInstalled
      ? [status.runtimeVersion ? `当前 ${status.runtimeVersion}` : '', status.latestVersion ? `最新 ${status.latestVersion}` : ''].filter(Boolean).join(' · ')
      : '可以点击安装 Ollama。'
  });
  return status;
}

function pullOllamaModel(model) {
  return new Promise((resolve, reject) => {
    const u = new URL(`${OLLAMA_DEFAULT_URL}/api/pull`);
    const body = JSON.stringify({ model, stream: true });
    const req = http.request(u, {
      method: 'POST',
      headers: {
        'content-type': 'application/json; charset=utf-8',
        'content-length': Buffer.byteLength(body)
      },
      timeout: 0
    }, res => {
      if ((res.statusCode || 500) >= 400) {
        let errorRaw = '';
        res.setEncoding('utf8');
        res.on('data', chunk => { errorRaw += chunk; });
        res.on('end', () => reject(new Error(`下载模型失败 HTTP ${res.statusCode}：${errorRaw.slice(0, 800)}`)));
        return;
      }
      res.setEncoding('utf8');
      let buffer = '';
      let lastPercent = 0;
      const handleLine = line => {
        const trimmed = String(line || '').trim();
        if (!trimmed) return;
        let data;
        try { data = JSON.parse(trimmed); } catch { return; }
        if (data?.error) throw new Error(String(data.error));
        const total = Number(data?.total || 0);
        const completed = Number(data?.completed || 0);
        let percent = total > 0 ? Math.floor((completed / total) * 100) : lastPercent;
        if (/success/i.test(String(data?.status || ''))) percent = 100;
        lastPercent = Math.max(lastPercent, Math.max(0, Math.min(100, percent)));
        sendOllamaManagerProgress({
          phase: 'model', model,
          status: String(data?.status || '正在下载模型…'),
          percent: lastPercent, completed, total
        });
      };
      res.on('data', chunk => {
        buffer += chunk;
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() || '';
        try { for (const line of lines) handleLine(line); }
        catch (error) { req.destroy(error); }
      });
      res.on('end', () => {
        try { if (buffer.trim()) handleLine(buffer); }
        catch (error) { reject(error); return; }
        sendOllamaManagerProgress({ phase: 'model', model, status: '模型下载完成', percent: 100 });
        resolve(true);
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function installOllamaModelOneClick(model) {
  const selected = OLLAMA_MODEL_CATALOG.find(item => item.id === String(model || '').trim());
  if (!selected) throw new Error('不支持的 Qwen 模型。');
  if (ollamaManagerTask) throw new Error('已有 Ollama 安装/下载任务正在进行，请等待完成。');
  ollamaManagerTask = { type: 'model', model: selected.id };
  try {
    sendOllamaManagerProgress({ phase: 'runtime', model: selected.id, status: '正在检查 Ollama 环境…', percent: 1 });
    const ready = await ensureLocalOllamaServerForManager({ installIfMissing: true });
    if (!ready) throw new Error('Ollama 环境没有成功启动。');
    const installed = await localOllamaTagList();
    if (!modelNameInstalled(installed, selected.id)) {
      sendOllamaManagerProgress({ phase: 'model', model: selected.id, status: `开始下载 ${selected.label}…`, percent: 0 });
      await pullOllamaModel(selected.id);
    }
    config.translation = config.translation || {};
    config.translation.engine = 'ollama';
    config.translation.ollamaUrl = OLLAMA_DEFAULT_URL;
    config.translation.ollamaModelMode = normalizeOllamaModelMode(config.translation.ollamaModelMode);
    if (config.translation.ollamaModelMode === 'fixed' || !String(config.translation.ollamaModel || '').trim()) {
      config.translation.ollamaModel = selected.id;
    }
    ollamaAutoInstalledCache.at = 0;
    saveConfig(config);
    return { ok: true, selectedModel: selected.id, modelMode: config.translation.ollamaModelMode, status: await getOllamaManagerStatus() };
  } finally {
    ollamaManagerTask = null;
  }
}

async function installOllamaRuntimeOnly(options = {}) {
  if (ollamaManagerTask) throw new Error('已有 Ollama 安装/下载任务正在进行，请等待完成。');
  const forceUpdate = options?.forceUpdate === true;
  ollamaManagerTask = { type: forceUpdate ? 'runtime-update' : 'runtime-install' };
  try {
    if (forceUpdate) await installOfficialOllamaRuntime({ forceUpdate: true });
    else await ensureLocalOllamaServerForManager({ installIfMissing: true });
    ollamaLatestVersionCache.at = 0;
    return { ok: true, status: await getOllamaManagerStatus({ checkLatest: true, forceLatest: true }) };
  } finally {
    ollamaManagerTask = null;
  }
}

function resolveInstalledOllamaModelName(installed = [], model = '') {
  const wanted = String(model || '').trim().toLowerCase();
  if (!wanted) return '';
  for (const name of installed || []) {
    const raw = String(name || '').trim();
    const normalized = raw.toLowerCase();
    if (normalized === wanted || normalized === `${wanted}:latest` || `${normalized}:latest` === wanted) return raw;
  }
  return '';
}

async function unloadLocalOllamaModel(model) {
  const body = JSON.stringify({ model, prompt: '', stream: false, keep_alive: 0 });
  try {
    await requestJson(`${OLLAMA_DEFAULT_URL}/api/generate`, {
      method: 'POST', timeout: 20000,
      headers: {
        'content-type': 'application/json; charset=utf-8',
        'content-length': Buffer.byteLength(body)
      }
    }, body);
  } catch (error) {
    // Unloading is a best-effort step. Older Ollama versions may reject it,
    // but deletion can still succeed. Never treat unload failure as success.
    console.debug('[Yoko Ollama unload before delete skipped]', error?.message || error);
  }
}

async function waitUntilOllamaModelRemoved(model, timeoutMs = 8000) {
  const started = Date.now();
  let installed = await localOllamaTagList();
  while (modelNameInstalled(installed, model) && Date.now() - started < timeoutMs) {
    await new Promise(resolve => setTimeout(resolve, 350));
    installed = await localOllamaTagList();
  }
  return installed;
}

async function removeOllamaModelWithCli(model) {
  const exe = systemOllamaExePath() || bundledOllamaExePath();
  if (!exe) return false;
  try {
    await runHiddenProcess(exe, ['rm', model], { timeoutMs: 90000 });
    return true;
  } catch (error) {
    console.debug('[Yoko Ollama CLI rm fallback failed]', error?.message || error);
    return false;
  }
}

async function deleteLocalOllamaModel(model) {
  const selected = OLLAMA_MODEL_CATALOG.find(item => item.id === String(model || '').trim());
  if (!selected) throw new Error('不支持的 Qwen 模型。');
  if (ollamaManagerTask) throw new Error('已有 Ollama 安装/下载任务正在进行，请等待完成。');
  if (!await ensureLocalOllamaServerForManager({ installIfMissing: false })) throw new Error('Ollama 当前没有运行。');

  ollamaManagerTask = { type: 'delete-model', model: selected.id };
  try {
    const before = await localOllamaTagList();
    const actualName = resolveInstalledOllamaModelName(before, selected.id);
    if (!actualName) {
      const status = await getOllamaManagerStatus();
      return { ok: true, alreadyMissing: true, selectedModel: String(config?.translation?.ollamaModel || ''), status };
    }

    // A model can remain resident in Ollama memory after translation. Unload it
    // first so Windows file handles do not make model removal appear successful
    // while the model is still usable in the current process.
    await unloadLocalOllamaModel(actualName);

    const body = JSON.stringify({ model: actualName, name: actualName });
    let apiError = null;
    try {
      await requestJson(`${OLLAMA_DEFAULT_URL}/api/delete`, {
        method: 'DELETE', timeout: 30000,
        headers: {
          'content-type': 'application/json; charset=utf-8',
          'content-length': Buffer.byteLength(body),
          'cache-control': 'no-cache'
        }
      }, body);
    } catch (error) {
      apiError = error;
    }

    let remaining = await waitUntilOllamaModelRemoved(actualName, 5500);
    if (modelNameInstalled(remaining, actualName)) {
      // Some Windows/Ollama combinations are more reliable through the official
      // CLI. Fall back to `ollama rm` and verify /api/tags again instead of
      // reporting a fake successful deletion.
      await removeOllamaModelWithCli(actualName);
      remaining = await waitUntilOllamaModelRemoved(actualName, 5500);
    }

    if (modelNameInstalled(remaining, actualName)) {
      throw new Error(`模型 ${actualName} 删除后仍出现在 Ollama 模型列表中${apiError ? `：${apiError.message}` : ''}。已阻止界面显示“删除成功”。`);
    }

    ollamaAutoInstalledCache.at = 0;
    config.translation = config.translation || {};
    const modelMode = normalizeOllamaModelMode(config.translation.ollamaModelMode);
    const current = String(config.translation.ollamaModel || '').trim();
    let replacementModel = current;
    let removedCurrent = false;
    if (current && (current.toLowerCase() === selected.id.toLowerCase() || current.toLowerCase() === actualName.toLowerCase())) {
      removedCurrent = true;
      replacementModel = '';
      config.translation.ollamaModel = '';
      // In fixed mode deleting the selected model disables local translation until
      // the operator explicitly chooses another one. In intelligent mode there is
      // no single active model, so keep Ollama enabled as long as another managed
      // Qwen model is still installed.
      if (modelMode === 'fixed' && config.translation.engine === 'ollama') config.translation.engine = 'none';
      if (modelMode !== 'fixed') {
        const remainingManaged = OLLAMA_MODEL_CATALOG.some(item => modelNameInstalled(remaining, item.id));
        if (!remainingManaged && config.translation.engine === 'ollama') config.translation.engine = 'none';
      }
      saveConfig(config);
      try { broadcastGlobalTranslationSettings(); } catch {}
    }

    const status = await getOllamaManagerStatus();
    return {
      ok: true,
      deletedModel: actualName,
      removedCurrent,
      selectedModel: replacementModel,
      status
    };
  } finally {
    ollamaManagerTask = null;
  }
}

async function selectLocalOllamaModel(model) {
  const selected = OLLAMA_MODEL_CATALOG.find(item => item.id === String(model || '').trim());
  if (!selected) throw new Error('不支持的 Qwen 模型。');
  if (!await ensureLocalOllamaServerForManager({ installIfMissing: false })) throw new Error('Ollama 当前没有运行。');
  const installed = await localOllamaTagList();
  if (!modelNameInstalled(installed, selected.id)) throw new Error(`模型 ${selected.id} 尚未下载。`);
  config.translation = config.translation || {};
  config.translation.engine = 'ollama';
  config.translation.ollamaUrl = OLLAMA_DEFAULT_URL;
  config.translation.ollamaModel = selected.id;
  config.translation.ollamaModelMode = 'fixed';
  saveConfig(config);
  return { ok: true, selectedModel: selected.id, status: await getOllamaManagerStatus() };
}

function userDataRoot() {
  return app.getPath('userData');
}

// V1.15.22 durability: write frequently-changing JSON atomically and keep one
// last-known-good backup. This protects config/cache state from power loss or a
// renderer/process crash during a write without changing any LINE session data.
function atomicWriteTextFile(target, text, { keepBackup = false } = {}) {
  const activity=beginUiLatencyAttributionActivity('sync-atomic-file-write',{phase:'filesystem'});
  try {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    const tmp = `${target}.${process.pid}.${Date.now()}.tmp`;
    const bak = `${target}.bak`;
    fs.writeFileSync(tmp, String(text), 'utf8');
    try {
      if (keepBackup && fs.existsSync(target)) fs.copyFileSync(target, bak);
    } catch {}
    try { fs.rmSync(target, { force: true }); } catch {}
    fs.renameSync(tmp, target);
  } finally { activity.finish({phase:'filesystem-complete'}); }
}

function atomicWriteJson(target, payload, options = {}) {
  atomicWriteTextFile(target, JSON.stringify(payload, null, 2), options);
}

function readJsonWithBackup(target) {
  for (const candidate of [target, `${target}.bak`]) {
    try {
      if (!fs.existsSync(candidate)) continue;
      const parsed = JSON.parse(fs.readFileSync(candidate, 'utf8'));
      if (parsed && typeof parsed === 'object') return parsed;
    } catch {}
  }
  return null;
}

function configPath() {
  return path.join(userDataRoot(), 'config.json');
}

function customerNumberVaultPath() {
  return path.join(userDataRoot(), 'customer-number-vault.json');
}

function loadCustomerNumberVault() {
  return normalizeCustomerNumberVault(readJsonWithBackup(customerNumberVaultPath()) || emptyCustomerNumberVault());
}

function saveCustomerNumberVault() {
  customerNumberVault.updatedAt = new Date().toISOString();
  atomicWriteJson(customerNumberVaultPath(), customerNumberVault, { keepBackup:true });
  return true;
}

// Capture only explicit phone fields supplied by an authorized CRM/API/import
// path. WhatsApp Web does not expose arbitrary group-member lists to this app;
// no hidden scraping is attempted.
function captureCustomerNumberPayload(payload = {}, meta = {}) {
  const rows = [];
  if (Array.isArray(payload?.phoneNumbers)) rows.push(...payload.phoneNumbers.map(phone => ({ phone })));
  if (Array.isArray(payload?.members)) rows.push(...payload.members);
  if (payload?.phone || payload?.phoneNumber) rows.push(payload);
  if (!rows.length) return { added:0, updated:0, skipped:0 };
  let added = 0; let updated = 0; let skipped = 0;
  for (const row of rows.slice(0, 5000)) {
    const sourceType = String(row?.sourceType || row?.type || meta.sourceType || 'import').toLowerCase();
    const result = upsertCustomerPhone(customerNumberVault, {
      ...row,
      phone: row?.phone || row?.phoneNumber,
      sourceType,
      accountId: row?.accountId || meta.accountId,
      accountName: row?.accountName || meta.accountName,
      groupId: row?.groupId || meta.groupId,
      groupName: row?.groupName || meta.groupName,
      groupType: row?.groupType || meta.groupType,
      timestamp: row?.timestamp || meta.timestamp
    });
    if (!result.ok) { skipped += 1; continue; }
    customerNumberVault = result.state;
    if (result.inserted) added += 1; else updated += 1;
  }
  if (added || updated) {
    saveCustomerNumberVault();
    try { sendUI('customer-number-vault-updated', { added, updated, sourceType:meta.sourceType || '' }); } catch {}
  }
  return { added, updated, skipped };
}

function translationCachePath() {
  return path.join(userDataRoot(), 'translation-cache.json');
}

function restoredLineDraftsPath() {
  return path.join(userDataRoot(), 'restored-line-drafts.json');
}

function aggregateCachePath() {
  return path.join(userDataRoot(), 'aggregate-cache.json');
}

function aggregateCustomerAvatarCachePath() {
  return path.join(userDataRoot(), 'aggregate-customer-avatar-cache.json');
}

function aggregateCustomerAvatarCacheDir() {
  const dir = path.join(userDataRoot(), 'aggregate-customer-avatars');
  try { fs.mkdirSync(dir, { recursive: true }); } catch {}
  return dir;
}

function aggregateCustomerAvatarKey(accountId, chatId) {
  return `${String(accountId || '').trim()}::${String(chatId || '').trim()}`;
}

function aggregateCustomerAvatarBaseName(accountId, chatId) {
  return crypto.createHash('sha256').update(aggregateCustomerAvatarKey(accountId, chatId)).digest('hex');
}

function aggregateCustomerAvatarBrowserUrl(accountId, chatId, hintedFile = '', avatarHash = '') {
  let fileName = path.basename(String(hintedFile || '').trim());
  if (!fileName) {
    const localFile = aggregateCustomerAvatarExistingFile(accountId, chatId);
    fileName = localFile ? path.basename(localFile) : '';
  }
  if (!fileName) return '';
  const version = String(avatarHash || '').trim().slice(0, 16);
  return `yoko-avatar://customer/${encodeURIComponent(fileName)}${version ? `?v=${encodeURIComponent(version)}` : ''}`;
}

function registerYokoAvatarProtocol() {
  try {
    protocol.registerFileProtocol('yoko-avatar', (request, callback) => {
      try {
        const parsed = new URL(String(request?.url || ''));
        if (String(parsed.hostname || '').toLowerCase() !== 'customer') {
          callback({ error: -6 });
          return;
        }
        const requested = decodeURIComponent(String(parsed.pathname || '').replace(/^\/+/, ''));
        const fileName = path.basename(requested);
        if (!/^[a-f0-9]{64}\.(?:jpg|jpeg|png|webp|gif|avif|bmp)$/i.test(fileName)) {
          callback({ error: -6 });
          return;
        }
        const root = path.resolve(aggregateCustomerAvatarCacheDir()) + path.sep;
        const resolved = path.resolve(path.join(aggregateCustomerAvatarCacheDir(), fileName));
        if (!resolved.startsWith(root) || !fs.existsSync(resolved) || fs.statSync(resolved).size <= 0) {
          callback({ error: -6 });
          return;
        }
        callback({ path: resolved });
      } catch {
        callback({ error: -2 });
      }
    });
  } catch (error) {
    console.debug('[Yoko avatar protocol register skipped]', error?.message || error);
  }
}

function avatarDataUrlParts(value) {
  const dataUrl = normalizeAvatarDataUrl(value);
  if (!dataUrl) return null;
  const match = dataUrl.match(/^data:image\/([a-z0-9.+-]+);base64,(.+)$/i);
  if (!match) return null;
  const mimePart = String(match[1] || '').toLowerCase();
  const ext = mimePart.includes('jpeg') || mimePart.includes('jpg') ? 'jpg'
    : mimePart.includes('webp') ? 'webp'
      : mimePart.includes('gif') ? 'gif'
        : mimePart.includes('avif') ? 'avif'
          : mimePart.includes('bmp') ? 'bmp'
            : 'png';
  try {
    const buffer = Buffer.from(match[2], 'base64');
    if (!buffer.length || buffer.length > 3 * 1024 * 1024) return null;
    return { ext, buffer };
  } catch {
    return null;
  }
}

function lineAvatarBinaryHash(buffer) {
  try {
    return crypto.createHash('sha256').update(buffer).digest('hex');
  } catch {
    return '';
  }
}

function isKnownLinePlaceholderAvatarBuffer(buffer) {
  if (!buffer?.length) return false;
  return KNOWN_LINE_PLACEHOLDER_AVATAR_SHA256.has(lineAvatarBinaryHash(buffer));
}

function isKnownLinePlaceholderAvatarDataUrl(value) {
  const parts = avatarDataUrlParts(value);
  return !!(parts && isKnownLinePlaceholderAvatarBuffer(parts.buffer));
}

function isKnownLinePlaceholderAvatarFile(file) {
  try {
    if (!file || !fs.existsSync(file)) return false;
    return isKnownLinePlaceholderAvatarBuffer(fs.readFileSync(file));
  } catch {
    return false;
  }
}

function aggregateCustomerAvatarHash(value) {
  const dataUrl = normalizeAvatarDataUrl(value);
  if (!dataUrl || isKnownLinePlaceholderAvatarDataUrl(dataUrl)) return '';
  const parts = avatarDataUrlParts(dataUrl);
  return parts ? lineAvatarBinaryHash(parts.buffer) : '';
}

function aggregateCustomerAvatarExistingFile(accountId, chatId, hintedFile = '') {
  const dir = aggregateCustomerAvatarCacheDir();
  const hintedBase = path.basename(String(hintedFile || '').trim());
  if (hintedBase) {
    const hinted = path.join(dir, hintedBase);
    try { if (fs.existsSync(hinted) && fs.statSync(hinted).size > 0) return hinted; } catch {}
  }
  const base = aggregateCustomerAvatarBaseName(accountId, chatId);
  for (const ext of ['jpg', 'png', 'webp', 'gif', 'avif', 'bmp']) {
    const candidate = path.join(dir, `${base}.${ext}`);
    try { if (fs.existsSync(candidate) && fs.statSync(candidate).size > 0) return candidate; } catch {}
  }
  return '';
}

function persistAggregateCustomerAvatarFile(accountId, chatId, avatarDataUrl) {
  const parts = avatarDataUrlParts(avatarDataUrl);
  if (!parts || isKnownLinePlaceholderAvatarBuffer(parts.buffer)) return { avatarFile: '', avatarLocalUrl: '' };
  const dir = aggregateCustomerAvatarCacheDir();
  const base = aggregateCustomerAvatarBaseName(accountId, chatId);
  const target = path.join(dir, `${base}.${parts.ext}`);
  const tmp = `${target}.${process.pid}.tmp`;
  try {
    fs.writeFileSync(tmp, parts.buffer);
    for (const ext of ['jpg', 'png', 'webp', 'gif', 'avif', 'bmp']) {
      const other = path.join(dir, `${base}.${ext}`);
      if (other !== target) {
        try { fs.rmSync(other, { force: true }); } catch {}
      }
    }
    try { fs.rmSync(target, { force: true }); } catch {}
    fs.renameSync(tmp, target);
    return { avatarFile: path.basename(target), avatarLocalUrl: aggregateCustomerAvatarBrowserUrl(accountId, chatId, path.basename(target)) };
  } catch (error) {
    try { fs.rmSync(tmp, { force: true }); } catch {}
    console.debug('[Yoko aggregate customer avatar file save skipped]', error?.message || error);
    return { avatarFile: '', avatarLocalUrl: '' };
  }
}


function metaNativeAvatarMirrorPath() {
  return path.join(userDataRoot(), 'meta-native-avatar-mirror.json');
}

function metaNativeAvatarStableKey(target = {}) {
  const pageId = String(target?.pageId || String(target?.accountId || '').replace(/^fb-api:/, '')).trim();
  const peerId = String(target?.remoteId || String(target?.chatId || '').replace(/^fb-api:/, '')).trim();
  return pageId && peerId ? `facebook|${pageId}|${peerId}` : '';
}

function metaNativeAvatarMirrorBrowserUrl(entry = {}) {
  const fileName = path.basename(String(entry?.avatarFile || '').trim());
  if (!fileName) return '';
  const local = path.join(aggregateCustomerAvatarCacheDir(), fileName);
  try { if (!fs.existsSync(local) || fs.statSync(local).size <= 0) return ''; } catch { return ''; }
  return aggregateCustomerAvatarBrowserUrl('', '', fileName, String(entry?.avatarHash || '').trim());
}

function metaNativeAvatarMimeExtension(contentType = '', sourceUrl = '') {
  const mime = String(contentType || '').toLowerCase();
  if (mime.includes('jpeg') || mime.includes('jpg')) return 'jpg';
  if (mime.includes('png')) return 'png';
  if (mime.includes('webp')) return 'webp';
  if (mime.includes('gif')) return 'gif';
  if (mime.includes('avif')) return 'avif';
  if (mime.includes('bmp')) return 'bmp';
  try {
    const ext = String(new URL(String(sourceUrl || '')).pathname.split('.').pop() || '').toLowerCase();
    if (['jpg', 'jpeg', 'png', 'webp', 'gif', 'avif', 'bmp'].includes(ext)) return ext === 'jpeg' ? 'jpg' : ext;
  } catch {}
  return 'jpg';
}

async function persistMetaNativeAvatarFromSession(sender, sourceUrl, candidateId) {
  const url = String(sourceUrl || '').trim();
  if (!trustedMetaAvatarUrl(url) || !/^[a-f0-9]{64}$/i.test(String(candidateId || ''))) return null;
  try {
    const response = await sender?.session?.fetch?.(url, { credentials:'include', cache:'force-cache' });
    if (!response?.ok) throw new Error(`HTTP ${response?.status || 0}`);
    const declared = Number(response.headers?.get?.('content-length') || 0) || 0;
    if (declared > 3 * 1024 * 1024) throw new Error('avatar too large');
    const buffer = Buffer.from(await response.arrayBuffer());
    if (!buffer.length || buffer.length > 3 * 1024 * 1024) throw new Error('avatar bytes invalid');
    const image = nativeImage.createFromBuffer(buffer);
    const size = image?.getSize?.() || { width:0, height:0 };
    if (image?.isEmpty?.() || Number(size.width || 0) < 16 || Number(size.height || 0) < 16) throw new Error('avatar image invalid');
    const ext = metaNativeAvatarMimeExtension(response.headers?.get?.('content-type') || '', url);
    const dir = aggregateCustomerAvatarCacheDir();
    const target = path.join(dir, `${candidateId}.${ext}`);
    const tmp = `${target}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(tmp, buffer);
    for (const otherExt of ['jpg','jpeg','png','webp','gif','avif','bmp']) {
      const other = path.join(dir, `${candidateId}.${otherExt}`);
      if (other !== target) { try { fs.rmSync(other, { force:true }); } catch {} }
    }
    try { fs.rmSync(target, { force:true }); } catch {}
    fs.renameSync(tmp, target);
    const avatarHash = crypto.createHash('sha256').update(buffer).digest('hex');
    return { avatarFile:path.basename(target), avatarHash, avatarLocalUrl:aggregateCustomerAvatarBrowserUrl('', '', path.basename(target), avatarHash) };
  } catch (error) {
    console.debug('[Meta native avatar mirror download skipped]', String(error?.message || error));
    return null;
  }
}

function loadMetaNativeAvatarMirrorCache() {
  metaNativeAvatarCandidates.clear();
  metaNativeAvatarBindings.clear();
  try {
    const raw = readJsonWithBackup(metaNativeAvatarMirrorPath());
    for (const row of (Array.isArray(raw?.candidates) ? raw.candidates : []).slice(-META_NATIVE_AVATAR_CANDIDATE_MAX)) {
      const candidateId = String(row?.candidateId || '').trim();
      const name = String(row?.name || '').trim().slice(0, 180);
      const avatarFile = path.basename(String(row?.avatarFile || '').trim());
      if (!/^[a-f0-9]{64}$/i.test(candidateId) || !name || !/^[a-f0-9]{64}\.(?:jpg|jpeg|png|webp|gif|avif|bmp)$/i.test(avatarFile)) continue;
      const local = path.join(aggregateCustomerAvatarCacheDir(), avatarFile);
      try { if (!fs.existsSync(local) || fs.statSync(local).size <= 0) continue; } catch { continue; }
      const entry = {
        candidateId,
        sourceAccountId:String(row?.sourceAccountId || '').trim().slice(0, 240),
        name,
        preview:String(row?.preview || '').trim().slice(0, 1200),
        timeText:String(row?.timeText || '').trim().slice(0, 120),
        avatarSourceBase:String(row?.avatarSourceBase || '').trim().slice(0, 4000),
        avatarFile,
        avatarHash:String(row?.avatarHash || '').trim().slice(0, 128),
        updatedAt:Number(row?.updatedAt || 0) || Date.now()
      };
      entry.avatarLocalUrl = metaNativeAvatarMirrorBrowserUrl(entry);
      if (entry.avatarLocalUrl) metaNativeAvatarCandidates.set(candidateId, entry);
    }
    const validIds = new Set(metaNativeAvatarCandidates.keys());
    for (const row of (Array.isArray(raw?.bindings) ? raw.bindings : []).slice(-META_NATIVE_AVATAR_BINDING_MAX)) {
      const stableKey = String(row?.stableKey || '').trim();
      const candidateId = String(row?.candidateId || '').trim();
      if (!/^facebook\|[^|]+\|[^|]+$/.test(stableKey) || !validIds.has(candidateId)) continue;
      metaNativeAvatarBindings.set(stableKey, { candidateId, updatedAt:Number(row?.updatedAt || 0) || Date.now() });
    }
  } catch (error) {
    console.debug('[Meta native avatar mirror cache load skipped]', error?.message || error);
  }
}

function saveMetaNativeAvatarMirrorCache() {
  try {
    const candidates = [...metaNativeAvatarCandidates.values()]
      .filter(row => metaNativeAvatarMirrorBrowserUrl(row))
      .sort((a,b)=>Number(a.updatedAt||0)-Number(b.updatedAt||0))
      .slice(-META_NATIVE_AVATAR_CANDIDATE_MAX)
      .map(row => ({
        candidateId:row.candidateId, sourceAccountId:row.sourceAccountId, name:row.name,
        preview:row.preview, timeText:row.timeText, avatarSourceBase:row.avatarSourceBase,
        avatarFile:row.avatarFile, avatarHash:row.avatarHash, updatedAt:Number(row.updatedAt||0)||Date.now()
      }));
    const validIds = new Set(candidates.map(row => row.candidateId));
    const bindings = [...metaNativeAvatarBindings.entries()]
      .filter(([,row])=>validIds.has(String(row?.candidateId||'')))
      .sort((a,b)=>Number(a[1]?.updatedAt||0)-Number(b[1]?.updatedAt||0))
      .slice(-META_NATIVE_AVATAR_BINDING_MAX)
      .map(([stableKey,row])=>({stableKey,candidateId:row.candidateId,updatedAt:Number(row.updatedAt||0)||Date.now()}));
    atomicWriteJson(metaNativeAvatarMirrorPath(), { version:1, updatedAt:new Date().toISOString(), candidates, bindings }, { keepBackup:true });
  } catch (error) {
    console.debug('[Meta native avatar mirror cache save skipped]', error?.message || error);
  }
}

function scheduleMetaNativeAvatarMirrorSave() {
  if (metaNativeAvatarMirrorSaveTimer) clearTimeout(metaNativeAvatarMirrorSaveTimer);
  metaNativeAvatarMirrorSaveTimer = setTimeout(() => { metaNativeAvatarMirrorSaveTimer = null; saveMetaNativeAvatarMirrorCache(); }, 700);
}

function applyMetaNativeAvatarMirrors(items = []) {
  const rows = (Array.isArray(items) ? items : []).map(item => ({ ...item }));
  const candidates = [...metaNativeAvatarCandidates.values()].filter(row => metaNativeAvatarMirrorBrowserUrl(row));
  let bindingChanged = false;
  for (const item of rows) {
    if (String(item?.platform || '').toLowerCase() !== 'facebook' || String(item?.avatarUrl || '').trim()) continue;
    const stableKey = metaNativeAvatarStableKey(item);
    if (!stableKey) continue;
    let candidate = null;
    const binding = metaNativeAvatarBindings.get(stableKey);
    if (binding) {
      candidate = metaNativeAvatarCandidates.get(String(binding.candidateId || '')) || null;
      if (!candidate || !metaNativeAvatarMirrorBrowserUrl(candidate)) {
        metaNativeAvatarBindings.delete(stableKey);
        candidate = null;
        bindingChanged = true;
      }
    }
    if (!candidate) {
      candidate = chooseMetaNativeAvatarCandidate(item, candidates, rows);
      if (candidate) {
        metaNativeAvatarBindings.set(stableKey, { candidateId:candidate.candidateId, updatedAt:Date.now() });
        bindingChanged = true;
      }
    }
    const localUrl = candidate ? metaNativeAvatarMirrorBrowserUrl(candidate) : '';
    if (localUrl) {
      item.avatarUrl = localUrl;
      item.avatarSource = 'meta-native-mirror';
    }
  }
  if (bindingChanged) scheduleMetaNativeAvatarMirrorSave();
  return rows;
}

async function ingestMetaNativeAvatarMirrorSnapshot(event, payload = {}) {
  const accountId = resolveExternalAccountIdFromSender(event?.sender);
  const account = appCenterAccountById(accountId);
  if (!account || String(account.platform || '') !== 'metabusiness') return { ok:false, ignored:true };
  const rawRows = Array.isArray(payload?.rows) ? payload.rows.slice(0, 80) : [];
  const rows = [];
  const seen = new Set();
  for (const row of rawRows) {
    const name = String(row?.name || row?.displayName || '').trim().slice(0, 180);
    const avatarUrl = String(row?.avatarUrl || '').trim().slice(0, 4000);
    if (!name || !trustedMetaAvatarUrl(avatarUrl)) continue;
    const avatarSourceBase = metaNativeAvatarCanonicalSource(avatarUrl);
    const identity = metaNativeAvatarCandidateIdentity({ name, avatarUrl });
    if (!identity || !avatarSourceBase) continue;
    const candidateId = crypto.createHash('sha256').update(`${accountId}|${identity}`).digest('hex');
    if (seen.has(candidateId)) continue;
    seen.add(candidateId);
    rows.push({ candidateId, sourceAccountId:accountId, name, preview:String(row?.preview || '').trim().slice(0, 1200), timeText:String(row?.timeText || '').trim().slice(0,120), avatarUrl, avatarSourceBase });
  }
  if (!rows.length) return { ok:true, stored:0 };
  let cursor = 0, stored = 0, changed = false;
  const worker = async () => {
    while (cursor < rows.length) {
      const row = rows[cursor++];
      const previous = metaNativeAvatarCandidates.get(row.candidateId) || null;
      let persisted = previous && metaNativeAvatarMirrorBrowserUrl(previous) ? { avatarFile:previous.avatarFile, avatarHash:previous.avatarHash, avatarLocalUrl:previous.avatarLocalUrl } : null;
      if (!persisted) persisted = await persistMetaNativeAvatarFromSession(event.sender, row.avatarUrl, row.candidateId);
      if (!persisted?.avatarFile) continue;
      const next = {
        candidateId:row.candidateId, sourceAccountId:row.sourceAccountId, name:row.name,
        preview:row.preview || previous?.preview || '', timeText:row.timeText || previous?.timeText || '',
        avatarSourceBase:row.avatarSourceBase, avatarFile:persisted.avatarFile,
        avatarHash:persisted.avatarHash || previous?.avatarHash || '', updatedAt:Date.now()
      };
      next.avatarLocalUrl = metaNativeAvatarMirrorBrowserUrl(next);
      if (!next.avatarLocalUrl) continue;
      const same = previous && previous.avatarFile===next.avatarFile && previous.preview===next.preview && previous.timeText===next.timeText && previous.name===next.name;
      metaNativeAvatarCandidates.set(row.candidateId, next);
      stored += 1;
      if (!same) changed = true;
    }
  };
  await Promise.all(Array.from({ length:Math.min(4, rows.length) }, worker));
  if (metaNativeAvatarCandidates.size > META_NATIVE_AVATAR_CANDIDATE_MAX) {
    const oldest = [...metaNativeAvatarCandidates.entries()].sort((a,b)=>Number(a[1]?.updatedAt||0)-Number(b[1]?.updatedAt||0)).slice(0, metaNativeAvatarCandidates.size-META_NATIVE_AVATAR_CANDIDATE_MAX);
    for (const [key] of oldest) metaNativeAvatarCandidates.delete(key);
    changed = true;
  }
  if (changed) scheduleMetaNativeAvatarMirrorSave();
  return { ok:true, stored, candidates:metaNativeAvatarCandidates.size };
}

function loadAggregateCustomerAvatarCache() {
  aggregateCustomerAvatarCache.clear();
  try {
    const file = aggregateCustomerAvatarCachePath();
    const raw = readJsonWithBackup(file);
    if (!raw) return;
    const entries = Array.isArray(raw?.entries) ? raw.entries : [];
    let migrated = false;
    for (const entry of entries.slice(-AGGREGATE_CUSTOMER_AVATAR_CACHE_MAX)) {
      const accountId = String(entry?.accountId || '').trim();
      const chatId = String(entry?.chatId || '').trim();
      if (!accountId || !chatId || !getAccount(accountId)) continue;

      let avatarDataUrl = normalizeAvatarDataUrl(entry?.avatarDataUrl || '');
      let avatarFile = String(entry?.avatarFile || '').trim();
      let localFile = aggregateCustomerAvatarExistingFile(accountId, chatId, avatarFile);

      // Remove V1.20.2-and-earlier entries that accidentally persisted LINE's
      // built-in silhouette/loading image instead of the real contact photo.
      if (localFile && isKnownLinePlaceholderAvatarFile(localFile)) {
        try { fs.rmSync(localFile, { force: true }); } catch {}
        localFile = '';
        avatarFile = '';
        migrated = true;
      }
      if (avatarDataUrl && isKnownLinePlaceholderAvatarDataUrl(avatarDataUrl)) {
        avatarDataUrl = '';
        migrated = true;
      }

      let avatarLocalUrl = localFile ? aggregateCustomerAvatarBrowserUrl(accountId, chatId, path.basename(localFile), entry?.avatarHash || '') : '';

      // Migrate V1 cache entries that stored the full image inside one JSON file.
      if (!avatarLocalUrl && avatarDataUrl) {
        const persisted = persistAggregateCustomerAvatarFile(accountId, chatId, avatarDataUrl);
        avatarFile = persisted.avatarFile;
        avatarLocalUrl = persisted.avatarLocalUrl;
        if (avatarLocalUrl) migrated = true;
      }
      if (!avatarLocalUrl && !avatarDataUrl) continue;

      aggregateCustomerAvatarCache.set(aggregateCustomerAvatarKey(accountId, chatId), {
        accountId,
        chatId,
        avatarDataUrl: avatarLocalUrl ? '' : avatarDataUrl,
        avatarHash: String(entry?.avatarHash || aggregateCustomerAvatarHash(avatarDataUrl) || '').trim(),
        avatarFile: avatarFile || (localFile ? path.basename(localFile) : ''),
        avatarLocalUrl,
        avatarUrl: String(entry?.avatarUrl || '').trim().slice(0, 2000),
        updatedAt: Number(entry?.updatedAt || 0) || Date.now()
      });
    }
    if (migrated || Number(raw?.version || 0) < AGGREGATE_CUSTOMER_AVATAR_FILE_CACHE_VERSION) {
      saveAggregateCustomerAvatarCache();
    }
  } catch (error) {
    console.debug('[Yoko aggregate customer avatar cache load skipped]', error?.message || error);
  }
}

function saveAggregateCustomerAvatarCache() {
  try {
    const entries = [...aggregateCustomerAvatarCache.values()]
      .filter(entry => entry?.avatarLocalUrl || normalizeAvatarDataUrl(entry?.avatarDataUrl || ''))
      .sort((a, b) => Number(a.updatedAt || 0) - Number(b.updatedAt || 0))
      .slice(-AGGREGATE_CUSTOMER_AVATAR_CACHE_MAX)
      .map(entry => ({
        accountId: entry.accountId,
        chatId: entry.chatId,
        avatarFile: String(entry.avatarFile || '').trim(),
        avatarHash: String(entry.avatarHash || '').trim(),
        // Only keep base64 as an emergency fallback if disk persistence failed.
        avatarDataUrl: entry.avatarLocalUrl ? '' : normalizeAvatarDataUrl(entry.avatarDataUrl || ''),
        avatarUrl: String(entry.avatarUrl || '').trim().slice(0, 2000),
        updatedAt: Number(entry.updatedAt || 0) || Date.now()
      }));
    atomicWriteJson(
      aggregateCustomerAvatarCachePath(),
      { version: AGGREGATE_CUSTOMER_AVATAR_FILE_CACHE_VERSION, updatedAt: new Date().toISOString(), entries },
      { keepBackup: true }
    );
  } catch (error) {
    console.debug('[Yoko aggregate customer avatar cache save skipped]', error?.message || error);
  }
}

function scheduleAggregateCustomerAvatarCacheSave() {
  if (aggregateCustomerAvatarCacheSaveTimer) clearTimeout(aggregateCustomerAvatarCacheSaveTimer);
  aggregateCustomerAvatarCacheSaveTimer = setTimeout(() => {
    aggregateCustomerAvatarCacheSaveTimer = null;
    saveAggregateCustomerAvatarCache();
  }, 900);
}

function rememberAggregateCustomerAvatar(accountId, conversation = {}) {
  accountId = String(accountId || '').trim();
  const chatId = String(conversation?.chatId || '').trim();
  const avatarDataUrl = normalizeAvatarDataUrl(conversation?.avatarDataUrl || '');
  if (!accountId || !chatId || !avatarDataUrl || isKnownLinePlaceholderAvatarDataUrl(avatarDataUrl)) return false;
  const key = aggregateCustomerAvatarKey(accountId, chatId);
  const previous = aggregateCustomerAvatarCache.get(key) || {};
  const avatarUrl = String(conversation?.avatarUrl || previous.avatarUrl || '').trim().slice(0, 2000);
  const avatarHash = aggregateCustomerAvatarHash(avatarDataUrl);

  // Do not rewrite the same picture on every aggregate snapshot, but repair a
  // missing local file if an older install only had the in-memory/base64 copy.
  let persisted = { avatarFile: previous.avatarFile || '', avatarLocalUrl: previous.avatarLocalUrl || '' };
  let previousFile = '';
  if (!previous.avatarLocalUrl) previousFile = aggregateCustomerAvatarExistingFile(accountId, chatId, previous.avatarFile || '');
  if (previous.avatarHash !== avatarHash || (!previous.avatarLocalUrl && !previousFile)) {
    persisted = persistAggregateCustomerAvatarFile(accountId, chatId, avatarDataUrl);
  } else if (!previous.avatarLocalUrl && previousFile) {
    persisted = { avatarFile: path.basename(previousFile), avatarLocalUrl: aggregateCustomerAvatarBrowserUrl(accountId, chatId, path.basename(previousFile), avatarHash) };
  }

  const persistedLocalUrl = persisted.avatarFile
    ? aggregateCustomerAvatarBrowserUrl(accountId, chatId, persisted.avatarFile, avatarHash)
    : String(persisted.avatarLocalUrl || '');
  if (
    previous.avatarHash === avatarHash &&
    previous.avatarUrl === avatarUrl &&
    previous.avatarLocalUrl === persistedLocalUrl
  ) return false;

  aggregateCustomerAvatarCache.set(key, {
    accountId,
    chatId,
    avatarDataUrl: persistedLocalUrl ? '' : avatarDataUrl,
    avatarHash,
    avatarFile: persisted.avatarFile || '',
    avatarLocalUrl: persistedLocalUrl,
    avatarUrl,
    updatedAt: Date.now()
  });
  if (aggregateCustomerAvatarCache.size > AGGREGATE_CUSTOMER_AVATAR_CACHE_MAX) {
    const oldest = [...aggregateCustomerAvatarCache.entries()]
      .sort((a, b) => Number(a[1]?.updatedAt || 0) - Number(b[1]?.updatedAt || 0))
      .slice(0, aggregateCustomerAvatarCache.size - AGGREGATE_CUSTOMER_AVATAR_CACHE_MAX);
    for (const [oldKey, oldEntry] of oldest) {
      aggregateCustomerAvatarCache.delete(oldKey);
      const oldFile = aggregateCustomerAvatarExistingFile(oldEntry?.accountId, oldEntry?.chatId, oldEntry?.avatarFile || '');
      try { if (oldFile) fs.rmSync(oldFile, { force: true }); } catch {}
    }
  }
  scheduleAggregateCustomerAvatarCacheSave();
  return true;
}

function hydrateAggregateCustomerAvatar(accountId, conversation = {}) {
  const chatId = String(conversation?.chatId || '').trim();
  if (!chatId) return conversation;
  const cached = aggregateCustomerAvatarCache.get(aggregateCustomerAvatarKey(accountId, chatId));
  if (!cached) return conversation;

  if (cached.avatarLocalUrl) {
    conversation.avatarLocalUrl = cached.avatarLocalUrl;
  } else {
    const localFile = aggregateCustomerAvatarExistingFile(accountId, chatId, cached.avatarFile || '');
    if (localFile) {
      cached.avatarFile = path.basename(localFile);
      cached.avatarLocalUrl = aggregateCustomerAvatarBrowserUrl(accountId, chatId, path.basename(localFile), cached.avatarHash || '');
      conversation.avatarLocalUrl = cached.avatarLocalUrl;
    }
  }
  if (!conversation.avatarLocalUrl && cached.avatarDataUrl && !normalizeAvatarDataUrl(conversation?.avatarDataUrl || '')) {
    conversation.avatarDataUrl = cached.avatarDataUrl;
  }
  if (!String(conversation.avatarUrl || '').trim() && cached.avatarUrl) conversation.avatarUrl = cached.avatarUrl;
  return conversation;
}

// V1.15.29: aggregate display accepts LINE's live conversation keys without
// assuming one internal MID shape. V1.15.28's u/c/r+32hex-only rule could drop
// the entire real inbox. We explicitly reject only known UI/system placeholders.
function isValidLineAggregateChatId(value) {
  const id = String(value || '').trim();
  if (!id || id.length > 160) return false;
  const lowered = id.toLowerCase();
  if (['line', 'null', 'undefined', 'none', 'unknown'].includes(lowered)) return false;
  if (/^https?:\/\//i.test(id) || /\s/.test(id)) return false;
  return true;
}

// Operations that call LINE contact APIs still use a canonical MID when one is
// available. This is intentionally separate from aggregate row visibility.
function isCanonicalLineMid(value) {
  return /^[ucr][0-9a-z]{32}$/i.test(String(value || '').trim());
}

function sanitizeAggregateConversation(raw = {}) {
  const chatId = String(raw.chatId || '').trim().slice(0, 160);
  if (!isValidLineAggregateChatId(chatId)) return null;
  const displayNameRaw = String(raw.displayName || '').trim().slice(0, 160);
  const typeRaw = String(raw.type || '').trim().slice(0, 40);
  const sourceRaw = String(raw.source || 'line-store').trim().slice(0, 40);
  const contactTypeRaw = raw.contactType;
  const contactType = contactTypeRaw === null || contactTypeRaw === undefined || contactTypeRaw === ''
    ? null
    : (Number.isFinite(Number(contactTypeRaw)) ? Number(contactTypeRaw) : null);
  const isOfficial = raw.isOfficial === true || contactType === 8 || String(contactTypeRaw || '').trim().toUpperCase() === 'PROMOTION_BOT';
  // V1.23.10: Aggregate Mode is customer-only. Drop group/room/system rows and
  // LINE Official Accounts at the main-process cache boundary as a second guard
  // so stale snapshots can never leak them back into the UI.
  if ((typeRaw && typeRaw !== 'contact') || isOfficial) return null;
  // V1.15.31: LINE's QR/login flow can create an internal system talk named
  // exactly "LINE". It is not a customer and must never enter Aggregate Mode,
  // regardless of which transient type/message fields LINE attaches to it.
  if (displayNameRaw.toLowerCase() === 'line') return null;
  const timestamp = Number(raw.timestamp || 0) || 0;
  const lastIncomingAt = Number(raw.lastIncomingAt || 0) || 0;
  const lastOutgoingAt = Number(raw.lastOutgoingAt || 0) || 0;
  const firstMessageAt = Number(raw.firstMessageAt || 0) || 0;
  const firstSeenAt = Number(raw.firstSeenAt || 0) || 0;
  // V1.23.13: dedicated lead-arrival timestamp. Do not infer "today new"
  // from cache discovery/capture time; that made historical customers count as
  // new immediately after a fresh install/scan. 1 means known historical/baseline.
  const newCustomerAt = Number(raw.newCustomerAt || 0) || 0;
  return {
    chatId,
    displayName: displayNameRaw || '未命名聊天',
    preview: String(raw.preview || '').replace(/\s+/g, ' ').trim().slice(0, 600),
    unreadCount: Math.max(0, Math.min(99999, Number(raw.unreadCount || 0) || 0)),
    timestamp,
    lastMessageId: String(raw.lastMessageId || '').slice(0, 160),
    lastDirection: raw.lastDirection === 'me' ? 'me' : 'customer',
    lastIncomingAt,
    lastOutgoingAt,
    firstMessageAt,
    firstSeenAt,
    newCustomerAt,
    searchText: String(raw.searchText || '').replace(/\s+/g, ' ').trim().slice(0, 4000),
    avatarUrl: String(raw.avatarUrl || '').trim().slice(0, 2000),
    avatarDataUrl: normalizeAvatarDataUrl(raw.avatarDataUrl || ''),
    avatarLocalUrl: String(raw.avatarLocalUrl || '').trim().slice(0, 3000),
    type: typeRaw || 'contact',
    contactType,
    isOfficial: false,
    hasConversation: raw.hasConversation === false ? false : true,
    source: sourceRaw
  };
}

function setAggregateSnapshot(accountId, payload = {}, { persist = true, emit = true, fromDisk = false } = {}) {
  accountId = String(accountId || '').trim();
  if (!accountId || !getAccount(accountId)) return null;
  const list = Array.isArray(payload?.conversations) ? payload.conversations : [];
  const previousRecord = aggregateConversationCache.get(accountId) || { conversations: [] };
  // V1.23.13 lead baseline: legacy caches did not know whether a customer was
  // actually new today or merely first discovered by Yoko today. During the
  // first live snapshot after migration, every already-present row is baseline
  // history. Only rows first appearing after that baseline may count as new.
  const leadBaselineEstablished = previousRecord.leadBaselineEstablished === true || payload?.leadBaselineEstablished === true;
  const previousById = new Map((previousRecord.conversations || []).map(item => [String(item.chatId || ''), item]));
  const byId = new Map();
  for (const item of list) {
    const normalized = sanitizeAggregateConversation(item);
    if (!normalized) continue;
    // V1.13.2: restore a previously captured customer avatar before merging the
    // current live snapshot. This survives full app restarts and LINE CDN/login
    // timing, unlike renderer-only blob/CDN URLs.
    hydrateAggregateCustomerAvatar(accountId, normalized);
    // V1.12.6: avatar fetches are asynchronous inside LINE. A later refresh can
    // temporarily arrive without avatar bytes; keep the last known real photo
    // instead of flashing back to an initial in the aggregate customer list.
    const cached = previousById.get(normalized.chatId);
    if (cached) {
      if (!normalized.avatarDataUrl && cached.avatarDataUrl) normalized.avatarDataUrl = cached.avatarDataUrl;
      if (!normalized.avatarUrl && cached.avatarUrl) normalized.avatarUrl = cached.avatarUrl;
      if (!normalized.avatarLocalUrl && cached.avatarLocalUrl) normalized.avatarLocalUrl = cached.avatarLocalUrl;
      // LINE may unload older message entities while keeping the messageBox.
      // Never forget a previously observed incoming timestamp just because the
      // current lightweight Redux snapshot no longer contains that message.
      if (!normalized.lastIncomingAt && Number(cached.lastIncomingAt || 0) > 0) {
        normalized.lastIncomingAt = Number(cached.lastIncomingAt || 0);
      }
      if (!normalized.lastOutgoingAt && Number(cached.lastOutgoingAt || 0) > 0) {
        normalized.lastOutgoingAt = Number(cached.lastOutgoingAt || 0);
      }
      if (!normalized.firstMessageAt && Number(cached.firstMessageAt || 0) > 0) {
        normalized.firstMessageAt = Number(cached.firstMessageAt || 0);
      }
      if (!normalized.searchText && cached.searchText) normalized.searchText = String(cached.searchText || '').slice(0, 4000);
      if (Number(cached.firstSeenAt || 0) > 0) normalized.firstSeenAt = Number(cached.firstSeenAt || 0);
      if (Number(cached.newCustomerAt || 0) > 0) normalized.newCustomerAt = Number(cached.newCustomerAt || 0);
      else if (!normalized.newCustomerAt) normalized.newCustomerAt = 1;
    } else if (!normalized.newCustomerAt) {
      normalized.newCustomerAt = leadBaselineEstablished ? inferNewLineCustomerAt(accountId, normalized) : 1;
    }
    // Repair previously persisted false positives: if the alleged acquisition
    // date cannot be corroborated by the real first-message day, keep the row
    // as historical instead of inflating today's new-customer KPI.
    if (Number(normalized.newCustomerAt || 0) > 1 && !reliableLeadArrivalAt(normalized)) {
      normalized.newCustomerAt = 1;
    }
    if (!normalized.firstSeenAt && normalized.hasConversation !== false) {
      normalized.firstSeenAt = normalized.firstMessageAt || normalized.timestamp || 0;
    }
    if (normalized.avatarDataUrl) rememberAggregateCustomerAvatar(accountId, normalized);
    hydrateAggregateCustomerAvatar(accountId, normalized);
    const previous = byId.get(normalized.chatId);
    if (!previous || normalized.timestamp >= previous.timestamp) byId.set(normalized.chatId, normalized);
  }
  let conversations = [...byId.values()]
    .sort((a, b) => b.timestamp - a.timestamp || b.unreadCount - a.unreadCount)
    .slice(0, AGGREGATE_MAX_CONVERSATIONS_PER_ACCOUNT);

  // V1.23.12 stability guard: LINE's Redux bridge can briefly be readable while
  // messageBox/contact hydration is still empty during mode changes or renderer
  // bootstrap. Never let one such zero-row snapshot erase a previously valid
  // aggregate inbox. A later non-empty live snapshot replaces it normally.
  // payload.rawCandidateCount/listedCount/contactCount are emitted by the preload
  // for diagnostics, but older payloads are protected too when they are empty.
  const previousRows = Array.isArray(previousRecord?.conversations) ? previousRecord.conversations : [];
  const rawCandidateCount = Math.max(0, Number(payload?.rawCandidateCount || 0) || 0);
  const listedCount = Math.max(0, Number(payload?.listedCount || 0) || 0);
  const contactCount = Math.max(0, Number(payload?.contactCount || 0) || 0);
  const hasSnapshotDiagnostics = !!(payload && Object.prototype.hasOwnProperty.call(payload, 'rawCandidateCount'));
  const transientEmpty = conversations.length === 0 && previousRows.length > 0 &&
    (payload?.ready !== false) && (!hasSnapshotDiagnostics || rawCandidateCount === 0);
  if (transientEmpty) {
    conversations = previousRows.map(item => hydrateAggregateCustomerAvatar(accountId, { ...item }));
  }

  const record = {
    updatedAt: String(payload?.updatedAt || new Date().toISOString()),
    // A disk-loaded legacy cache stays un-baselined until one live snapshot has
    // completed. New-format caches preserve the marker across restarts.
    leadBaselineEstablished: fromDisk
      ? payload?.leadBaselineEstablished === true
      : (leadBaselineEstablished || !transientEmpty),
    conversations
  };
  aggregateConversationCache.set(accountId, record);

  // V1.15.28: as soon as a live snapshot reveals missing customer photos, ask
  // the owning authenticated LINE renderer to repair exactly those MIDs. This
  // runs in the background and never blocks aggregate switching.
  if (runtime.has(accountId) && getAccount(accountId)?.isOpen !== false) {
    const missingAvatarMids = conversations
      .filter(item =>
        String(item?.type || '') === 'contact' &&
        isCanonicalLineMid(item?.chatId) &&
        !String(item?.avatarLocalUrl || '').trim() &&
        !normalizeAvatarDataUrl(item?.avatarDataUrl || '')
      )
      .map(item => String(item.chatId || '').trim())
      .slice(0, 120);
    const now = Date.now();
    const lastSweep = Number(aggregateAvatarRecoveryAt.get(accountId) || 0);
    if (missingAvatarMids.length && now - lastSweep > 6000) {
      aggregateAvatarRecoveryAt.set(accountId, now);
      setTimeout(() => {
        callLineBridgeForAccount(
          accountId,
          'refreshAggregateAvatars',
          missingAvatarMids.length,
          { force: false, mids: missingAvatarMids }
        ).catch(() => {});
      }, 180);
    }
  }

  if (persist) scheduleAggregateCacheSave();
  if (emit) sendUI('aggregate-updated', publicAggregateInbox());
  return record;
}

function loadAggregateCache() {
  aggregateConversationCache.clear();
  try {
    const file = aggregateCachePath();
    const raw = readJsonWithBackup(file);
    if (!raw) return;
    const accounts = raw?.accounts && typeof raw.accounts === 'object' ? raw.accounts : {};
    for (const [accountId, record] of Object.entries(accounts)) {
      if (!getAccount(accountId)) continue;
      setAggregateSnapshot(accountId, record || {}, { persist: false, emit: false, fromDisk: true });
    }
  } catch (error) {
    console.debug('[Yoko aggregate cache load skipped]', error?.message || error);
  }
}

function saveAggregateCache() {
  try {
    const accounts = {};
    for (const [accountId, record] of aggregateConversationCache.entries()) {
      if (!getAccount(accountId)) continue;
      accounts[accountId] = {
        ...record,
        conversations: Array.isArray(record?.conversations)
          ? record.conversations.map(item => ({ ...item, avatarDataUrl: '', avatarLocalUrl: '' }))
          : []
      };
    }
    atomicWriteJson(
      aggregateCachePath(),
      { version: 1, updatedAt: new Date().toISOString(), accounts },
      { keepBackup: true }
    );
  } catch (error) {
    console.debug('[Yoko aggregate cache save skipped]', error?.message || error);
  }
}

function scheduleAggregateCacheSave() {
  if (aggregateCacheSaveTimer) clearTimeout(aggregateCacheSaveTimer);
  aggregateCacheSaveTimer = setTimeout(() => {
    aggregateCacheSaveTimer = null;
    saveAggregateCache();
  }, 500);
}

function aggregateTimestampMs(value) {
  let number = Number(value || 0) || 0;
  if (number > 0 && number < 1e12) number *= 1000;
  return number;
}

// V1.23.54: "今日新进" must describe a customer's real first conversation date,
// not the day Yoko happened to discover an old row after Redux/virtual-list hydration.
// Be deliberately conservative: ambiguous rows are historical rather than false-positive leads.
function isSameLocalCalendarDay(a, b) {
  const aa = aggregateTimestampMs(a);
  const bb = aggregateTimestampMs(b);
  if (!aa || !bb) return false;
  const da = new Date(aa);
  const db = new Date(bb);
  return da.getFullYear() === db.getFullYear() && da.getMonth() === db.getMonth() && da.getDate() === db.getDate();
}

function reliableLeadArrivalAt(raw = {}) {
  const leadAt = aggregateTimestampMs(raw?.newCustomerAt);
  if (!leadAt || leadAt <= 1) return 0;
  const firstMessageAt = aggregateTimestampMs(raw?.firstMessageAt);
  // A persisted lead marker is only trusted when LINE can corroborate that the
  // customer's first known message belongs to the same calendar day. This also
  // repairs V1.23.53-era false positives already saved as Date.now().
  if (!firstMessageAt || !isSameLocalCalendarDay(leadAt, firstMessageAt)) return 0;
  return leadAt;
}

// V1.23.57: non-LINE platforms establish a persisted inbox baseline before
// tracking acquisition. Existing rows are written with newCustomerAt=1; only a
// conversation first appearing after that baseline receives a real timestamp.
// Unlike LINE, external web inboxes usually do not expose the thread's true
// first-message timestamp, so the baseline delta itself is the trustworthy
// acquisition signal. Never promote baseline/history rows into the lead funnel.
function reliableExternalLeadArrivalAt(raw = {}) {
  const rawLeadAt = Number(raw?.newCustomerAt || 0) || 0;
  // Sentinel 1 means historical baseline. Check before second->millisecond
  // normalization so it can never become a fake 1970 timestamp.
  if (!rawLeadAt || rawLeadAt <= 1) return 0;
  const leadAt = aggregateTimestampMs(rawLeadAt);
  const now = Date.now();
  if (leadAt > now + 60000) return 0;
  return leadAt;
}

function inferNewLineCustomerAt(accountId, raw = {}) {
  const explicit = aggregateTimestampMs(raw?.newCustomerAt);
  if (explicit > 1 && reliableLeadArrivalAt(raw)) return explicit;
  const firstMessageAt = aggregateTimestampMs(raw?.firstMessageAt);
  if (!firstMessageAt) return 1;
  const now = Date.now();
  if (!isSameLocalCalendarDay(firstMessageAt, now)) return 1;
  // An existing CRM record proves this is not a newly acquired customer even if
  // LINE only hydrated today's most recent message entities.
  try {
    const match = getCrmContactForConversation(String(accountId || ''), String(raw?.chatId || ''), String(raw?.displayName || ''));
    if (match?.contact) return 1;
  } catch {}
  return firstMessageAt;
}

// V1.27.276: customer-day calibration is a CRM/operator display concept, not the
// retired GPT Day 1-10 automation.  A manual choice rebases only today's
// customer-day number; 05:00 JST remains authoritative afterwards and advances
// the number automatically on following operational days.
function ensureCustomerDayCalibrations() {
  if (!config.customerDayCalibrations || typeof config.customerDayCalibrations !== 'object' || Array.isArray(config.customerDayCalibrations)) {
    config.customerDayCalibrations = {};
  }
  return config.customerDayCalibrations;
}
function customerDayCalibrationKey(platform = '', accountId = '', chatId = '', displayName = '') {
  const p = String(platform || '').trim().toLowerCase();
  const account = String(accountId || '').trim();
  const chat = String(chatId || '').trim();
  const name = String(displayName || '').trim();
  if (!p || !account || (!chat && !name)) return '';
  const identity = chat ? `chat:${chat}` : `name:${name.toLocaleLowerCase()}`;
  return crypto.createHash('sha256').update(`${p}\u001f${account}\u001f${identity}`).digest('hex');
}
function customerDayCalibrationFor(platform = '', accountId = '', chatId = '', displayName = '') {
  const key = customerDayCalibrationKey(platform, accountId, chatId, displayName);
  if (!key) return null;
  const row = ensureCustomerDayCalibrations()[key];
  return row && typeof row === 'object' ? { ...row, key } : null;
}
function customerDayCalibratedLifecycle(platform = '', accountId = '', raw = {}, now = Date.now()) {
  const calibration = customerDayCalibrationFor(platform, accountId, raw?.chatId, raw?.displayName);
  const state = customerDayStateFromCalibration(calibration, now);
  if (!state) return null;
  return {
    arrivalAt: lineLifecycleArrivalAt(raw),
    businessDateKey: '',
    day: state.day,
    rawDay: state.rawDay,
    group: state.group,
    label: state.label,
    calibrated: true,
    calibration: calibration ? {
      selectedDay:Number(calibration.selectedDay||0)||0,
      anchorOrdinal:Number(calibration.anchorOrdinal),
      calibratedAt:Number(calibration.calibratedAt||0)||0,
      source:String(calibration.source||'operator')
    } : null
  };
}
function customerDayPublicState(platform = '', accountId = '', raw = {}, now = Date.now()) {
  const calibrated = customerDayCalibratedLifecycle(platform, accountId, raw, now);
  const automatic = lineLifecycleStateFromArrival(lineLifecycleArrivalAt(raw), now);
  const state = calibrated || automatic;
  return {
    ok:true,
    platform:String(platform||'').toLowerCase(),
    accountId:String(accountId||''),
    chatId:String(raw?.chatId||''),
    displayName:String(raw?.displayName||''),
    day:Math.max(0,Number(state?.day||0)||0),
    rawDay:Math.max(0,Number(state?.rawDay||state?.day||0)||0),
    group:String(state?.group||''),
    label:String(state?.label||'未归类'),
    calibrated:!!state?.calibrated,
    calibration:state?.calibration||null,
    boundaryHourJst:5
  };
}
function setCustomerDayCalibration({ platform = '', accountId = '', chatId = '', displayName = '', day = 0 } = {}, now = Date.now()) {
  const p = String(platform || '').trim().toLowerCase();
  const account = String(accountId || '').trim();
  const chat = String(chatId || '').trim();
  const name = String(displayName || '').trim();
  const selectedDay = Math.max(0, Math.min(10, Number(day || 0) || 0));
  const key = customerDayCalibrationKey(p, account, chat, name);
  if (!key) return { ok:false, error:'客户身份为空，无法校准天数。' };
  const registry = ensureCustomerDayCalibrations();
  if (!selectedDay) {
    delete registry[key];
    saveConfig(config);
    return { ok:true, cleared:true, state:customerDayPublicState(p, account, {chatId:chat,displayName:name}, now) };
  }
  const anchorOrdinal = customerDayBusinessOrdinalJst(now);
  if (!Number.isFinite(anchorOrdinal)) return { ok:false, error:'无法计算日本时间业务日。' };
  registry[key] = {
    platform:p,
    accountId:account,
    chatId:chat,
    displayName:name,
    selectedDay,
    anchorOrdinal,
    calibratedAt:Number(now)||Date.now(),
    source:'operator-v127276'
  };
  saveConfig(config);
  return { ok:true, cleared:false, calibration:{...registry[key]}, state:customerDayPublicState(p, account, {chatId:chat,displayName:name}, now) };
}

// V1.27.206: LINE customer lifecycle grouping is independent from Official API and GPT bindings.
function lineLifecycleArrivalAt(raw={}) {
  const reliable=reliableLeadArrivalAt(raw);
  if(reliable>1)return reliable;
  const firstMessageAt=aggregateTimestampMs(raw?.firstMessageAt);
  if(firstMessageAt>1)return firstMessageAt;
  const firstSeenAt=aggregateTimestampMs(raw?.firstSeenAt);
  if(firstSeenAt>1)return firstSeenAt;
  const explicit=aggregateTimestampMs(raw?.newCustomerAt);
  return explicit>1?explicit:0;
}
function lineLifecycleState(raw={},now=Date.now(),accountId='') {
  return customerDayCalibratedLifecycle('line',accountId,raw,now) || lineLifecycleStateFromArrival(lineLifecycleArrivalAt(raw),now);
}

function isAggregateCustomerActive(conversation = {}, now = Date.now()) {
  // Unread always wins: an actionable new customer message must never be hidden.
  if ((Number(conversation?.unreadCount || 0) || 0) > 0) return true;

  // The user's rule is specifically based on CUSTOMER activity, not on our own
  // follow-up. Prefer the cached newest incoming timestamp. If LINE has not yet
  // supplied one, only a latest message explicitly identified as customer-side
  // may stand in for it. Our own recent reply must never keep a silent customer
  // visible for another 72 hours.
  let incoming = aggregateTimestampMs(conversation?.lastIncomingAt);
  if (!incoming && String(conversation?.lastDirection || '') === 'customer') {
    incoming = aggregateTimestampMs(conversation?.timestamp);
  }
  if (!incoming) return false;
  return now - incoming <= AGGREGATE_ACTIVE_CUSTOMER_WINDOW_MS;
}

function lineAggregateDuplicateIdentity(item = {}) {
  const chatId = String(item?.chatId || '').trim().toLowerCase();
  if (isCanonicalLineMid(chatId)) return `line:mid:${chatId}`;
  const name = String(item?.displayName || '').trim().toLowerCase();
  const avatarUrl = String(item?.avatarUrl || '').split('?')[0].trim().toLowerCase();
  if (avatarUrl && name) return `line:avatar-name:${avatarUrl}\u001f${name}`;
  const avatarDataUrl = normalizeAvatarDataUrl(item?.avatarDataUrl || '');
  if (avatarDataUrl && name) {
    try {
      const hash = crypto.createHash('sha1').update(avatarDataUrl).digest('hex');
      return `line:avatar-data:${hash}\u001f${name}`;
    } catch {}
  }
  return '';
}

function annotateLineAggregateDuplicateCustomers(conversations = []) {
  const groups = new Map();
  for (const item of conversations) {
    const identity = lineAggregateDuplicateIdentity(item);
    if (!identity) continue;
    if (!groups.has(identity)) groups.set(identity, []);
    groups.get(identity).push(item);
  }
  for (const [identity, rows] of groups.entries()) {
    const accountIds = [...new Set(rows.map(row => String(row.accountId || '')).filter(Boolean))];
    if (accountIds.length < 2) continue;
    const accountNames = [...new Set(rows.map(row => String(row.accountRemark || row.accountName || '')).filter(Boolean))];
    for (const row of rows) {
      row.duplicate = true;
      row.duplicateKey = identity;
      row.duplicateCount = accountIds.length;
      row.duplicateAccountIds = accountIds;
      row.duplicateAccounts = accountNames;
    }
  }
  return conversations;
}

function publicAggregateInbox() {
  const items = [];
  const accounts = [];
  const seenConversationKeys = new Set();
  const now = Date.now();
  // LINE "今日新进粉" uses the operator's 05:00 business-day boundary.
  const todayStartMs = lineLifecycleBusinessStartAt(now);

  for (const account of config.accounts || []) {
    const record = aggregateConversationCache.get(account.id) || { updatedAt: '', conversations: [] };
    const overview = accountOverview(account.id);
    const accountName = String(overview.displayName || account.lineProfile?.displayName || account.name || 'LINE');
    const accountRemark = String(account.remark || account.name || '').trim();
    const isOpen = account.isOpen !== false;
    // V1.23.12: Aggregate Mode is the complete personal-customer inbox, not a
    // hidden 72-hour window. The renderer already provides All/Unread/Read,
    // search, account and recent-customer controls, so dropping older personal
    // chats here made a healthy LINE account look completely broken whenever no
    // customer had written in the last three days. Keep every sanitized personal
    // customer in the public inbox; recency remains a metric, not a visibility gate.
    const allPersonalConversations = Array.isArray(record.conversations) ? record.conversations : [];
    const totalUnread = allPersonalConversations.reduce((sum, item) => sum + (Number(item.unreadCount) || 0), 0);
    let unreadConversationCount = 0;
    let waitingCount = 0;
    let todayNewCustomerCount = 0;
    let latestIncomingAt = 0;

    const hydratedRows = [];
    let recentActiveCustomerCount = 0;
    for (const conversation of allPersonalConversations) {
      const hydratedConversation = hydrateAggregateCustomerAvatar(account.id, { ...conversation });
      const uniqueKey = `${account.id}::${hydratedConversation.chatId}`;
      if (seenConversationKeys.has(uniqueKey)) continue;
      seenConversationKeys.add(uniqueKey);

      const crmMatch = getCrmContactForConversation(account.id, hydratedConversation.chatId, hydratedConversation.displayName);
      const crmProfile = crmContactSummary(crmMatch.contact);
      const effectiveUnread = Math.max(0, Number(hydratedConversation.unreadCount || 0) || 0);
      if (effectiveUnread > 0) unreadConversationCount += 1;
      if (isAggregateCustomerActive(hydratedConversation, now)) recentActiveCustomerCount += 1;
      const serviceStatus = String(crmProfile?.serviceStatus || 'auto');
      const autoWaiting = serviceStatus === 'auto' && hydratedConversation.hasConversation !== false &&
        String(hydratedConversation.lastDirection || '') === 'customer' &&
        Math.max(aggregateTimestampMs(hydratedConversation.lastIncomingAt), aggregateTimestampMs(hydratedConversation.timestamp)) > 0;
      if (serviceStatus === 'waiting' || autoWaiting) waitingCount += 1;
      const leadAt = reliableLeadArrivalAt(hydratedConversation);
      if (leadAt >= todayStartMs && leadAt <= now + 60000) todayNewCustomerCount += 1;
      latestIncomingAt = Math.max(latestIncomingAt, aggregateTimestampMs(hydratedConversation.lastIncomingAt));
      const lifecycleBlocked = lineCrmBlacklisted(crmProfile);
      const lifecycle = lineLifecycleState(hydratedConversation, now, account.id);

      hydratedRows.push({
        ...hydratedConversation,
        lineLifecycleArrivalAt:lifecycle.arrivalAt,
        lineLifecycleBusinessDateKey:lifecycle.businessDateKey,
        lineLifecycleDay:lifecycleBlocked ? 0 : lifecycle.day,
        lineLifecycleRawDay:lifecycleBlocked ? 0 : Number(lifecycle.rawDay || lifecycle.day || 0),
        lineLifecycleGroup:lifecycleBlocked ? '' : lifecycle.group,
        lineLifecycleLabel:lifecycleBlocked ? '黑名单' : lifecycle.label,
        lineLifecycleBlocked:lifecycleBlocked,
        accountId: account.id,
        accountName,
        accountRemark,
        accountIsOpen: isOpen,
        accountOnline: overview.online === true,
        accountAvatarDataUrl: overview.avatarDataUrl || '',
        snapshotUpdatedAt: record.updatedAt || '',
        crmProfile
      });
    }

    accounts.push({
      accountId: account.id,
      accountName,
      accountRemark,
      isOpen,
      online: overview.online === true,
      unreadCount: totalUnread,
      unreadConversationCount,
      // Kept for renderer/backward compatibility: from V1.23.12 this means
      // total visible personal customers. recentActiveCustomerCount is the old
      // 72-hour activity metric for diagnostics/operations only.
      activeCustomerCount: hydratedRows.length,
      recentActiveCustomerCount,
      waitingCount,
      todayNewCustomerCount,
      latestIncomingAt,
      updatedAt: record.updatedAt || '',
      avatarDataUrl: overview.avatarDataUrl || ''
    });
    items.push(...hydratedRows);
  }
  annotateLineAggregateDuplicateCustomers(items);
  const duplicateGroups = new Set();
  const accountDuplicateGroups = new Map();
  for (const item of items) {
    if (!item?.duplicate) continue;
    const identity = String(item.duplicateKey || lineAggregateDuplicateIdentity(item) || '');
    if (!identity) continue;
    duplicateGroups.add(identity);
    const accountId = String(item.accountId || '');
    if (!accountDuplicateGroups.has(accountId)) accountDuplicateGroups.set(accountId, new Set());
    accountDuplicateGroups.get(accountId).add(identity);
  }
  for (const account of accounts) {
    account.duplicateCustomerCount = accountDuplicateGroups.get(String(account.accountId || ''))?.size || 0;
  }

  items.sort((a, b) => b.timestamp - a.timestamp || b.unreadCount - a.unreadCount);
  return {
    generatedAt: new Date().toISOString(),
    accounts,
    conversations: items,
    unreadCount: items.reduce((sum, item) => sum + (Number(item.unreadCount) || 0), 0),
    todayNewCustomerCount: accounts.reduce((sum, account) => sum + Math.max(0, Number(account.todayNewCustomerCount || 0) || 0), 0),
    duplicateCustomerCount: duplicateGroups.size
  };
}

function removeAggregateCacheRecord(accountId) {
  aggregateConversationCache.delete(String(accountId || ''));
  scheduleAggregateCacheSave();
  sendUI('aggregate-updated', publicAggregateInbox());
}

function avatarCacheDir() {
  const p = path.join(userDataRoot(), 'avatar-cache');
  fs.mkdirSync(p, { recursive: true });
  return p;
}

function avatarCacheFile(accountId) {
  const key = crypto.createHash('sha256').update(String(accountId || '')).digest('hex');
  return path.join(avatarCacheDir(), `${key}.json`);
}

function normalizeAvatarDataUrl(value) {
  const dataUrl = String(value || '').trim();
  if (!dataUrl || dataUrl.length > AVATAR_DATA_URL_MAX_LENGTH) return '';
  if (!/^data:image\/[a-z0-9.+-]+;base64,/i.test(dataUrl)) return '';
  return dataUrl;
}

function readAvatarCacheRecord(accountId, { force = false } = {}) {
  accountId = String(accountId || '').trim();
  if (!accountId) return null;
  if (!force && accountAvatarCache.has(accountId)) return accountAvatarCache.get(accountId);

  const file = avatarCacheFile(accountId);
  const candidates = [file, `${file}.bak`];
  for (const candidate of candidates) {
    try {
      if (!fs.existsSync(candidate)) continue;
      const raw = JSON.parse(fs.readFileSync(candidate, 'utf8'));
      const avatarDataUrl = normalizeAvatarDataUrl(raw?.avatarDataUrl);
      if (!avatarDataUrl) continue;
      const record = {
        avatarDataUrl,
        pictureUrl: String(raw?.pictureUrl || ''),
        updatedAt: String(raw?.updatedAt || '')
      };
      accountAvatarCache.set(accountId, record);
      return record;
    } catch {}
  }
  accountAvatarCache.delete(accountId);
  return null;
}

function writeAvatarCacheRecord(accountId, avatarDataUrl, pictureUrl = '') {
  accountId = String(accountId || '').trim();
  avatarDataUrl = normalizeAvatarDataUrl(avatarDataUrl);
  if (!accountId || !avatarDataUrl) return false;

  const previous = accountAvatarCache.get(accountId) || readAvatarCacheRecord(accountId) || {};
  const next = {
    avatarDataUrl,
    pictureUrl: String(pictureUrl || previous.pictureUrl || ''),
    updatedAt: new Date().toISOString()
  };
  accountAvatarCache.set(accountId, next);

  try {
    const file = avatarCacheFile(accountId);
    const tmp = `${file}.${process.pid}.tmp`;
    const bak = `${file}.bak`;
    fs.writeFileSync(tmp, JSON.stringify({ version: 1, ...next }), 'utf8');
    try {
      if (fs.existsSync(file)) fs.copyFileSync(file, bak);
    } catch {}
    try { fs.rmSync(file, { force: true }); } catch {}
    fs.renameSync(tmp, file);
    try { fs.rmSync(bak, { force: true }); } catch {}
    return true;
  } catch (error) {
    console.debug('[Yoko avatar cache write skipped]', error?.message || error);
    return false;
  }
}

function removeAvatarCacheRecord(accountId) {
  accountId = String(accountId || '').trim();
  if (!accountId) return;
  accountAvatarCache.delete(accountId);
  try {
    const file = avatarCacheFile(accountId);
    fs.rmSync(file, { force: true });
    fs.rmSync(`${file}.bak`, { force: true });
  } catch {}
}

function hydrateAccountAvatarCache(account) {
  if (!account?.id) return false;
  account.lineProfile = account.lineProfile || {};
  const inline = normalizeAvatarDataUrl(account.lineProfile.avatarDataUrl);
  if (inline) {
    writeAvatarCacheRecord(account.id, inline, account.lineProfile.pictureUrl);
    return true;
  }
  const cached = readAvatarCacheRecord(account.id);
  if (!cached?.avatarDataUrl) return false;
  account.lineProfile.avatarDataUrl = cached.avatarDataUrl;
  if (!String(account.lineProfile.pictureUrl || '').trim() && cached.pictureUrl) {
    account.lineProfile.pictureUrl = cached.pictureUrl;
  }
  return true;
}

// V1.27.253: provider-result cache is a true LRU instead of an ever-growing
// insertion-order Map. This is insert-driven only (no new periodic cleanup task).
const TRANSLATION_CACHE_LRU_MAX = 12000;
const TRANSLATION_CACHE_LRU_RETAIN = 11000;
class TranslationLruMap extends Map {
  get(key) {
    if (!super.has(key)) return undefined;
    const value=super.get(key);
    super.delete(key);
    super.set(key,value);
    return value;
  }
  set(key,value) {
    if (super.has(key)) super.delete(key);
    super.set(key,value);
    if (this.size > TRANSLATION_CACHE_LRU_MAX) {
      let drop=Math.max(0,this.size-TRANSLATION_CACHE_LRU_RETAIN);
      for (const oldest of this.keys()) {
        super.delete(oldest);
        if (--drop <= 0) break;
      }
    }
    return this;
  }
}
let translationCache = new TranslationLruMap();
let translationDisplayCache = new Map();
// V1.27.280: durable, local-only GPT usage counters. Never record source text or credentials.
const gptTranslationStats = { apiCalls:0, cacheHits:0, lastApiAt:'' };
const pendingGptTranslations = new Map();
function gptTranslationCacheSettings(settings={}) {
  return { ...settings, engine:'openai', aiContextMessages:0 };
}
function gptTranslationCacheKey(text,source,target,settings={}) {
  return translationCacheDescriptor(text,source,target,[],gptTranslationCacheSettings(settings)).cacheKey;
}
function gptCachedTranslation(text,source,target,settings={}) {
  if (settings.cacheEnabled === false) return '';
  const key=gptTranslationCacheKey(text,source,target,settings);
  const value=String(translationCache.get(key)||'').trim();
  if (!value || (value===String(text).trim() && !sameTranslationLanguage(source,target,text))) return '';
  gptTranslationStats.cacheHits += 1;
  saveTranslationCache();
  return value;
}
function gptTranslationCacheSnapshot() {
  return { ...gptTranslationStats, entries:[...translationCache.keys()].filter(k=>typeof k==='string').length, model:String(config?.translation?.openaiTranslationModel||'gpt-6-luna') };
}
// V1.27.169 — visible translations stay highly durable, but an actually
// unbounded Map eventually turns months of desktop usage into RAM + JSON
// serialization debt. 50k keeps a very large working history while providing
// a hard ceiling; prune in chunks so normal inserts remain O(1).
const TRANSLATION_DISPLAY_CACHE_MAX = 50000;
const TRANSLATION_DISPLAY_CACHE_RETAIN = 45000;
function trimTranslationDisplayCacheIfNeeded() {
  if (translationDisplayCache.size <= TRANSLATION_DISPLAY_CACHE_MAX) return false;
  let drop = Math.max(0, translationDisplayCache.size - TRANSLATION_DISPLAY_CACHE_RETAIN);
  for (const key of translationDisplayCache.keys()) {
    translationDisplayCache.delete(key);
    if (--drop <= 0) break;
  }
  return true;
}

function loadTranslationCache() {
  try {
    const p = translationCachePath();
    const raw = readJsonWithBackup(p);
    if (!raw) return;
    const entries = Array.isArray(raw?.entries) ? raw.entries : [];
    const renderEntries = Array.isArray(raw?.renderEntries) ? raw.renderEntries : [];
    translationCache = new TranslationLruMap(entries.filter(x => Array.isArray(x) && x.length === 2).slice(-TRANSLATION_CACHE_LRU_MAX));
    translationDisplayCache = new Map(renderEntries.filter(x => Array.isArray(x) && x.length === 2));
    trimTranslationDisplayCacheIfNeeded();
    for (const name of ['apiCalls','cacheHits']) gptTranslationStats[name]=Math.max(0,Number(raw?.gptStats?.[name])||0);
    gptTranslationStats.lastApiAt=String(raw?.gptStats?.lastApiAt||'');
  } catch {
    translationCache = new TranslationLruMap();
    translationDisplayCache = new Map();
  }
}

let translationCacheSaveTimer = null;

function flushTranslationCache() {
  if (translationCacheSaveTimer) {
    clearTimeout(translationCacheSaveTimer);
    translationCacheSaveTimer = null;
  }
  try {
    const entries = [...translationCache.entries()];
    const trimmed = entries.slice(Math.max(0, entries.length - 12000));
    translationCache = new TranslationLruMap(trimmed);
    // V1.27.169: keep display translations durable but bounded for long-running
    // desktop installations. Pruning only happens past 50k entries.
    trimTranslationDisplayCacheIfNeeded();
    const renderEntries=[...translationDisplayCache.entries()];
    translationDisplayCache=new Map(renderEntries);
    atomicWriteJson(
      translationCachePath(),
      { version: 4, entries: trimmed, renderEntries, gptStats:gptTranslationStats },
      { keepBackup: true }
    );
  } catch {}
}

function saveTranslationCache() {
  // V1.27.71: provider/cache hits can arrive in bursts. Coalesce disk writes so
  // Electron's main thread never blocks the Meta renderer once per bubble.
  if (translationCacheSaveTimer) return;
  translationCacheSaveTimer = setTimeout(() => {
    translationCacheSaveTimer = null;
    flushTranslationCache();
  }, 180);
}

function translationCacheKey(engine, source, target, text) {
  return crypto
    .createHash('sha256')
    .update([engine, source, target, text].join('\u001f'))
    .digest('hex');
}

function translationDisplayCacheKey(source, target, text) {
  const stable=String(text||'').replace(/\s+/g,' ').trim();
  return crypto.createHash('sha256').update(['render-v1',String(source||'auto'),String(target||'zh'),stable].join('\u001f')).digest('hex');
}
function rememberTranslationDisplayCache(text, source, target, translated) {
  const original=String(text||'').trim(), value=String(translated||'').trim();
  if(!original||!value||value===original)return false;
  translationDisplayCache.set(translationDisplayCacheKey(source,target,original),value);
  trimTranslationDisplayCacheIfNeeded();
  return true;
}

function translationCacheDescriptor(text, source='auto', target='zh', context=[], settings=null) {
  const t = settings || config.translation || {};
  const engine = String(t.engine || 'none');
  const aiContextForCache = isAiProvider(engine) && engine !== 'openai'
    ? sanitizeAiContext(Array.isArray(context) ? context : [], Number(t.aiContextMessages ?? 4))
        .map(item => `${item.role}:${item.text}`)
        .join('\n')
    : '';
  const cacheEngine = isAiProvider(engine)
    ? (engine === 'ollama' && normalizeOllamaModelMode(t.ollamaModelMode) !== 'fixed'
        ? `ollama:auto-balanced:${OLLAMA_AUTO_ROUTER_VERSION}:${AI_TRANSLATION_PROMPT_VERSION}`
        : `${engine === 'ai' ? 'openai' : engine}:${aiProviderModel(engine, t)}:${AI_TRANSLATION_PROMPT_VERSION}`)
    : engine;
  const cacheText = isAiProvider(engine) ? `${text}\u001e${aiContextForCache}` : text;
  return { engine, cacheEngine, cacheText, cacheKey:translationCacheKey(cacheEngine, source, target, cacheText) };
}

function vaultDir() {
  const p = path.join(userDataRoot(), 'secure-store');
  fs.mkdirSync(p, { recursive: true });
  return p;
}


function speechLibraryAssetsDir() {
  const dir = path.join(userDataRoot(), 'speech-library-assets');
  try { fs.mkdirSync(dir, { recursive:true }); } catch {}
  return dir;
}
function speechLibraryAssetUrl(fileName = '') {
  const safe = path.basename(String(fileName || ''));
  return safe ? `yoko-speech://asset/${encodeURIComponent(safe)}` : '';
}
function registerYokoSpeechProtocol() {
  try {
    protocol.registerFileProtocol('yoko-speech', (request, callback) => {
      try {
        const parsed = new URL(String(request?.url || ''));
        if (String(parsed.hostname || '').toLowerCase() !== 'asset') return callback({error:-6});
        const fileName = path.basename(decodeURIComponent(String(parsed.pathname || '').replace(/^\/+/,'')));
        if (!/^[a-f0-9]{64}\.(?:jpg|jpeg|png|webp|gif|bmp)$/i.test(fileName)) return callback({error:-6});
        const root = path.resolve(speechLibraryAssetsDir()) + path.sep;
        const resolved = path.resolve(path.join(speechLibraryAssetsDir(), fileName));
        if (!resolved.startsWith(root) || !fs.existsSync(resolved) || fs.statSync(resolved).size <= 0) return callback({error:-6});
        callback({path:resolved});
      } catch { callback({error:-2}); }
    });
  } catch (error) { console.debug('[Yoko speech asset protocol skipped]', error?.message || error); }
}
function normalizeSpeechLibraryImage(raw = {}) {
  const fileName = path.basename(String(raw?.fileName || '').trim());
  if (!/^[a-f0-9]{64}\.(?:jpg|jpeg|png|webp|gif|bmp)$/i.test(fileName)) return null;
  return { id:String(raw?.id || `image-${crypto.randomUUID()}`).slice(0,100), fileName, originalName:String(raw?.originalName || fileName).slice(0,240), size:Math.max(0,Number(raw?.size||0)||0), url:speechLibraryAssetUrl(fileName) };
}
function importSpeechLibraryImages(filePaths = []) {
  const out=[];
  for (const input of Array.isArray(filePaths)?filePaths:[]) {
    const source=String(input||''); const ext=path.extname(source).replace(/^\./,'').toLowerCase();
    if(!['jpg','jpeg','png','webp','gif','bmp'].includes(ext)) continue;
    let data=null; try{data=fs.readFileSync(source)}catch{continue}
    if(!data?.length || data.length>24*1024*1024) continue;
    const hash=crypto.createHash('sha256').update(data).digest('hex');
    const normalizedExt=ext==='jpeg'?'jpg':ext; const fileName=`${hash}.${normalizedExt}`; const dst=path.join(speechLibraryAssetsDir(),fileName);
    try{if(!fs.existsSync(dst))fs.writeFileSync(dst,data)}catch{continue}
    out.push({id:`image-${crypto.randomUUID()}`,fileName,originalName:path.basename(source).slice(0,240),size:data.length,url:speechLibraryAssetUrl(fileName)});
  }
  return out;
}

function cleanupSpeechLibraryAssets(library = {}) {
  const used = new Set();
  for (const group of Array.isArray(library?.groups) ? library.groups : []) {
    for (const item of Array.isArray(group?.items) ? group.items : []) {
      for (const raw of Array.isArray(item?.images) ? item.images : []) {
        const image = normalizeSpeechLibraryImage(raw);
        if (image?.fileName) used.add(image.fileName);
      }
    }
  }
  try {
    for (const name of fs.readdirSync(speechLibraryAssetsDir())) {
      if (!/^[a-f0-9]{64}\.(?:jpg|jpeg|png|webp|gif|bmp)$/i.test(name)) continue;
      if (used.has(name)) continue;
      try { fs.unlinkSync(path.join(speechLibraryAssetsDir(), name)); } catch {}
    }
  } catch {}
}

function defaultSpeechLibrary() {
  return {
    version: 2,
    groups: [
      { id: 'day-1', title: '第一天', items: [] }
    ]
  };
}

function speechLibrarySubjectFromText(text = '', index = 0) {
  const line = String(text || '').split(/\r?\n/).map(value => value.trim()).find(Boolean) || '';
  const cleaned = line.replace(/\{\{?\s*(?:称呼|名字|name)\s*\}?\}/gi, '').trim();
  return cleaned.slice(0, 28) || `话术 ${index + 1}`;
}

function normalizeSpeechLibrary(raw = {}) {
  const inputGroups = Array.isArray(raw?.groups) ? raw.groups : [];
  const groups = [];
  const usedGroupIds = new Set();
  const makeId = (prefix, wanted = '') => {
    let id = String(wanted || '').trim().replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
    if (!id || usedGroupIds.has(id)) id = `${prefix}-${crypto.randomUUID()}`;
    usedGroupIds.add(id);
    return id;
  };
  for (let gi = 0; gi < inputGroups.length && groups.length < 80; gi += 1) {
    const group = inputGroups[gi] || {};
    const title = String(group.title || '').replace(/\s+/g, ' ').trim().slice(0, 80) || `第${groups.length + 1}天`;
    const groupId = makeId('group', group.id);
    const usedItemIds = new Set();
    const items = [];
    const rows = Array.isArray(group.items) ? group.items : [];
    for (let itemIndex = 0; itemIndex < rows.length; itemIndex += 1) {
      const row = rows[itemIndex];
      const text = String(row?.text ?? (typeof row === 'string' ? row : '')).replace(/\r\n/g, '\n').trim().slice(0, 12000);
      const images = (Array.isArray(row?.images) ? row.images : []).map(normalizeSpeechLibraryImage).filter(Boolean).slice(0, 12);
      // V1.27.9: preserve explicit empty item objects as editable drafts.
      // Deletion is a user action; autosave normalization must never delete a
      // card merely because its textarea is temporarily empty while editing.
      if (!text && !images.length && (row == null || typeof row !== 'object')) continue;
      let itemId = String(row?.id || '').trim().replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
      if (!itemId || usedItemIds.has(itemId)) itemId = `item-${crypto.randomUUID()}`;
      usedItemIds.add(itemId);
      const subject = String(row?.subject || row?.topic || '').replace(/\s+/g, ' ').trim().slice(0, 80) || speechLibrarySubjectFromText(text, itemIndex);
      const salutationEnabled = row?.salutationEnabled !== false;
      items.push({ id: itemId, subject, text, salutationEnabled, images });
      if (items.length >= 500) break;
    }
    groups.push({ id: groupId, title, items });
  }
  if (!groups.length) groups.push({ id: 'day-1', title: '第一天', items: [] });
  return { version: 2, groups };
}

