function normalizeStabilityConfig(raw = {}) {
  const previous = Number(raw?.schemaVersion || 0) || 0;
  const base = defaultConfig().stability;
  return {
    ...base,
    ...(raw && typeof raw === 'object' ? raw : {}),
    schemaVersion: CONFIG_MIGRATION_VERSION,
    sampleIntervalMs: Math.max(10000, Math.min(120000, Number(raw?.sampleIntervalMs || base.sampleIntervalMs) || 30000)),
    staleWorkflowMs: Math.max(60000, Math.min(15 * 60 * 1000, Number(raw?.staleWorkflowMs || base.staleWorkflowMs) || 120000)),
    lastMigrationVersion: previous < CONFIG_MIGRATION_VERSION ? '1.27.266' : String(raw?.lastMigrationVersion || '1.27.266'),
    lastMigrationAt: previous < CONFIG_MIGRATION_VERSION ? new Date().toISOString() : String(raw?.lastMigrationAt || '')
  };
}

function loadConfig() {
  try {
    const primary = configPath();
    let cfg = null;
    for (const candidate of [primary, `${primary}.bak`]) {
      try {
        if (!fs.existsSync(candidate)) continue;
        cfg = JSON.parse(fs.readFileSync(candidate, 'utf8'));
        if (cfg && typeof cfg === 'object') break;
      } catch {}
    }
    if (!cfg) return defaultConfig();
    const translation = {
      ...defaultConfig().translation,
      ...(cfg.translation || {})
    };
    // V1.10.9 removes paid/unused AI providers from both UI and active config.
    for (const key of ['aiBaseUrl','aiApiKey','aiModel','deepseekApiKey','deepseekModel','geminiApiKey','geminiModel','qwenApiKey','qwenModel','qwenRegion','aiReplyProvider','aiReplyContextMessages','aiReplyLanguage','aiReplyRequirements']) {
      delete translation[key];
    }
    // V1.27.131: cloud credentials stay off the desktop. DeepL is reached only
    // through the authenticated Team/VPS gateway; local Ollama remains fallback.
    for (const key of [
      'libreUrl','googleApiKey','deeplApiKey','groqApiKey','groqModel',
      'openrouterApiKey','openrouterModel','ollamaFallbackEnabled',
      'aiFallbackChain','aiFallbackGoogle'
    ]) delete translation[key];
    translation.engine = 'ollama';
    translation.incomingTranslationProvider = translation.incomingTranslationProvider === 'openai' ? 'openai' : 'deepl';
    translation.openaiTranslationModel = /^[-a-zA-Z0-9_.]{2,80}$/.test(String(translation.openaiTranslationModel || '')) ? translation.openaiTranslationModel : 'gpt-4o-mini';
    translation.vpsGatewayEnabled = true;
    translation.gatewayPrimaryV127130 = true;
    translation.translateIncomingOnlyV127130 = true;
    if (typeof translation.ollamaTranslateOutgoing !== 'boolean') translation.ollamaTranslateOutgoing = true;
    translation.outgoingLocalOnlyV127170 = true;
    if (translation.localFallbackEnabledV127133 !== false) translation.localFallbackEnabledV127133 = true;
    if (translation.serverPreTranslationV127133 !== false) translation.serverPreTranslationV127133 = true;
    delete translation.localOnlyV127111;
    translation.localProviderOnlyV127112 = true;
    return {
      ...defaultConfig(),
      ...cfg,
      translation,
      updates: {
        ...defaultConfig().updates,
        ...(cfg.updates || {})
      },
      speechLibrary: normalizeSpeechLibrary(cfg.speechLibrary || defaultSpeechLibrary()),
      crm: {
        contacts:
          cfg.crm?.contacts && typeof cfg.crm.contacts === 'object'
            ? cfg.crm.contacts
            : {}
      },
      teamSync: normalizeTeamSettings({
        ...defaultConfig().teamSync,
        ...(cfg.teamSync && typeof cfg.teamSync === 'object' ? cfg.teamSync : {})
      }),
      appCenter: {
        accounts: Array.isArray(cfg.appCenter?.accounts) ? cfg.appCenter.accounts : [],
        // V1.20.2: installed apps are explicit. Upgrading from V1.20.1 starts
        // with an empty rail until the operator adds apps from App Center.
        installedPlatforms: Array.isArray(cfg.appCenter?.installedPlatforms)
          ? cfg.appCenter.installedPlatforms.filter(id => id === 'line' || !!APP_CENTER_PLATFORMS[String(id || '').toLowerCase()])
          : []
      },
      nativeApiInbox: {
        ...defaultConfig().nativeApiInbox,
        ...(cfg.nativeApiInbox && typeof cfg.nativeApiInbox === 'object' ? cfg.nativeApiInbox : {})
      },
      chatgptWorkbench: {
        ...defaultConfig().chatgptWorkbench,
        ...(cfg.chatgptWorkbench && typeof cfg.chatgptWorkbench === 'object' ? cfg.chatgptWorkbench : {}),
        bindings: cfg.chatgptWorkbench?.bindings && typeof cfg.chatgptWorkbench.bindings === 'object' ? cfg.chatgptWorkbench.bindings : {},
        customerReplySettings: cfg.chatgptWorkbench?.customerReplySettings && typeof cfg.chatgptWorkbench.customerReplySettings === 'object' ? cfg.chatgptWorkbench.customerReplySettings : {},
        pendingAutoBinds: cfg.chatgptWorkbench?.pendingAutoBinds && typeof cfg.chatgptWorkbench.pendingAutoBinds === 'object' ? cfg.chatgptWorkbench.pendingAutoBinds : {},
        customerMessageDeliveryReceipts: cfg.chatgptWorkbench?.customerMessageDeliveryReceipts && typeof cfg.chatgptWorkbench.customerMessageDeliveryReceipts === 'object' ? cfg.chatgptWorkbench.customerMessageDeliveryReceipts : {},
        replyFreshnessLocks: cfg.chatgptWorkbench?.replyFreshnessLocks && typeof cfg.chatgptWorkbench.replyFreshnessLocks === 'object' ? cfg.chatgptWorkbench.replyFreshnessLocks : {},
        manualCustomerDrafts: cfg.chatgptWorkbench?.manualCustomerDrafts && typeof cfg.chatgptWorkbench.manualCustomerDrafts === 'object' ? cfg.chatgptWorkbench.manualCustomerDrafts : {}
      },
      automation: {
        ...defaultConfig().automation,
        ...(cfg.automation && typeof cfg.automation === 'object' ? cfg.automation : {}),
        processedCustomerTurns: cfg.automation?.processedCustomerTurns && typeof cfg.automation.processedCustomerTurns === 'object' ? cfg.automation.processedCustomerTurns : {}
      },
      stability: normalizeStabilityConfig(cfg.stability || {}),
      accounts: Array.isArray(cfg.accounts) ? cfg.accounts : []
    };
  } catch {
    return defaultConfig();
  }
}

function configPersistenceSnapshot(cfg) {
  // V1.11.4 stores avatar image bytes in avatar-cache instead of repeatedly
  // embedding multi-megabyte data URLs in config.json. The live object still
  // keeps the avatar for immediate UI use; only the persisted snapshot is slim.
  return {
    ...cfg,
    accounts: Array.isArray(cfg?.accounts)
      ? cfg.accounts.map(account => ({
          ...account,
          lineProfile: {
            ...(account.lineProfile || {}),
            avatarDataUrl: ''
          }
        }))
      : []
  };
}

async function atomicWriteTextFileAsync(target, text, { keepBackup = false } = {}) {
  const dir=path.dirname(target);
  const tmp=`${target}.${process.pid}.${Date.now()}.tmp`;
  const bak=`${target}.bak`;
  await fs.promises.mkdir(dir,{recursive:true});
  await fs.promises.writeFile(tmp,String(text),'utf8');
  try {
    if (keepBackup) {
      await fs.promises.access(target,fs.constants.F_OK);
      await fs.promises.copyFile(target,bak);
    }
  } catch {}
  try { await fs.promises.rm(target,{force:true}); } catch {}
  await fs.promises.rename(tmp,target);
}

async function atomicWriteJsonAsync(target, payload, options = {}) {
  // V1.27.180: JSON serialization remains deterministic on the main thread, but
  // filesystem writes/copy/rename are moved off the Electron main-thread path.
  const json = JSON.stringify(payload, null, 2);
  await atomicWriteTextFileAsync(target, json, options);
}

function scheduleConfigWriteBehind(delayMs = CONFIG_WRITE_BEHIND_DEBOUNCE_MS) {
  if (configWriteBehindTimer || configWriteBehindRunning) return;
  configWriteBehindTimer=setTimeout(()=>{
    configWriteBehindTimer=null;
    runConfigWriteBehind().catch(()=>{});
  },Math.max(0,Number(delayMs||0)));
  configWriteBehindTimer.unref?.();
}

async function runConfigWriteBehind() {
  if (configWriteBehindRunning) return configWriteBehindRunning;
  if (!configWriteBehindDirty) return true;

  const generation=configWriteBehindGeneration;
  const cfg=configWriteBehindLatestCfg || config;
  configWriteBehindDirty=false;
  configWriteBehindStats.pending=true;
  configWriteBehindStats.lastStartedAt=Date.now();

  // Coalescing is the important Main-thread protection: many saveConfig() calls
  // in one customer/GPT transition become one serialization + one disk write.
  const serializeStarted=Date.now();
  const serializeAttribution=beginUiLatencyAttributionActivity('config-json-serialize',{phase:'serialize'});
  let json='';
  try { json=JSON.stringify(configPersistenceSnapshot(cfg),null,2); }
  catch (error) {
    serializeAttribution.finish({phase:'serialize-error'});
    configWriteBehindDirty=true;
    configWriteBehindStats.errors+=1;
    configWriteBehindStats.lastError=String(error?.message||error).slice(0,180);
    configWriteBehindStats.pending=true;
    scheduleConfigWriteBehind(250);
    return false;
  }
  const serializeMs=Math.max(0,Date.now()-serializeStarted);
  serializeAttribution.finish({phase:'serialize-complete'});
  configWriteBehindStats.lastSerializeMs=serializeMs;
  configWriteBehindStats.maxSerializeMs=Math.max(Number(configWriteBehindStats.maxSerializeMs||0),serializeMs);

  const target=configPath();
  const writeStarted=Date.now();
  configWriteBehindRunning=(async()=>{
    try {
      // Keep config.json.bak exactly as before, but move filesystem I/O off the
      // synchronous Main-thread path. loadConfig() can still recover from it.
      await atomicWriteTextFileAsync(target,json,{keepBackup:true});
      configWriteBehindFlushedGeneration=Math.max(configWriteBehindFlushedGeneration,generation);
      configWriteBehindStats.writes+=1;
      configWriteBehindStats.lastCompletedAt=Date.now();
      configWriteBehindStats.lastError='';
      return true;
    } catch (error) {
      configWriteBehindDirty=true;
      configWriteBehindStats.errors+=1;
      configWriteBehindStats.lastError=String(error?.message||error).slice(0,180);
      return false;
    } finally {
      const writeMs=Math.max(0,Date.now()-writeStarted);
      configWriteBehindStats.lastWriteMs=writeMs;
      configWriteBehindStats.maxWriteMs=Math.max(Number(configWriteBehindStats.maxWriteMs||0),writeMs);
    }
  })();

  try { return await configWriteBehindRunning; }
  finally {
    configWriteBehindRunning=null;
    configWriteBehindStats.pending=!!configWriteBehindDirty;
    if (configWriteBehindDirty) scheduleConfigWriteBehind(0);
  }
}

async function flushConfigWriteBehind() {
  if (configWriteBehindTimer) { clearTimeout(configWriteBehindTimer); configWriteBehindTimer=null; }
  // A save may arrive while an async write is in progress. Drain until the
  // latest in-memory generation has reached disk before full application quit.
  for (let guard=0; guard<8; guard++) {
    if (configWriteBehindRunning) await configWriteBehindRunning.catch(()=>false);
    if (configWriteBehindDirty || configWriteBehindFlushedGeneration < configWriteBehindGeneration) {
      configWriteBehindDirty=true;
      await runConfigWriteBehind().catch(()=>false);
      continue;
    }
    break;
  }
  configWriteBehindStats.pending=!!configWriteBehindDirty || !!configWriteBehindRunning;
  return !configWriteBehindStats.pending && configWriteBehindFlushedGeneration>=configWriteBehindGeneration;
}

function saveConfig(cfg) {
  configWriteBehindLatestCfg=cfg || config;
  configWriteBehindGeneration+=1;
  configWriteBehindStats.requested+=1;
  configWriteBehindStats.lastRequestedAt=Date.now();
  if (configWriteBehindDirty || configWriteBehindTimer || configWriteBehindRunning) configWriteBehindStats.coalesced+=1;
  configWriteBehindDirty=true;
  configWriteBehindStats.pending=true;
  scheduleConfigWriteBehind();
  return true;
}

let config = defaultConfig();
let customerNumberVault = emptyCustomerNumberVault();
let teamSyncRuntime = null;

// V1.25.11 — stable-seal diagnostics for the proven LINE handoff terminal chain.
// This log stores routing/verification metadata only: never chat text, cookies,
// credentials, proxy passwords or API keys. It is intentionally independent
// from the conversion trace so support can see which exact terminal stage broke.
function handoffStabilityLogPath() {
  try { return path.join(app.getPath('userData'), 'diagnostics', 'handoff-stability.jsonl'); } catch { return ''; }
}
function handoffIntegrityReportPath() {
  try { return path.join(app.getPath('userData'), 'diagnostics', 'handoff-integrity-latest.json'); } catch { return ''; }
}
const handoffStabilityLogger = new AutomationLogger(() => handoffStabilityLogPath(), { maxBytes:2 * 1024 * 1024, backups:2 });
let handoffIntegrityLatest = { version:'1.25.11', at:'', ok:true, reason:'not-run', counts:{boundTasks:0,healthy:0,unhealthy:0}, issueCounts:{}, rows:[] };
let handoffIntegrityLastSignature = '';
function traceHandoff(event, payload = {}) {
  try { handoffStabilityLogger.write(event, payload && typeof payload === 'object' ? payload : {}); } catch {}
}
function handoffTraceRowId(row = {}) {
  try {
    const stable = JSON.stringify({
      at:String(row?.at || ''), event:String(row?.event || ''), taskId:String(row?.taskId || ''),
      accountId:String(row?.accountId || ''), chatId:String(row?.chatId || ''), error:String(row?.error || ''),
      targetKey:String(row?.targetKey || ''), wantedConversation:String(row?.wantedConversation || ''),
      currentConversation:String(row?.currentConversation || ''), issueCounts:row?.issueCounts || null
    });
    return crypto.createHash('sha256').update(stable).digest('hex').slice(0,24);
  } catch { return ''; }
}
function handoffRecentTraceRows(limit = 100) {
  return handoffStabilityLogger.tail(limit).slice(-Math.max(1, Math.min(500, Number(limit)||100))).map(row => ({ ...row, _traceId:handoffTraceRowId(row) }));
}
function deleteHandoffTraceRows(traceIds = []) {
  const wanted = new Set((Array.isArray(traceIds) ? traceIds : []).map(v => String(v || '').trim()).filter(Boolean).slice(0,100));
  if (!wanted.size) return { ok:true, deleted:0, health:publicHandoffHealthSnapshot('trace-delete-noop') };
  const file = handoffStabilityLogPath();
  if (!file || !fs.existsSync(file)) return { ok:true, deleted:0, health:publicHandoffHealthSnapshot('trace-delete-empty') };
  const raw = fs.readFileSync(file, 'utf8');
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const kept=[]; let deleted=0;
  for (const line of lines) {
    let row=null; try { row=JSON.parse(line); } catch { kept.push(line); continue; }
    const id=handoffTraceRowId(row);
    if (id && wanted.has(id)) { deleted += 1; continue; }
    kept.push(line);
  }
  if (deleted) {
    fs.mkdirSync(path.dirname(file), { recursive:true });
    const tmp=`${file}.tmp-delete-${process.pid}-${Date.now()}`;
    fs.writeFileSync(tmp, kept.length ? `${kept.join('\n')}\n` : '', 'utf8');
    try { if (fs.existsSync(file)) fs.unlinkSync(file); } catch {}
    fs.renameSync(tmp, file);
  }
  return { ok:true, deleted, health:publicHandoffHealthSnapshot('trace-delete') };
}
function runHandoffIntegrityCheck(reason = 'manual', snapshot = null) {
  try {
    const snap = snapshot && typeof snapshot === 'object' ? snapshot : (teamSyncRuntime?.snapshot?.() || {});
    const report = inspectHandoffIntegrity({
      tasks:Array.isArray(snap?.tasks) ? snap.tasks : [],
      contacts:config?.crm?.contacts || {},
      bindings:config?.chatgptWorkbench?.bindings || {},
      lineAccounts:config?.accounts || [],
      deviceId:teamSyncSettings().deviceId,
      continuityVersion:'1.25.9'
    });
    handoffIntegrityLatest = { ...report, reason:String(reason || 'manual').slice(0,80) };
    const file = handoffIntegrityReportPath();
    if (file) {
      fs.mkdirSync(path.dirname(file), { recursive:true });
      const tmp = `${file}.tmp`;
      fs.writeFileSync(tmp, JSON.stringify(handoffIntegrityLatest, null, 2), 'utf8');
      try { if (fs.existsSync(file)) fs.unlinkSync(file); } catch {}
      fs.renameSync(tmp, file);
    }
    const signature = JSON.stringify({ ok:report.ok, counts:report.counts, issueCounts:report.issueCounts });
    if (signature !== handoffIntegrityLastSignature) {
      handoffIntegrityLastSignature = signature;
      traceHandoff('integrity-check', { reason:handoffIntegrityLatest.reason, ok:report.ok, counts:report.counts, issueCounts:report.issueCounts });
    }
    return handoffIntegrityLatest;
  } catch (error) {
    const failed = { version:'1.25.11', at:new Date().toISOString(), ok:false, reason:String(reason || 'manual'), error:String(error?.message || error || '').slice(0,500), counts:{boundTasks:0,healthy:0,unhealthy:0}, issueCounts:{selfCheckException:1}, rows:[] };
    handoffIntegrityLatest = failed;
    traceHandoff('integrity-check-exception', { reason:failed.reason, error:failed.error });
    return failed;
  }
}

// V1.25.12 — production health/recovery console. This is a read-only
// projection of the V1.25.11 integrity guard plus privacy-safe recent trace
// metadata. It never exposes chat text, cookies, credentials or API keys.
function publicHandoffHealthSnapshot(reason = 'health-console') {
  const snapshot = teamSyncRuntime?.snapshot?.() || {};
  const report = runHandoffIntegrityCheck(reason, snapshot);
  const taskMap = new Map((Array.isArray(snapshot?.tasks) ? snapshot.tasks : []).map(task => [String(task?.taskId || ''), task]));
  const rows = (Array.isArray(report?.rows) ? report.rows : []).map(row => {
    const task = taskMap.get(String(row?.taskId || '')) || {};
    const customer = task?.customer && typeof task.customer === 'object' ? task.customer : {};
    return {
      ...row,
      sourcePlatform:String(task?.sourcePlatform || customer?.sourcePlatform || ''),
      sourceAccountName:String(task?.sourceAccountName || customer?.sourceAccountName || ''),
      sourceDisplayName:String(task?.sourceDisplayName || customer?.sourceDisplayName || ''),
      sourceHandle:String(task?.sourceHandle || customer?.sourceHandle || '').replace(/^@+/, ''),
      targetLineAccountName:String(task?.targetLineAccountName || task?.targetLineLogicalKey || ''),
      boundLineAccountName:String(task?.boundLineAccountName || ''),
      boundLineDisplayName:String(task?.boundLineDisplayName || ''),
      assignedDeviceName:String(task?.assignedDeviceName || '')
    };
  });
  let currentWorkbenchUrl = '';
  let workbenchLoading = false;
  try { currentWorkbenchUrl = String(chatgptWorkbenchWindow?.webContents?.getURL?.() || ''); } catch {}
  try { workbenchLoading = !!chatgptWorkbenchWindow?.webContents?.isLoadingMainFrame?.(); } catch {}
  return {
    ...report,
    version:'1.25.14',
    rows,
    recentTrace:handoffStabilityLogger.tail(100).slice(-100).map(row => ({ ...row, _traceId:handoffTraceRowId(row) })),
    // V1.25.14: read-only workbench settle state lets the health console
    // distinguish a normal loading handoff from a real stuck retarget.  No
    // chat content, cookies, credentials or other sensitive page data is exposed.
    workbench:{
      visible:!!chatgptWorkbenchVisible,
      ready:!!chatgptWorkbenchReady,
      loading:!!workbenchLoading,
      loginProtected:!!chatgptLoginProtectionActive,
      targetKey:String(chatgptWorkbenchTargetKey || ''),
      pendingRetargetKey:String(chatgptWorkbenchPendingRetargetKey || ''),
      inFlight:!!chatgptWorkbenchRetargetInFlightKey,
      currentConversation:handoffConversationRef(currentWorkbenchUrl)
    }
  };
}

function localBoundHandoffTask(taskId = '') {
  if (!teamSyncRuntime) throw new Error('团队同步尚未初始化。');
  const task = (teamSyncRuntime.snapshot()?.tasks || []).find(row => String(row?.taskId || '') === String(taskId || ''));
  if (!task) throw new Error('没有找到这条已绑定承接任务。请先同步一次。');
  if (!['bound','completed'].includes(String(task?.status || ''))) throw new Error('只有已经绑定的承接任务才能使用链路恢复。');
  const localDeviceId = String(teamSyncSettings().deviceId || '');
  if (String(task?.assignedDeviceId || '') && String(task?.assignedDeviceId || '') !== localDeviceId) {
    throw new Error(task?.assignedDeviceName ? `这条任务属于「${task.assignedDeviceName}」，当前设备不能修复。` : '这条任务属于其他设备，当前设备不能修复。');
  }
  const accountId = normalizeCrmText(task?.boundLineAccountId, 128);
  const chatId = normalizeCrmText(task?.boundLineChatId, 300);
  const displayName = normalizeCrmText(task?.boundLineDisplayName, 180);
  if (!accountId || (!chatId && !displayName) || !getAccount(accountId)) throw new Error('这条任务缺少有效的本机 LINE 绑定信息。');
  return { task, accountId, chatId, displayName };
}

function markRecoveredLocalCommitIfComplete(task, contactHint = null) {
  try {
    const report = runHandoffIntegrityCheck('recovery-verify', teamSyncRuntime?.snapshot?.() || {});
    const row = (report?.rows || []).find(item => String(item?.taskId || '') === String(task?.taskId || ''));
    if (!row) return { report, finalized:false };
    const remaining = (row.issues || []).filter(code => code !== 'localCommitVerified');
    if (!remaining.length && (row.issues || []).includes('localCommitVerified')) {
      const crm = ensureCrmConfig();
      const match = getCrmContactForConversation(task?.boundLineAccountId, task?.boundLineChatId, task?.boundLineDisplayName);
      const contact = contactHint || match.contact;
      if (contact) {
        const next = {
          ...contact,
          _teamSync:{ ...(contact._teamSync || {}), localCommitState:'verified', localCommitVerifiedAt:new Date().toISOString(), recoveredBy:'1.25.12-health-console' },
          updatedAt:new Date().toISOString()
        };
        crm.contacts[match.stableKey] = next;
        saveConfig(config);
        return { report:runHandoffIntegrityCheck('recovery-finalized', teamSyncRuntime?.snapshot?.() || {}), finalized:true };
      }
    }
    return { report, finalized:false };
  } catch (error) {
    return { report:runHandoffIntegrityCheck('recovery-finalize-failed', teamSyncRuntime?.snapshot?.() || {}), finalized:false, error:String(error?.message || error || '') };
  }
}

async function repairBoundHandoffGpt(taskId = '') {
  const { task, accountId, chatId, displayName } = localBoundHandoffTask(taskId);
  const destinationTargetKey = speechLibraryTargetKey({ platform:'line', accountId, chatId, displayName, handle:'' });
  const cfg = chatgptWorkbenchConfig();
  const hadBinding = Object.prototype.hasOwnProperty.call(cfg.bindings || {}, destinationTargetKey);
  const priorBinding = hadBinding ? cfg.bindings[destinationTargetKey] : null;
  const hadReply = Object.prototype.hasOwnProperty.call(cfg.customerReplySettings || {}, destinationTargetKey);
  const priorReply = hadReply ? cfg.customerReplySettings[destinationTargetKey] : null;
  try {
    const result = inheritTeamHandoffChatgptState(task, { accountId, chatId, displayName });
    if (!result?.sourceBindingRequired) throw new Error('来源客户目前没有有效的 ChatGPT 历史会话，无法执行 GPT 连续性恢复。');
    if (!result?.destinationBindingPresent || result?.bindingUrlMatches !== true) throw new Error('GPT 连续性恢复后的历史会话 URL 仍不一致，已取消本次修复。');
    const crm = ensureCrmConfig();
    const match = getCrmContactForConversation(accountId, chatId, displayName);
    if (match.contact) {
      crm.contacts[match.stableKey] = {
        ...match.contact,
        _teamSync:{
          ...(match.contact._teamSync || {}),
          gptContinuityVersion:'1.25.9',
          gptContinuityVerifiedAt:new Date().toISOString(),
          gptSourceTargetKey:normalizeCrmText(result?.sourceTargetKey,800),
          recoveredBy:'1.25.12-health-console'
        },
        updatedAt:new Date().toISOString()
      };
    }
    saveConfig(config);
    const final = markRecoveredLocalCommitIfComplete(task, crm.contacts[match.stableKey] || match.contact || null);
    try { await syncChatgptWorkbenchTarget({ force:true, focus:false, navigationMode:'binding-repair' }); } catch {}
    traceHandoff('health-repair-gpt', {
      taskId:String(task?.taskId || ''), accountId, chatId, ok:true,
      sourceConversation:handoffConversationRef(result?.sourceUrl || ''),
      destinationConversation:handoffConversationRef(result?.destinationUrlAfter || ''),
      localCommitFinalized:!!final.finalized
    });
    return { ok:true, repair:'gpt', continuity:result, health:publicHandoffHealthSnapshot('repair-gpt-complete') };
  } catch (error) {
    if (hadBinding) cfg.bindings[destinationTargetKey] = priorBinding;
    else delete cfg.bindings[destinationTargetKey];
    if (hadReply) cfg.customerReplySettings[destinationTargetKey] = priorReply;
    else delete cfg.customerReplySettings[destinationTargetKey];
    try { saveConfig(config); } catch {}
    traceHandoff('health-repair-gpt-failed', { taskId:String(task?.taskId || ''), accountId, chatId, error:String(error?.message || error || '').slice(0,500) });
    throw error;
  }
}

function repairBoundHandoffCrm(taskId = '') {
  const { task, accountId, chatId, displayName } = localBoundHandoffTask(taskId);
  const crm = ensureCrmConfig();
  const match = getCrmContactForConversation(accountId, chatId, displayName);
  const existing = match.contact || {};
  const taskGlobal = normalizeCrmText(task?.globalCustomerId || task?.customer?.globalCustomerId, 120);
  const existingGlobal = normalizeCrmText(existing?.globalCustomerId || existing?.crossPlatform?.globalCustomerId, 120);
  if (existingGlobal && taskGlobal && existingGlobal !== taskGlobal) throw new Error('当前 LINE 客户已经绑定到另一个 globalCustomerId，为防止串客户，本次 CRM 恢复已停止。');
  const now = new Date().toISOString();
  const merged = mergeCustomerIntoLineContact(existing, { ...(task?.customer || {}), taskId:task?.taskId, globalCustomerId:taskGlobal });
  const stage = normalizeLineCrmStage(existing.stage || merged.stage || '初步认识');
  const record = {
    ...existing,
    ...merged,
    globalCustomerId:taskGlobal,
    key:match.stableKey,
    platform:'line', accountId, chatId, displayName,
    stage,
    serviceStatus:['auto','waiting','active','done','paused','blacklist'].includes(String(existing.serviceStatus || '')) ? existing.serviceStatus : 'auto',
    ...crmBusinessFields('line', stage),
    createdAt:existing.createdAt || now,
    updatedAt:now,
    _teamSync:{
      ...(existing._teamSync && typeof existing._teamSync === 'object' ? existing._teamSync : {}),
      taskId:normalizeCrmText(task?.taskId,120),
      globalCustomerId:taskGlobal,
      remoteRevision:normalizeCrmText(task?.customer?.serverUpdatedAt || task?.customer?.updatedAt || task?.updatedAt,100),
      remoteSyncedAt:now,
      recoveredBy:'1.25.12-health-console'
    }
  };
  record.summary = buildAutoSummary(record, stage);
  crm.contacts[match.stableKey] = record;
  saveConfig(config);
  try { sendUI('aggregate-updated', publicAggregateInbox()); } catch {}
  const final = markRecoveredLocalCommitIfComplete(task, record);
  traceHandoff('health-repair-crm', { taskId:String(task?.taskId || ''), accountId, chatId, ok:true, localCommitFinalized:!!final.finalized });
  return { ok:true, repair:'crm', contact:crmContactSummary(crm.contacts[match.stableKey] || record), health:publicHandoffHealthSnapshot('repair-crm-complete') };
}

function teamSyncSettings() {
  const current = normalizeTeamSettings(config.teamSync || {});
  if (!current.deviceId) current.deviceId = randomId('device');
  if (!current.deviceName) current.deviceName = `Yoko-${os.hostname() || '设备'}`;
  config.teamSync = current;
  if (officialApiSession.token && officialApiSession.baseUrl) {
    return {...current,serverUrl:officialApiSession.baseUrl,cloudflarePublicUrl:'',officialApiSessionToken:officialApiSession.token,sessionToken:officialApiSession.token};
  }
  return current;
}

function gptOrchestratorStateConfig() {
  if (!config.chatgptWorkbench || typeof config.chatgptWorkbench !== 'object') config.chatgptWorkbench = {};
  return config.chatgptWorkbench;
}

function gptOrchestratorClone(value) {
  try { return JSON.parse(JSON.stringify(value ?? {})); } catch { return {}; }
}

function gptOrchestratorSectionValue(key = '') {
  const cfg=gptOrchestratorStateConfig();
  const value=cfg[String(key||'')];
  return value && typeof value === 'object' ? gptOrchestratorClone(value) : {};
}

function gptOrchestratorKnownSection(key = '') {
  return gptOrchestrator.STATE_KEYS.includes(String(key||''));
}

function scheduleGptOrchestratorStatePersist(keys = [], { immediate = false, localCritical = false } = {}) {
  const list=(Array.isArray(keys)?keys:[keys]).map(String).filter(gptOrchestratorKnownSection);
  if(!list.length)return false;
  const now=Date.now();
  for(const key of list) gptOrchestratorWriteQueue.set(key,{key,value:gptOrchestratorSectionValue(key),updatedAt:now});
  if(localCritical || !gptOrchestratorRemoteReady){
    // Before the VPS capability is confirmed, retain the established local
    // durability contract. Once remote is healthy, high-churn receipts/day state
    // stop rewriting the monolithic config and use SQLite instead.
    if(localCritical || now-Number(gptOrchestratorFallbackLocalSaveAt||0)>8000){
      gptOrchestratorFallbackLocalSaveAt=now;
      try{saveConfig(config)}catch{}
    }
  }
  if(gptOrchestratorWriteTimer)clearTimeout(gptOrchestratorWriteTimer);
  gptOrchestratorWriteTimer=setTimeout(()=>{
    gptOrchestratorWriteTimer=null;
    flushGptOrchestratorStatePersist().catch(()=>{});
  },immediate?0:550);
  return true;
}

async function flushGptOrchestratorStatePersist() {
  if(gptOrchestratorWriteInFlight || !gptOrchestratorWriteQueue.size)return {ok:true,skipped:true};
  const settings=teamSyncSettings();
  if(!gptOrchestrator.settingsFor(settings)){
    gptOrchestratorRemoteReady=false;
    return {ok:false,skipped:true,error:'team-sync-disabled'};
  }
  const items=[...gptOrchestratorWriteQueue.values()].slice(0,16);
  for(const row of items)gptOrchestratorWriteQueue.delete(row.key);
  gptOrchestratorWriteInFlight=true;
  try{
    const result=await gptOrchestrator.putState(settings,items,3200);
    gptOrchestratorRemoteReady=!!result?.ok;
    gptOrchestratorLastSyncAt=Date.now();
    gptOrchestratorLastError='';
    return result;
  }catch(error){
    for(const row of items)if(!gptOrchestratorWriteQueue.has(row.key))gptOrchestratorWriteQueue.set(row.key,row);
    gptOrchestratorRemoteReady=false;
    gptOrchestratorLastError=String(error?.message||error||'').slice(0,300);
    const now=Date.now();
    if(now-Number(gptOrchestratorFallbackLocalSaveAt||0)>8000){gptOrchestratorFallbackLocalSaveAt=now;try{saveConfig(config)}catch{}}
    return {ok:false,error:gptOrchestratorLastError};
  }finally{
    gptOrchestratorWriteInFlight=false;
    if(gptOrchestratorWriteQueue.size&&!gptOrchestratorWriteTimer){gptOrchestratorWriteTimer=setTimeout(()=>{gptOrchestratorWriteTimer=null;flushGptOrchestratorStatePersist().catch(()=>{});},1800);}
  }
}

function mergeGptOrchestratorSection(localValue, remoteValue) {
  const local=localValue&&typeof localValue==='object'?localValue:{};
  const remote=remoteValue&&typeof remoteValue==='object'?remoteValue:{};
  // Remote rows are the runtime authority once present, while local-only keys
  // from an offline session are preserved until the next write-behind flush.
  return {...local,...remote};
}

async function hydrateGptOrchestratorStateFromServer({ retry = false } = {}) {
  if(gptOrchestratorHydrated&&!retry)return {ok:true,skipped:true};
  const settings=teamSyncSettings();
  if(!gptOrchestrator.settingsFor(settings))return {ok:false,skipped:true,error:'team-sync-disabled'};
  try{
    const result=await gptOrchestrator.getState(settings,gptOrchestrator.STATE_KEYS,3200);
    if(!result?.ok)throw new Error(result?.error||'gpt-orchestrator-not-ready');
    const cfg=gptOrchestratorStateConfig();
    const received=new Set();
    for(const item of Array.isArray(result.items)?result.items:[]){
      const key=String(item?.key||'');if(!gptOrchestratorKnownSection(key))continue;
      cfg[key]=mergeGptOrchestratorSection(cfg[key],item?.value);
      received.add(key);
    }
    gptOrchestratorHydrated=true;
    gptOrchestratorRemoteReady=true;
    gptOrchestratorLastSyncAt=Date.now();
    gptOrchestratorLastError='';
    // First connection on an existing desktop seeds missing VPS sections.
    const missing=gptOrchestrator.STATE_KEYS.filter(key=>!received.has(key));
    if(missing.length)scheduleGptOrchestratorStatePersist(missing,{immediate:true,localCritical:false});
    // One local snapshot after hydration keeps rollback/offline startup safe. The
    // hot path after this point persists receipts/day state to server SQLite.
    saveConfig(config);
    persistChatgptBindingsShadow(cfg);
    // Stage 3 warms only the most recent bounded customer snapshots into RAM;
    // the full history index stays on VPS SQLite and is fetched lazily.
    setTimeout(()=>prefetchGptStage3RecentContexts().catch(()=>{}),250);
    return {ok:true,received:[...received],missing};
  }catch(error){
    gptOrchestratorRemoteReady=false;
    gptOrchestratorLastError=String(error?.message||error||'').slice(0,300);
    if(!retry)setTimeout(()=>hydrateGptOrchestratorStateFromServer({retry:true}).catch(()=>{}),4500);
    return {ok:false,error:gptOrchestratorLastError};
  }
}

function gptStage2HistoryIndex(rows = []) {
  return (Array.isArray(rows)?rows:[]).slice(-40).map((row,index)=>{
    const text=String(row?.text||'').trim().slice(0,4000);
    return {
      id:String(row?.id||row?.messageId||automationRowStableId(row)||`row-${index}`).slice(0,160),
      role:String(row?.role||'').slice(0,24),
      at:Number(row?.delivered||row?.at||row?.timestamp||0)||0,
      hash:text?automationFingerprint(text).slice(0,64):'',
      preview:text.slice(0,220)
    };
  });
}

function gptStage2ContextSnapshot(target = null) {
  if(!target?.ok)return null;
  const targetKey=chatgptWorkflowTargetKey(target);if(!targetKey)return null;
  const binding=chatgptBindingForTarget(target);
  const modeInfo=chatgptChatModeForTarget(target,binding);
  let dailyState=null;
  try{dailyState=chatgptDailyFlowStateForBinding(binding,target)}catch{dailyState=null}
  const stage=dailyState&&typeof dailyState==='object'?{
    currentDay:Number(dailyState.currentDay||0)||0,
    status:String(dailyState.status||''),
    enrollmentDateKey:String(dailyState.enrollmentDateKey||''),
    activeDateKey:String(dailyState.activeDateKey||''),
    currentStageId:String(dailyState.currentStageId||''),
    currentStageLabel:String(dailyState.currentStageLabel||''),
    intradayDirectionProgress:dailyState.intradayDirectionProgress&&typeof dailyState.intradayDirectionProgress==='object'?gptOrchestratorClone(dailyState.intradayDirectionProgress):{},
    delivery:dailyState.delivery&&typeof dailyState.delivery==='object'?{
      day:Number(dailyState.delivery.day||0)||0,status:String(dailyState.delivery.status||''),deliveryId:String(dailyState.delivery.deliveryId||''),fingerprint:String(dailyState.delivery.fingerprint||'')
    }:null
  }:null;
  return {
    version:'v127236-gpt-lite-stage2',targetKey,
    customer:{surface:String(target.surface||''),platform:String(target.platform||''),accountId:String(target.accountId||''),chatId:String(target.chatId||''),displayName:String(target.displayName||target.handle||'').slice(0,180),globalCustomerId:String(chatgptGlobalCustomerIdForTarget(target)||'').slice(0,140)},
    binding:binding?{conversationRef:String(chatgptBoundConversationRef(binding)||''),displayName:String(binding.displayName||'').slice(0,180),personaInitialized:chatgptBindingPersonaInitialized(binding),flowLibraryFingerprint:String(chatgptBindingFlowLibraryFingerprint(binding)||'').slice(0,128)}:null,
    chatMode:String(modeInfo?.mode||''),dailyFlow:stage,flowAdvisorVersion:CHATGPT_FLOW_ADVISOR_VERSION,updatedAt:Date.now()
  };
}

function scheduleGptStage2ContextWarm(target = null, rows = [], { force = false, reason = 'selection' } = {}) {
  if(!target?.ok)return false;
  const targetKey=chatgptWorkflowTargetKey(target);if(!targetKey)return false;
  const now=Date.now();
  if(!force && targetKey===gptStage2LastTargetKey && now-Number(gptStage2LastWarmAt||0)<20000){gptStage2ContextWarmSkipCount+=1;return false;}
  gptStage2LastTargetKey=targetKey;
  if(gptStage2ContextWarmTimer)clearTimeout(gptStage2ContextWarmTimer);
  const targetSnapshot={...target};const history=gptStage2HistoryIndex(rows);
  gptStage2ContextWarmTimer=setTimeout(async()=>{
    gptStage2ContextWarmTimer=null;
    if(gptStage2ContextWarmInFlight){gptStage2ContextWarmSkipCount+=1;return;}
    const settings=teamSyncSettings();if(!gptOrchestrator.settingsFor(settings)){gptStage2ContextWarmSkipCount+=1;return;}
    const snapshot=gptStage2ContextSnapshot(targetSnapshot);if(!snapshot){gptStage2ContextWarmSkipCount+=1;return;}
    gptStage2ContextWarmInFlight=true;
    try{
      const result=await gptOrchestrator.putContext(settings,targetKey,{...snapshot,reason:String(reason||'').slice(0,80)},history,1800);
      if(!result?.ok)throw new Error(result?.error||'context-warm-failed');
      gptStage2ContextWarmCount+=1;gptStage2LastWarmAt=Date.now();gptStage2LastContextAt=gptStage2LastWarmAt;gptStage2LastContextError='';gptStage2LastContextTargetHash=automationFingerprint(targetKey).slice(0,16);
    }catch(error){gptStage2ContextWarmFailureCount+=1;gptStage2LastContextError=String(error?.message||error||'').slice(0,240);}
    finally{gptStage2ContextWarmInFlight=false;}
  },force?0:650);
  return true;
}

function gptStage3CacheContext(targetKey = '', row = null) {
  const key=String(targetKey||'').trim();
  if(!key||!row||typeof row!=='object')return false;
  if(gptStage3ContextCache.has(key))gptStage3ContextCache.delete(key);
  gptStage3ContextCache.set(key,{...gptOrchestratorClone(row),cachedAt:Date.now()});
  while(gptStage3ContextCache.size>GPT_STAGE3_CONTEXT_CACHE_MAX){
    const oldest=gptStage3ContextCache.keys().next().value;
    if(!oldest)break;
    gptStage3ContextCache.delete(oldest);
  }
  return true;
}

function gptStage3CachedContext(targetKey = '') {
  const key=String(targetKey||'').trim();
  if(!key)return null;
  const row=gptStage3ContextCache.get(key);
  if(!row){gptStage3ContextCacheMissCount+=1;return null;}
  gptStage3ContextCache.delete(key);gptStage3ContextCache.set(key,row);
  gptStage3ContextCacheHitCount+=1;
  return row;
}

function gptStage5TargetTimestamp(target = null) {
  return Math.max(0,
    Number(target?.lastTimestampMs||0)||0,
    Number(target?.timestampMs||0)||0,
    Number(target?.timestamp||0)||0
  );
}

function gptStage5SnapshotEligibleTarget(target = null) {
  if(!target?.ok)return false;
  const surface=String(target?.surface||'').toLowerCase();
  const platform=String(target?.platform||'').toLowerCase();
  // Stage 5 hot snapshots are safe only for authoritative sources. External
  // browser clients (Telegram/TikTok/Facebook Web/Meta Business) can still be
  // painting the previous chat for a few frames after selection, so caching
  // their DOM rows under the new customer key can cross-stale the manual GPT
  // handoff. Those surfaces must read LIVE when the operator clicks.
  return surface==='native-api' || platform==='line';
}

function gptStage5ComposerWarmEligible(target = null) {
  if(!target?.ok)return false;
  const binding=chatgptBindingForTarget(target);
  return !!(binding?.url && isChatgptStableConversationUrl(binding.url));
}

function gptStage5RowsMaxTimestamp(rows = []) {
  let max=0;
  for(const row of Array.isArray(rows)?rows:[]){
    max=Math.max(max,
      Number(row?.delivered||0)||0,
      Number(row?.timestampMs||0)||0,
      Number(row?.timestamp||0)||0,
      Number(row?.at||0)||0
    );
  }
  return max;
}

function gptStage5RememberSnapshot(target = null, rows = [], source = 'snapshot') {
  if(!target?.ok || !Array.isArray(rows) || !rows.length)return null;
  const key=chatgptWorkflowTargetKey(target);if(!key)return null;
  const compact=rows.slice(-140).map(row=>({...row}));
  const record={
    targetKey:key,at:Date.now(),rows:compact,
    maxTimestamp:gptStage5RowsMaxTimestamp(compact),
    targetTimestamp:gptStage5TargetTimestamp(target),
    source:String(source||'snapshot').slice(0,80)
  };
  if(gptStage5SnapshotCache.has(key))gptStage5SnapshotCache.delete(key);
  gptStage5SnapshotCache.set(key,record);
  while(gptStage5SnapshotCache.size>GPT_STAGE5_SNAPSHOT_CACHE_MAX){
    const oldest=gptStage5SnapshotCache.keys().next().value;
    if(!oldest)break;
    gptStage5SnapshotCache.delete(oldest);
  }
  gptStage5LastSnapshotSource=record.source;
  gptStage5LastSnapshotAt=record.at;
  gptStage5LastSnapshotAgeMs=0;
  return {...record,rows:record.rows.map(row=>({...row}))};
}

function gptStage5ReadSnapshot(target = null, maxAgeMs = GPT_STAGE5_SNAPSHOT_TTL_MS, {count=true} = {}) {
  if(!target?.ok){if(count)gptStage5SnapshotMissCount+=1;return null;}
  const key=chatgptWorkflowTargetKey(target);if(!key){if(count)gptStage5SnapshotMissCount+=1;return null;}
  const record=gptStage5SnapshotCache.get(key);
  if(!record){if(count)gptStage5SnapshotMissCount+=1;return null;}
  const age=Date.now()-Number(record.at||0);
  const requestedTtl=Math.max(500,Number(maxAgeMs||GPT_STAGE5_SNAPSHOT_TTL_MS));
  const surface=String(target?.surface||'').toLowerCase();
  const platform=String(target?.platform||'').toLowerCase();
  // Official-API targets expose a monotonic lastTimestamp and are safe to keep
  // hot longer. LINE is also cross-checked against the activity snapshot.
  // Browser-scraped surfaces stay intentionally short-lived so a newly painted
  // customer bubble can never be hidden behind an older Stage 5 cache row.
  const ttl=surface==='native-api'
    ? requestedTtl
    : (platform==='line'?Math.min(requestedTtl,8000):Math.min(requestedTtl,2500));
  const targetTimestamp=gptStage5TargetTimestamp(target);
  const staleByTarget=targetTimestamp && Number(record.maxTimestamp||record.targetTimestamp||0) && targetTimestamp>Number(record.maxTimestamp||record.targetTimestamp||0)+1;
  let staleByLineActivity=false;
  if(platform==='line'){
    const accountId=String(target?.accountId||'').trim(),chatId=String(target?.chatId||'').trim();
    const live=automationLineMessageSnapshots.get(`${accountId}:${chatId}`);
    staleByLineActivity=!!live && Number(live.at||0)>Number(record.at||0)+5;
  }
  if(age<0 || age>ttl || staleByTarget || staleByLineActivity){
    gptStage5SnapshotCache.delete(key);
    if(count)gptStage5SnapshotMissCount+=1;
    return null;
  }
  gptStage5SnapshotCache.delete(key);gptStage5SnapshotCache.set(key,record);
  if(count)gptStage5SnapshotHitCount+=1;
  gptStage5LastSnapshotSource=String(record.source||'cache');
  gptStage5LastSnapshotAt=Number(record.at||0);
  gptStage5LastSnapshotAgeMs=Math.max(0,age);
  return {...record,rows:Array.isArray(record.rows)?record.rows.map(row=>({...row})):[]};
}

function gptStage5TrimSmallMap(map, max = 18) {
  if(!(map instanceof Map) || map.size<=max)return;
  for(const key of [...map.keys()].slice(0,Math.max(0,map.size-max)))map.delete(key);
}

function scheduleGptStage5SnapshotPrefetch(target = null, {delayMs=70, force=false, reason='selection'} = {}) {
  if(!target?.ok || !chatgptWorkbenchVisible || !gptStage5SnapshotEligibleTarget(target)){gptStage5SnapshotPrefetchSkipCount+=1;return false;}
  const key=chatgptWorkflowTargetKey(target);if(!key){gptStage5SnapshotPrefetchSkipCount+=1;return false;}
  const cached=gptStage5ReadSnapshot(target,GPT_STAGE5_SNAPSHOT_TTL_MS,{count:false});
  if(!force && cached){gptStage5SnapshotPrefetchSkipCount+=1;return false;}
  const now=Date.now();
  const last=Number(gptStage5SnapshotPrefetchLastAt.get(key)||0);
  if(!force && (gptStage5SnapshotPrefetchInFlight.has(key) || now-last<GPT_STAGE5_PREFETCH_COOLDOWN_MS)){
    gptStage5SnapshotPrefetchSkipCount+=1;return false;
  }
  const oldTimer=gptStage5SnapshotPrefetchTimers.get(key);if(oldTimer)clearTimeout(oldTimer);
  const targetCopy={...target};
  const timer=setTimeout(()=>{
    gptStage5SnapshotPrefetchTimers.delete(key);
    if(!chatgptWorkbenchVisible)return;
    const task=(async()=>{
      gptStage5SnapshotPrefetchLastAt.set(key,Date.now());
      try{
        const rows=await recentMessagesForChatgptTarget(targetCopy,{bypassStage5Cache:true,stage5Prefetch:true});
        if(Array.isArray(rows)&&rows.length){
          gptStage5RememberSnapshot(targetCopy,rows,`prefetch:${reason}`);
          gptStage5SnapshotPrefetchCount+=1;
        }else gptStage5SnapshotPrefetchSkipCount+=1;
        return rows;
      }catch(error){
        gptStage5SnapshotPrefetchFailureCount+=1;
        return [];
      }
    })();
    gptStage5SnapshotPrefetchInFlight.set(key,task);
    task.finally(()=>{if(gptStage5SnapshotPrefetchInFlight.get(key)===task)gptStage5SnapshotPrefetchInFlight.delete(key);}).catch(()=>{});
  },Math.max(0,Number(delayMs)||0));
  timer.unref?.();
  gptStage5SnapshotPrefetchTimers.set(key,timer);
  gptStage5TrimSmallMap(gptStage5SnapshotPrefetchLastAt);
  return true;
}

async function gptStage5SnapshotRowsForTurn(target = null) {
  if(!gptStage5SnapshotEligibleTarget(target))return {rows:null,hit:false,source:'live-external',ageMs:0};
  const cached=gptStage5ReadSnapshot(target);
  if(cached?.rows?.length)return {rows:cached.rows,hit:true,source:String(cached.source||'cache'),ageMs:Math.max(0,Date.now()-Number(cached.at||0))};
  const key=target?.ok?chatgptWorkflowTargetKey(target):'';
  const inflight=key?gptStage5SnapshotPrefetchInFlight.get(key):null;
  if(inflight){
    gptStage5SnapshotJoinCount+=1;
    await Promise.race([Promise.resolve(inflight).catch(()=>null),waitMs(GPT_STAGE5_PREFETCH_JOIN_MS)]);
    const joined=gptStage5ReadSnapshot(target,GPT_STAGE5_SNAPSHOT_TTL_MS,{count:false});
    if(joined?.rows?.length){
      gptStage5SnapshotHitCount+=1;
      return {rows:joined.rows,hit:true,joined:true,source:String(joined.source||'prefetch-join'),ageMs:Math.max(0,Date.now()-Number(joined.at||0))};
    }
  }
  return {rows:null,hit:false,source:'live',ageMs:0};
}

function resetGptStage5ComposerReady(reason = '') {
  if(gptStage5ComposerWarmTimer){clearTimeout(gptStage5ComposerWarmTimer);gptStage5ComposerWarmTimer=null;}
  gptStage5ComposerReady={webContentsId:0,url:'',at:0,found:false,empty:false,targetKey:'',reason:String(reason||'')};
}

function gptStage5ComposerReadyForWindow(win = chatgptWorkbenchWindow) {
  if(!win || win.isDestroyed?.() || win.webContents?.isDestroyed?.())return false;
  const age=Date.now()-Number(gptStage5ComposerReady?.at||0);
  if(age<0||age>GPT_STAGE5_COMPOSER_READY_TTL_MS||!gptStage5ComposerReady?.found)return false;
  let id=0,url='';try{id=Number(win.webContents.id||0);url=String(win.webContents.getURL?.()||'')}catch{}
  return id===Number(gptStage5ComposerReady.webContentsId||0) && url===String(gptStage5ComposerReady.url||'');
}

function scheduleGptStage5ComposerWarm(target = null, delayMs = 90) {
  if(!chatgptWorkbenchVisible)return false;
  const win=chatgptWorkbenchWindow;
  if(!win || win.isDestroyed?.() || win.webContents?.isDestroyed?.() || win.webContents?.isLoadingMainFrame?.())return false;
  if(gptStage5ComposerWarmTimer)clearTimeout(gptStage5ComposerWarmTimer);
  const targetKey=target?.ok?chatgptWorkflowTargetKey(target):'';
  gptStage5ComposerWarmTimer=setTimeout(async()=>{
    gptStage5ComposerWarmTimer=null;
    const current=chatgptWorkbenchWindow;
    if(!chatgptWorkbenchVisible||!current||current.isDestroyed?.()||current.webContents?.isDestroyed?.()||current.webContents?.isLoadingMainFrame?.())return;
    try{
      const result=await current.webContents.executeJavaScript(chatgptComposerProbeScript(),true);
      let url='';try{url=String(current.webContents.getURL?.()||'')}catch{}
      gptStage5ComposerReady={
        webContentsId:Number(current.webContents.id||0),url,at:Date.now(),
        found:!!result?.found,empty:!normalizeChatgptText(result?.existing||''),targetKey
      };
      if(result?.found)gptStage5ComposerWarmCount+=1;else gptStage5ComposerWarmFailureCount+=1;
    }catch{gptStage5ComposerWarmFailureCount+=1;resetGptStage5ComposerReady('warm-error');}
  },Math.max(0,Number(delayMs)||0));
  gptStage5ComposerWarmTimer.unref?.();
  return true;
}

function clearGptStage5EphemeralCaches(reason = '') {
  for(const timer of gptStage5SnapshotPrefetchTimers.values())try{clearTimeout(timer)}catch{}
  gptStage5SnapshotPrefetchTimers.clear();
  gptStage5SnapshotCache.clear();
  resetGptStage5ComposerReady(reason||'clear');
}

async function prefetchGptStage3RecentContexts({ limit = GPT_STAGE3_CONTEXT_CACHE_MAX } = {}) {
  if(gptStage3ContextPrefetchInFlight)return {ok:true,skipped:true,reason:'in-flight'};
  const settings=teamSyncSettings();
  if(!gptOrchestrator.settingsFor(settings)||!gptOrchestratorRemoteReady)return {ok:false,skipped:true,error:'orchestrator-not-ready'};
  gptStage3ContextPrefetchInFlight=true;
  try{
    const result=await gptOrchestrator.recentContexts(settings,limit,1800);
    if(!result?.ok)throw new Error(result?.error||'recent-context-prefetch-failed');
    let stored=0;
    for(const item of Array.isArray(result.items)?result.items:[]){
      const key=String(item?.targetKey||'').trim();if(!key)continue;
      if(gptStage3CacheContext(key,item))stored+=1;
    }
    gptStage3ContextPrefetchCount+=1;gptStage3LastContextFetchAt=Date.now();gptStage3LastContextError='';
    return {ok:true,stored};
  }catch(error){
    gptStage3ContextFetchFailureCount+=1;gptStage3LastContextError=String(error?.message||error||'').slice(0,240);
    return {ok:false,error:gptStage3LastContextError};
  }finally{gptStage3ContextPrefetchInFlight=false;}
}

function warmGptStage3ContextForTarget(target = null) {
  if(!target?.ok)return false;
  const targetKey=chatgptWorkflowTargetKey(target);if(!targetKey)return false;
  const cached=gptStage3ContextCache.get(targetKey);
  if(cached){
    gptStage3ContextCache.delete(targetKey);gptStage3ContextCache.set(targetKey,cached);
    gptStage3ContextCacheHitCount+=1;
    return true;
  }
  const now=Date.now();
  const lastAttempt=Number(gptStage5ContextFetchLastAttempt.get(targetKey)||0);
  if(gptStage5ContextFetchInFlight.has(targetKey) || now-lastAttempt<GPT_STAGE5_CONTEXT_FETCH_DEDUPE_MS){
    gptStage5ContextFetchDedupeCount+=1;
    return false;
  }
  const settings=teamSyncSettings();if(!gptOrchestrator.settingsFor(settings)||!gptOrchestratorRemoteReady)return false;
  gptStage3ContextCacheMissCount+=1;
  gptStage5ContextFetchLastAttempt.set(targetKey,now);
  gptStage5TrimSmallMap(gptStage5ContextFetchLastAttempt);
  const task=(async()=>{
    try{
      const result=await gptOrchestrator.getContext(settings,targetKey,1400);
      if(result?.ok&&result?.found){gptStage3CacheContext(targetKey,result);gptStage3LastContextFetchAt=Date.now();gptStage3LastContextError='';}
    }catch(error){gptStage3ContextFetchFailureCount+=1;gptStage3LastContextError=String(error?.message||error||'').slice(0,240);}
  })();
  gptStage5ContextFetchInFlight.set(targetKey,task);
  task.finally(()=>{if(gptStage5ContextFetchInFlight.get(targetKey)===task)gptStage5ContextFetchInFlight.delete(targetKey);}).catch(()=>{});
  return false;
}

function chatgptStage3PrewarmEligible() {
  if(fullQuitRequested||quittingAfterFlush)return false;
  if(chatgptWorkbenchWindow&&!chatgptWorkbenchWindow.isDestroyed?.())return false;
  const cfg=chatgptWorkbenchConfig();
  const bindingCount=Object.keys(cfg.bindings&&typeof cfg.bindings==='object'?cfg.bindings:{}).length;
  const pendingCount=Object.keys(cfg.pendingAutoBinds&&typeof cfg.pendingAutoBinds==='object'?cfg.pendingAutoBinds:{}).length;
  return bindingCount>0||pendingCount>0||String(cfg.lastUrl||'')!==String(CHATGPT_HOME_URL||'');
}

function scheduleChatgptStage3HiddenPrewarm(delayMs = 12000) {
  // V1.27.250: GPT window creation is manual-only. Keep this function as a
  // compatibility no-op so startup cannot create a hidden ChatGPT window.
  if(chatgptStage3PrewarmTimer){clearTimeout(chatgptStage3PrewarmTimer);chatgptStage3PrewarmTimer=null;}
  chatgptStage3PrewarmSkipCount+=1;
  return false;
}


function cancelChatgptStage4Hibernate(reason = '') {
  if(chatgptStage4HibernateTimer){clearTimeout(chatgptStage4HibernateTimer);chatgptStage4HibernateTimer=null;}
  chatgptStage4HibernateScheduledAt=0;
  return !!reason;
}

function cancelChatgptStage4RouteCoalesce(reason = '') {
  chatgptStage4RouteCoalesceToken += 1;
  if(chatgptStage4RouteCoalesceTimer){clearTimeout(chatgptStage4RouteCoalesceTimer);chatgptStage4RouteCoalesceTimer=null;chatgptStage4RouteCoalesceDropCount+=1;}
  return !!reason;
}

function chatgptStage4WorkflowBusy() {
  return !!(
    (chatgptAcceptedTurnResponseWatchers?.size||0) ||
    (chatgptQueuedJapaneseSendIntents?.size||0) ||
    (chatgptGenerationBusyDeferred?.size||0) ||
    (chatgptManualCustomerDraftWatchers?.size||0) ||
    (chatgptCustomerBootstrapInFlight?.size||0) ||
    (chatgptPersonaDraftInFlight?.size||0) ||
    chatgptWorkbenchDeferredBind ||
    chatgptWorkbenchFastRouteActive ||
    String(chatgptGenerationWatch?.signature||'')
  );
}

async function hibernateChatgptStage4IfIdle(reason = 'hidden-idle') {
  chatgptStage4HibernateTimer=null;chatgptStage4HibernateScheduledAt=0;
  const win=chatgptWorkbenchWindow;
  if(chatgptWorkbenchVisible || !win || win.isDestroyed?.() || win.webContents?.isDestroyed?.()){
    chatgptStage4HibernateSkipCount+=1;return {ok:false,skipped:true,reason:'visible-or-no-window'};
  }
  if(chatgptLoginProtectionActive || chatgptStage4WorkflowBusy()){
    chatgptStage4HibernateBusySkipCount+=1;
    scheduleChatgptStage4Hibernate('busy-retry',60000);
    return {ok:false,skipped:true,reason:'workflow-busy'};
  }
  let draft='';
  try{
    if(isChatgptUrl(String(win.webContents.getURL?.()||'')) && !win.webContents.isLoadingMainFrame?.()){
      const state=await win.webContents.executeJavaScript(chatgptComposerReadScript(),true).catch(()=>null);
      draft=normalizeChatgptText(state?.text||'');
    }
  }catch{}
  if(draft){
    chatgptStage4HibernateDraftSkipCount+=1;
    scheduleChatgptStage4Hibernate('draft-retry',90000);
    return {ok:false,skipped:true,reason:'unsent-draft'};
  }
  let url='';try{url=String(win.webContents.getURL?.()||'')}catch{}
  if(isChatgptUrl(url) && !isChatgptTransientConversationUrl(url)){
    chatgptWorkbenchConfig().lastUrl=url;
    saveConfig(config);
  }
  stopChatgptTargetPolling();
  stopChatgptOverlayFollow();
  stopChatgptWorkbenchHealthWatch();
  cancelChatgptStage4RouteCoalesce('hibernate');
  clearGptStage5EphemeralCaches('stage4-hibernate');
  // V1.27.252: soft-hibernate only. Keep ONE persistent BrowserWindow and the
  // same ChatGPT renderer/session alive while hidden. Destroy/recreate cycles
  // made every later customer look like a brand-new GPT window and amplified
  // ChatGPT load failures. We still stop polling/watchers and clear ephemeral
  // caches above, so hidden idle cost stays bounded without replacing the page.
  try{chatgptCopyOverlayWindow?.hide?.()}catch{}
  chatgptStage4HibernatingDestroy=false;
  chatgptStage4LastHibernateAt=Date.now();
  chatgptStage4LastHibernateReason=String(reason||'hidden-idle');
  chatgptStage4WakePending=false;
  chatgptStage4HibernateCount+=1;
  try{win.hide()}catch{}
  applyChatgptWorkbenchPerformanceMode('stage4-soft-hibernate-v252');
  pushChatgptStabilityEvent('gpt-single-window-soft-hibernate-v252',{version:CHATGPT_SINGLE_PERSISTENT_WINDOW_VERSION,reason:chatgptStage4LastHibernateReason});
  return {ok:true,hibernated:true,soft:true,persistentWindow:true,reason:chatgptStage4LastHibernateReason};
}

function scheduleChatgptStage4Hibernate(reason = 'hidden-idle', delayMs = CHATGPT_STAGE4_HIDDEN_HIBERNATE_MS) {
  cancelChatgptStage4Hibernate('reschedule');
  if(chatgptWorkbenchVisible)return false;
  const win=chatgptWorkbenchWindow;
  if(!win || win.isDestroyed?.())return false;
  const delay=Math.max(15000,Number(delayMs)||CHATGPT_STAGE4_HIDDEN_HIBERNATE_MS);
  chatgptStage4HibernateScheduledAt=Date.now()+delay;
  chatgptStage4HibernateTimer=setTimeout(()=>hibernateChatgptStage4IfIdle(reason).catch(()=>false),delay);
  chatgptStage4HibernateTimer.unref?.();
  return true;
}

function scheduleChatgptStage4CoalescedRoute(win,target,binding,{force=false,delayMs=CHATGPT_STAGE4_ROUTE_COALESCE_MS}={}) {
  if(!win || win.isDestroyed?.() || win.webContents?.isDestroyed?.() || !target?.ok)return {started:false,reason:'no-window'};
  const token=++chatgptStage4RouteCoalesceToken;
  if(chatgptStage4RouteCoalesceTimer){clearTimeout(chatgptStage4RouteCoalesceTimer);chatgptStage4RouteCoalesceDropCount+=1;}
  chatgptStage4RouteCoalesceCount+=1;
  const targetCopy={...target};
  const bindingCopy=binding&&typeof binding==='object'?{...binding}:binding;
  chatgptStage4RouteCoalesceTimer=setTimeout(()=>{
    chatgptStage4RouteCoalesceTimer=null;
    if(token!==chatgptStage4RouteCoalesceToken || !chatgptWorkbenchVisible)return;
    startChatgptFastSelectionRoute(win,targetCopy,bindingCopy,{force:!!force,bypassCoalesce:true});
  },Math.max(CHATGPT_STAGE4_ROUTE_COALESCE_MS,Number(delayMs||CHATGPT_STAGE4_ROUTE_COALESCE_MS)));
  chatgptStage4RouteCoalesceTimer.unref?.();
  return {started:true,queued:true,reason:'latest-wins-coalesced'};
}

