      cfg.receptionFlow=String(v.receptionFlow||cfg.receptionFlow||DEFAULT_CHATGPT_RECEPTION_FLOW).replace(/\r\n?/g,'\n').trim().slice(0,12000)||DEFAULT_CHATGPT_RECEPTION_FLOW;
      cfg.serverRulesVersion=Number(remote.version||0);cfg.serverRulesUpdatedAt=String(remote.updatedAt||'');saveConfig(config);
