            if (ir.width<18 || ir.width>80 || ir.height<18 || ir.height>80) continue;
            if (ir.bottom<hr.top-30 || ir.top>hr.bottom+30) continue;
            const vertical=Math.abs(((ir.top+ir.bottom)/2)-cy);
            let side='', horizontal=Infinity;
            if (ir.right<=hr.left+14 && hr.left-ir.right<180) { side='left'; horizontal=Math.max(0,hr.left-ir.right); }
            else if (ir.left>=hr.right-14 && ir.left-hr.right<180) { side='right'; horizontal=Math.max(0,ir.left-hr.right); }
