  if(!draft){const setResult=await callLineBridgeForAccount(accountId,'setInputText',text);if(setResult?.ok===false)throw new Error(setResult?.error||'无法写入 LINE 输入框。');}
  const expected=String(text||'').replace(/\s+/g,' ').trim();let matchingBefore=0;
