function nativeApiGptSnapshotKey(target = null) {
  return nativeApiTargetValid(target) ? String(speechLibraryTargetKey(target) || '').trim() : '';
}
function rememberNativeApiGptConversationSnapshot(target = null, rows = [], source = '') {
  const key=nativeApiGptSnapshotKey(target);
  if(!key)return null;
  const items=(Array.isArray(rows)?rows:[]).slice(-320).map(row=>({...row}));
  let maxTimestamp=0;
  for(const row of items)maxTimestamp=Math.max(maxTimestamp,Number(row?.timestampMs||row?.timestamp||0)||0);
  const record={key,at:Date.now(),rows:items,maxTimestamp,source:String(source||'').slice(0,80)};
  nativeApiGptConversationSnapshots.set(key,record);
  if(nativeApiGptConversationSnapshots.size>80){
    const ordered=[...nativeApiGptConversationSnapshots.entries()].sort((a,b)=>Number(a[1]?.at||0)-Number(b[1]?.at||0));
    for(const [oldKey] of ordered.slice(0,Math.max(0,ordered.length-60)))nativeApiGptConversationSnapshots.delete(oldKey);
  }
  return record;
}
function readNativeApiGptConversationSnapshot(target = null, maxAgeMs = CHATGPT_NATIVE_API_SNAPSHOT_TTL_MS) {
  const key=nativeApiGptSnapshotKey(target);
  const record=key?nativeApiGptConversationSnapshots.get(key):null;
  if(!record)return null;
  const age=Date.now()-Number(record.at||0);
  if(age<0||age>Math.max(500,Number(maxAgeMs||CHATGPT_NATIVE_API_SNAPSHOT_TTL_MS)))return null;
  const targetTimestamp=Number(target?.lastTimestampMs||target?.timestampMs||target?.timestamp||0)||0;
  if(targetTimestamp&&Number(record.maxTimestamp||0)&&targetTimestamp>Number(record.maxTimestamp||0)+1)return null;
  return {...record,rows:Array.isArray(record.rows)?record.rows.map(row=>({...row})):[]};
}

// V1.27.109: attach the operator's CRM stage/service status directly to each
// official-API customer row. This is local config data only; no CRM content is
// sent to Meta/LINE or the VPS.
function nativeApiConversationCrmSummary(item = {}) {
  const accountId = normalizeCrmText(item?.accountId, 128);
  const chatId = normalizeCrmText(item?.chatId, 300);
  const displayName = normalizeCrmText(item?.displayName, 180);
  if (!accountId || (!chatId && !displayName)) return { crmStage:'', crmServiceStatus:'auto' };
  try {
    const match = getCrmContactForConversation(accountId, chatId, displayName);
    const contact = match?.contact || {};
    const platform = String(item?.platform || '').trim().toLowerCase();
    const stage = platform === 'line' ? normalizeLineCrmStage(contact.stage) : normalizeNonLineCrmStage(contact.stage);
    const serviceStatus = ['auto','waiting','active','done','paused','blacklist'].includes(String(contact.serviceStatus || '')) ? String(contact.serviceStatus) : 'auto';
    return { crmStage:stage || '', crmServiceStatus:serviceStatus };
  } catch { return { crmStage:'', crmServiceStatus:'auto' }; }
}
function nativeApiDecorateConversationCrm(result = {}) {
  const items = (Array.isArray(result?.items) ? result.items : []).map(item => ({ ...item, ...nativeApiConversationCrmSummary(item) }));
  return { ...(result || {}), items };
}

async function platformCrmContact(payload = {}) {
  const platform = String(payload?.platform || '').trim().toLowerCase();
  const accountId = normalizeCrmText(payload?.accountId, 128);
  const chatId = normalizeCrmText(payload?.chatId, 300);
  const displayName = normalizeCrmText(payload?.displayName, 180);
  const account = appCenterAccountById(accountId) || nativeApiVirtualAccount(accountId, platform);
  if (!account || account.platform !== platform) throw new Error('应用账号不存在。');
  const aggregateItem = (platformAggregateMap(platform).get(accountId)?.conversations || []).find(item =>
    (chatId && String(item?.chatId || '') === chatId) ||
    (displayName && String(item?.displayName || '') === displayName)
  ) || {};
  const resolvedChatId = chatId || normalizeCrmText(aggregateItem?.chatId, 300);
  const resolvedDisplayName = displayName || normalizeCrmText(aggregateItem?.displayName, 180);
  let match = getCrmContactForConversation(accountId, resolvedChatId, resolvedDisplayName);
  if (platform === 'metabusiness' && match.contact && typeof mergeCrmAutoFacts === 'function') {
    const healed = mergeCrmAutoFacts(match.contact, {}, { displayName:resolvedDisplayName });
    if (healed.changed) {
      const crm = ensureCrmConfig();
      crm.contacts[match.stableKey] = healed.contact;
      saveConfig(config);
      match = { ...match, contact:healed.contact };
    }
  }

  // V1.27.33 REAL aggregate-CRM entry point. The aggregate right panel calls
  // platform-crm-contact (not currentPlatformChatCrm), so V1.27.31/32 live
  // backfill never ran in the exact UI the operator was testing. Ask the live
  // Meta preload for the current visible chat HERE, verify that it is still the
  // requested customer, then commit strong facts and run the unified extractor
  // before returning the panel record. This makes "私は44です" repair the
  // stale 52 on the first aggregate-panel hydration without requiring another
  // customer message or a different CRM API path.
  if (platform === 'metabusiness') {
    try {
      const envelope = await externalRecentMessagesEnvelopeRequest(accountId, 1200);
      const liveName = normalizeCrmText(envelope?.identity?.name, 180);
      const liveChatId = normalizeCrmText(envelope?.identity?.chatId, 520) || metaBusinessCanonicalChatId(envelope?.identity?.url || '');
      const targetName = normalizeCrmText(resolvedDisplayName, 180);
      // V1.27.178: live-panel backfill is a write path. A matching name is not
      // enough; only the same durable conversation identity may authorize it.
      const sameName = !!liveName && !!targetName && liveName.toLocaleLowerCase() === targetName.toLocaleLowerCase();
      const sameIdentity = sameDurableConversationId(liveChatId, resolvedChatId);
      const identityMatches = sameName && sameIdentity;
      if (identityMatches) {
        const liveMessages = Array.isArray(envelope?.messages) ? envelope.messages.slice(-30) : [];
        let extractionMessages = liveMessages;
        const hintedAge = normalizeCrmText(envelope?.explicitFacts?.age, 16);
        const hintedEvidence = normalizeCrmText(envelope?.explicitFacts?.ageEvidence, 1200);
        if (/^\d{2,3}$/.test(hintedAge) && hintedEvidence) {
          const alreadyPresent = liveMessages.some(row => ['customer','incoming'].includes(String(row?.role || '').toLowerCase()) && normalizeCrmText(row?.text,1200) === hintedEvidence);
          if (!alreadyPresent) extractionMessages = [...liveMessages, { role:'customer', text:hintedEvidence }].slice(-30);
          commitMetaBusinessExplicitAgeAliases({ accountId, chatId:resolvedChatId, displayName:resolvedDisplayName, explicitFacts:envelope?.explicitFacts });
        }
        if (extractionMessages.length) {
          applyCrmAutoExtraction({ platform, accountId, chatId:resolvedChatId, displayName:resolvedDisplayName, messages:extractionMessages });
        }
        match = getCrmContactForConversation(accountId, resolvedChatId, resolvedDisplayName);
      }
    } catch (error) {
      console.debug('[MB aggregate CRM panel live backfill skipped]', error?.message || error);
    }
  }

  if (facebookCrmSurface(platform)) {
    match = reconcileFacebookCrmCrossSurface(match, { platform, accountId, chatId:resolvedChatId, displayName:resolvedDisplayName });
  }
  const serverProfile=await hydrateServerCustomerProfileForTarget({platform,accountId,chatId:resolvedChatId,displayName:resolvedDisplayName}).catch(()=>null);
  if(serverProfile)match={...match,contact:serverProfile};

  const fallbackObservedAt = externalConversationTimeMs(aggregateItem.lastMessageAt, dashboardStatsTimestamp(aggregateItem.capturedAt) || Date.now());
  const firstContactAt = externalFirstContactAt(aggregateItem, match.contact?.createdAt);
  const lastIncomingAt = Number(aggregateItem.lastIncomingAt || 0) || fallbackObservedAt || aggregateItem.lastMessageAt || '';
  return { ok:true, platform, accountId, accountName:account.name, chatId:resolvedChatId, displayName:resolvedDisplayName, contactKey:match.stableKey, contact:match.contact, firstContactAt, lastIncomingAt };
}

async function backfillPlatformCrmFromHistory(raw = {}) {
  const platform = String(raw?.platform || '').trim().toLowerCase();
  const accountId = normalizeCrmText(raw?.accountId, 128);
  const chatId = normalizeCrmText(raw?.chatId, 500);
  const displayName = normalizeCrmText(raw?.displayName, 180);
  const handle = normalizeCrmText(raw?.handle, 180).replace(/^@/, '');
  const account = appCenterAccountById(accountId);
  if (!account || String(account.platform || '') !== platform) throw new Error('应用账号不存在。');
  if (!chatId && !displayName) throw new Error('客户身份为空。');
  const target = { ok:true, surface:'external-aggregate', platform, platformName:APP_CENTER_PLATFORMS[platform]?.name || platform, accountId, accountName:String(account.name || ''), chatId, displayName, handle };

  // First capture whatever history is currently visible. This uses the existing
  // sealed history bridge and does not require a new preload API.
  if (platform === 'line') {
    try {
      const entries = await callLineBridgeForAccount(accountId, 'getRecentArchiveEntries', CHAT_HISTORY_MAX_CAPTURE_ITEMS) || [];
      await appendChatHistorySnapshot(target, entries);
    } catch {}
  } else {
    try {
      const entries = await externalChatHistorySnapshotRequest(accountId, 2600);
      await appendChatHistorySnapshot(target, entries);
    } catch {}
  }

  const conversationId = chatHistoryConversationId(target);
  const archived = readChatHistoryRecords(conversationId, 1200)
    .filter(row => String(row?.type || 'text') === 'text' && normalizeCrmText(row?.text, 12000))
    .map(row => {
      const capturedMs = aggregateTimestampMs(row?.capturedAt);
      const sourceMs = aggregateTimestampMs(row?.delivered) || externalConversationTimeMs(row?.nativeTime, capturedMs || Date.now());
      return {
        role:String(row?.role || '').toLowerCase() === 'me' ? 'me' : 'customer',
        text:normalizeCrmText(row?.text, 12000),
        translatedText:normalizeCrmTranslatedText(row?.translatedText || ''),
        messageId:normalizeCrmText(row?.sourceKey || row?.id, 240),
        messageTimestamp:sourceMs ? new Date(sourceMs).toISOString() : '',
        delivered:sourceMs || 0,
        historyBackfill:true
      };
    });
  if (!archived.length) return { ok:false, error:'当前还没有可回溯的聊天记录，请先打开该客户聊天后重试。' };

  // Run in bounded chunks so old facts are not lost merely because the latest
  // visible DOM snapshot only contains a handful of messages. The common CRM
  // engine owns manual-field precedence, long-term memory and LINE intent.
  let lastResult = null;
  let changed = false;
  for (let i = 0; i < archived.length; i += 80) {
    const chunk = archived.slice(i, i + 80);
    const result = applyCrmAutoExtraction({ platform, accountId, chatId, displayName, messages:chunk, historyBackfill:true });
    if (result?.changed) changed = true;
    if (result) lastResult = result;
  }
  return { ok:true, changed, scanned:archived.length, contact:lastResult?.contact || crmContactSummary(getCrmContactForConversation(accountId, chatId, displayName).contact || {}) };
}

function savePlatformCrmContact(raw = {}) {
  if (String(raw?._action || '') === 'mark-read') return markExternalConversationManualRead(raw);
  if (String(raw?._action || '') === 'backfill-history') return backfillPlatformCrmFromHistory(raw);
  if (String(raw?._action || '') === 'native-api-stage-only') {
    const platform = String(raw?.platform || '').trim().toLowerCase();
    const accountId = normalizeCrmText(raw?.accountId, 128);
    const chatId = normalizeCrmText(raw?.chatId, 300);
    const displayName = normalizeCrmText(raw?.displayName, 180);
    const existing = getCrmContactForConversation(accountId, chatId, displayName)?.contact || {};
    return savePlatformCrmContact({
      ...raw, _action:'',
      name:existing.name || '', serviceStatus:existing.serviceStatus || 'auto', tags:existing.tags || '',
      region:existing.region || '', age:existing.age || '', occupation:existing.occupation || '',
      interests:existing.interests || '', note:existing.note || '', language:existing.language || 'ja',
      targetLineAccountId:existing.targetLineAccountId || '', targetLineAccountName:existing.targetLineAccountName || ''
    });
  }
  const platform = String(raw?.platform || '').trim().toLowerCase();
  const accountId = normalizeCrmText(raw?.accountId, 128);
  const chatId = normalizeCrmText(raw?.chatId, 300);
  const displayName = normalizeCrmText(raw?.displayName, 180);
  const account = appCenterAccountById(accountId) || nativeApiVirtualAccount(accountId, platform);
  if (!account || account.platform !== platform) throw new Error('应用账号不存在。');
  if (!chatId && !displayName) throw new Error('客户身份为空。');
  const crm = ensureCrmConfig();
  const match = getCrmContactForConversation(accountId, chatId, displayName);
  const existing = match.contact || {};
  const now = new Date().toISOString();
  let status = normalizeCrmText(raw?.serviceStatus, 20);
  const stage = platform === 'line' ? normalizeLineCrmStage(raw?.stage) : normalizeNonLineCrmStage(raw?.stage);
  if (platform === 'line' && /^(?:黑名单|blacklist|ブラックリスト)$/i.test(stage)) status = 'blacklist';
  const existingStage = platform === 'line' ? normalizeLineCrmStage(existing.stage) : normalizeNonLineCrmStage(existing.stage);
  const autoLifecycle = existing._autoLifecycle && typeof existing._autoLifecycle === 'object' ? { ...existing._autoLifecycle } : {};
  // V1.23.66: if the operator explicitly changes the stage in CRM, that manual
  // decision becomes authoritative. Automatic lifecycle inference remains
  // forward-only but will no longer move this customer until a later manual
  // stage change says otherwise.
  if (existing?.stage && stage !== existingStage) {
    autoLifecycle.stageLocked = true;
    autoLifecycle.manualStage = stage;
    autoLifecycle.stageUpdatedAt = now;
    autoLifecycle.stageReason = 'operator-manual-stage';
  }
  const rawTargetLineAccountId = normalizeCrmText(raw?.targetLineAccountId, 128);
  const baseLineStageState = platform === 'line'
    ? {
        lineIntent:normalizeCrmText(existing.lineIntent, 30) || 'none',
        lineIntentScore:Math.max(0, Math.min(100, Number(existing.lineIntentScore || 0) || 0)),
        lineProgress:normalizeCrmText(existing.lineProgress, 40) || 'not_started',
        lineEvidence:normalizeCrmText(existing.lineEvidence, 360),
        _lineJourney:existing._lineJourney && typeof existing._lineJourney === 'object' ? existing._lineJourney : {},
        _linePauseSnapshot:existing._linePauseSnapshot && typeof existing._linePauseSnapshot === 'object' ? existing._linePauseSnapshot : null,
        restored:false, targetLineAccountId:'', targetLineAccountName:''
      }
    : synchronizeLineStateForStage(existing, stage, now);
  const lineStageState = platform === 'line'
    ? baseLineStageState
    : applyLeadStageLineTerminalState(existing, stage, baseLineStageState, now);
  const effectiveTargetLineAccountId = rawTargetLineAccountId
    || (lineStageState.restored ? normalizeCrmText(lineStageState.targetLineAccountId, 128) : '');
  const targetLineAccount = effectiveTargetLineAccountId ? (config.accounts || []).find(item => item.id === effectiveTargetLineAccountId) : null;
  const targetLineAccountName = effectiveTargetLineAccountId
    ? normalizeCrmText(
        targetLineAccount?.displayNameOverride
        || targetLineAccount?.name
        || raw?.targetLineAccountName
        || (lineStageState.restored ? lineStageState.targetLineAccountName : ''),
        160
      )
    : '';
  const aggregateForStatus = (platformAggregateMap(platform).get(accountId)?.conversations || []).find(item =>
    (chatId && String(item?.chatId || '') === chatId) ||
    (displayName && String(item?.displayName || '') === displayName)
  ) || {};
  const priorBoundary = existing?._serviceStatusBoundary && typeof existing._serviceStatusBoundary === 'object' ? existing._serviceStatusBoundary : null;
  const serviceStatusBoundary = status === 'done'
    ? {
        at:Date.now(),
        lastIncomingAt:Math.max(0, Number(aggregateForStatus?.lastIncomingAt || 0) || 0),
        unreadCount:Math.max(0, Number(aggregateForStatus?.unreadCount || 0) || 0)
      }
    : (status === normalizeCrmText(existing?.serviceStatus, 20) ? priorBoundary : null);
  const record = {
    key: match.stableKey,
    platform,
    accountId,
    chatId,
    displayName,
    name: normalizeCrmText(raw?.name, 160),
    stage,
    serviceStatus: ['auto','waiting','active','done','paused','blacklist'].includes(status) ? status : 'auto',
    tags: stage === 'LINE已添加' ? ensureAddedLineCrmTag(raw?.tags) : removeAddedLineCrmTag(raw?.tags),
    targetLineAccountId: nonLineStageUsesTargetLine(stage) ? effectiveTargetLineAccountId : '',
    targetLineAccountName: nonLineStageUsesTargetLine(stage) ? targetLineAccountName : '',
    ...crmBusinessFields(platform, stage),
    language: normalizeCrmText(raw?.language, 20) || 'ja',
    region: normalizeCrmText(raw?.region, 100),
    age: normalizeCrmText(raw?.age, 20),
    occupation: normalizeCrmText(raw?.occupation, 120),
    interests: normalizeCrmText(raw?.interests, 500),
    lineIntent: lineStageState.lineIntent,
    lineIntentScore: lineStageState.lineIntentScore,
    lineProgress: lineStageState.lineProgress,
    lineEvidence: lineStageState.lineEvidence,
    memoryItems: Array.isArray(existing.memoryItems) ? existing.memoryItems.slice(-80) : [],
    memorySummary: normalizeCrmText(existing.memorySummary, 1200) || buildMemorySummary(existing.memoryItems || [], 10),
    note: normalizeCrmText(raw?.note, 8000),
    // V1.23.16: internal ownership metadata lets automatic extraction update
    // its own prior values while never overwriting later manual edits.
    _autoExtract: existing._autoExtract && typeof existing._autoExtract === 'object' ? existing._autoExtract : {},
    _autoLifecycle: autoLifecycle,
    _lineJourney: lineStageState._lineJourney,
    _linePauseSnapshot: lineStageState._linePauseSnapshot,
    _serviceStatusBoundary: serviceStatusBoundary,
    createdAt: existing.createdAt || now,
    updatedAt: now
  };
  record.summary = buildAutoSummary(record, stage);
  crm.contacts[match.stableKey] = record;
  if (match.legacyMatched && match.legacyKey && match.legacyKey !== match.stableKey && crm.contacts[match.legacyKey]) delete crm.contacts[match.legacyKey];
  saveConfig(config);
  teamSyncQueueCrmContact(record, { platform, accountId, accountName:teamSyncAccountName(accountId, platform), chatId, displayName });
  let savedRecord = record;
  if (facebookCrmSurface(platform)) {
    const unified = reconcileFacebookCrmCrossSurface({ stableKey:match.stableKey, legacyKey:match.legacyKey, contact:record }, { platform, accountId, chatId, displayName });
    savedRecord = unified?.contact || record;
    try { sendPlatformAggregateUpdated('metabusiness'); } catch {}
  }
  sendPlatformAggregateUpdated(platform);
  captureCustomerNumberPayload(raw, { sourceType:platform === 'whatsapp' ? 'whatsapp' : 'import', accountId, accountName:account.name, groupId:raw?.groupId, groupName:raw?.groupName, groupType:raw?.groupType });
  return savedRecord;
}


function crmAutoExtractTokenList(value = '') {
  return String(value || '')
    .split(/[,，、;；/|\n]+/)
    .map(item => item.trim())
    .filter(Boolean);
}

function crmAutoExtractionChanges(before = {}, after = {}) {
  const labels = { name:'姓名', region:'地区', age:'年龄', occupation:'工作' };
  const changes = [];
  for (const field of ['name','region','age','occupation']) {
    const oldValue = normalizeCrmText(before?.[field], field === 'age' ? 20 : 180);
    const newValue = normalizeCrmText(after?.[field], field === 'age' ? 20 : 180);
    if (!newValue || oldValue === newValue) continue;
    changes.push({
      field,
      label: labels[field],
      kind: oldValue ? 'updated' : 'added',
      before: oldValue,
      after: newValue
    });
  }
  const oldInterests = crmAutoExtractTokenList(before?.interests);
  const newInterests = crmAutoExtractTokenList(after?.interests);
  const oldKeys = new Set(oldInterests.map(item => item.toLocaleLowerCase()));
  const addedInterests = newInterests.filter(item => !oldKeys.has(item.toLocaleLowerCase()));
  if (addedInterests.length) {
    changes.push({
      field:'interests',
      label:'兴趣',
      kind:'added',
      before:normalizeCrmText(before?.interests, 500),
      after:normalizeCrmText(after?.interests, 500),
      added:addedInterests.slice(0, 12)
    });
  }
  return changes;
}


function crmLineJourneyMerge(existing = {}, detected = {}, now = new Date().toISOString()) {
  const currentIntent = normalizeCrmText(existing?.lineIntent, 30) || 'none';
  const currentProgress = normalizeCrmText(existing?.lineProgress, 40) || 'not_started';
  const hasDetection = Number(detected?.eventCount || 0) > 0;
  let intent = currentIntent;
  let progress = currentProgress;
  let score = Math.max(0, Math.min(100, Number(existing?.lineIntentScore || 0) || 0));
  let evidence = normalizeCrmText(existing?.lineEvidence, 360);
  let reason = normalizeCrmText(existing?._lineJourney?.reason, 300);

  if (hasDetection) {
    const nextProgress = normalizeCrmText(detected?.progress, 40) || 'not_started';
    const nextIntent = normalizeCrmText(detected?.intent, 30) || 'none';
    // Confirmed addition is terminal. Otherwise explicit negative feedback may
    // supersede an earlier intent/invite, while an old waiting-add state is not
    // downgraded merely because a later snapshot only contains "I use LINE".
    if (currentProgress === 'added' || nextProgress === 'added') {
      progress = 'added'; intent = 'high'; score = 100;
    } else if (nextProgress === 'declined') {
      progress = 'declined'; intent = 'negative'; score = 0;
    } else if (nextProgress === 'waiting_add') {
      progress = 'waiting_add'; intent = nextIntent === 'high' ? 'high' : (currentIntent === 'high' ? 'high' : nextIntent); score = Math.max(score, Number(detected?.score || 0));
    } else if (nextProgress === 'interested') {
      if (currentProgress !== 'waiting_add') progress = 'interested';
      if (nextIntent === 'high' || currentIntent !== 'high') intent = nextIntent;
      score = Math.max(score, Number(detected?.score || 0));
    }
    if (detected?.evidence) evidence = normalizeCrmText(detected.evidence, 360);
    if (detected?.reason) reason = normalizeCrmText(detected.reason, 300);
  }

  return {
    lineIntent:intent || 'none',
    lineProgress:progress || 'not_started',
    lineIntentScore:Math.max(0, Math.min(100, Number(score || 0) || 0)),
    lineEvidence:evidence,
    _lineJourney:{
      ...(existing?._lineJourney && typeof existing._lineJourney === 'object' ? existing._lineJourney : {}),
      intent:intent || 'none', progress:progress || 'not_started', score:Math.max(0, Math.min(100, Number(score || 0) || 0)),
      evidence, reason, lastDetectedEvent:normalizeCrmText(detected?.lastEvent, 40),
      updatedAt:hasDetection ? now : normalizeCrmText(existing?._lineJourney?.updatedAt, 60)
    },
    changed:intent !== currentIntent || progress !== currentProgress || score !== Math.max(0, Math.min(100, Number(existing?.lineIntentScore || 0) || 0)) || evidence !== normalizeCrmText(existing?.lineEvidence, 360)
  };
}

function crmMemoryChanges(merged = {}) {
  const added = Array.isArray(merged?.added) ? merged.added : [];
  if (!added.length) return [];
  return [{
    field:'memory', label:'长期记忆', kind:'added',
    added:added.slice(-6).map(item => `${normalizeCrmText(item?.label, 40)}：${normalizeCrmText(item?.text, 160)}`).filter(Boolean)
  }];
}


function metaBusinessExplicitAgeFact(explicitFacts = {}) {
  const age = normalizeCrmText(explicitFacts?.translatedAge, 16);
  const evidence = normalizeCrmText(explicitFacts?.translatedAgeEvidence, 1200);
  if (!/^\d{2,3}$/.test(age) || !evidence) return null;
  const n = Number(age);
  if (n < 15 || n > 100) return null;
  const escaped = age.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const strong = new RegExp(String.raw`(?:我(?:今年|的年龄是|的年齡是)?\s*)?${escaped}\s*(?:岁|歲)(?:[。！!？?、,\s]|$)|(?:^|[。！!？?、,\s])${escaped}\s*(?:岁|歲)(?:[。！!？?、,\s]|$)`, 'u');
  const delivered=aggregateTimestampMs(explicitFacts?.translatedAgeDelivered);
  return strong.test(evidence) ? { age, evidence, messageTimestamp:delivered?new Date(delivered).toISOString():'' } : null;
}

function metaBusinessExplicitRegionFact(explicitFacts = {}) {
  // V1.27.171: raw Japanese region hints may still help identity/diagnostics,
  // but they may no longer write CRM. Region text is committed only after a
  // translated Chinese fact reaches the normal translated-evidence extractor.
  const region = normalizeCrmText(explicitFacts?.translatedRegion, 100);
  const evidence = normalizeCrmText(explicitFacts?.translatedRegionEvidence, 1200);
  if (!region || !evidence) return null;
  const strong = /(?:住在|居住|目前在|来自|出生|老家|地区|地區|城市|省|市|县|縣)/u;
  const delivered=aggregateTimestampMs(explicitFacts?.translatedRegionDelivered);
  return strong.test(evidence) ? { region, evidence, messageTimestamp:delivered?new Date(delivered).toISOString():'' } : null;
}

// V1.27.32: an explicit customer fact from the live Meta customer lane is
// authoritative enough to repair every local CRM alias for the CURRENT customer.
// Previous builds could extract 44 correctly but write it under a hydrated
// mb-thread key while the visible CRM panel was still reading an older name:* / legacy
// key that contained 52.  Update only same-account aliases whose durable thread
// or exact normalized display name matches the resolved current customer.
function commitMetaBusinessExplicitAgeAliases({ accountId = '', chatId = '', displayName = '', explicitFacts = null } = {}) {
  accountId = normalizeCrmText(accountId, 128);
  chatId = normalizeCrmText(chatId, 500);
  displayName = normalizeCrmText(displayName, 180);
  const ageFact = metaBusinessExplicitAgeFact(explicitFacts || {});
  const regionFact = metaBusinessExplicitRegionFact(explicitFacts || {});
  if (!accountId || (!ageFact && !regionFact)) return { ok:false, changed:false, age:'', region:'', updatedKeys:[] };
  const crm = ensureCrmConfig();
  const candidateKeys = new Set();
  const direct = getCrmContactForConversation(accountId, chatId, displayName);
  if (direct?.stableKey && crm.contacts?.[direct.stableKey]) candidateKeys.add(direct.stableKey);
  if (direct?.legacyMatched && direct?.legacyKey && crm.contacts?.[direct.legacyKey]) candidateKeys.add(direct.legacyKey);
  // V1.27.178: alias repair must never fan out by display name. Only records
  // carrying the same durable conversation id may receive this live fact.
  if (strongConversationIdentity(chatId)) {
    for (const [key, contact] of Object.entries(crm.contacts || {})) {
      if (String(contact?.accountId || '') !== accountId) continue;
      if (sameDurableConversationId(chatId, contact?.chatId || '')) candidateKeys.add(key);
    }
  }
  if (!candidateKeys.size) return { ok:true, changed:false, age:ageFact?.age || '', region:regionFact?.region || '', updatedKeys:[] };
  const updatedKeys=[];
  const now=new Date().toISOString();
  const changes=[];
  let acceptedAgeChange=false;
  let acceptedRegionChange=false;
  const makeEvidence=(field,value,fact)=>({
    field,value,kind:'explicit',confidence:100,evidence:fact?.evidence || '',rawEvidence:'',source:'customer',textSource:'translated',
    temporal:temporalState(fact?.evidence || ''),messageTimestamp:fact?.messageTimestamp || '',platform:'metabusiness',accountId,chatId,
    // If Meta exposes a fact-only translated host but no reliable source clock,
    // treat it like unknown-time backfill: it may fill an empty field but cannot
    // overwrite a known current value.
    historyBackfill:!fact?.messageTimestamp
  });
  for (const key of candidateKeys) {
    const old=crm.contacts[key];
    if (!old || typeof old !== 'object') continue;
    const facts={name:'',age:'',region:'',occupation:'',interests:[],interestRemovals:[],fieldEvidence:{name:null,age:null,region:null,occupation:null,interests:[]},confidence:{name:0,age:0,region:0,occupation:0,interests:0}};
    const forceFields=[];
    if (ageFact) { facts.age=ageFact.age; facts.fieldEvidence.age=makeEvidence('age',ageFact.age,ageFact); facts.confidence.age=100; forceFields.push('age'); }
    if (regionFact) { facts.region=regionFact.region; facts.fieldEvidence.region=makeEvidence('region',regionFact.region,regionFact); facts.confidence.region=100; forceFields.push('region'); }
    const merged=mergeCrmAutoFacts(old,facts,{displayName,forceFields});
    if (!merged?.changed) continue;
    const next={...(merged.contact||old),updatedAt:now};
    if (normalizeCrmText(old.age,20)!==normalizeCrmText(next.age,20)) acceptedAgeChange=true;
    if (normalizeCrmText(old.region,100)!==normalizeCrmText(next.region,100)) acceptedRegionChange=true;
    next.summary = buildAutoSummary(next, normalizeNonLineCrmStage(next.stage));
    crm.contacts[key]=next;
    updatedKeys.push(key);
    try { teamSyncQueueCrmContact(next, { platform:'metabusiness', accountId, accountName:teamSyncAccountName(accountId,'metabusiness'), chatId:next.chatId || chatId, displayName:next.displayName || displayName }); } catch {}
  }
  if (!updatedKeys.length) return { ok:true, changed:false, age:ageFact?.age || '', region:regionFact?.region || '', updatedKeys:[] };
  if (ageFact && acceptedAgeChange) changes.push({ field:'age', label:'年龄', kind:'updated', after:ageFact.age, evidence:ageFact.evidence });
  if (regionFact && acceptedRegionChange) changes.push({ field:'region', label:'地区', kind:'updated', after:regionFact.region, evidence:regionFact.evidence });
  saveConfig(config);
  const latest=getCrmContactForConversation(accountId,chatId,displayName).contact || null;
  try { sendUI('crm-auto-extracted', { platform:'metabusiness', accountId, chatId, displayName, contact:crmContactSummary(latest || {}), facts:{ age:ageFact?.age || '', region:regionFact?.region || '', evidence:[ageFact?.evidence,regionFact?.evidence].filter(Boolean) }, changes, directExplicitFact:true }); } catch {}
  // Native-only MB has no software aggregate customer list to repaint.
  return { ok:true, changed:true, age:ageFact?.age || '', region:regionFact?.region || '', updatedKeys };
}


const CRM_TRANSLATED_EXTRACTION_VERSION = 'v127179-monotonic-message-time-closure-translated-crm-extraction';
function normalizeCrmTranslatedText(value = '') {
  return sanitizeCustomerTurnTextForChatgpt(value)
    .replace(/^[-—–_\s]*中文译文[-—–_\s：:]*/u, '')
    .replace(/^译[：:]\s*/u, '')
    .replace(/^中文译文[：:]\s*/u, '')
    .trim();
}
function crmTranslatedProfileMessages(messages = []) {
  const out=[];
  for (const item of Array.isArray(messages)?messages:[]) {
    const row = typeof item === 'string' ? {role:'customer',text:item} : (item && typeof item === 'object' ? item : null);
    if(!row) continue;
    const role=normalizeCrmText(row.role || row.direction || 'customer',30).toLowerCase();
    if(!['customer','incoming','me','outgoing'].includes(role)) continue;
    const raw=normalizeCrmText(row.text ?? row.content ?? row.message ?? '',1600);
    const translated=normalizeCrmTranslatedText(
      row.translatedText ?? row.translationText ?? row.translatedValue ?? row.translation?.text ?? ''
    );
    const incoming = role==='customer' || role==='incoming';
    if(incoming) {
      // V1.27.171 hard contract: profile/memory extraction is translation-first.
      // Japanese source text is audit evidence only and is never allowed to
      // become a CRM profile value. Pure numeric replies are language-neutral.
      const neutral=/^[\d０-９\s.,，+\-]+$/u.test(raw);
      if(!translated && !neutral) continue;
      out.push({...row,role:'customer',text:translated || raw,rawText:raw,translated:true,textSource:translated?'translated':'language-neutral'});
    } else {
      // Operator text is context only (for example "你几岁？" -> "43").
      // Prefer its Chinese translation when available, otherwise keep the raw
      // question solely as context; outgoing text is never written as customer data.
      if(!translated && !raw) continue;
      out.push({...row,role:'me',text:translated || raw,rawText:raw,translated:!!translated,textSource:translated?'translated':'operator-context'});
    }
  }
  return out.slice(-60);
}

function explicitCustomerAgeForceFields(messages = [], facts = {}) {
  const age=normalizeCrmText(facts?.age,16);
  if (!age || !/^\d{2,3}$/.test(age)) return [];
  const escaped=age.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const firstPerson=new RegExp(`(?:私は|わたしは|僕は|ぼくは|俺は)\\s*${escaped}\\s*(?:歳|才|です|ですよ|ですね)(?:[。！!？?\\s]|$)`,'u');
  const directAge=new RegExp(`(?:^|[。！!？?、,\\s])${escaped}\\s*(?:歳|才)(?:です|ですよ|ですね)?(?:[。！!？?\\s]|$)`,'u');
  const rows=(Array.isArray(messages)?messages:[]).slice(-12);
  for (let i=rows.length-1;i>=0;i--) {
    const row=rows[i]||{};
    const role=normalizeCrmText(row.role||row.direction,30).toLowerCase();
    if (!['customer','incoming'].includes(role)) continue;
    const text=normalizeCrmText(row.text||row.content||row.message,1200);
    if (firstPerson.test(text)||directAge.test(text)) return ['age'];
  }
  return [];
}

function applyCrmAutoExtraction({ platform = 'line', accountId = '', chatId = '', displayName = '', messages = [], historyBackfill = false } = {}) {
  platform = String(platform || 'line').trim().toLowerCase() || 'line';
  accountId = normalizeCrmText(accountId, 128);
  chatId = normalizeCrmText(chatId, 300);
  displayName = normalizeCrmText(displayName, 180);
  if (!accountId || (!chatId && !displayName)) return { ok:false, skipped:true };

  // CRM must never consume Yoko's injected Copy/Retranslate/GPT controls. Clean
  // every role at the main-process boundary as a second barrier even if a preload
  // snapshot was polluted during Meta hydration.
  messages = (Array.isArray(messages) ? messages : []).map(item => {
    if (typeof item === 'string') return sanitizeCustomerTurnTextForChatgpt(item);
    if (!item || typeof item !== 'object') return item;
    const raw = item.text ?? item.content ?? item.message ?? '';
    const text = sanitizeCustomerTurnTextForChatgpt(raw);
    const translatedText = normalizeCrmTranslatedText(item.translatedText ?? item.translationText ?? item.translatedValue ?? item.translation?.text ?? '');
    return { ...item, text, ...(translatedText ? {translatedText} : {}) };
  }).filter(item => typeof item === 'string' ? !!item : !!String(item?.text || '').trim());

  const profileMessages = crmTranslatedProfileMessages(messages).map(row => ({ ...row, platform, accountId, chatId }));
  const facts = extractCustomerFacts(profileMessages);
  // V1.27.179: history backfill uses the same extractor, but unknown-time archive
  // rows are deliberately marked fail-closed so they may fill empty fields yet
  // can never overwrite a known current value merely because they were read later.
  if (historyBackfill === true) {
    const mark = ev => { if (ev && typeof ev === 'object') ev.historyBackfill = true; return ev; };
    for (const field of ['name','age','region','occupation']) mark(facts?.fieldEvidence?.[field]);
    if (Array.isArray(facts?.fieldEvidence?.interests)) facts.fieldEvidence.interests.forEach(mark);
    if (Array.isArray(facts?.interestRemovalEvidence)) facts.interestRemovalEvidence.forEach(mark);
    facts.historyBackfill = true;
  }
  facts.extractionContract = CRM_TRANSLATED_EXTRACTION_VERSION;
  facts.translatedMessageCount = profileMessages.filter(row => row?.textSource === 'translated').length;
  facts.skippedUntranslatedCustomerCount = Math.max(0, messages.filter(row => ['customer','incoming'].includes(normalizeCrmText(row?.role||row?.direction,30).toLowerCase())).length - profileMessages.filter(row => row?.role === 'customer').length);
  const photoExchange = detectPhotoExchange(messages);
  const crm = ensureCrmConfig();
  const match = getCrmContactForConversation(accountId, chatId, displayName);
  const identityIsolation = isolateAutoOwnedContact(match.contact || {}, { accountId, chatId, stableKey:match.stableKey });
  const existing = identityIsolation.contact || {};
  // V1.27.178: if an older build ever copied auto-owned facts across customer
  // identities, message-level provenance/scope now quarantines those fields
  // before any new extraction can reuse or resurrect them. Manual edits survive.
  // V1.27.30: Meta's current customer can explicitly correct a stale age that
  // older broken extraction already persisted (screenshot: CRM=52 while the
  // live customer says "私は44です"). Only strong explicit customer-age
  // evidence from the most recent messages gets this repair authority.
  const forceFields = platform === 'metabusiness' ? explicitCustomerAgeForceFields(profileMessages, facts) : [];
  const merged = mergeCrmAutoFacts(existing, facts, { displayName, forceFields });
  const now = new Date().toISOString();
  const currentStage = platform === 'line'
    ? normalizeLineCrmStage(existing.stage)
    : normalizeNonLineCrmStage(existing.stage);
  const detectedJourney = platform === 'line' ? { eventCount:0 } : analyzeLineJourney(messages);
  let lineJourney = crmLineJourneyMerge(existing, detectedJourney, now);
  let linePauseSnapshot = existing._linePauseSnapshot && typeof existing._linePauseSnapshot === 'object'
    ? existing._linePauseSnapshot
    : null;
  // V1.25.3: an operator's 无效/暂停 decision freezes LINE automation as
  // well. Message analysis must not resurrect high/added while the customer is
  // manually paused. Keep the pre-pause state in _linePauseSnapshot so a later
  // manual resume can restore it without losing history.
  if (platform !== 'line' && currentStage === '无效/暂停') {
    const pausedState = synchronizeLineStateForStage(existing, currentStage, now);
    lineJourney = {
      lineIntent:pausedState.lineIntent,
      lineIntentScore:pausedState.lineIntentScore,
      lineProgress:pausedState.lineProgress,
      lineEvidence:pausedState.lineEvidence,
      _lineJourney:pausedState._lineJourney,
      changed:normalizeCrmText(existing.lineIntent, 30) !== pausedState.lineIntent
        || normalizeCrmText(existing.lineProgress, 40) !== pausedState.lineProgress
        || Number(existing.lineIntentScore || 0) !== pausedState.lineIntentScore
    };
    linePauseSnapshot = pausedState._linePauseSnapshot;
  }
  const detectedMemory = extractLongTermMemory(profileMessages);
  const prunedMemory = pruneLongTermMemoryAgainstOutgoing(existing.memoryItems || [], messages);
  const mergedMemory = mergeLongTermMemory(prunedMemory.items, detectedMemory, now);
  const lifecycleMeta = existing._autoLifecycle && typeof existing._autoLifecycle === 'object' ? { ...existing._autoLifecycle } : {};
  let inferred = platform === 'line' ? null : inferredLeadStage(messages, facts);
  if (platform !== 'line') {
    const journeyStage = lineJourney.lineProgress === 'added'
      ? 'LINE已添加'
      : (lineJourney.lineProgress === 'waiting_add'
        ? '已邀请LINE'
        : (lineJourney.lineProgress === 'interested' ? '准备引导LINE' : ''));
    if (journeyStage) {
      const confirmedLineAdded = lineJourney.lineProgress === 'added';
      inferred = {
        ...(inferred || {}),
        stage:journeyStage,
        reason:lineJourney._lineJourney?.reason || detectedJourney?.reason || 'LINE 引导状态更新',
        // Keep both the current detector output and the merged/persisted journey
        // available to the lifecycle policy. A contact whose progress is already
        // terminal `added` must self-heal the CRM stage even if the current DOM
        // snapshot no longer contains the original confirmation bubble.
        lineJourney:{ ...(detectedJourney || {}), progress:lineJourney.lineProgress },
        lineProgress:lineJourney.lineProgress,
        confirmedLineAdded,
        signals:{ ...(inferred?.signals || {}), ...(confirmedLineAdded ? { customerAdded:true } : {}) }
      };
    }
  }
  const stageDecision = platform === 'line'
    ? { stage:currentStage, changed:false, locked:true, reason:'line-stage-managed-separately' }
    : chooseSafeLeadStage(currentStage, inferred, lifecycleMeta);
  const stage = stageDecision.stage || currentStage;
  const status = normalizeCrmText(existing.serviceStatus, 20);
  const contact = merged.contact || { ...existing };
  const nextLifecycle = { ...lifecycleMeta };
  if (platform !== 'line') {
    nextLifecycle.lastInferredStage = normalizeCrmText(inferred?.stage, 40);
    nextLifecycle.lastInferredReason = normalizeCrmText(inferred?.reason, 160);
    nextLifecycle.lastAnalyzedAt = now;
    if (stageDecision.changed) {
      nextLifecycle.stage = stage;
      nextLifecycle.stageUpdatedAt = now;
      nextLifecycle.stageReason = normalizeCrmText(stageDecision.reason || inferred?.reason, 160);
      nextLifecycle.stageLocked = false;
    }
  }
  const record = {
    ...existing,
    key: match.stableKey,
    platform,
    accountId,
    chatId,
    displayName,
    name: normalizeCrmText(contact.name, 160),
    stage,
    serviceStatus: ['auto','waiting','active','done','paused','blacklist'].includes(status) ? status : 'auto',
    tags: (() => {
      let value = platform !== 'line' && stage !== 'LINE已添加'
        ? removeAddedLineCrmTag(existing.tags)
        : (platform !== 'line' && stage === 'LINE已添加' ? ensureAddedLineCrmTag(existing.tags) : normalizeCrmText(existing.tags, 300));
      if (photoExchange.exchanged) value = ensureCrmTag(value, '已交换照片');
      return value;
    })(),
    targetLineAccountId: nonLineStageUsesTargetLine(stage) ? normalizeCrmText(existing.targetLineAccountId, 128) : '',
    targetLineAccountName: nonLineStageUsesTargetLine(stage) ? normalizeCrmText(existing.targetLineAccountName, 160) : '',
    ...crmBusinessFields(platform, stage),
    language: normalizeCrmText(existing.language, 20) || 'ja',
    region: normalizeCrmText(contact.region, 100),
    age: normalizeCrmText(contact.age, 20),
    occupation: normalizeCrmText(contact.occupation, 120),
    interests: normalizeCrmText(contact.interests, 500),
    lineIntent: platform === 'line' ? normalizeCrmText(existing.lineIntent, 30) || 'none' : lineJourney.lineIntent,
    lineIntentScore: platform === 'line' ? Math.max(0, Math.min(100, Number(existing.lineIntentScore || 0) || 0)) : lineJourney.lineIntentScore,
    lineProgress: platform === 'line' ? normalizeCrmText(existing.lineProgress, 40) || 'not_started' : lineJourney.lineProgress,
    lineEvidence: platform === 'line' ? normalizeCrmText(existing.lineEvidence, 360) : lineJourney.lineEvidence,
    memoryItems: mergedMemory.items,
    memorySummary: buildMemorySummary(mergedMemory.items, 10),
    note: normalizeCrmText(existing.note, 8000),
    _autoExtract: contact._autoExtract || {},
    _autoLifecycle: nextLifecycle,
    _lineJourney: platform === 'line' ? (existing._lineJourney && typeof existing._lineJourney === 'object' ? existing._lineJourney : {}) : lineJourney._lineJourney,
    _linePauseSnapshot: platform === 'line'
      ? (existing._linePauseSnapshot && typeof existing._linePauseSnapshot === 'object' ? existing._linePauseSnapshot : null)
      : linePauseSnapshot,
    createdAt: existing.createdAt || now,
    updatedAt: now
  };
  record.summary = buildAutoSummary(record, stage);

  const factChanges = crmAutoExtractionChanges(existing, record);
  const memoryChanges = crmMemoryChanges(mergedMemory);
  if (Array.isArray(prunedMemory.removed) && prunedMemory.removed.length) {
    memoryChanges.push({
      field:'memory', label:'长期记忆', kind:'removed',
      removed:prunedMemory.removed.slice(-6).map(item => `${normalizeCrmText(item?.label, 40)}：${normalizeCrmText(item?.text, 160)}`).filter(Boolean)
    });
  }
  const stageChanged = stage !== currentStage;
  const lineChanged = platform !== 'line' && lineJourney.changed;
  const memoryChanged = memoryChanges.length > 0;
  const oldSummary = normalizeCrmText(existing.summary, 900) || buildAutoSummary(existing, currentStage);
  const summaryChanged = record.summary !== oldSummary;
  const recordWasMissing = !match.contact;
  if (!recordWasMissing && !identityIsolation.changed && !merged.changed && !stageChanged && !lineChanged && !memoryChanged && !summaryChanged) {
    return { ok:true, changed:false, facts, contact:crmContactSummary(existing), lifecycle:{ inferred, stageDecision }, lineJourney:detectedJourney, memory:{ added:[] } };
  }

  crm.contacts[match.stableKey] = record;
  if (match.legacyMatched && match.legacyKey && match.legacyKey !== match.stableKey && crm.contacts[match.legacyKey]) delete crm.contacts[match.legacyKey];
  saveConfig(config);
  teamSyncQueueCrmContact(record, { platform, accountId, accountName:teamSyncAccountName(accountId, platform), chatId, displayName });

  const publicContact = crmContactSummary(record);
  const identityIsolationChanges = (identityIsolation.quarantined || []).map(row => ({
    field:row.field || 'identity', label:'身份隔离', kind:'quarantined', before:row.value || '', reason:row.reason || 'identity-mismatch'
  }));
  const changes = [...factChanges, ...memoryChanges, ...identityIsolationChanges];
  if (photoExchange.exchanged && !crmAutoExtractTokenList(existing.tags).some(tag => tag === '已交换照片')) {
    changes.push({ field:'tags', label:'标签', kind:'added', added:['已交换照片'], evidence:photoExchange.evidence || '' });
  }
  if (stageChanged) {
    changes.push({ field:'stage', label:'跟进阶段', kind:'updated', before:currentStage, after:stage, reason:stageDecision.reason || inferred?.reason || '' });
  }
  if (lineChanged) {
    changes.push({
      field:'lineProgress', label:'LINE进度', kind:'updated',
      before:lineProgressLabel(existing.lineProgress), after:lineProgressLabel(record.lineProgress),
      intent:lineIntentLabel(record.lineIntent), score:record.lineIntentScore, evidence:record.lineEvidence
    });
  }
  try { sendUI('crm-auto-extracted', { platform, accountId, chatId, displayName, contact:publicContact, facts, changes, lifecycle:{ inferred, stageDecision }, lineJourney:detectedJourney, memory:{ added:mergedMemory.added }, summaryChanged }); } catch {}
  if (platform === 'line') {
    try { sendUI('aggregate-updated', publicAggregateInbox()); } catch {}
  } else {
    try { sendPlatformAggregateUpdated(platform); } catch {}
  }
  return { ok:true, changed:true, facts, changes, contact:publicContact, lifecycle:{ inferred, stageDecision }, lineJourney:detectedJourney, memory:{ added:mergedMemory.added }, summaryChanged };
}


// V1.23.24 — ChatGPT web workbench. This is a real persistent ChatGPT web
// session embedded beside the active customer. It deliberately does NOT call
// the OpenAI API: customer -> ChatGPT bindings point at the operator's existing
// chatgpt.com conversation URLs, preserving the history already stored there.
function chatgptBindingsShadowPath() { return path.join(userDataRoot(), 'chatgpt-bindings.json'); }
let chatgptBindingsShadowHydrated = false;
function hydrateChatgptBindingsShadow(cfg) {
  if (chatgptBindingsShadowHydrated) return;
  chatgptBindingsShadowHydrated = true;
  try {
    const shadow = readJsonWithBackup(chatgptBindingsShadowPath());
    const rows = shadow?.bindings && typeof shadow.bindings === 'object' ? shadow.bindings : {};
    cfg.bindings = cfg.bindings && typeof cfg.bindings === 'object' ? cfg.bindings : {};
    let changed = false;
    for (const [key,row] of Object.entries(rows)) {
      if (!cfg.bindings[key] && row && typeof row === 'object' && isChatgptStableConversationUrl(row.url || '')) {
        cfg.bindings[key] = row; changed = true;
      }
    }
    if (changed) saveConfig(config);
  } catch {}
}
function persistChatgptBindingsShadow(cfg = null) {
  try {
    const state = cfg || config?.chatgptWorkbench || {};
    const rows = state?.bindings && typeof state.bindings === 'object' ? state.bindings : {};
    atomicWriteJson(chatgptBindingsShadowPath(), { version:1, updatedAt:new Date().toISOString(), bindings:rows }, { keepBackup:true });
  } catch {}
}

function chatgptWorkbenchConfig() {
  if (!config.chatgptWorkbench || typeof config.chatgptWorkbench !== 'object') config.chatgptWorkbench = {};
  if (!config.chatgptWorkbench.bindings || typeof config.chatgptWorkbench.bindings !== 'object') config.chatgptWorkbench.bindings = {};
  hydrateChatgptBindingsShadow(config.chatgptWorkbench);
  // V1.27.252 migration: older builds treated ChatGPT's optimistic
  // `local-chatgpt:` route as durable because it syntactically looked like a
  // normal /c/<id>. Remove only these known non-durable bindings. Valid server
  // conversation bindings are untouched.
  let nonDurableBindingPruned = 0;
  for (const [bindingKey,bindingRow] of Object.entries(config.chatgptWorkbench.bindings || {})) {
    if (!bindingRow || typeof bindingRow !== 'object') continue;
    if (!isChatgptTransientConversationUrl(bindingRow.url || '')) continue;
    noteChatgptTransientBinding(bindingRow.url,bindingKey,'v252-config-prune');
    delete config.chatgptWorkbench.bindings[bindingKey];
    nonDurableBindingPruned += 1;
  }
  if (nonDurableBindingPruned) {
    saveConfig(config);
    persistChatgptBindingsShadow(config.chatgptWorkbench);
    pushChatgptStabilityEvent('gpt-nondurable-binding-pruned-v252',{version:CHATGPT_SINGLE_PERSISTENT_WINDOW_VERSION,count:nonDurableBindingPruned});
  }
  if (!config.chatgptWorkbench.lastUrl) config.chatgptWorkbench.lastUrl = CHATGPT_HOME_URL;
  // V1.27.139 migration: V1.27.138 and older could remember a transient
  // /c/WEB:<uuid> as the workbench startup URL. Never resurrect that temporary
  // route after restart; a selected bound customer will route to its canonical
  // conversation through the normal customer-follow lane.
  if (isChatgptTransientConversationUrl(config.chatgptWorkbench.lastUrl || '')) config.chatgptWorkbench.lastUrl = CHATGPT_HOME_URL;
  const ratio = Number(config.chatgptWorkbench.splitRatio || 0.48);
  config.chatgptWorkbench.splitRatio = Math.max(0.36, Math.min(0.62, Number.isFinite(ratio) ? ratio : 0.48));
  const tone = String(config.chatgptWorkbench.replyTone || '').replace(/\r\n/g, '\n').trim().slice(0, 1200);
  config.chatgptWorkbench.replyTone = tone || DEFAULT_CHATGPT_REPLY_TONE;
  const format = String(config.chatgptWorkbench.replyFormat || 'bilingual').trim().toLowerCase();
  config.chatgptWorkbench.replyFormat = CHATGPT_REPLY_FORMATS.has(format) ? format : 'bilingual';
  if (!config.chatgptWorkbench.customerReplySettings || typeof config.chatgptWorkbench.customerReplySettings !== 'object') config.chatgptWorkbench.customerReplySettings = {};
  if (!config.chatgptWorkbench.customerMessageDeliveryReceipts || typeof config.chatgptWorkbench.customerMessageDeliveryReceipts !== 'object') config.chatgptWorkbench.customerMessageDeliveryReceipts = {};
  if (!config.chatgptWorkbench.replyFreshnessLocks || typeof config.chatgptWorkbench.replyFreshnessLocks !== 'object') config.chatgptWorkbench.replyFreshnessLocks = {};
  if (!config.chatgptWorkbench.replyDirectSendReceipts || typeof config.chatgptWorkbench.replyDirectSendReceipts !== 'object') config.chatgptWorkbench.replyDirectSendReceipts = {};
  if (!config.chatgptWorkbench.manualCustomerDrafts || typeof config.chatgptWorkbench.manualCustomerDrafts !== 'object') config.chatgptWorkbench.manualCustomerDrafts = {};
  const persona = String(config.chatgptWorkbench.personaProfile || '').replace(/\r\n/g, '\n').trim().slice(0, 20000);
  // V1.27.150: upgrade only the untouched V1.27.149 built-in persona. Preserve
  // any user-edited custom persona verbatim so an upgrade never overwrites it.
  config.chatgptWorkbench.personaProfile = !persona || persona === LEGACY_DEFAULT_CHATGPT_PERSONA_PROFILE_V149
    ? DEFAULT_CHATGPT_PERSONA_PROFILE
    : persona;
  const replyRules = String(config.chatgptWorkbench.replyRules || '').replace(/\r\n?/g, '\n').trim().slice(0, 40000);
  // V1.27.256: apply the anti-echo guard to existing/custom rule sets too, so already-bound customers
  // stop receiving paraphrase-first replies without requiring a new GPT conversation.
  config.chatgptWorkbench.replyRules = stripRetiredChatgptRules(replyRules) || DEFAULT_CHATGPT_REPLY_RULES;
  config.chatgptWorkbench.dayFlowEnabled = false;
  // V1.27.255: Day 1–Day 10 is retired. Do not repopulate legacy day files
  // into runtime config during startup. Keep only the long-term stage-based rules.
  if (!config.chatgptWorkbench.customerChatModes || typeof config.chatgptWorkbench.customerChatModes !== 'object' || Array.isArray(config.chatgptWorkbench.customerChatModes)) config.chatgptWorkbench.customerChatModes = {};
  const receptionFlow = String(config.chatgptWorkbench.receptionFlow || '').replace(/\r\n?/g,'\n').trim().slice(0,12000);
  config.chatgptWorkbench.receptionFlow = !receptionFlow || receptionFlow === LEGACY_DEFAULT_CHATGPT_RECEPTION_FLOW_V159
    ? DEFAULT_CHATGPT_RECEPTION_FLOW
    : receptionFlow;
  config.chatgptWorkbench.flowDays = {};
  config.chatgptWorkbench.flowLibrary = '';
  config.chatgptWorkbench.flowLibraryUpdatedAt = 0;
  config.chatgptWorkbench.flowLibraryBuiltinVersion = 'retired-v127255';
  config.chatgptWorkbench.dailyFlowCustomers = {};
  for (const row of Object.values(config.chatgptWorkbench.bindings || {})) {
    if (!row || typeof row !== 'object') continue;
    row.dailyFlowState = null;
    row.flowFingerprint = '';
    row.flowSyncFingerprint = '';
    row.dailyFlowRetired = true;
  }
  return config.chatgptWorkbench;
}

function chatgptProfilePath() {
  const profile = path.join(app.getPath('sessionData'), 'chatgpt-profile');
  fs.mkdirSync(profile, { recursive:true });
  return profile;
}

function isChatgptUrl(value) {
  try {
    const u = new URL(String(value || ''));
    return (u.protocol === 'https:' || u.protocol === 'http:') && (u.hostname === 'chatgpt.com' || u.hostname.endsWith('.chatgpt.com') || u.hostname === 'auth.openai.com');
  } catch { return false; }
}

function isChatgptConversationUrl(value) {
  try {
    const u = new URL(String(value || ''));
    if (u.hostname !== 'chatgpt.com' && !u.hostname.endsWith('.chatgpt.com')) return false;
    return /\/c\/[^/?#]+/i.test(u.pathname) || /\/g\/[^/]+\/c\/[^/?#]+/i.test(u.pathname) || /\/project\/[^/]+\/c\/[^/?#]+/i.test(u.pathname);
  } catch { return false; }
}

function chatgptConversationIdentityToken(value = '') {
  const ref=String(handoffConversationRef(value) || '').trim();
  if(!ref.toLowerCase().startsWith('c/')) return '';
  let token=ref.slice(2);
  try { token=decodeURIComponent(token); } catch {}
  return String(token || '').trim();
}

function isChatgptTransientConversationUrl(value = '') {
  if(!isChatgptConversationUrl(value)) return false;
  // V1.27.252: ChatGPT may expose optimistic/local conversation identities
  // such as /c/local-chatgpt%3A<uuid> before the server-backed /c/<uuid> is
  // durable. Those routes can later render "Unable to load this ChatGPT
  // conversation" and must never be persisted as customer bindings.
  return /^(?:WEB:|local-chatgpt:)/i.test(chatgptConversationIdentityToken(value));
}

function isChatgptStableConversationUrl(value = '') {
  return isChatgptConversationUrl(value) && !isChatgptTransientConversationUrl(value);
}

function noteChatgptTransientBinding(url = '', targetKey = '', reason = 'ignored') {
  const ref=String(handoffConversationRef(url) || url || '').slice(0,260);
  const key=`${String(targetKey||'')}|${ref}|${String(reason||'')}`;
  if(String(reason||'').includes('reject')) chatgptCanonicalBindingGuardState.transientRejectedCount += 1;
  else if(!chatgptCanonicalBindingSeen.has(key)) chatgptCanonicalBindingGuardState.transientIgnoredCount += 1;
  chatgptCanonicalBindingSeen.add(key);
  // V1.27.169 — keep the long-session de-duplication set bounded. Set iteration
  // order is insertion order, so pruning the oldest keys is cheap and stable.
  if(chatgptCanonicalBindingSeen.size > 3000) {
    let drop = 1000;
    for(const oldKey of chatgptCanonicalBindingSeen) {
      chatgptCanonicalBindingSeen.delete(oldKey);
      if(--drop <= 0) break;
    }
  }
  chatgptCanonicalBindingGuardState.last={at:Date.now(),targetKey:String(targetKey||''),conversation:ref,reason:String(reason||'')};
  pushChatgptStabilityEvent('gpt-transient-binding-blocked',chatgptCanonicalBindingGuardState.last);
}


function chatgptTransientPageDriftSelectedContext() {
  const metaAuthority=activeChatgptMetaSelectionAuthority();
  let target=metaAuthority?.ok ? { ...metaAuthority } : null;
  if(!target && chatgptWorkbenchStableTarget?.ok && chatgptWorkbenchTargetStillMatchesActiveContext(chatgptWorkbenchStableTarget)) {
    target={ ...chatgptWorkbenchStableTarget };
  }
  if(!target?.ok || !chatgptWorkbenchTargetStillMatchesActiveContext(target)) return null;
  const binding=chatgptBindingForTarget(target);
  if(!binding?.url || !isChatgptStableConversationUrl(binding.url)) return null;
  return { target, binding, targetKey:chatgptWorkflowTargetKey(target), bindingRef:chatgptBoundConversationRef(binding) };
}

function noteChatgptTransientPageDrift(status='', payload={}) {
  const row={ status:String(status||''), at:Date.now(), ...(payload&&typeof payload==='object'?payload:{}) };
  chatgptTransientPageDriftState.last=row;
  pushChatgptStabilityEvent(`gpt-transient-page-drift-${String(status||'event')}`,row);
  return row;
}

function cancelScheduledChatgptTransientPageDrift(reason='cancelled', payload={}) {
  const hadTimer=!!chatgptTransientPageDriftTimer;
  if(chatgptTransientPageDriftTimer) clearTimeout(chatgptTransientPageDriftTimer);
  chatgptTransientPageDriftTimer=null;
  chatgptTransientPageDriftTimerToken += 1;
  if(hadTimer){
    chatgptTransientPageDriftState.cancelledCount += 1;
    noteChatgptTransientPageDrift('cancelled',{reason:String(reason||''),...(payload||{})});
  }
}

async function recoverChatgptTransientPageDriftNow(win, target, binding, {source='recovery'}={}) {
  if(!win || win.isDestroyed() || win.webContents.isDestroyed() || !target?.ok || !binding?.url || !isChatgptStableConversationUrl(binding.url)) {
    return {ok:false,reason:'invalid-recovery-context'};
  }
  const targetKey=chatgptWorkflowTargetKey(target);
  const bindingRef=chatgptBoundConversationRef(binding);
  if(!targetKey || !bindingRef) return {ok:false,reason:'missing-recovery-identity'};
  const active=chatgptTransientPageDriftActive;
  if(active && active.targetKey===targetKey && active.bindingRef===bindingRef && active.promise) return active.promise;

  const task=(async()=>{
    const currentContext=chatgptTransientPageDriftSelectedContext();
    if(!currentContext || currentContext.targetKey!==targetKey || currentContext.bindingRef!==bindingRef) {
      chatgptTransientPageDriftState.cancelledCount += 1;
      noteChatgptTransientPageDrift('cancelled',{source,targetKey,bindingConversation:bindingRef,reason:'selection-or-binding-changed-before-recovery'});
      return {ok:false,cancelled:true,reason:'selection-or-binding-changed'};
    }
    let current=''; try{current=String(win.webContents.getURL?.()||'')}catch{}
    if(!isChatgptTransientConversationUrl(current)) {
      if(chatgptWorkbenchDestinationMatches(current,binding.url,binding)) {
        chatgptTransientPageDriftState.naturalSettleCount += 1;
        noteChatgptTransientPageDrift('natural-settle',{source,targetKey,bindingConversation:bindingRef,currentConversation:handoffConversationRef(current)});
        return {ok:true,natural:true,url:current};
      }
      return {ok:false,reason:'page-no-longer-transient',url:current};
    }
    const sinceLast=Math.max(0,Date.now()-Number(chatgptTransientPageDriftLastStartedAt||0));
    if(chatgptTransientPageDriftLastStartedAt && sinceLast<CHATGPT_TRANSIENT_PAGE_DRIFT_COOLDOWN_MS) {
      await waitMs(CHATGPT_TRANSIENT_PAGE_DRIFT_COOLDOWN_MS-sinceLast);
    }
    const recheck=chatgptTransientPageDriftSelectedContext();
    if(!recheck || recheck.targetKey!==targetKey || recheck.bindingRef!==bindingRef) {
      chatgptTransientPageDriftState.cancelledCount += 1;
      noteChatgptTransientPageDrift('cancelled',{source,targetKey,bindingConversation:bindingRef,reason:'selection-or-binding-changed-after-cooldown'});
      return {ok:false,cancelled:true,reason:'selection-or-binding-changed'};
    }
    let stillCurrent=''; try{stillCurrent=String(win.webContents.getURL?.()||'')}catch{}
    if(!isChatgptTransientConversationUrl(stillCurrent)) {
      if(chatgptWorkbenchDestinationMatches(stillCurrent,binding.url,binding)) {
        chatgptTransientPageDriftState.naturalSettleCount += 1;
        noteChatgptTransientPageDrift('natural-settle',{source,targetKey,bindingConversation:bindingRef,currentConversation:handoffConversationRef(stillCurrent)});
        return {ok:true,natural:true,url:stillCurrent};
      }
      return {ok:false,reason:'page-left-transient-before-recovery',url:stillCurrent};
    }

    chatgptTransientPageDriftLastStartedAt=Date.now();
    chatgptTransientPageDriftState.recoveryStartedCount += 1;
    noteChatgptTransientPageDrift('recovery-start',{source,targetKey,bindingConversation:bindingRef,currentConversation:handoffConversationRef(stillCurrent)});
    if(chatgptWorkbenchFastRouteActive) releaseChatgptFastRouteActive('transient-page-drift-recovery',{epoch:Number(chatgptWorkbenchFastRouteActive.epoch||0),finalUrl:stillCurrent});
    const route=startChatgptFastSelectionRoute(win,target,binding,{force:true});
    const settled=await waitForChatgptDestinationMatch(win,binding.url,binding,4800);
    const finalContext=chatgptTransientPageDriftSelectedContext();
    if(!finalContext || finalContext.targetKey!==targetKey || finalContext.bindingRef!==bindingRef) {
      chatgptTransientPageDriftState.cancelledCount += 1;
      noteChatgptTransientPageDrift('cancelled',{source,targetKey,bindingConversation:bindingRef,reason:'selection-or-binding-changed-during-recovery'});
      return {ok:false,cancelled:true,reason:'selection-or-binding-changed'};
    }
    if(settled?.ok) {
      chatgptTransientPageDriftState.recoveredCount += 1;
      noteChatgptTransientPageDrift('recovered',{source,targetKey,bindingConversation:bindingRef,currentConversation:handoffConversationRef(settled.url||binding.url),elapsedMs:Number(settled.elapsedMs||0),fastMode:String(route?.directBound?'direct-bound':chatgptWorkbenchLastFastRouteMode||'')});
      sendChatgptWorkbenchUpdated(target);
      return {ok:true,recovered:true,url:settled.url||binding.url,elapsedMs:Number(settled.elapsedMs||0)};
    }
    chatgptTransientPageDriftState.failedCount += 1;
    noteChatgptTransientPageDrift('failed',{source,targetKey,bindingConversation:bindingRef,currentConversation:handoffConversationRef(settled?.url||''),elapsedMs:Number(settled?.elapsedMs||0)});
    sendChatgptWorkbenchUpdated(target);
    return {ok:false,reason:'canonical-recovery-not-settled',url:String(settled?.url||''),elapsedMs:Number(settled?.elapsedMs||0)};
  })();
  chatgptTransientPageDriftActive={targetKey,bindingRef,startedAt:Date.now(),promise:task};
  try{return await task;}finally{if(chatgptTransientPageDriftActive?.promise===task)chatgptTransientPageDriftActive=null;}
}

function scheduleChatgptTransientPageDriftRecovery(url='', source='navigation') {
  // V1.27.296: Passive mode. ChatGPT sometimes temporarily lands on an
  // intermediate URL during hydration. Automatic corrective routing can loop,
  // repeatedly blank the view, and interrupt the customer's draft.
  // Selecting another customer or using manual refresh still routes normally.
  if (isChatgptTransientConversationUrl(url)) {
    chatgptTransientPageDriftState.detectedCount += 1;
    noteChatgptTransientPageDrift('passive-suppression',{source,currentConversation:handoffConversationRef(url)});
  }
  cancelScheduledChatgptTransientPageDrift('automatic-route-disabled',{source,currentConversation:handoffConversationRef(url)});
  return false;
}

// V1.25.13: compare the destination by ChatGPT conversation identity instead
// of raw URL text. ChatGPT may canonicalize a conversation URL (query/hash,
// project wrapper, sidebar navigation), but the /c/<id> identity is what the
// customer binding actually means. Treat an already-open matching conversation
// as settled so did-finish-load cannot recursively force-load it again.
function chatgptWorkbenchDestinationMatches(currentUrl = '', wantedUrl = '', binding = null) {
  const current = String(currentUrl || '');
  const wanted = String(wantedUrl || '');
  const currentRef = handoffConversationRef(current);
  const wantedRef = handoffConversationRef(wanted);
  if (binding?.url && wantedRef) return !!currentRef && currentRef === wantedRef;
  if (!binding?.url) {
    try {
      const u = new URL(current);
      const hostOk = u.hostname === 'chatgpt.com' || u.hostname.endsWith('.chatgpt.com');
      return hostOk && !currentRef && (u.pathname === '/' || u.pathname === '');
    } catch { return current === wanted; }
  }
  return current === wanted;
}

function chatgptGlobalCustomerIdForTarget(target = {}) {
  try {
    const match = getCrmContactForConversation(String(target?.accountId || ''), String(target?.chatId || ''), String(target?.displayName || ''));
    const contact = match?.contact || {};
    return normalizeCrmText(contact.globalCustomerId || contact?.crossPlatform?.globalCustomerId, 120);
  } catch { return ''; }
}

function chatgptBindingTargetGlobalCustomerId(binding = {}) {
  if (!binding || typeof binding !== 'object') return '';
  return chatgptGlobalCustomerIdForTarget({
    platform:String(binding.platform || ''), accountId:String(binding.accountId || ''),
    chatId:String(binding.chatId || ''), displayName:String(binding.displayName || '')
  });
}

function chatgptMetaBindingMatchesHydratedTarget(binding = {}, target = {}) {
  if (!binding || !target?.ok) return false;
  if (String(binding.platform || '').toLowerCase() !== 'metabusiness' || String(target.platform || '').toLowerCase() !== 'metabusiness') return false;
  if (String(binding.accountId || '') !== String(target.accountId || '')) return false;
  const rowChat=String(binding.chatId || '').trim(), targetChat=String(target.chatId || '').trim();
  const rowStrong=rowChat ? metaBusinessCanonicalChatId(rowChat) : '';
  const targetStrong=targetChat ? metaBusinessCanonicalChatId(targetChat) : '';
  if (rowStrong && targetStrong) return rowStrong === targetStrong;
  if (rowChat && targetChat && !rowStrong && !targetStrong && rowChat !== targetChat) return false;
  const rowName=normalizeCrmText(binding.displayName || '',180).replace(/^@/,'').toLocaleLowerCase();
  const targetName=normalizeCrmText(target.displayName || target.handle || '',180).replace(/^@/,'').toLocaleLowerCase();
  return !!rowName && rowName === targetName;
}

function chatgptBindingForTarget(target = {}) {
  const key = String(target?.targetKey || speechLibraryTargetKey(target) || '').trim();
  if (!key) return null;
  const bindings = chatgptWorkbenchConfig().bindings;
  const direct = bindings[key];
  if (direct && typeof direct === 'object') {
    if (isChatgptStableConversationUrl(direct.url || '')) return { ...direct, targetKey:key };
    if (isChatgptTransientConversationUrl(direct.url || '')) noteChatgptTransientBinding(direct.url,key,'direct-ignore');
  }
  const globalCustomerId = chatgptGlobalCustomerIdForTarget(target);
  let best = null;
  if (globalCustomerId) {
    for (const [sourceKey,row] of Object.entries(bindings || {})) {
      if (!row || typeof row !== 'object') continue;
      if (!isChatgptStableConversationUrl(row.url || '')) { if(isChatgptTransientConversationUrl(row.url || '')) noteChatgptTransientBinding(row.url,sourceKey,'inherited-ignore'); continue; }
      if (chatgptBindingTargetGlobalCustomerId(row) !== globalCustomerId) continue;
      if (!best || String(row.boundAt || '') > String(best.row?.boundAt || '')) best = { sourceKey, row, reason:'global-customer-id' };
    }
  }
  // V1.27.244: LINE/Web surfaces may briefly resolve the same customer with a
  // strong chatId on one render and only the visible display name on the next.
  // That changes speechLibraryTargetKey() even though the operator returned to
  // the same customer. Recover the existing binding only inside the same
  // platform+account. If both sides have strong chat IDs they MUST match; the
  // exact-name fallback is allowed only when at least one side is temporarily
  // missing the strong chat ID.
  if (!best && ['line','telegram'].includes(String(target.platform || '').toLowerCase())) {
    const targetPlatform=String(target.platform||'').toLowerCase();
    const targetAccount=String(target.accountId||'');
    const targetChat=String(target.chatId||'').trim();
    const targetName=normalizeCrmText(target.displayName||target.handle,180).replace(/^@/,'').toLocaleLowerCase();
    for (const [sourceKey,row] of Object.entries(bindings || {})) {
      if (!row || typeof row !== 'object') continue;
      if (!isChatgptStableConversationUrl(row.url || '')) continue;
      if (String(row.platform||'').toLowerCase()!==targetPlatform || String(row.accountId||'')!==targetAccount) continue;
      const rowChat=String(row.chatId||'').trim();
      const rowName=normalizeCrmText(row.displayName||row.handle,180).replace(/^@/,'').toLocaleLowerCase();
      let same=false, reason='';
      if (targetChat && rowChat) {
        same=targetChat===rowChat;
        reason='same-chat-id';
      } else if (targetName && rowName && targetName===rowName) {
        same=true;
        reason='weak-name-alias';
      }
      if (!same) continue;
      if (!best || String(row.boundAt || '') > String(best.row?.boundAt || '')) best = { sourceKey, row, reason:`${targetPlatform}-${reason}` };
    }
  }
  // V1.27.72: Meta may first expose a weak name/handle identity and hydrate the
  // same row into mb-thread:<id> later. Recover historical GPT history after
  // restart, but never bridge two conflicting canonical thread IDs.
  if (!best && String(target.platform || '').toLowerCase() === 'metabusiness') {
    for (const [sourceKey,row] of Object.entries(bindings || {})) {
      if (!row || typeof row !== 'object') continue;
      if (!isChatgptStableConversationUrl(row.url || '')) { if(isChatgptTransientConversationUrl(row.url || '')) noteChatgptTransientBinding(row.url,sourceKey,'meta-inherited-ignore'); continue; }
      if (!chatgptMetaBindingMatchesHydratedTarget(row,target)) continue;
      if (!best || String(row.boundAt || '') > String(best.row?.boundAt || '')) best = { sourceKey, row, reason:'meta-identity-hydration' };
    }
  }
  return best ? { ...best.row, targetKey:key, inherited:true, inheritedFromTargetKey:best.sourceKey, inheritedReason:best.reason } : null;
}


function chatgptWorkflowTargetKey(target = {}) {
  return String(target?.targetKey || speechLibraryTargetKey(target) || '').trim();
}

function chatgptBindingAsTarget(binding = {}, sourceKey = '') {
  if (!binding || typeof binding !== 'object') return null;
  const target = {
    ok:true,
    surface:String(binding.surface || (String(binding.platform || '').toLowerCase() === 'line' ? 'line' : 'external')),
    platform:String(binding.platform || ''),
    accountId:String(binding.accountId || ''),
    chatId:String(binding.chatId || ''),
    displayName:String(binding.displayName || ''),
    handle:String(binding.handle || ''),
    targetKey:String(sourceKey || binding.targetKey || '')
  };
  return target.accountId || target.chatId || target.displayName ? target : null;
}

function chatgptConversationBindingCollision(url = '', target = {}) {
  const conversation = handoffConversationRef(url);
  if (!conversation || !target?.ok) return null;
  const bindings = chatgptWorkbenchConfig().bindings || {};
  for (const [sourceKey, row] of Object.entries(bindings)) {
    if (!row || typeof row !== 'object') continue;
    if (!isChatgptStableConversationUrl(row.url || '')) continue;
    if (handoffConversationRef(row.url || '') !== conversation) continue;
    const rowTarget = chatgptBindingAsTarget(row, sourceKey);
    if (!rowTarget) continue;
    const rowGlobal=chatgptGlobalCustomerIdForTarget(rowTarget);
    const targetGlobal=chatgptGlobalCustomerIdForTarget(target);
    if ((rowGlobal && targetGlobal && rowGlobal===targetGlobal) || chatgptTargetsRepresentSameCustomer(rowTarget, target)) continue;
    // V1.27.290: only an explicitly confirmed FB -> WhatsApp pair may reuse one conversation.
    const ownKey=chatgptWorkflowTargetKey(target);
    const ownRow=bindings[ownKey];
    if (ownRow?.linkedSourceKey===sourceKey && ownRow?.url===row.url) continue;
    if (row?.linkedSourceKey===ownKey && ownRow?.url===row.url) continue;
    return {
      conversation,
      sourceKey:String(sourceKey || ''),
      sourceDisplayName:String(row.displayName || ''),
      sourcePlatform:String(row.platform || ''),
      sourceAccountId:String(row.accountId || '')
    };
  }
  return null;
}

function cancelChatgptResponseWatchesExcept(target = null, reason = 'customer-selection-changed') {
  const keepTargetKey=target?.ok?chatgptWorkflowTargetKey(target):'';
  let cancelled=0;
  for(const [key,token] of chatgptAcceptedTurnResponseWatchers){
    const tokenTargetKey=String(token?.targetKey||chatgptWorkflowTargetKey(token?.target||{}));
    if(keepTargetKey && tokenTargetKey===keepTargetKey)continue;
    if(token)token.cancelled=true;
    chatgptAcceptedTurnResponseWatchers.delete(key);
    cancelled+=1;
  }
  if(cancelled){
    chatgptResponseWatchState.cancelledCount+=cancelled;
    chatgptResponseWatchState.last={at:Date.now(),type:'cancelled-selection-change',targetKey:keepTargetKey,count:cancelled,reason:String(reason||'')};
    pushChatgptStabilityEvent('gpt-response-watch-cancelled-v186',{version:CHATGPT_BIND_ROUTE_RESPONSE_CLOSURE_VERSION,targetKey:keepTargetKey,count:cancelled,reason:String(reason||'')});
  }
  return cancelled;
}

function noteChatgptWorkflowSelection(target = null, reason = 'selection') {
  if (!target?.ok) return chatgptWorkflowAuthority.snapshot();
  const key = chatgptWorkflowTargetKey(target);
  if (!key) return chatgptWorkflowAuthority.snapshot();
  const current = chatgptWorkflowAuthority.snapshot();
  const sameLogical = !!(chatgptWorkbenchStableTarget?.ok && chatgptTargetsRepresentSameCustomer(chatgptWorkbenchStableTarget, target));
  const genuineSwitch=!!String(current.selectionTargetKey||'') && String(current.selectionTargetKey||'')!==key && !sameLogical;
  if(genuineSwitch){
    cancelChatgptResponseWatchesExcept(target,'workflow-selection-changed');
    if(chatgptWorkbenchDeferredBind && String(chatgptWorkbenchDeferredBind.targetKey||'')!==key){
      pushChatgptStabilityEvent('gpt-deferred-auto-bind-live-cancelled-v186',{version:CHATGPT_BIND_ROUTE_RESPONSE_CLOSURE_VERSION,oldTargetKey:String(chatgptWorkbenchDeferredBind.targetKey||''),targetKey:key,reason:'customer-selection-changed'});
      // Keep the durable pendingAutoBind row for safe later recovery; only stop
      // the live worker that belongs to the old page/selection.
      chatgptWorkbenchDeferredBind=null;
    }
  }
  // Do not rotate the canonical key during weak->strong identity hydration. A
  // genuine new customer increments selectionEpoch and instantly invalidates
  // every older mutation lease.
  chatgptWorkflowAuthority.noteSelection(key, { sameLogical, reason });
  return chatgptWorkflowAuthority.snapshot();
}

function beginChatgptMutationLease(target = null, purpose = 'mutation') {
  const key = chatgptWorkflowTargetKey(target);
  if (!target?.ok || !key) return null;
  const snap = chatgptWorkflowAuthority.snapshot();
  const pending=normalizeChatgptExpectedSelectionTarget(chatgptWorkbenchPendingExplicitSelectionTarget);
  const authority=activeChatgptMetaSelectionAuthority();
  if (pending?.ok && !chatgptTargetsRepresentSameCustomer(pending,target)) {
    chatgptWorkflowAuthority.rejectStale();
    pushChatgptStabilityEvent('gpt-workflow-mutation-refused',{targetKey:key,currentSelectionKey:String(snap.selectionTargetKey||''),purpose:String(purpose||''),reason:'pending-selection-mismatch'});
    return null;
  }
  if (authority?.ok && String(target.platform||'').toLowerCase()==='metabusiness' && !chatgptTargetsRepresentSameCustomer(authority,target)) {
    chatgptWorkflowAuthority.rejectStale();
    pushChatgptStabilityEvent('gpt-workflow-mutation-refused',{targetKey:key,currentSelectionKey:String(snap.selectionTargetKey||''),purpose:String(purpose||''),reason:'meta-authority-mismatch'});
    return null;
  }
  if (!snap.selectionTargetKey) chatgptWorkflowAuthority.noteSelection(key, { reason:`${purpose}-bootstrap` });
  else if (snap.selectionTargetKey !== key) {
    // A mutation may be the first authoritative event for native-api/automation.
    // Align only after the live/pending guards above; treating this as a real
    // selection change invalidates every older lease.
    chatgptWorkflowAuthority.noteSelection(key, { sameLogical:false, reason:`${purpose}-live-align` });
  }
  const lease = chatgptWorkflowAuthority.beginMutation(key,purpose);
  pushChatgptStabilityEvent('gpt-workflow-mutation-start',{id:lease.id,targetKey:key,purpose:String(purpose||'')});
  return lease;
}


async function acquireChatgptMutationLease(target = null, purpose = 'mutation', { maxWaitMs = 10000 } = {}) {
  const key=chatgptWorkflowTargetKey(target);
  if(!target?.ok||!key)return null;
  const started=Date.now();
  let waited=false;
  while(true){
    const pending=normalizeChatgptExpectedSelectionTarget(chatgptWorkbenchPendingExplicitSelectionTarget);
    const authority=activeChatgptMetaSelectionAuthority();
    if(pending?.ok&&!chatgptTargetsRepresentSameCustomer(pending,target))return null;
    if(authority?.ok&&String(target.platform||'').toLowerCase()==='metabusiness'&&!chatgptTargetsRepresentSameCustomer(authority,target))return null;
    const snap=chatgptWorkflowAuthority.snapshot();
    const active=snap?.activeMutation||null;
    if(!active||String(active.targetKey||'')!==key){
      const lease=beginChatgptMutationLease(target,purpose);
      if(lease&&waited){
        const elapsed=Date.now()-started;
        chatgptInteractionTransactionState.sameTargetWaitMs+=elapsed;
        chatgptInteractionTransactionState.last={at:Date.now(),type:'same-target-acquired',targetKey:key,purpose:String(purpose||''),waitedMs:elapsed};
        pushChatgptStabilityEvent('gpt-interaction-same-target-acquired-v163',{targetKey:key,purpose:String(purpose||''),waitedMs:elapsed});
      }
      return lease;
    }
    if(!waited){
      waited=true;
      chatgptInteractionTransactionState.sameTargetWaitCount+=1;
      pushChatgptStabilityEvent('gpt-interaction-same-target-wait-v163',{targetKey:key,purpose:String(purpose||''),activePurpose:String(active.purpose||''),activeId:Number(active.id||0)});
    }
    const activeAge=Date.now()-Number(active.startedAt||Date.now());
    const waitAge=Date.now()-started;
    if(activeAge>CHATGPT_WORKFLOW_WATCHDOG_THRESHOLDS.mutationLeaseMs||waitAge>Math.max(1500,Number(maxWaitMs||10000))){
      if(chatgptWorkflowAuthority.finish(active)){
        chatgptInteractionTransactionState.forcedRecoveryCount+=1;
        chatgptInteractionTransactionState.last={at:Date.now(),type:'stale-same-target-release',targetKey:key,purpose:String(purpose||''),activePurpose:String(active.purpose||''),activeAge,waitAge};
        pushChatgptStabilityEvent('gpt-interaction-stale-same-target-release-v163',{targetKey:key,purpose:String(purpose||''),activePurpose:String(active.purpose||''),activeAge,waitAge});
        continue;
      }
    }
    await waitMs(45);
  }
}

function assertChatgptMutationLease(lease = null, target = null, phase = 'mutation') {
  const key = chatgptWorkflowTargetKey(target) || String(lease?.targetKey || '');
  const pending = normalizeChatgptExpectedSelectionTarget(chatgptWorkbenchPendingExplicitSelectionTarget);
  const authority = activeChatgptMetaSelectionAuthority();
  let valid = !!lease && chatgptWorkflowAuthority.isCurrent(lease,key);
  if (valid && pending?.ok && target?.ok && !chatgptTargetsRepresentSameCustomer(pending,target)) valid=false;
  if (valid && authority?.ok && String(target?.platform||'').toLowerCase()==='metabusiness' && target?.ok && !chatgptTargetsRepresentSameCustomer(authority,target)) valid=false;
  if (!valid) {
    chatgptWorkflowAuthority.rejectStale();
    pushChatgptStabilityEvent('gpt-workflow-stale-blocked',{id:Number(lease?.id||0),targetKey:key,phase:String(phase||'')});
    return { ok:false, targetChanged:true, staleWorkflow:true, error:'客户已经切换，本次 GPT 操作已自动终止，旧任务不会写入或发送到新客户。' };
  }
  return { ok:true };
}

function finishChatgptMutationLease(lease = null, result = '') {
  if (!lease) return false;
  const finished = chatgptWorkflowAuthority.finish(lease);
  if (finished) pushChatgptStabilityEvent('gpt-workflow-mutation-finish',{id:Number(lease.id||0),targetKey:String(lease.targetKey||''),result:String(result||'')});
  return finished;
}

function chatgptFreshConversationOwnedByTarget(target = null, currentUrl = '') {
  const key = chatgptWorkflowTargetKey(target);
  if (!key || String(chatgptWorkbenchFreshConversationOwnerKey || '') !== key) return false;
  if (Date.now() - Number(chatgptWorkbenchFreshConversationOwnerAt || 0) >= 10 * 60 * 1000) return false;
  return isChatgptConversationUrl(currentUrl) || chatgptWorkbenchDestinationMatches(currentUrl, CHATGPT_HOME_URL, null);
}

function noteChatgptPendingAutoBindReject(targetKey = '', conversation = '', reason = 'fingerprint-mismatch') {
  const key=`${String(targetKey||'')}::${String(conversation||'')}::${String(reason||'')}`;
  const now=Date.now();
  const previous=Number(chatgptPendingAutoBindRejectMemo.get(key)||0);
  if(now-previous<5000)return false;
  chatgptPendingAutoBindRejectMemo.set(key,now);
  if(chatgptPendingAutoBindRejectMemo.size>240){
    for(const [memoKey,at] of chatgptPendingAutoBindRejectMemo){if(now-Number(at||0)>60000)chatgptPendingAutoBindRejectMemo.delete(memoKey)}
  }
  chatgptPendingAutoBindRejectCount += 1;
  return true;
}

function chatgptPendingAutoBindRows() {
  const cfg=chatgptWorkbenchConfig();
  if (!cfg.pendingAutoBinds || typeof cfg.pendingAutoBinds!=='object') cfg.pendingAutoBinds={};
  // Migrate the V1.27.113/early-114 single pending row without losing it.
  if (cfg.pendingAutoBind && typeof cfg.pendingAutoBind==='object') {
    const key=String(cfg.pendingAutoBind.targetKey||'').trim();
    if (key && !cfg.pendingAutoBinds[key]) cfg.pendingAutoBinds[key]={...cfg.pendingAutoBind};
    cfg.pendingAutoBind=null;
    saveConfig(config);
  }
  return cfg.pendingAutoBinds;
}

function chatgptPendingAutoBindConfig(target = null) {
  const rows=chatgptPendingAutoBindRows();
  const key=target?.ok ? chatgptWorkflowTargetKey(target) : '';
  if (key && rows[key]) return rows[key];
  if (target?.ok) {
    for (const row of Object.values(rows)) {
      const saved=normalizeChatgptExpectedSelectionTarget(row?.target);
      if (saved?.ok && chatgptTargetsRepresentSameCustomer(saved,target)) return row;
    }
    return null;
  }
  const values=Object.values(rows).filter(row=>row&&typeof row==='object');
  values.sort((a,b)=>Number(b.startedAt||0)-Number(a.startedAt||0));
  return values[0]||null;
}

function chatgptDurableBootstrapPendingForTarget(target = null) {
  if (!target?.ok) return null;
  const pending=chatgptPendingAutoBindConfig(target);
  if (!pending || String(pending.purpose || '') !== 'customer-bootstrap-draft') return null;
  if (Number(pending.expiresAt || 0) && Date.now() > Number(pending.expiresAt || 0)) return null;
  const saved=normalizeChatgptExpectedSelectionTarget(pending.target);
  if (!saved?.ok || !chatgptTargetsRepresentSameCustomer(saved,target)) return null;
  return pending;
}

function persistChatgptPendingAutoBind(target = null, prompt = '', { ttlMs = 10 * 60 * 1000, purpose = 'customer-turn', metadata = null } = {}) {
  if (!target?.ok) return null;
  const targetKey=chatgptWorkflowTargetKey(target);
  const fingerprint=chatgptPromptFingerprint(prompt);
  if (!targetKey || !fingerprint) return null;
  const now=Date.now();
  const row={
    version:2,
    target:chatgptSafeTargetSnapshot(target),
    targetKey,
    promptFingerprint:fingerprint,
    promptLength:normalizeChatgptText(prompt).length,
    purpose:String(purpose || 'customer-turn').trim().slice(0,80) || 'customer-turn',
    metadata:metadata && typeof metadata === 'object' ? {
      bootstrapVersion:String(metadata.bootstrapVersion || '').slice(0,120),
      customerName:String(metadata.customerName || '').slice(0,180),
      personaFingerprint:String(metadata.personaFingerprint || '').slice(0,128)
    } : null,
    startedAt:now,
    expiresAt:now+Math.max(60000,Number(ttlMs||0))
  };
  const rows=chatgptPendingAutoBindRows();
  rows[targetKey]=row;
  // Bound growth while preserving recent crash/restart recovery.
  const entries=Object.entries(rows).sort((a,b)=>Number(b[1]?.startedAt||0)-Number(a[1]?.startedAt||0));
  for (const [oldKey] of entries.slice(24)) delete rows[oldKey];
  if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['pendingAutoBinds'],{immediate:true});else saveConfig(config);
  return row;
}

function clearChatgptPendingAutoBind(reason = '', target = null) {
  const cfg=chatgptWorkbenchConfig();
  const rows=chatgptPendingAutoBindRows();
  let removed=false;
  if (target?.ok) {
    for (const [key,row] of Object.entries(rows)) {
      const saved=normalizeChatgptExpectedSelectionTarget(row?.target);
      if (key===chatgptWorkflowTargetKey(target) || (saved?.ok && chatgptTargetsRepresentSameCustomer(saved,target))) {
        delete rows[key]; removed=true;
      }
    }
  } else {
    for (const key of Object.keys(rows)) { delete rows[key]; removed=true; }
  }
  cfg.pendingAutoBind=null;
  if (removed) {if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['pendingAutoBinds'],{immediate:true});else saveConfig(config);}
  if (removed && reason) pushChatgptStabilityEvent('gpt-pending-autobind-cleared',{reason:String(reason||''),targetKey:target?.ok?chatgptWorkflowTargetKey(target):''});
  return removed;
}

async function chatgptCurrentConversationMatchesPromptFingerprint(view, fingerprint = '') {
  if (!view || view.isDestroyed() || !fingerprint) return false;
  let state=null;
  try { state=await view.webContents.executeJavaScript(chatgptSubmissionStateScript(),true); } catch { state=null; }
  return !!state && chatgptPromptFingerprint(state.latestUser || '') === String(fingerprint || '');
}

function storeChatgptBindingForTarget(target = {}, url = '', win = chatgptWorkbenchWindow, reason = 'manual') {
  if (!target?.ok || !isChatgptStableConversationUrl(url)) { if(target?.ok && isChatgptTransientConversationUrl(url)) noteChatgptTransientBinding(url,chatgptWorkflowTargetKey(target),'store-reject'); return null; }
  const key = String(target.targetKey || speechLibraryTargetKey(target) || '').trim();
  if (!key) return null;
  const collision = chatgptConversationBindingCollision(url,target);
  if (collision) {
    chatgptBindingCollisionRejectCount += 1;
    chatgptLastBindingCollision = { ...collision, targetKey:key, targetDisplayName:String(target.displayName||''), at:Date.now(), reason:String(reason||'manual') };
    pushChatgptStabilityEvent('gpt-binding-collision-blocked', chatgptLastBindingCollision);
    traceHandoff('gpt-binding-collision-blocked', chatgptLastBindingCollision);
    return null;
  }
  const previousRow = chatgptWorkbenchConfig().bindings[key] && typeof chatgptWorkbenchConfig().bindings[key] === 'object'
    ? chatgptWorkbenchConfig().bindings[key] : null;
  const row = {
    ...(previousRow?.customerBootstrap ? { customerBootstrap:{ ...previousRow.customerBootstrap } } : {}),
    ...(previousRow?.dailyFlowState ? { dailyFlowState:{ ...previousRow.dailyFlowState } } : {}),
    personaInitialized:previousRow?.personaInitialized === true || !!previousRow?.customerBootstrap?.initializedAt,
    flowLibraryFingerprint:String(previousRow?.flowLibraryFingerprint || previousRow?.customerBootstrap?.flowLibraryFingerprint || '').slice(0,128),
    flowLibraryInitializedAt:String(previousRow?.flowLibraryInitializedAt || previousRow?.customerBootstrap?.flowLibraryInitializedAt || ''),
    url:String(url),
    title:String(win && !win.isDestroyed?.() ? (win.webContents?.getTitle?.() || '') : '').slice(0,240),
    platform:String(target.platform || ''),
    accountId:String(target.accountId || ''),
    chatId:String(target.chatId || ''),
    displayName:String(target.displayName || ''),
    boundAt:new Date().toISOString(),
    boundReason:String(reason || 'manual').slice(0,80)
  };
  chatgptWorkbenchConfig().bindings[key] = row;
  saveConfig(config);
  persistChatgptBindingsShadow(chatgptWorkbenchConfig());
  if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings'],{immediate:true,localCritical:true});
  chatgptWorkbenchTargetKey = key;
  traceHandoff('gpt-binding-stored', {
    reason:String(reason || 'manual'), targetKey:key,
    conversation:handoffConversationRef(url), displayName:String(target.displayName || '')
  });
  try{updateChatgptWorkbenchWindowTitle(target)}catch{}
  return { ...row, targetKey:key };
}

function chatgptCustomerBootstrapName(target = {}) {
  let crmName = '';
  try {
    const context = chatgptCrmContextForTarget(target);
    crmName = speechLibrarySanitizeCustomerName(context?.contact?.name || '');
  } catch {}
  // V1.27.117: for the official API inbox, the selected customer card/header is
  // the identity authority. CRM auto-extraction can temporarily contain a
  // placeholder such as "未" before profile hydration; that placeholder must
  // never outrank a real Messenger/LINE profile name already visible in Yoko.
  const visibleName = speechLibrarySanitizeCustomerName(target?.displayName || '');
  const librarySafe = speechLibrarySafeCustomerName({ ...target, crmName });
  const candidates = String(target?.surface || '') === 'native-api'
    ? [visibleName, librarySafe, crmName, target?.crmName, target?.salutationName, target?.handle]
    : [crmName, librarySafe, target?.crmName, visibleName, target?.salutationName, target?.handle];
  for (const candidate of candidates) {
    const safe = speechLibrarySanitizeCustomerName(candidate || '');
    if (safe) return safe;
  }
  return '未识别姓名';
}

function chatgptSplitLegacyFlowLibrary(value = '') {
  const text = String(value || '').replace(/\r\n?/g, '\n').trim();
  if (!text) return {};
  const markers = [
    /(?:^|\n)(DAY 1｜[^\n]*)/,
    /(?:^|\n)(DAY 2｜[^\n]*)/,
    /(?:^|\n)(DAY 3｜[^\n]*)/,
    /(?:^|\n)(第四天主题[^\n]*)/,
    /(?:^|\n)(第五天主题[^\n]*)/,
    /(?:^|\n)(第六天主题[^\n]*)/,
    /(?:^|\n)(第七天主题[^\n]*)/,
    /(?:^|\n)(第八天主题[^\n]*)/,
    /(?:^|\n)(第九天主题[^\n]*)/,
    /(?:^|\n)(#?\s*第十天主题[^\n]*)/
  ];
  const starts = [];
  for (let i = 0; i < markers.length; i += 1) {
    const match = markers[i].exec(text);
    if (!match || match.index < 0) continue;
    const markerOffset = match[0].startsWith('\n') ? 1 : 0;
    starts.push({ day:i + 1, index:match.index + markerOffset });
  }
  if (!starts.length) return {};
  starts.sort((a,b)=>a.index-b.index);
  const out = {};
  for (let i = 0; i < starts.length; i += 1) {
    const row = starts[i];
    const next = starts[i + 1];
    const chunk = text.slice(row.index, next ? next.index : text.length).trim().slice(0, 20000);
    if (chunk) out[`day${row.day}`] = chunk;
  }
  return out;
}

function chatgptNormalizeFlowDays(value = {}, fallback = {}) {
  const src = value && typeof value === 'object' ? value : {};
  const fb = fallback && typeof fallback === 'object' ? fallback : {};
  const out = {};
  for (let day = 1; day <= CHATGPT_DAILY_FLOW_DAY_COUNT; day += 1) {
    const key = `day${day}`;
    const raw = src[key] ?? src[String(day)] ?? fb[key] ?? fb[String(day)] ?? '';
    out[key] = String(raw || '').replace(/\r\n?/g, '\n').trim().slice(0, 20000);
  }
  return out;
}

function chatgptCombineFlowDays(value = {}) {
  const days = chatgptNormalizeFlowDays(value, {});
  return Array.from({length:CHATGPT_DAILY_FLOW_DAY_COUNT}, (_,idx)=>String(days[`day${idx+1}`] || '').trim())
    .filter(Boolean).join('\n\n').trim().slice(0, 60000);
}

function chatgptFlowDays() {
  const cfg = chatgptWorkbenchConfig();
  return chatgptNormalizeFlowDays(cfg.flowDays, DEFAULT_CHATGPT_FLOW_DAYS);
}

function chatgptFlowLibraryText() {
  return chatgptCombineFlowDays(chatgptFlowDays());
}

function chatgptFlowDayText(day = 0) {
  const index = Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(day || 0) || 0));
  if (!index) return '';
  // V1.27.154 freeze hotfix: hot Day-state reads need only ONE Day. Do not
  // normalize/copy all ten Day scripts (up to ~60-80KB) for every fingerprint.
  const cfg = chatgptWorkbenchConfig();
  const key = `day${index}`;
  const raw = cfg?.flowDays?.[key] ?? cfg?.flowDays?.[String(index)] ?? DEFAULT_CHATGPT_FLOW_DAYS?.[key] ?? DEFAULT_CHATGPT_FLOW_DAYS?.[String(index)] ?? '';
  return String(raw || '').replace(/\r\n?/g, '\n').trim().slice(0, 20000);
}

function chatgptFlowLibraryFingerprint(value = null) {
  const text = value === null ? chatgptFlowLibraryText() : String(value || '').replace(/\r\n?/g, '\n').trim();
  return text ? chatgptPromptFingerprint(`${CHATGPT_FLOW_ADVISOR_VERSION}\n${text}`) : '';
}

function chatgptFlowDayFingerprint(day = 0, value = null) {
  const safeDay = Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(day || 0) || 0));
  const text = value === null ? chatgptFlowDayText(safeDay) : String(value || '').replace(/\r\n?/g, '\n').trim();
  return safeDay && text ? chatgptPromptFingerprint(`${CHATGPT_DAILY_FLOW_SYNC_VERSION}\nDay ${safeDay}\n${text}`) : '';
}

function chatgptBindingFlowFingerprint(binding = null) {
  if (!binding || typeof binding !== 'object') return '';
  return String(binding.flowLibraryFingerprint || binding.customerBootstrap?.flowLibraryFingerprint || '').trim();
}

function chatgptNormalizeChatMode(value = '') {
  const mode = String(value || '').trim().toLowerCase();
  if (['deep','deep-chat','precision','精聊','精聊模式'].includes(mode)) return CHATGPT_CHAT_MODE_DEEP;
  if (['reception','receive','intake','接待','接待模式'].includes(mode)) return CHATGPT_CHAT_MODE_RECEPTION;
  return '';
}

function chatgptDefaultChatModeForTarget(target = {}) {
  const surface = String(target?.surface || '').trim().toLowerCase();
  const platform = String(target?.platform || '').trim().toLowerCase();
  // V1.27.159 final user rule: the aggregated Official API workspace is an
  // acquisition/reception surface even when its current provider is LINE API.
  if (surface === 'native-api' || surface === 'official-api' || surface === 'aggregate-api') return CHATGPT_CHAT_MODE_RECEPTION;
  // Telegram / WhatsApp / LINE real chat clients are handoff/relationship apps.
  if (['telegram','tg','whatsapp','ws','line'].includes(platform)) return CHATGPT_CHAT_MODE_DEEP;
  // TikTok / Instagram / Facebook / Meta Business and all unknown acquisition
  // surfaces start in reception mode unless the operator explicitly overrides.
  return CHATGPT_CHAT_MODE_RECEPTION;
}

function chatgptChatModeTargetKey(target = {}) {
  return String(chatgptWorkflowTargetKey(target) || speechLibraryTargetKey(target) || '').trim();
}

function chatgptChatModeForTarget(target = null, binding = null) {
  const cfg = chatgptWorkbenchConfig();
  const t = target && typeof target === 'object' ? target : {};
  const directKey = chatgptChatModeTargetKey(t);
  const row = binding && typeof binding === 'object' ? binding : (t?.ok ? chatgptBindingForTarget(t) : null);
  const inheritedKey = String(row?.inheritedFromTargetKey || '').trim();
  const map = cfg.customerChatModes && typeof cfg.customerChatModes === 'object' ? cfg.customerChatModes : {};
  for (const key of [directKey, inheritedKey]) {
    if (!key) continue;
    const raw = map[key];
    const explicit = chatgptNormalizeChatMode(raw?.mode ?? raw);
    if (explicit) return { mode:explicit, source:'manual', targetKey:key, version:CHATGPT_CHAT_MODE_VERSION };
  }
  const rowExplicit = chatgptNormalizeChatMode(row?.chatModeManual ? row?.chatMode : '');
  if (rowExplicit) return { mode:rowExplicit, source:'manual-binding', targetKey:directKey || inheritedKey, version:CHATGPT_CHAT_MODE_VERSION };
  return { mode:chatgptDefaultChatModeForTarget(t || row || {}), source:'channel-default', targetKey:directKey || inheritedKey, version:CHATGPT_CHAT_MODE_VERSION };
}

function chatgptReceptionStateForTarget(target = {}, binding = null) {
  const crm = chatgptCrmContextForTarget(target);
  const c = crm?.contact && typeof crm.contact === 'object' ? crm.contact : {};
  const genericName = /^(?:facebook|instagram|tiktok|telegram|whatsapp|line|meta|mb)?\s*(?:用户|user|customer|客户)?$/i;
  const name = String(c.name || '').trim();
  const known = {
    name: !!name && !genericName.test(name),
    age: !!String(c.age || '').trim(),
    region: !!String(c.region || '').trim(),
    interests: !!String(c.interests || '').trim(),
    occupation: !!String(c.occupation || '').trim()
  };
  const memoryCount = Array.isArray(c.memoryItems) ? c.memoryItems.filter(x => String(x?.text || '').trim()).length : 0;
  const basicChat = memoryCount >= 2 || String(c.memorySummary || '').trim().length >= 40;
  const lineProgress = String(c.lineProgress || 'not_started').trim();
  const lineReady = ['added','completed','bound','handoff_complete','done'].includes(lineProgress) || String(c.stage || '').includes('LINE已添加');
  let nextStep = 'greeting';
  if (binding?.customerBootstrap?.initializedAt || binding?.personaInitialized) nextStep = 'name';
  if (!known.name) nextStep = 'name';
  else if (!known.age) nextStep = 'age';
  else if (!known.occupation) nextStep = 'occupation';
  else if (!known.region) nextStep = 'region';
  else if (!known.interests) nextStep = 'interests';
  else if (!basicChat) nextStep = 'basic-chat';
  else if (!lineReady) nextStep = 'line-exchange';
  else nextStep = 'completed';
  const completedCount = [known.name,known.age,known.occupation,known.region,known.interests,basicChat,lineReady].filter(Boolean).length;
  const labelMap = { greeting:'打招呼', name:'了解姓名', age:'了解年龄', occupation:'了解工作', region:'了解地区', interests:'了解兴趣爱好', 'basic-chat':'基础交流', 'line-exchange':'自然提出交换 LINE', completed:'接待完成' };
  return {
    version:CHATGPT_RECEPTION_FLOW_VERSION,
    known,
    basicChat,
    lineReady,
    lineProgress,
    nextStep,
    nextLabel:labelMap[nextStep] || '自然接待',
    completedCount,
    totalCount:7,
    crmText:String(crm?.text || '').slice(0,5200)
  };
}

function chatgptReceptionInstruction(target = {}, binding = null) {
  const state = chatgptReceptionStateForTarget(target,binding);
  const missing = [];
  if (!state.known.name) missing.push('姓名');
  if (!state.known.age) missing.push('年龄');
  if (!state.known.occupation) missing.push('工作');
  if (!state.known.region) missing.push('地区');
  if (!state.known.interests) missing.push('兴趣爱好');
  const lines = [
    '【当前聊天模式：接待模式｜内部规则】',
    '当前客户来自前端获客/接待渠道。现在不要启动、推荐或提前执行 Day 1～Day 10 精聊流程。',
    '接待目标：先自然打招呼，然后根据真实对话逐步了解姓名、年龄、工作、地区、兴趣爱好；再做一点自然基础交流，最后在气氛自然时提出交换 LINE。',
    '不要像表格盘问。一次最多自然推进一个主要资料点；如果客户一条消息已经主动提供多个资料，直接记住并跳过，不得重复询问。',
    CHATGPT_REPLY_PRIORITY_RULES,
    '优先回应客户正在说的内容和情绪，再顺势推进接待目标；资料收集服务于自然交流，不得压过真实对话。',
    '接待前期不要主动透露Yoko所在地；只有客户明确询问时才按固定人设真实回答。聊到Yoko工作时只需自然说明“我现在经营一家精品店”，不要主动扩展城市、进货或经营细节。',
    `当前系统已知资料：${state.crmText || '暂无已保存资料。'}`,
    missing.length ? `当前仍缺：${missing.join('、')}。` : '姓名、年龄、工作、地区、兴趣爱好五项基础资料已基本齐全。',
    `当前建议接待节点：${state.nextLabel}。`,
    '当姓名、年龄、工作、地区、兴趣爱好和基础了解已经足够时，才自然提出交换 LINE；不要过早索要联系方式。',
    '如果客户拒绝交换 LINE，不纠缠、不施压，继续正常聊天，并在【当前阶段建议｜内部参考】里提示我暂缓。',
    '',
    '【接待流程库｜当前配置】',
    String(chatgptWorkbenchConfig().receptionFlow || DEFAULT_CHATGPT_RECEPTION_FLOW).trim().slice(0,12000)
  ];
  return { state, text:lines.join('\n') };
}

function chatgptSetCustomerChatMode(target = {}, mode = '') {
  const normalized = chatgptNormalizeChatMode(mode);
  if (!target?.ok || !normalized) return { ok:false, error:'当前没有可设置模式的客户。' };
  const cfg = chatgptWorkbenchConfig();
  if (!cfg.customerChatModes || typeof cfg.customerChatModes !== 'object') cfg.customerChatModes = {};
  const key = chatgptChatModeTargetKey(target);
  if (!key) return { ok:false, error:'当前客户缺少稳定标识。' };
  cfg.customerChatModes[key] = { mode:normalized, updatedAt:Date.now(), version:CHATGPT_CHAT_MODE_VERSION };
  const binding = chatgptBindingForTarget(target);
  if (binding && typeof binding === 'object') {
    binding.chatMode = normalized;
    binding.chatModeManual = true;
    binding.chatModeUpdatedAt = Date.now();
    binding.chatModeVersion = CHATGPT_CHAT_MODE_VERSION;
  }
  saveConfig(config);
  persistChatgptBindingsShadow(cfg);
  if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings','customerChatModes'],{immediate:true,localCritical:true});
  pushChatgptStabilityEvent('gpt-chat-mode-changed-v159',{targetKey:key,mode:normalized,platform:String(target.platform||''),surface:String(target.surface||'')});
  sendChatgptWorkbenchUpdated(target);
  return { ok:true, mode:normalized, source:'manual', reception:chatgptReceptionStateForTarget(target,binding) };
}

function chatgptNormalizeDailyFlowState(value = null, now = Date.now()) {
  const src = value && typeof value === 'object' ? value : {};
  let currentDay = Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(src.currentDay || 0) || 0));
  let status = String(src.status || '').trim();
  if (!['waiting-morning','active','finished'].includes(status)) status = currentDay >= CHATGPT_DAILY_FLOW_DAY_COUNT && src.completedAt ? 'finished' : 'waiting-morning';
  if (status === 'finished') currentDay = CHATGPT_DAILY_FLOW_DAY_COUNT;
  const initializedAtMs = Math.max(0, Number(src.initializedAtMs || 0) || Number(now || Date.now()));
  const enrollmentDateKey = String(src.enrollmentDateKey || src.newCustomerDateKey || '').trim();
  const stageNow = resolveDailyFlowStage(now);
  const stageActive = status === 'active' && currentDay >= 1 && currentDay <= CHATGPT_DAILY_FLOW_DAY_COUNT && stageNow.active;
  const normalized = {
    version:CHATGPT_DAILY_FLOW_STATE_VERSION,
    clockVersion:CHATGPT_DAILY_FLOW_CLOCK_VERSION,
    dayStageVersion:CHATGPT_DAILY_FLOW_STAGE_VERSION,
    currentDay,
    status,
    waitingNextMorning:status === 'waiting-morning',
    enrollmentDateKey,
    newCustomerDateKey:enrollmentDateKey,
    schedulePhase:String(src.schedulePhase || (currentDay ? (status === 'active' ? 'active' : status === 'finished' ? 'finished' : 'waiting-window') : 'new-customer')),
    scheduleDateKey:String(src.scheduleDateKey || ''),
    dayDateKey:String(src.dayDateKey || ''),
    scheduleStartMinute:Math.max(0, Number(src.scheduleStartMinute ?? CHATGPT_DAILY_FLOW_CLOCK_DEFAULTS.startMinute) || CHATGPT_DAILY_FLOW_CLOCK_DEFAULTS.startMinute),
    scheduleEndMinute:Math.max(0, Number(src.scheduleEndMinute ?? CHATGPT_DAILY_FLOW_CLOCK_DEFAULTS.endMinute) || CHATGPT_DAILY_FLOW_CLOCK_DEFAULTS.endMinute),
    lastScheduleReconciledAt:String(src.lastScheduleReconciledAt || ''),
    startedAt:String(src.startedAt || ''),
    completedAt:String(src.completedAt || ''),
    lastBoundaryAt:String(src.lastBoundaryAt || ''),
    lastBoundaryType:String(src.lastBoundaryType || ''),
    lastBoundarySource:String(src.lastBoundarySource || ''),
    manualDayCorrectionDay:Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(src.manualDayCorrectionDay || 0) || 0)),
    manualDayCorrectionDateKey:String(src.manualDayCorrectionDateKey || ''),
    manualDayCorrectionAt:String(src.manualDayCorrectionAt || ''),
    manualDayCorrectionSource:String(src.manualDayCorrectionSource || ''),
    dayStageKey:stageActive ? String(stageNow.key||'') : '',
    dayStageLabel:stageActive ? String(stageNow.label||'') : '',
    dayStageIndex:stageActive ? Number(stageNow.index||0) : -1,
    dayStageClock:stageActive ? String(stageNow.clockText||'') : '',
    dayStageCompletedKeys:stageActive ? [...stageNow.completedKeys] : [],
    dayStageCompletedLabels:stageActive ? [...stageNow.completedLabels] : [],
    dayStageNextKey:stageActive ? String(stageNow.nextKey||'') : '',
    dayStageNextLabel:stageActive ? String(stageNow.nextLabel||'') : '',
    intradayDirectionProgress:normalizeDailyFlowDirectionProgress(src.intradayDirectionProgress,currentDay),
    lastObservedOutgoingAt:Math.max(0, Number(src.lastObservedOutgoingAt || 0) || initializedAtMs),
    initializedAtMs
  };
  normalized.delivery = chatgptNormalizeDailyFlowDelivery(src.delivery, normalized, now);
  return normalized;
}

function chatgptDailyFlowDeliveryId(day = 0, fingerprint = '', startedAt = '', initializedAtMs = 0) {
  // Exactly-once identity is per customer Day start, not per editable flow text.
  // Editing today's flow before/after delivery must never manufacture a second
  // delivery identity for the same Day.
  const seed = `${CHATGPT_DAILY_FLOW_DELIVERY_VERSION}|${Number(day||0)}|${String(startedAt||'')}|${Number(initializedAtMs||0)}`;
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return `df${Number(day||0)}-${Number(initializedAtMs||0).toString(36)}-${hash.toString(36)}`.slice(0,80);
}

function chatgptNormalizeDailyFlowDelivery(value = null, state = null, now = Date.now()) {
  const src = value && typeof value === 'object' ? value : {};
  const day = Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(src.day || state?.currentDay || 0) || 0));
  // V1.27.154 freeze hotfix: normalization runs on high-frequency UI/state reads.
  // It must stay pure and cheap. Never parse/hash the 10-day flow library here.
  // Fingerprints are computed only when a Day is created or actively delivered.
  const fingerprint = String(src.fingerprint || '').trim().slice(0,128);
  let status = String(src.status || '').trim();
  const allowed = ['none','pending','in-flight','failed','delivered','locked'];
  if (!allowed.includes(status)) status = day && state?.status === 'active' ? 'pending' : 'none';
  if (!day) status = 'none';
  const initializedAtMs = Math.max(0, Number(state?.initializedAtMs || 0) || Number(now || Date.now()));
  const startedAt = String(state?.startedAt || src.startedAt || '');
  const deliveryId = day ? String(src.deliveryId || chatgptDailyFlowDeliveryId(day,fingerprint,startedAt,initializedAtMs)).slice(0,80) : '';
  return {
    version:CHATGPT_DAILY_FLOW_DELIVERY_VERSION,
    day,
    fingerprint,
    deliveryId,
    status,
    attempts:Math.max(0, Number(src.attempts || 0) || 0),
    queuedAt:String(src.queuedAt || ''),
    lastAttemptAt:String(src.lastAttemptAt || ''),
    submittedAt:String(src.submittedAt || ''),
    deliveredAt:String(src.deliveredAt || ''),
    lockedAt:String(src.lockedAt || ''),
    conversationRef:String(src.conversationRef || '').slice(0,240),
    lastError:String(src.lastError || '').slice(0,500),
    lastReason:String(src.lastReason || '').slice(0,160)
  };
}

function chatgptCreateDailyFlowDelivery(day = 0, state = null, now = Date.now(), reason = 'clock-day-start') {
  const safeDay = Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(day || 0) || 0));
  let fingerprint = '';
  if (safeDay && typeof chatgptFlowDayFingerprint === 'function') {
    try { fingerprint = String(chatgptFlowDayFingerprint(safeDay) || '').trim().slice(0,128); } catch {}
  }
  const base = state && typeof state === 'object' ? state : {};
  const startedAt = String(base.startedAt || new Date(Number(now || Date.now())).toISOString());
  const initializedAtMs = Math.max(0, Number(base.initializedAtMs || 0) || Number(now || Date.now()));
  return chatgptNormalizeDailyFlowDelivery({
    day:safeDay,
    fingerprint,
    deliveryId:chatgptDailyFlowDeliveryId(safeDay,fingerprint,startedAt,initializedAtMs),
    status:safeDay ? 'pending' : 'none',
    queuedAt:safeDay ? new Date(Number(now || Date.now())).toISOString() : '',
    lastReason:String(reason || 'clock-day-start')
  }, {...base,currentDay:safeDay,status:safeDay?'active':String(base.status||'waiting-morning'),startedAt,initializedAtMs}, now);
}

function chatgptDailyFlowClockSettings() {
  return normalizeDailyFlowClockSettings(CHATGPT_DAILY_FLOW_CLOCK_DEFAULTS);
}

function chatgptPendingClockDelivery(day = 0, state = null, now = Date.now(), reason = 'clock-day-start') {
  const safeDay = Math.max(0, Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT, Number(day || 0) || 0));
  const base = state && typeof state === 'object' ? state : {};
  const startedAt = String(base.startedAt || new Date(Number(now || Date.now())).toISOString());
  const initializedAtMs = Math.max(0, Number(base.initializedAtMs || 0) || Number(now || Date.now()));
  return chatgptNormalizeDailyFlowDelivery({
    day:safeDay,
    fingerprint:'',
    deliveryId:chatgptDailyFlowDeliveryId(safeDay,'',startedAt,initializedAtMs),
    status:safeDay ? 'pending' : 'none',
    queuedAt:safeDay ? new Date(Number(now || Date.now())).toISOString() : '',
    lastReason:String(reason || 'clock-day-start')
  }, {...base,currentDay:safeDay,status:safeDay?'active':String(base.status||'waiting-morning'),startedAt,initializedAtMs}, now);
}

function chatgptReconcileDailyFlowClockState(value = null, now = Date.now(), reason = 'clock-read') {
  const base = chatgptNormalizeDailyFlowState(value,now);
  // V1.27.200: Day selection is calendar/time authoritative. The customer's
  // first local calendar date is ALWAYS the new-customer day; Day 1 begins on
  // the next calendar date at 05:00. Every Day is active 05:00-23:00 and the
  // next Day opens automatically at 05:00 without any greeting trigger.
  const raw = reconcileScheduledState(base,now,chatgptDailyFlowClockSettings());
  // Once Day 10 has been completed it is terminal; a version migration must
  // never reopen Day 10 just because the current wall clock is before 23:00.
  if(base.status==='finished' && Number(base.currentDay||0)>=CHATGPT_DAILY_FLOW_DAY_COUNT){
    raw.currentDay=CHATGPT_DAILY_FLOW_DAY_COUNT; raw.status='finished'; raw.waitingNextMorning=false; raw.schedulePhase='finished';
  }
  const previousDay=Math.max(0,Number(raw._previousDay||0)||0), previousStatus=String(raw._previousStatus||'');
  const next=chatgptNormalizeDailyFlowState(raw,now);
  const scheduleChanged=!!raw._scheduleChanged;
  const dayChanged=previousDay!==next.currentDay;
  const statusChanged=previousStatus!==next.status;
  let delivery=chatgptNormalizeDailyFlowDelivery(base.delivery,base,now);
  if(next.currentDay<=0){
    delivery=chatgptNormalizeDailyFlowDelivery({day:0,status:'none'},next,now);
  } else if(next.status==='active'){
    if(dayChanged || delivery.day!==next.currentDay || ['none','locked'].includes(String(delivery.status||''))){
      delivery=chatgptPendingClockDelivery(next.currentDay,next,now,dayChanged?'clock-new-day':'clock-day-start');
    } else {
      delivery=chatgptNormalizeDailyFlowDelivery(delivery,next,now);
    }
  } else {
    delivery=chatgptNormalizeDailyFlowDelivery(delivery,next,now);
    if(delivery.day===next.currentDay && ['pending','failed','in-flight'].includes(String(delivery.status||''))){
      const closedAt=String(next.completedAt || new Date(Number(now||Date.now())).toISOString());
      delivery=chatgptNormalizeDailyFlowDelivery({
        ...delivery,status:'locked',lockedAt:closedAt,lastError:'day-window-closed-before-flow-delivery',lastReason:'clock-2300-close'
      },next,now);
    }
  }
  next.delivery=delivery;
  if(scheduleChanged||dayChanged||statusChanged){
    const at=next.status==='active'?String(next.startedAt||new Date(now).toISOString()):String(next.completedAt||new Date(now).toISOString());
    next.lastBoundaryAt=at;
    next.lastBoundaryType=next.currentDay<=0?'new-customer-day':(next.status==='active'?'clock-start':next.status==='finished'?'clock-finished':'clock-end');
    next.lastBoundarySource=String(reason||'clock').slice(0,100);
  }
  return {state:next,changed:scheduleChanged||dayChanged||statusChanged,dayChanged,statusChanged,previousDay,previousStatus};
}

function chatgptDailyFlowDeliveryRank(value = null) {
  const status = String(value?.status || 'none');
  return ({ none:0, pending:1, failed:2, 'in-flight':3, locked:4, delivered:5 })[status] || 0;
}

function chatgptDailyFlowProgressRank(value = null) {
  const state = chatgptNormalizeDailyFlowState(value);
  const day = Math.max(0, Number(state.currentDay || 0) || 0);
  if (state.status === 'finished') return (CHATGPT_DAILY_FLOW_DAY_COUNT * 10) + 3;
  if (day <= 0) return 0;
  if (state.status === 'waiting-morning') return (day * 10) + 2;
  if (state.status === 'active') return (day * 10) + 1;
  return day * 10;
}

function chatgptDailyFlowStateFreshness(value = null) {
  const state = chatgptNormalizeDailyFlowState(value);
  // V1.27.154: read delivery timestamps directly. Avoid nested delivery
  // normalization in this hot comparison path; callers may compare many aliases.
  const delivery = state?.delivery && typeof state.delivery === 'object' ? state.delivery : {};
  const parsed = Date.parse(String(state.lastBoundaryAt || state.completedAt || state.startedAt || ''));
  const deliveryFreshness = Math.max(
    Date.parse(String(delivery.deliveredAt || '')) || 0,
    Date.parse(String(delivery.lockedAt || '')) || 0,
    Date.parse(String(delivery.lastAttemptAt || '')) || 0,
    Date.parse(String(delivery.queuedAt || '')) || 0
  );
  return Math.max(Number.isFinite(parsed) ? parsed : 0, deliveryFreshness, Number(state.lastObservedOutgoingAt || 0) || 0, Number(state.initializedAtMs || 0) || 0);
}

function chatgptMoreAdvancedDailyFlowState(a = null, b = null) {
  const left = chatgptNormalizeDailyFlowState(a);
  const right = chatgptNormalizeDailyFlowState(b);
  const rankA = chatgptDailyFlowProgressRank(left), rankB = chatgptDailyFlowProgressRank(right);
  if (rankB > rankA) return right;
  if (rankA > rankB) return left;
  if (left.currentDay === right.currentDay && left.status === right.status) {
    const deliveryRankA = chatgptDailyFlowDeliveryRank(left.delivery);
    const deliveryRankB = chatgptDailyFlowDeliveryRank(right.delivery);
    if (deliveryRankB > deliveryRankA) return right;
    if (deliveryRankA > deliveryRankB) return left;
  }
  return chatgptDailyFlowStateFreshness(right) > chatgptDailyFlowStateFreshness(left) ? right : left;
}

function chatgptDailyFlowIdentityAliases(target = null, binding = null) {
  const aliases = [];
  let globalCustomerId = '';
  try { if (target?.ok) globalCustomerId = chatgptGlobalCustomerIdForTarget(target); } catch {}
  try { if (!globalCustomerId && binding && typeof binding === 'object') globalCustomerId = chatgptBindingTargetGlobalCustomerId(binding); } catch {}
  if (globalCustomerId) aliases.push(`global:${globalCustomerId}`);
  const conversation = handoffConversationRef(binding?.url || '');
  if (conversation) aliases.push(`conversation:${conversation}`);
  return [...new Set(aliases.filter(Boolean))];
}

function chatgptDailyFlowIdentityKey(target = null, binding = null) {
  return chatgptDailyFlowIdentityAliases(target,binding)[0] || '';
}

function chatgptDailyFlowBindingTarget(row = null, sourceKey = '') {
  if (!row || typeof row !== 'object') return null;
  return {
    ok:true,
    surface:String(row.surface || (String(row.platform || '').toLowerCase() === 'line' ? 'line' : 'external')),
    platform:String(row.platform || ''),
    accountId:String(row.accountId || ''),
    chatId:String(row.chatId || ''),
    displayName:String(row.displayName || ''),
    handle:String(row.handle || ''),
    targetKey:String(sourceKey || row.targetKey || '')
  };
}

function chatgptDailyFlowRegistryRow(cfg = null, identityKey = '') {
  if (!cfg || typeof cfg !== 'object' || !identityKey) return null;
  if (!cfg.dailyFlowCustomers || typeof cfg.dailyFlowCustomers !== 'object') cfg.dailyFlowCustomers = {};
  const row = cfg.dailyFlowCustomers[identityKey];
  return row && typeof row === 'object' ? row : null;
}

function chatgptDailyFlowCanonicalKeyForAliases(cfg = null, aliases = []) {
  const list = Array.isArray(aliases) ? aliases.filter(Boolean) : [];
  for (const alias of list) {
    const row = chatgptDailyFlowRegistryRow(cfg,alias);
    if (row?.canonicalKey) return String(row.canonicalKey || '');
  }
  return list.find(alias => String(alias).startsWith('global:')) || list[0] || '';
}

function chatgptReconcileSharedDailyFlowRegistry(cfg = null, now = Date.now()) {
  if (!cfg || typeof cfg !== 'object') return { changed:false, groups:0 };
  if (!cfg.dailyFlowCustomers || typeof cfg.dailyFlowCustomers !== 'object') cfg.dailyFlowCustomers = {};
  const entries = [];
  for (const [targetKey,row] of Object.entries(cfg.bindings || {})) {
    if (!row || typeof row !== 'object') continue;
    const target = chatgptDailyFlowBindingTarget(row, targetKey);
    const aliases = chatgptDailyFlowIdentityAliases(target,row);
    if (!aliases.length) continue;
    entries.push({ targetKey,row,aliases });
  }
  const parent = entries.map((_,i)=>i);
  const find = i => { while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; } return i; };
  const union = (a,b) => { a=find(a); b=find(b); if(a!==b) parent[b]=a; };
  const aliasOwner = new Map();
  entries.forEach((entry,index)=>{
    for (const alias of entry.aliases) {
      if (aliasOwner.has(alias)) union(index,aliasOwner.get(alias));
      else aliasOwner.set(alias,index);
    }
  });
  const groups = new Map();
  entries.forEach((entry,index)=>{
    const root=find(index);
    if(!groups.has(root))groups.set(root,{entries:[],aliases:new Set()});
    const group=groups.get(root); group.entries.push(entry); entry.aliases.forEach(alias=>group.aliases.add(alias));
  });
  let changed = false;
  for (const group of groups.values()) {
    const aliases=[...group.aliases];
    const canonicalKey=aliases.find(alias=>String(alias).startsWith('global:')) || aliases.find(alias=>String(alias).startsWith('conversation:')) || aliases[0] || '';
    let winner = null;
    for (const alias of aliases) {
      const existing=chatgptDailyFlowRegistryRow(cfg,alias);
      if(existing?.state)winner=winner?chatgptMoreAdvancedDailyFlowState(winner,existing.state):chatgptNormalizeDailyFlowState(existing.state,now);
    }
    for (const entry of group.entries) winner=winner?chatgptMoreAdvancedDailyFlowState(winner,entry.row.dailyFlowState):chatgptNormalizeDailyFlowState(entry.row.dailyFlowState,now);
    if(!winner)winner=chatgptNormalizeDailyFlowState(null,now);
    const sourceTargetKey=String(group.entries[0]?.targetKey || '').slice(0,800);
    for (const alias of aliases) {
      const existing=chatgptDailyFlowRegistryRow(cfg,alias);
      const sameState=!!existing && JSON.stringify(chatgptNormalizeDailyFlowState(existing.state,now))===JSON.stringify(winner);
      const sameCanonical=String(existing?.canonicalKey||'')===canonicalKey;
      if(!sameState || !sameCanonical || String(existing?.version||'')!==CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION) {
        cfg.dailyFlowCustomers[alias]={
          version:CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION,
          canonicalKey,
          state:{...winner},
          updatedAt:new Date(now).toISOString(),
          sourceTargetKey:sourceTargetKey || String(existing?.sourceTargetKey || '').slice(0,800)
        };
        changed=true;
      }
    }
    for (const entry of group.entries) {
      const normalized=chatgptNormalizeDailyFlowState(entry.row.dailyFlowState,now);
      if(JSON.stringify(normalized)!==JSON.stringify(winner) || entry.row.sharedDailyFlowKey!==canonicalKey || entry.row.sharedDailyFlowVersion!==CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION) {
        entry.row.dailyFlowState={...winner};
        entry.row.sharedDailyFlowKey=canonicalKey;
        entry.row.sharedDailyFlowVersion=CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION;
        changed=true;
      }
    }
  }
  const registryEntries=Object.entries(cfg.dailyFlowCustomers || {});
  if(registryEntries.length>1200) {
    const activeAliases=new Set(entries.flatMap(entry=>entry.aliases));
    const active=registryEntries.filter(([key])=>activeAliases.has(key));
    const inactive=registryEntries.filter(([key])=>!activeAliases.has(key)).sort((a,b)=>String(b[1]?.updatedAt||'').localeCompare(String(a[1]?.updatedAt||'')));
    cfg.dailyFlowCustomers=Object.fromEntries([...active,...inactive].slice(0,Math.max(1200,active.length)));
    changed=true;
  }
  return {changed,groups:groups.size};
}

function chatgptApplySharedDailyFlowState(cfg = null, target = null, rowKey = '', row = null, state = null, now = Date.now()) {
  const normalized=chatgptNormalizeDailyFlowState(state,now);
  if(!cfg || typeof cfg!=='object' || !row || typeof row!=='object')return {state:normalized,identityKey:'',mirrored:0};
  chatgptReconcileSharedDailyFlowRegistry(cfg,now);
  const aliases=chatgptDailyFlowIdentityAliases(target,row);
  if(!aliases.length){row.dailyFlowState={...normalized};return {state:normalized,identityKey:'',mirrored:1};}
  const canonicalKey=chatgptDailyFlowCanonicalKeyForAliases(cfg,aliases);
  const groupAliases=new Set(aliases);
  for(const [alias,meta] of Object.entries(cfg.dailyFlowCustomers||{}))if(String(meta?.canonicalKey||'')===canonicalKey)groupAliases.add(alias);
  const sourceTargetKey=String(rowKey || target?.targetKey || '').slice(0,800);
  for(const alias of groupAliases){
    cfg.dailyFlowCustomers[alias]={version:CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION,canonicalKey,state:{...normalized},updatedAt:new Date(now).toISOString(),sourceTargetKey};
  }
  let mirrored=0;
  for(const [peerKey,peer] of Object.entries(cfg.bindings||{})){
    if(!peer || typeof peer!=='object')continue;
    const peerAliases=chatgptDailyFlowIdentityAliases(chatgptDailyFlowBindingTarget(peer,peerKey),peer);
    const peerCanonical=chatgptDailyFlowCanonicalKeyForAliases(cfg,peerAliases);
    const overlaps=peerAliases.some(alias=>groupAliases.has(alias));
    if(peerCanonical!==canonicalKey && !overlaps)continue;
    peer.dailyFlowState={...normalized};
    peer.sharedDailyFlowKey=canonicalKey;
    peer.sharedDailyFlowVersion=CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION;
    peerAliases.forEach(alias=>groupAliases.add(alias));
    mirrored+=1;
  }
  row.dailyFlowState={...normalized};
  row.sharedDailyFlowKey=canonicalKey;
  row.sharedDailyFlowVersion=CHATGPT_CROSS_CHANNEL_DAILY_FLOW_VERSION;
  return {state:normalized,identityKey:canonicalKey,mirrored:Math.max(1,mirrored)};
}

function chatgptRawDailyFlowStateForBinding(binding = null, target = null, now = Date.now()) {
  let winner=chatgptNormalizeDailyFlowState(binding?.dailyFlowState || null,now);
  if(!binding || typeof binding!=='object')return winner;
  const cfg=chatgptWorkbenchConfig();
  const aliases=chatgptDailyFlowIdentityAliases(target,binding);
  for(const alias of aliases){
    const shared=chatgptDailyFlowRegistryRow(cfg,alias);
    if(shared?.state)winner=chatgptMoreAdvancedDailyFlowState(winner,shared.state);
  }
  return winner;
}
function chatgptDailyFlowStateForBinding(binding = null, target = null) {
  const now=Date.now();
  return chatgptReconcileDailyFlowClockState(chatgptRawDailyFlowStateForBinding(binding,target,now),now,'clock-read').state;
}

function chatgptMutableBindingEntry(target = {}) {
  if (!target?.ok) return null;
  const cfg = chatgptWorkbenchConfig();
  const directKey = chatgptWorkflowTargetKey(target);
  let rowKey = directKey;
  let row = cfg.bindings?.[rowKey];
  if (!row || typeof row !== 'object') {
    const resolved = chatgptBindingForTarget(target);
    if (resolved?.inheritedFromTargetKey) {
      rowKey = String(resolved.inheritedFromTargetKey || '');
      row = cfg.bindings?.[rowKey];
    }
  }
  if (!row || typeof row !== 'object') return null;
  const identityKey = chatgptDailyFlowIdentityKey(target,row);
  return { cfg, rowKey, row, directKey, identityKey };
}

function chatgptDailyFlowBoundaryType(text = '') {
  const source = String(text || '');
  if (!source.trim()) return '';
  const morningMatches = [...source.matchAll(/おはよう(?:ございます)?|早安|早上好|早晨好/gi)];
  const nightMatches = [...source.matchAll(/おやすみ(?:なさい)?|晚安/gi)];
  const morningAt = morningMatches.length ? Number(morningMatches[morningMatches.length - 1].index || 0) : -1;
  const nightAt = nightMatches.length ? Number(nightMatches[nightMatches.length - 1].index || 0) : -1;
  if (morningAt < 0 && nightAt < 0) return '';
  return nightAt > morningAt ? 'goodnight' : 'morning';
}

function chatgptOutgoingDeliveryConfirmed(result = null) {
  if (!result || result.ok !== true) return false;
  // Official API and LINE verification explicitly return true only after the
  // platform/API confirms the send or the own-side row appears.
  if (result.verified === true) return true;
  // Browser surfaces are strict in V1.27.151: only a newly observed outgoing
  // message row is hard proof. Composer-cleared/draft-consumed signals stay
  // pending and must not open/close a Day.
  return String(result.verified || '') === 'outgoing-message';
}

function updateChatgptDailyFlowBoundary(target = {}, text = '', source = 'yoko-outgoing', observedAt = Date.now(), { persist = true } = {}) {
  const type = chatgptDailyFlowBoundaryType(text);
  const mutable = chatgptMutableBindingEntry(target);
  if (!mutable) return { ok:false, changed:false, type, reason:'no-binding' };
  const { cfg, rowKey, row, directKey } = mutable;
  const now = Math.max(0, Number(observedAt || 0) || Date.now());
  const before = chatgptRawDailyFlowStateForBinding(row,target,now);
  before.lastObservedOutgoingAt = Math.max(before.lastObservedOutgoingAt, now);
  const clock = chatgptReconcileDailyFlowClockState(before,now,'time-window-authority');
  const state=clock.state;
  let changed=clock.changed;
  if(String(state.status||'')==='active' && Number(state.currentDay||0)>0){
    const flowText=chatgptFlowDayText(state.currentDay);
    const beforeProgress=normalizeDailyFlowDirectionProgress(state.intradayDirectionProgress,state.currentDay);
    const nextProgress=markDailyFlowDirectionTouched(flowText,state.currentDay,now,beforeProgress);
    if(JSON.stringify(nextProgress)!==JSON.stringify(beforeProgress)){
      state.intradayDirectionProgress=nextProgress;
      changed=true;
    }
  }
  if(clock.dayChanged || (clock.statusChanged && state.status!=='active')){
    row.flowLibraryFingerprint='';
    row.flowLibraryInitializedAt='';
  }
  const sharedWrite = chatgptApplySharedDailyFlowState(cfg,target,rowKey,row,state,now);
  cfg.bindings[rowKey] = row;
  if (persist) {if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings']);else{saveConfig(config);persistChatgptBindingsShadow(cfg);}}
  if (changed) {
    pushChatgptStabilityEvent('gpt-daily-flow-clock-boundary', {
      targetKey:directKey,
      observedGreetingType:type,
      currentDay:state.currentDay,
      status:state.status,
      source:String(source || ''),
      schedulePhase:String(state.schedulePhase||''),
      enrollmentDateKey:String(state.enrollmentDateKey||''),
      sharedDailyFlowKey:String(sharedWrite?.identityKey || ''),
      mirroredBindings:Number(sharedWrite?.mirrored || 0)
    });
    if (persist) { try { sendChatgptWorkbenchUpdated(target); } catch {} }
  }
  // V1.27.200: greetings are ordinary chat content. They are intentionally
  // detected only for diagnostics and NEVER start/end/advance the Day clock.
  return { ok:true, changed, type, ignoredGreetingBoundary:!!type, reason:'clock-authoritative', state:{...state}, rowKey, sharedDailyFlowKey:String(sharedWrite?.identityKey || ''), mirroredBindings:Number(sharedWrite?.mirrored || 0) };
}


function setChatgptDailyFlowCurrentDay(target = {}, requestedDay = 0, now = Date.now()) {
  const day=Math.max(1,Math.min(CHATGPT_DAILY_FLOW_DAY_COUNT,Number(requestedDay||0)||0));
  if(!target?.ok || !day) return {ok:false,error:'请先选择客户并选择 Day 1～Day 10。'};
  const mutable=chatgptMutableBindingEntry(target);
  if(!mutable) return {ok:false,error:'当前客户还没有绑定 GPT，无法校正 Day 流程。请先绑定后再操作。'};
  const {cfg,rowKey,row,directKey}=mutable;
  const at=Math.max(0,Number(now||0)||Date.now());
  const before=chatgptDailyFlowStateForBinding(row,target);
  const today=dailyFlowLocalDateKey(at);
  // Manual selection is a one-time calendar rebase, NOT a permanent manual mode.
  // If today is selected as Day N, enrollment is N calendar days before today.
  // From then on the existing 05:00/23:00 clock remains authoritative and
  // advances Day N -> Day N+1 automatically on following days.
  const enrollmentDateKey=dailyFlowAddLocalDays(today,-day) || today;
  const sameDay=Number(before?.currentDay||0)===day && String(before?.manualDayCorrectionDateKey||'')===today && Number(before?.manualDayCorrectionDay||0)===day;
  if(sameDay){
    return {ok:true,changed:false,day,state:{...before},message:`今天已经校正为 Day ${day}，后续仍会自动推进。`};
  }
  const seeded={
    ...before,
    enrollmentDateKey,
    newCustomerDateKey:enrollmentDateKey,
    // clear terminal/old delivery state so the newly selected current Day can
    // participate in the normal exactly-once delivery pipeline if its window is active.
    status:'waiting-morning',
    completedAt:'',
    startedAt:'',
    scheduleDateKey:'',
    dayDateKey:'',
    delivery:{day:0,status:'none'},
    manualDayCorrectionDay:day,
    manualDayCorrectionDateKey:today,
    manualDayCorrectionAt:new Date(at).toISOString(),
    manualDayCorrectionSource:'operator-current-day-rebase-v127217'
  };
  const clock=chatgptReconcileDailyFlowClockState(seeded,at,'manual-day-correction-v127217');
  const state=clock.state;
  state.manualDayCorrectionDay=day;
  state.manualDayCorrectionDateKey=today;
  state.manualDayCorrectionAt=new Date(at).toISOString();
  state.manualDayCorrectionSource='operator-current-day-rebase-v127217';
  row.flowLibraryFingerprint='';
  row.flowLibraryInitializedAt='';
  const sharedWrite=chatgptApplySharedDailyFlowState(cfg,target,rowKey,row,state,at);
  cfg.bindings[rowKey]=row;
  saveConfig(config);
  persistChatgptBindingsShadow(cfg);
  if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings'],{immediate:true,localCritical:true});
  pushChatgptStabilityEvent('gpt-daily-flow-manual-day-rebase-v127217',{
    targetKey:directKey,
    selectedDay:day,
    currentDay:Number(state.currentDay||0),
    status:String(state.status||''),
    today,
    enrollmentDateKey,
    sharedDailyFlowKey:String(sharedWrite?.identityKey||''),
    mirroredBindings:Number(sharedWrite?.mirrored||0)
  });
  try{sendChatgptWorkbenchUpdated(target);}catch{}
  if(String(state.status||'')==='active' && Number(state.currentDay||0)===day){
    setTimeout(()=>syncActiveDailyFlowToChatgptIfCurrent(target,'manual-day-correction-v127217').catch(()=>{}),0);
  }
  return {ok:true,changed:true,day,state:{...state},message:`已把今天校正为 Day ${day}；之后继续按系统时间自动推进。`};
}

function reconcileChatgptDailyFlowStateFromRows(target = {}, rows = []) {
  const mutable = chatgptMutableBindingEntry(target);
  if (!mutable) return { ok:false, changed:false };
  const {cfg,rowKey,row}=mutable;
  const current=chatgptRawDailyFlowStateForBinding(row,target,Date.now());
  const outgoing=(Array.isArray(rows)?rows:[])
    .filter(item=>String(item?.role||'')==='me')
    .map(item=>Math.max(0,Number(item?.delivered||item?.timestampMs||item?.timeMs||0)||0))
    .filter(Boolean);
  const newest=outgoing.length?Math.max(...outgoing):0;
  if(newest)current.lastObservedOutgoingAt=Math.max(Number(current.lastObservedOutgoingAt||0)||0,newest);
  // V1.27.200: historical greetings are never replayed as Day boundaries.
  // Reconcile only against the CURRENT clock so old rows cannot rewind/advance Day.
  const clock=chatgptReconcileDailyFlowClockState(current,Date.now(),'history-clock-reconcile');
  const sharedWrite=chatgptApplySharedDailyFlowState(cfg,target,rowKey,row,clock.state,Date.now());
  cfg.bindings[rowKey]=row;
  if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings']);else{saveConfig(config);persistChatgptBindingsShadow(cfg);}
  return {ok:true,changed:clock.changed,state:{...clock.state},sharedDailyFlowKey:String(sharedWrite?.identityKey||'')};
}

function chatgptSharedDailyFlowLegacyDelivered(binding = null, target = null, fingerprint = '') {
  const fp = String(fingerprint || '').trim();
  if (!fp) return false;
  if (chatgptBindingFlowFingerprint(binding) === fp) return true;
  // V1.27.154 freeze hotfix: this is migration-only compatibility for V1.27.152.
  // Never resolve canonical alias graphs in a hot read. Compare only strong,
  // already-persisted identities: global customer id or stable GPT conversation.
  const cfg = chatgptWorkbenchConfig();
  const globalId = String(chatgptGlobalCustomerIdForTarget(target) || chatgptBindingTargetGlobalCustomerId(binding) || '').trim();
  const conversationRef = String(chatgptBoundConversationRef(binding) || '').trim();
  for (const peer of Object.values(cfg.bindings || {})) {
    if (!peer || typeof peer !== 'object' || peer === binding || chatgptBindingFlowFingerprint(peer) !== fp) continue;
    const peerGlobalId = String(chatgptBindingTargetGlobalCustomerId(peer) || '').trim();
    if (globalId && peerGlobalId && globalId === peerGlobalId) return true;
    const peerConversationRef = String(chatgptBoundConversationRef(peer) || '').trim();
    if (conversationRef && peerConversationRef && conversationRef === peerConversationRef) return true;
  }
  return false;
}

function chatgptUpdateDailyFlowDelivery(target = {}, expected = {}, patch = {}, { persist = true } = {}) {
  const mutable = chatgptMutableBindingEntry(target);
  if (!mutable) return { ok:false, reason:'no-binding' };
  const { cfg,rowKey,row } = mutable;
  const now = Math.max(0, Number(expected?.now || 0) || Date.now());
  const state = chatgptDailyFlowStateForBinding(row,target);
  let delivery = chatgptNormalizeDailyFlowDelivery(state.delivery,state,now);
  const expectedDay = Math.max(0, Number(expected?.day || 0) || 0);
  const expectedFingerprint = String(expected?.fingerprint || '').trim();
  const expectedDeliveryId = String(expected?.deliveryId || '').trim();
  if (expectedDay && delivery.day !== expectedDay) return { ok:false, stale:true, reason:'day-changed', state, delivery };
  if (expectedFingerprint && delivery.fingerprint && delivery.fingerprint !== expectedFingerprint) return { ok:false, stale:true, reason:'fingerprint-changed', state, delivery };
  if (expectedDeliveryId && delivery.deliveryId && delivery.deliveryId !== expectedDeliveryId) return { ok:false, stale:true, reason:'delivery-id-changed', state, delivery };
  delivery = chatgptNormalizeDailyFlowDelivery({ ...delivery, ...(patch || {}) },state,now);
  state.delivery = delivery;
  const sharedWrite=chatgptApplySharedDailyFlowState(cfg,target,rowKey,row,state,now);
  cfg.bindings[rowKey]=row;
  if (persist) {if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings']);else{saveConfig(config);persistChatgptBindingsShadow(cfg);}}
  return { ok:true, state:{...state}, delivery:{...delivery}, sharedDailyFlowKey:String(sharedWrite?.identityKey || ''), mirroredBindings:Number(sharedWrite?.mirrored || 0) };
}

function chatgptDailyFlowDeliveryMarker(deliveryId = '') {
  const safe = String(deliveryId || '').trim().replace(/[^a-zA-Z0-9._:-]/g,'').slice(0,80);
  return safe ? `【YokoSCRM_DAY_FLOW_DELIVERY:${safe}】` : '';
}

function chatgptConversationHasDailyFlowDeliveryScript(deliveryId = '') {
  const marker = JSON.stringify(chatgptDailyFlowDeliveryMarker(deliveryId));
  // V1.27.154 freeze hotfix: never walk every DOM node / shadow root. ChatGPT
  // user turns are exposed by a stable role selector; inspect only the latest
  // bounded set so crash recovery cannot monopolize a renderer/main IPC lane.
  return `(()=>{const marker=${marker};if(!marker)return {found:false,userCount:0};let users=[];try{users=Array.from(document.querySelectorAll('[data-message-author-role="user"]'))}catch{}const start=Math.max(0,users.length-80);for(let i=users.length-1;i>=start;i--){const text=String(users[i]?.innerText||users[i]?.textContent||'');if(text.includes(marker))return {found:true,index:i,userCount:users.length};}return {found:false,userCount:users.length,bounded:true};})()`;
}

function chatgptActiveDailyFlowContext(binding = null, target = null) {
  if (!CHATGPT_DAY_FLOW_ENABLED) {
    const retiredState = { currentDay:0, status:'retired', waitingNextMorning:false, schedulePhase:'retired', delivery:{status:'none'} };
    return { state:retiredState, active:false, day:0, flowText:'', fingerprint:'', delivery:{status:'none'}, blacklisted:false, retired:true };
  }
  const state = chatgptDailyFlowStateForBinding(binding,target);
  const modeInfo = typeof chatgptChatModeForTarget === 'function' ? chatgptChatModeForTarget(target,binding) : {mode:'deep'};
  const blacklisted = lineCrmTargetBlacklisted(target);
  const active = !blacklisted && modeInfo.mode === (typeof CHATGPT_CHAT_MODE_DEEP === 'string' ? CHATGPT_CHAT_MODE_DEEP : 'deep') && state.status === 'active' && state.currentDay >= 1 && state.currentDay <= CHATGPT_DAILY_FLOW_DAY_COUNT;
  const flowText = active ? chatgptFlowDayText(state.currentDay) : '';
  const fingerprint = active ? chatgptFlowDayFingerprint(state.currentDay, flowText) : '';
  let delivery = chatgptNormalizeDailyFlowDelivery(state.delivery,state);
  if (active && delivery.day !== state.currentDay) {
    delivery = chatgptCreateDailyFlowDelivery(state.currentDay,state,Date.now(),'delivery-state-repair');
  } else if (active && fingerprint && delivery.fingerprint !== fingerprint && ['pending','failed'].includes(String(delivery.status||''))) {
    // Before delivery we may use the operator's latest edited Day text, while
    // keeping the SAME per-Day deliveryId. Once in-flight/delivered/locked, the
    // day identity is immutable and can never become a second send.
    delivery = chatgptNormalizeDailyFlowDelivery({...delivery,fingerprint},state);
  }
  if (active && fingerprint && delivery.status !== 'delivered' && chatgptSharedDailyFlowLegacyDelivered(binding,target,fingerprint)) {
    delivery = chatgptNormalizeDailyFlowDelivery({
      ...delivery,
      day:state.currentDay,
      fingerprint,
      status:'delivered',
      deliveredAt:String(binding?.flowLibraryInitializedAt || new Date().toISOString()),
      conversationRef:chatgptBoundConversationRef(binding),
      lastError:'',
      lastReason:'legacy-v152-fingerprint-migration'
    },state);
  }
  return {
    state:{...state,delivery},
    active,
    day:state.currentDay,
    flowText,
    fingerprint,
    delivery,
    blacklisted
  };
}

function chatgptIntradayStageInstruction(flowText = '', dailyContext = null, now = Date.now()) {
  const day=Math.max(0,Number(dailyContext?.day||0)||0);
  const state=dailyContext?.state&&typeof dailyContext.state==='object'?dailyContext.state:{};
  const stage=resolveDailyFlowStage(now);
  if(!day||String(state.status||'')!=='active'||!stage.active){
    return '【Day 日内阶段锁】\n当前不在可执行的日内阶段；不要补播或提前执行任何时间节点。';
  }
  const timeline=dailyFlowTimelineAt(flowText,now,{maxChars:4200});
  const direction=dailyFlowDirectionSnapshot(flowText,day,now,state.intradayDirectionProgress);
  const completed=stage.completedLabels.length?stage.completedLabels.join(' → '):'无';
  const touched=direction.touchedObjectives.length?direction.touchedObjectives.join(' → '):'无';
  const lines=[
    '【Day 日内阶段锁＋方向记忆＋问题优先｜V1.27.231】',
    `当前 Day：Day ${day}`,
    `当前时间：${stage.clockText}`,
    `当前阶段：${stage.label}`,
    `已过阶段：${completed}`,
    `Day 当天主线目标：${direction.dayGoal}`,
    `当前节点目标：${direction.currentObjective || '先回应客户真实内容；当前没有必须推进的新节点。'}`,
    `今天已经触达的节点目标：${touched}`,
    direction.currentAlreadyTouched ? '当前时间片此前已经触达过：不要机械重复同一句或同一问法；优先承接客户回复，再决定是否自然深化。' : '当前时间片尚未触达：只有在客户话题允许时，最多自然推进这一项。',
    CHATGPT_REPLY_PRIORITY_RULES,
    '硬规则：Day 主线目标只用于保持方向，不是必须完成的 KPI。客户不愿意聊、情绪不合适或话题正在进行时，可以延后或跳过。',
    '硬规则：只能向前，不能回到已经过去的生活节点；错过的早餐、上午工作、午饭、午休等节点直接跳过，不补播。',
    '硬规则：客户真实内容优先。先回应客户正在说的事情；不要为了赶流程突然切题；一轮最多自然推进一个主要节点。',
    '硬规则：不得提前执行当前时间之后的节点，也不得因为聊天内容看起来合适就预演未来节点。'
  ];
  if(timeline.hasTimeline){
    if(!timeline.segment){
      lines.push(`今天流程的第一个明确时间节点尚未到达${timeline.next?.label?`（下一个标记 ${timeline.next.label}）`:''}；现在只自然回应客户，不预播后面内容。`);
    }else if(timeline.blocked){
      lines.push(`当前可定位到 ${timeline.segment.label} 的原始流程片段，但其中包含投资、充值、提现、收益/金额推进等资金执行内容；自动流程必须跳过这类推进。`, '此时只回应客户真实内容，或继续普通生活、兴趣、工作、家庭等非资金话题；不得劝导、诱导或协助客户投入资金。');
    }else if(timeline.text){
      lines.push(`当前允许参考的时间片（${timeline.segment.label} 起；只限这一片，不得读取后面的时间片）：`, timeline.text);
    }
  }else{
    lines.push('当天流程没有可识别的 HH:MM 时间轴；只使用当前阶段名称和真实聊天历史，不自行猜测后续节点。');
  }
  return lines.join('\n');
}

function chatgptFlowAdvisorInstruction(flowText = '', dailyContext = null, modeContext = null) {
  return [
    '【客户聊天回复原则】',
    'Day 1～Day 10 已取消。不要根据聊天天数、早安/晚安、05:00/23:00 或任何日期自动推进关系。',
    '关系发展统一按 Stage 0～Stage 10 判断，但阶段只提供方向，真实对话决定路径；阶段可以保持，也可以因拒绝、冷淡或主动性下降而回退。',
    CHATGPT_REPLY_PRIORITY_RULES,
    '基础资料只能从当前话题寻找自然入口，一次最多自然推进一个信息点；已经知道就跳过，没有自然入口就不问。',
    '弱回应连续出现时减少问题；拒绝、忙碌、疲惫、准备睡觉或结束聊天时优先 HOLD / CLOSE，不换一种方式继续追问。',
    '只有双方已经存在明确且持续的好感信号才允许轻度暧昧；只有双方真实表达见面意愿才讨论约会；恋爱关系必须双方明确确认。',
    '正式输出按当前客户语言：【适合直接发送｜客户语言】→【中文对照】→【接待判断】；客户说斯瓦希里语时不得改成日语。'
  ].join('\n');
}

function chatgptPerTurnOutputContract(flowText = '', dailyContext = null, modeContext = null) {
  const jstClock = chatgptJstClockContext();
  return [
    '【本轮客户消息回复要求｜V1.27.288】',
    '固定人设与长期规则以当前已保存的规则为准；本轮不要重复解释规则。',
    '只处理下面这一次尚未回复的客户消息 + 末尾“补充：”内部意图；先回答明确问题，再回应情绪/边界，再决定是否自然延伸。',
    '没有自然入口就不推进；不要为了主题地图强行换话题。',
    '输出仅按顺序：【适合直接发送｜客户语言】→【中文对照】→【接待判断】。客户使用斯瓦希里语时，第一部分必须使用斯瓦希里语；如“Wapi”这类简短当地表达，不能误判为日语。不得附带日本精聊或旧版本追加规则。'
  ].join('\n');
}

function chatgptFlowSyncPromptForBinding(binding = null, target = null, options = {}) {
  if (!CHATGPT_DAY_FLOW_ENABLED) return { text:'', fingerprint:'', needed:false, day:0, status:'retired', delivery:{status:'none'}, retired:true };
  const context = chatgptActiveDailyFlowContext(binding,target);
  const flowText = context.flowText;
  const fingerprint = context.fingerprint;
  const delivery = chatgptNormalizeDailyFlowDelivery(context.delivery,context.state);
  const deliveryStatus = String(delivery.status || '');
  // A live in-flight delivery is owned by the automatic exactly-once lane.
  // Manual customer drafts must NOT embed the same Day flow concurrently.
  // Only the recovery lane may reopen in-flight so it can scan the unique marker
  // before deciding whether a retry is safe.
  const blocked = ['delivered','locked'].includes(deliveryStatus) || (deliveryStatus === 'in-flight' && options?.allowInFlightRecovery !== true);
  if (!context.active || !flowText || !fingerprint || blocked) {
    return { text:'', fingerprint:'', needed:false, day:context.day, status:context.state.status, delivery };
  }
  const marker = chatgptDailyFlowDeliveryMarker(delivery.deliveryId);
  return {
    needed:true,
    fingerprint,
    day:context.day,
    status:context.state.status,
    delivery,
    deliveryId:delivery.deliveryId,
    marker,
    text:[
      marker,
      `【Day ${context.day} 当天流程开始｜内部规则】`,
      `系统时间已经进入今天的 Day ${context.day} 有效窗口（05:00–23:00），因此现在只加载 Day ${context.day}。下面仅是今天的流程。`,
      `在今天 23:00 自动结束之前，只允许参考 Day ${context.day}；不得提前加载或推进其他 Day。`,
      '客户或 Yoko 发送早安/晚安都不会改变流程状态；Day 只由时间日切控制。',
      '上面的 YokoSCRM_DAY_FLOW_DELIVERY 标记只用于系统防重复投递，不要在回复里复述、解释或输出它。',
      '',
      'V1.27.231 起每轮先执行“客户明确问题优先”，再参考“当天主线目标 + 当前节点目标 + 已触达节点记忆”；Day 方向不得覆盖客户本轮明确提问；不再一次性把全天所有未来节点暴露给当前回复，仍然只按系统时间开放当前允许的时间片。',
      chatgptIntradayStageInstruction(flowText,context,Date.now()),
      '',
      chatgptFlowAdvisorInstruction(flowText, context, {mode:CHATGPT_CHAT_MODE_DEEP,reception:null})
    ].join('\n').trim()
  };
}


const chatgptDailyFlowAutoSyncInFlight = new Map();
const chatgptDailyFlowRetryTimers = new Map();
function scheduleChatgptDailyFlowDeliveryRetry(target = {}, reason = 'retry', delayMs = 1600) {
  if (!target?.ok) return false;
  const key=chatgptWorkflowTargetKey(target);
  if(!key)return false;
  const existing=chatgptDailyFlowRetryTimers.get(key);if(existing)clearTimeout(existing);
  const snapshot={...target};
  const timer=setTimeout(()=>{
    chatgptDailyFlowRetryTimers.delete(key);
    if(!chatgptWorkbenchVisible)return;
    const live=chatgptWorkbenchStableTarget?.ok?chatgptWorkbenchStableTarget:null;
    if(!live?.ok || !chatgptTargetsRepresentSameCustomer(live,snapshot))return;
    syncActiveDailyFlowToChatgptIfCurrent(live,`scheduled:${reason}`).catch(()=>{});
  },Math.max(250,Number(delayMs||0)));
  chatgptDailyFlowRetryTimers.set(key,timer);
  return true;
}

async function syncActiveDailyFlowToChatgptIfCurrent(target = {}, reason = 'clock-day-start') {
  if (!CHATGPT_DAY_FLOW_ENABLED) return { ok:true, skipped:true, retired:true, reason:'day-flow-retired-v127255' };
  if (!target?.ok) return { ok:false, skipped:true, reason:'no-target' };
  const binding = chatgptBindingForTarget(target);
  if (!binding?.url || !isChatgptStableConversationUrl(binding.url)) return { ok:false, skipped:true, reason:'no-stable-binding' };
  let flowSync = chatgptFlowSyncPromptForBinding(binding,target,{allowInFlightRecovery:true});
  if (!flowSync?.needed || !flowSync?.text) return { ok:true, skipped:true, reason:'already-delivered-locked-or-not-active', day:Number(flowSync?.day || 0), deliveryStatus:String(flowSync?.delivery?.status || '') };
  const win = chatgptWorkbenchWindow;
  if (!win || win.isDestroyed?.() || win.webContents?.isDestroyed?.()) return { ok:false, skipped:true, pending:true, reason:'workbench-not-open' };
  let current='';
  try { current=await currentChatgptConversationUrl(win); } catch { current=''; }
  if (!chatgptWorkbenchDestinationMatches(current,binding.url,binding)) return { ok:false, skipped:true, pending:true, reason:'different-gpt-conversation' };
  const targetKey=chatgptWorkflowTargetKey(target);
  const deliveryId=String(flowSync?.deliveryId || flowSync?.delivery?.deliveryId || '');
  const key=`${targetKey}|${chatgptBoundConversationRef(binding)}|day${Number(flowSync.day||0)}|${deliveryId}`;
  if(chatgptDailyFlowAutoSyncInFlight.has(key)) return chatgptDailyFlowAutoSyncInFlight.get(key);
  const task=(async()=>{
    try {
      // Crash/restart recovery comes before any retry. If the unique marker is
      // already present in this customer's GPT conversation, the flow was
      // accepted previously even if the app died before persisting success.
      if(deliveryId){
        let recovered=null;
        try{recovered=await win.webContents.executeJavaScript(chatgptConversationHasDailyFlowDeliveryScript(deliveryId),true)}catch{recovered=null}
        if(recovered?.found){
          markChatgptBindingFlowSynced(target,binding,flowSync.fingerprint,`daily-flow-marker-recovery:${reason}`);
          pushChatgptStabilityEvent('gpt-daily-flow-delivery-recovered-v153',{targetKey,day:Number(flowSync.day||0),deliveryId,reason:String(reason||'')});
          sendChatgptWorkbenchUpdated(target);
          return {ok:true,synced:true,recovered:true,day:Number(flowSync.day||0),deliveryId};
        }
      }
      let pageState=null;
      try { pageState=await win.webContents.executeJavaScript(chatgptSubmissionStateScript(),true); } catch {}
      if(pageState?.streaming){
        scheduleChatgptDailyFlowDeliveryRetry(target,'gpt-streaming',2200);
        return {ok:false,skipped:true,pending:true,reason:'gpt-streaming'};
      }
      if(normalizeChatgptText(pageState?.composer||'')) return {ok:false,skipped:true,pending:true,reason:'gpt-composer-not-empty'};
      const liveBefore=chatgptBindingForTarget(target) || binding;
      flowSync=chatgptFlowSyncPromptForBinding(liveBefore,target,{allowInFlightRecovery:true});
      if(!flowSync?.needed || !flowSync?.text)return {ok:true,skipped:true,reason:'delivery-no-longer-needed',day:Number(flowSync?.day||0)};
      const delivery=chatgptNormalizeDailyFlowDelivery(flowSync.delivery,chatgptActiveDailyFlowContext(liveBefore,target).state);
      const attemptAt=new Date().toISOString();
      const inFlight=chatgptUpdateDailyFlowDelivery(target,{day:flowSync.day,fingerprint:flowSync.fingerprint,deliveryId:delivery.deliveryId},{
        status:'in-flight',
        attempts:Number(delivery.attempts||0)+1,
        lastAttemptAt:attemptAt,
        conversationRef:chatgptBoundConversationRef(binding),
        lastError:'',
        lastReason:String(reason||'daily-flow-auto-sync')
      });
      if(!inFlight?.ok)return {ok:false,skipped:true,pending:false,stale:true,reason:String(inFlight?.reason||'delivery-state-changed')};
      const ack=`DAY_${Number(flowSync.day||0)}_FLOW_READY`;
      const prompt=[
        flowSync.text,
        '',
        '【本次仅同步当天流程】',
        `现在只回复“${ack}”。不要生成给客户发送的回复，不要重复流程内容，也不要复述系统投递标记。`
      ].join('\n').trim();
      const guard=async()=>{
        const live=chatgptBindingForTarget(target);
        if(!live?.url || chatgptBoundConversationRef(live)!==chatgptBoundConversationRef(binding)) return {ok:false,error:'binding-changed'};
        let url='';try{url=await currentChatgptConversationUrl(win)}catch{}
        if(!chatgptWorkbenchDestinationMatches(url,binding.url,binding))return {ok:false,error:'route-changed'};
        const ctx=chatgptActiveDailyFlowContext(live,target);
        if(!ctx.active || ctx.day!==Number(flowSync.day||0) || String(ctx.delivery?.status||'')==='locked')return {ok:false,error:'daily-flow-state-changed'};
        return {ok:true};
      };
      const sent=await sendTextToChatgpt(win,prompt,{guard});
      const accepted=!!(sent?.ok || sent?.sendAccepted || sent?.submitted===true);
      if(!accepted){
        const failed=chatgptUpdateDailyFlowDelivery(target,{day:flowSync.day,fingerprint:flowSync.fingerprint,deliveryId:delivery.deliveryId},{
          status:'failed',
          lastError:String(sent?.failureReason || sent?.error || 'gpt-flow-submit-not-confirmed').slice(0,500),
          lastReason:`send-failed:${String(reason||'')}`
        });
        const attempts=Number(failed?.delivery?.attempts||delivery.attempts||0);
        if(attempts<3)scheduleChatgptDailyFlowDeliveryRetry(target,'send-failed',1200+(attempts*900));
        return {...sent,pending:true,day:Number(flowSync.day||0),deliveryId,status:'failed'};
      }
      // Exactly-once authority is the confirmed user-message submission itself.
      // Do NOT wait for the assistant ACK before persisting delivered, otherwise
      // an app restart after submit but before ACK could duplicate the Day flow.
      markChatgptBindingFlowSynced(target,binding,flowSync.fingerprint,`daily-flow-confirmed-submit-v153:${reason}`);
      const submittedAt=new Date().toISOString();
      chatgptUpdateDailyFlowDelivery(target,{day:flowSync.day,fingerprint:flowSync.fingerprint,deliveryId:delivery.deliveryId},{
        status:'delivered',submittedAt,deliveredAt:submittedAt,conversationRef:chatgptBoundConversationRef(binding),lastError:'',lastReason:`confirmed-gpt-submit:${String(reason||'')}`
      });
      pushChatgptStabilityEvent('gpt-daily-flow-delivered-v153',{targetKey,day:Number(flowSync.day||0),deliveryId,reason:String(reason||''),sendAccepted:accepted});
      sendChatgptWorkbenchUpdated(target);
      // ACK is diagnostics only. Delivery is already durable at this point.
      const ready=await waitForChatgptBootstrapReady(win,prompt,5600,guard).catch(()=>null);
      return {ok:true,synced:true,delivered:true,assistantReady:!!ready?.ready,day:Number(flowSync.day||0),ack,deliveryId};
    } finally {
      chatgptDailyFlowAutoSyncInFlight.delete(key);
    }
  })();
  chatgptDailyFlowAutoSyncInFlight.set(key,task);
  return task;
}

let chatgptDailyFlowClockTimer = null;
let chatgptDailyFlowClockTickRunning = false;
async function runChatgptDailyFlowClockTick(reason = 'timer') {
  if (!CHATGPT_DAY_FLOW_ENABLED) return {ok:true,skipped:true,retired:true,reason:'day-flow-retired-v127255'};
  if (chatgptDailyFlowClockTickRunning || !config?.chatgptWorkbench) return {ok:true,skipped:true};
  chatgptDailyFlowClockTickRunning=true;
  try{
    const cfg=chatgptWorkbenchConfig();
    const now=Date.now();
    let changed=0,dayStarted=0,dayEnded=0;
    const seen=new Set();
    for(const [rowKey,row] of Object.entries(cfg.bindings||{})){
      if(!row||typeof row!=='object')continue;
      const target=chatgptDailyFlowBindingTarget(row,rowKey);
      if(!target?.ok)continue;
      if(lineCrmTargetBlacklisted(target))continue;
      const identity=chatgptDailyFlowIdentityKey(target,row)||rowKey;
      if(seen.has(identity))continue;
      seen.add(identity);
      const before=chatgptRawDailyFlowStateForBinding(row,target,now);
      const clock=chatgptReconcileDailyFlowClockState(before,now,`clock-tick:${reason}`);
      if(!clock.changed)continue;
      if(clock.dayChanged && clock.state.status==='active')dayStarted+=1;
      if(clock.statusChanged && clock.state.status!=='active' && clock.previousStatus==='active')dayEnded+=1;
      if(clock.dayChanged || (clock.statusChanged && clock.state.status!=='active')){
        row.flowLibraryFingerprint='';
        row.flowLibraryInitializedAt='';
      }
      chatgptApplySharedDailyFlowState(cfg,target,rowKey,row,clock.state,now);
      cfg.bindings[rowKey]=row;
      changed+=1;
      pushChatgptStabilityEvent('gpt-daily-flow-clock-tick-v127200',{
        reason:String(reason||''),targetKey:chatgptWorkflowTargetKey(target),currentDay:clock.state.currentDay,status:clock.state.status,
        schedulePhase:String(clock.state.schedulePhase||''),enrollmentDateKey:String(clock.state.enrollmentDateKey||'')
      });
    }
    if(changed){if(typeof scheduleGptOrchestratorStatePersist==='function')scheduleGptOrchestratorStatePersist(['bindings']);else{saveConfig(config);persistChatgptBindingsShadow(cfg);}}
    const live=chatgptWorkbenchStableTarget?.ok?chatgptWorkbenchStableTarget:null;
    if(live?.ok){
      try{sendChatgptWorkbenchUpdated(live)}catch{}
      const liveBinding=chatgptBindingForTarget(live);
      const ctx=liveBinding?chatgptActiveDailyFlowContext(liveBinding,live):null;
      if(ctx?.active && chatgptWorkbenchVisible){
        setTimeout(()=>syncActiveDailyFlowToChatgptIfCurrent(live,`clock-tick:${reason}`).catch(()=>{}),0);
      }
      if(ctx && !ctx.active && String(ctx.state?.lastBoundaryType||'').startsWith('clock-end')){
        setTimeout(()=>cancelStaleChatgptDailyFlowDraftAfterGoodnight(live,ctx.day).catch(()=>{}),0);
      }
    }
    return {ok:true,changed,dayStarted,dayEnded};
  }finally{chatgptDailyFlowClockTickRunning=false;}
}
function startChatgptDailyFlowClock(){
  stopChatgptDailyFlowClock();
  pushChatgptStabilityEvent('gpt-day-flow-retired-v127255',{version:CHATGPT_REPLY_RULES_VERSION});
  return {ok:true,retired:true};
}
function stopChatgptDailyFlowClock(){
  if(chatgptDailyFlowClockTimer){clearInterval(chatgptDailyFlowClockTimer);chatgptDailyFlowClockTimer=null;}
}

