function attachChatgptComposerDeleteKeyBridge(win) {
  if(!win||win.isDestroyed?.()||!win.webContents||win.webContents.isDestroyed?.())return;
  const wc=win.webContents;
  if(wc.__yokoDeleteKeyBridgeV127156)return;
  wc.__yokoDeleteKeyBridgeV127156=true;
  wc.on('before-input-event',(event,input={})=>{
    const type=String(input?.type||'');
    const key=String(input?.key||input?.code||'');
    const plain=!input?.control&&!input?.meta&&!input?.alt;
    if(!plain||!['Backspace','Delete'].includes(key)||!['keyDown','keyUp'].includes(type))return;
    // V1.27.156: Electron/Menu/ChatGPT keyboard layers have all changed over
    // time. Own plain Backspace/Delete in the dedicated ChatGPT workbench and
    // execute one editor-native delete against the ACTUALLY focused composer.
    // Outside the composer the script is a no-op; this also prevents Backspace
    // from accidentally navigating away from the bound customer conversation.
    try{event.preventDefault()}catch{}
    if(type!=='keyDown')return;
    const direction=key==='Delete'?'forward':'backward';
    wc.executeJavaScript(chatgptComposerDeleteOnceScript(direction),true).catch(()=>null);
  });
}

function formatCustomerTurnForChatgpt(target, messages, recentRows = [], options = {}) {
  const list = (Array.isArray(messages) ? messages : [])
    .map(sanitizeCustomerTurnTextForChatgpt)
    .filter(Boolean)
    .slice(-12);
  const binding = target?.ok ? chatgptBindingForTarget(target) : null;
  if (options?.manualReview === true) {
    const flowSync = options?.flowSync && typeof options.flowSync === 'object'
      ? options.flowSync
      : chatgptFlowSyncPromptForBinding(binding,target);
    const dailyContext = chatgptActiveDailyFlowContext(binding,target);
    const modeInfo = chatgptChatModeForTarget(target,binding);
    const reception = modeInfo.mode === CHATGPT_CHAT_MODE_RECEPTION ? chatgptReceptionStateForTarget(target,binding) : null;
    const modeContext = { ...modeInfo, reception };
    const perTurnContract = chatgptPerTurnOutputContract(dailyContext.flowText, dailyContext, modeContext);
    const blocks = list.length ? [
      '客户消息：',
      list.join('\n\n'),
      '',
      perTurnContract,
      '',
      '',
      '补充：'
    ].join('\n') : '';
    return [String(flowSync?.text || '').trim(), blocks]
      .filter(Boolean).join('\n\n').trim().slice(0, 12000);
  }
  // V1.27.144: after one-time initialization, automatic/non-review paths keep
  // the compact customer-only payload. V1.27.146 keeps the visible manual
  // Customer→GPT button to review-only without altering automation semantics.
  if (chatgptBindingPersonaInitialized(binding)) {
    // V1.27.255: the full persona + long-term Stage rules were already sent once
    // when this customer conversation was created. Later automatic turns carry
    // only the real customer content so legacy reception/Day scripts cannot
    // override the new relationship-stage rules.
    return ['客户消息：', list.join('\n\n'), '', '【本轮输出安全规则】只处理客户当前消息，依据客户原文语言回复。斯瓦希里语客户必须输出【适合直接发送｜客户语言】的斯瓦希里语正文，再输出【中文对照】和【接待判断】。禁止使用日语固定标题或旧日本精聊规则；如历史规则冲突，以当前已保存的 BELK 规则为准。'].filter(Boolean).join('\n').trim().slice(0, 10000);
  }
  const outputRule = chatgptReplyOutputInstruction(target, list);
  return [
    list.join('\n\n'),
    '',
    '【本次回复要求】',
    outputRule
  ].join('\n').trim().slice(0, 18000);
}

function externalRecentMessagesRequest(accountId, timeoutMs = 1400) {
  return new Promise(resolve => {
    const entry = appCenterRuntime.get(String(accountId || ''));
    if (!entry?.view || entry.view.webContents.isDestroyed()) return resolve([]);
    const requestId = crypto.randomUUID();
    const timer = setTimeout(() => { chatgptRecentMessageRequests.delete(requestId); resolve([]); }, Math.max(300, Number(timeoutMs) || 1400));
    chatgptRecentMessageRequests.set(requestId, payload => {
      clearTimeout(timer);
      chatgptRecentMessageRequests.delete(requestId);
      resolve(Array.isArray(payload?.messages) ? payload.messages : []);
    });
    try { entry.view.webContents.send('yoko-gpt-request-recent-messages', { requestId, limit:60 }); }
    catch { clearTimeout(timer); chatgptRecentMessageRequests.delete(requestId); resolve([]); }
  });
}


async function latestVisibleUnifiedCustomerMessageRequest(accountId, timeoutMs = 900) {
  const entry = appCenterRuntime.get(String(accountId || ''));
  const wc = entry?.view?.webContents;
  if (!wc || wc.isDestroyed()) return { ok:false, error:'view-unavailable', text:'' };
  const started = Date.now();
  let last = null;
  do {
    try {
      last = await wc.executeJavaScript(`(()=>{try{const api=window.__yokoUnifiedMessageActionsV12754||window.__yokoUnifiedMessageActionsV12753||window.__yokoUnifiedMessageActionsV12752||window.__yokoUnifiedMessageActionsV12751;if(!api)return {ok:false,error:'message-actions-not-ready'};api.scan?.();return api.latestCustomerMessage?.()||{ok:false,error:'latest-customer-api-missing'}}catch(e){return {ok:false,error:String(e?.message||e)}}})()`, true);
    } catch (error) {
      last = { ok:false, error:String(error?.message || error || 'page-probe-failed') };
    }
    if (last?.ok && String(last?.text || '').trim()) return { ...last, text:String(last.text).trim().slice(0,4000) };
    if (Date.now() - started >= Math.max(200, Number(timeoutMs || 900))) break;
    await waitMs(120);
  } while (true);
  return { ok:false, error:String(last?.error || 'no-visible-customer-text'), text:'' };
}

function externalRecentMessagesEnvelopeRequest(accountId, timeoutMs = 1400) {
  return new Promise(resolve => {
    const entry = appCenterRuntime.get(String(accountId || ''));
    if (!entry?.view || entry.view.webContents.isDestroyed()) return resolve({ messages:[], identity:null, error:'view-unavailable' });
    const requestId = crypto.randomUUID();
    const timer = setTimeout(() => { chatgptRecentMessageRequests.delete(requestId); resolve({ messages:[], identity:null, error:'timeout' }); }, Math.max(300, Number(timeoutMs) || 1400));
    chatgptRecentMessageRequests.set(requestId, payload => {
      clearTimeout(timer);
      chatgptRecentMessageRequests.delete(requestId);
      resolve({
        messages:Array.isArray(payload?.messages) ? payload.messages : [],
        terminalRows:Array.isArray(payload?.terminalRows) ? payload.terminalRows : [],
        scanMeta:payload?.scanMeta && typeof payload.scanMeta === 'object' ? payload.scanMeta : {},
        explicitFacts:payload?.explicitFacts && typeof payload.explicitFacts === 'object' ? payload.explicitFacts : null,
        identity:payload?.identity && typeof payload.identity === 'object' ? payload.identity : null,
        error:String(payload?.error || '')
      });
    });
    try { entry.view.webContents.send('yoko-gpt-request-recent-messages', { requestId, limit:60 }); }
    catch (error) { clearTimeout(timer); chatgptRecentMessageRequests.delete(requestId); resolve({ messages:[], identity:null, error:String(error?.message || error) }); }
  });
}


async function tiktokPreloadLineAddedEvidence(accountId, target = {}, { force = false } = {}) {
  accountId = String(accountId || '').trim();
  const targetHandle = normalizeCrmText(target?.handle, 180).replace(/^@/, '');
  const targetName = normalizeCrmText(target?.displayName, 180);
  const targetChatId = normalizeCrmText(target?.chatId, 300);
  const targetIdentity = `${targetChatId}|${targetHandle}|${targetName}`;
  const targetKey = `${accountId}:${targetIdentity}`;
  const now = Date.now();
  pruneTikTokPreloadSnapshotCache(now);
  const cached = tiktokLineAddedPreloadSnapshotCache.get(targetKey);
  if (!force && cached?.result && now - Number(cached.at || 0) < 1800) return cached.result;
  if (cached?.pending) return cached.pending;

  const pending = externalRecentMessagesEnvelopeRequest(accountId, 950)
    .then(envelope => {
      const snapshotName = normalizeCrmText(envelope?.identity?.name, 180);
      const snapshotHandle = normalizeCrmText(envelope?.identity?.handle, 180).replace(/^@/, '');
      const currentHint = externalNativeChatHints.get(accountId);
      const hintFresh = !!currentHint && Date.now() - Number(currentHint.at || 0) < 30000;
      const hintName = hintFresh ? normalizeCrmText(currentHint?.name, 180) : '';
      const hintHandle = hintFresh ? normalizeCrmText(currentHint?.handle, 180).replace(/^@/, '') : '';
      const identityCheck = preloadSnapshotMatchesTarget(
        { displayName:targetName, handle:targetHandle },
        { name:snapshotName, handle:snapshotHandle },
        { name:hintName, handle:hintHandle }
      );
      const identityVerified = !!identityCheck.verified;

      const sourceRows = Array.isArray(envelope?.terminalRows) && envelope.terminalRows.length
        ? envelope.terminalRows
        : (envelope?.messages || []);
      const result = identityVerified
        ? findConfirmedCustomerLineAddedEvidence(sourceRows, looksLikeConfirmedLineAddedText)
        : { evidence:'', messageCount:Array.isArray(sourceRows) ? sourceRows.length : 0, customerCount:0, terminalCount:0 };
      result.generalMessageCount = Array.isArray(envelope?.messages) ? envelope.messages.length : 0;
      result.terminalSnapshotCount = Array.isArray(envelope?.terminalRows) ? envelope.terminalRows.length : 0;
      result.laneSource = String(envelope?.scanMeta?.laneSource || '');
      result.terminalRawCount = Number(envelope?.scanMeta?.terminalRawCount || 0) || 0;
      result.identityVerified = identityVerified;
      result.snapshotName = snapshotName;
      result.snapshotHandle = snapshotHandle;
      result.hintName = hintName;
      result.hintHandle = hintHandle;
      result.error = String(envelope?.error || '');
      result.identityConflict = !!identityCheck.conflict;
      tiktokLineAddedPreloadSnapshotCache.set(targetKey, { at:Date.now(), result, pending:null });
      pruneTikTokPreloadSnapshotCache();
      traceConversion('tiktok.preload-message-snapshot', {
        accountId,
        targetIdentity:conversionDiagClean(targetIdentity, 220),
        snapshotName, snapshotHandle, hintName, hintHandle,
        identityVerified, identityConflict:result.identityConflict,
        messageCount:result.messageCount,
        generalMessageCount:result.generalMessageCount,
        terminalSnapshotCount:result.terminalSnapshotCount,
        terminalRawCount:result.terminalRawCount,
        laneSource:result.laneSource,
        customerCount:result.customerCount,
        terminalCount:result.terminalCount,
        evidence:conversionDiagClean(result.evidence, 160),
        evidenceTimeText:result.evidenceTimeText || '',
        error:result.error
      }, { dedupeMs:1000 });
      return result;
    })
    .catch(error => {
      const result = { evidence:'', messageCount:0, customerCount:0, terminalCount:0, identityVerified:false, error:String(error?.message || error) };
      tiktokLineAddedPreloadSnapshotCache.set(targetKey, { at:Date.now(), result, pending:null });
      pruneTikTokPreloadSnapshotCache();
      traceConversion('tiktok.preload-message-snapshot', { accountId, targetIdentity:conversionDiagClean(targetIdentity, 220), error:result.error }, { dedupeMs:1000 });
      return result;
    });
  tiktokLineAddedPreloadSnapshotCache.set(targetKey, { at:cached?.at || 0, result:cached?.result || null, pending });
  pruneTikTokPreloadSnapshotCache();
  return pending;
}


// V1.23.48: resilient LINE message collection. A selected customer is addressed
// by exact chatId/MID, so extraction no longer depends on one DOM/route read.
// We compare several privacy-local sources and pick the strongest coherent tail.
function lineLocalChatHistoryRows(target, limit = 120) {
  try {
    const conversationId = chatHistoryConversationId(target);
    return readChatHistoryRecords(conversationId, limit)
      .filter(row => String(row?.type || 'text') === 'text' && String(row?.text || '').trim())
      .map((row,index) => ({
        role:String(row?.role || '') === 'me' ? 'me' : 'customer',
        text:String(row?.text || '').replace(/\r\n/g,'\n').trim().slice(0,4000),
        delivered:Number(new Date(row?.capturedAt || 0).getTime()) || 0,
        id:String(row?.sourceKey || row?.id || `history-${index}`)
      }))
      .filter(row => row.text)
      .slice(-Math.max(1, Math.min(160, Number(limit) || 120)));
  } catch { return []; }
}

function lineAggregatePreviewRows(target) {
  try {
    const accountId = String(target?.accountId || '');
    const chatId = String(target?.chatId || '');
    const row = (aggregateConversationCache.get(accountId)?.conversations || [])
      .find(item => String(item?.chatId || '') === chatId);
    if (!row || row.lastDirection !== 'customer') return [];
    const text = String(row.preview || '').replace(/\s+/g,' ').trim().slice(0,4000);
    return text ? [{ role:'customer', text, delivered:Number(row.lastIncomingAt || row.timestamp || 0) || 0, id:String(row.lastMessageId || 'aggregate-preview') }] : [];
  } catch { return []; }
}

function lineRowsQuality(rawRows = [], source = '') {
  const rows = normalizeChatgptMessageRows(rawRows);
  if (!rows.length) return -100000;
  const latest = rows[rows.length - 1];
  const tail = trailingCustomerTurn(rows);
  let score = Math.min(40, rows.length);
  if (latest?.role === 'customer') score += 120;
  else score -= 80;
  if (rows.some(row => row.role === 'me')) score += 35;
  if (rows.some(row => row.delivered > 0)) score += 20;
  score += Math.min(40, tail.length) * 3;
  const priority = {
    'explicit-redux':70,
    'activity-cache':55,
    'route-redux':45,
    'route-dom':30,
    'local-history':25,
    'aggregate-preview':5
  };
  score += Number(priority[source] || 0);
  return score;
}

function chooseReliableLineRows(sources = []) {
  const candidates = [];
  for (const item of Array.isArray(sources) ? sources : []) {
    const rows = normalizeChatgptMessageRows(item?.rows || []);
    if (!rows.length) continue;
    candidates.push({ source:String(item?.source || ''), rows, score:lineRowsQuality(rows, item?.source) });
  }
  candidates.sort((a,b) => b.score - a.score || b.rows.length - a.rows.length);
  return candidates[0] || { source:'none', rows:[], score:-100000 };
}

async function readReliableLineMessageBundle(target) {
  const accountId = String(target?.accountId || '').trim();
  const chatId = String(target?.chatId || '').trim();
  if (!accountId || !chatId) return null;
  let last = null;
  const waits = [0, 90, 220, 420];
  for (let i=0;i<waits.length;i+=1) {
    if (waits[i]) await waitMs(waits[i]);
    try {
      const bundle = await callLineBridgeForAccount(accountId, 'getReliableMessageBundle', chatId, 100);
      if (bundle && String(bundle.chatId || '') === chatId) {
        last = bundle;
        const hasRows = ['reduxRows','routeRows','domRows'].some(key => Array.isArray(bundle[key]) && bundle[key].length);
        if (hasRows || (Array.isArray(bundle.unreadMessages) && bundle.unreadMessages.length)) break;
      }
    } catch (error) {
      if (!isExpectedLineExecutionCancellation(error)) {
        automationLogger.write('line-message-bundle-read-error', {
          platform:'line', accountId, targetHash:automationTargetHash(target), attempt:i+1,
          error:String(error?.message || error).slice(0,500)
        });
      }
    }
  }
  return last;
}

async function recentMessagesForChatgptTarget(target, options = {}) {
  if (!target?.ok) return [];
  if(options?.bypassStage5Cache!==true && gptStage5SnapshotEligibleTarget(target)){
    const stage5=gptStage5ReadSnapshot(target);
    if(stage5?.rows?.length)return stage5.rows;
  }
  if (String(target.surface || '') === 'native-api') {
    try {
      const cached=readNativeApiGptConversationSnapshot(target);
      let items=[];
      if(cached&&Array.isArray(cached.rows)&&cached.rows.length){
        items=cached.rows;
        chatgptInteractionTransactionState.nativeApiSnapshotHitCount+=1;
        chatgptInteractionTransactionState.last={at:Date.now(),type:'native-api-snapshot-hit',targetKey:chatgptWorkflowTargetKey(target),ageMs:Date.now()-Number(cached.at||0),source:String(cached.source||'')};
      }else{
        chatgptInteractionTransactionState.nativeApiSnapshotMissCount+=1;
        const result = await nativeApiInbox.getConversation(teamSyncSettings(), target, { limit:140 });
        items=Array.isArray(result?.items)?result.items:[];
        rememberNativeApiGptConversationSnapshot(target,items,'gpt-message-snapshot-fetch');
      }
      const normalized=items.map(row => ({
        role:row.role === 'me' ? 'me' : 'customer', text:String(row.text || ''), delivered:Number(row.timestampMs || 0), id:String(row.messageId || row.eventKey || '')
      })).filter(row => row.text).slice(-140);
      if(normalized.length)gptStage5RememberSnapshot(target,normalized,cached?'native-api-local-snapshot':'native-api-server-fetch');
      return normalized;
    } catch (error) {
      automationLogger.write('native-api-message-read-error', { platform:String(target.platform || ''), accountId:String(target.accountId || ''), error:String(error?.message || error).slice(0,500) });
      return [];
    }
  }
  if (target.platform === 'line') {
    const accountId = String(target.accountId || '').trim();
    const chatId = String(target.chatId || '').trim();
    const snapshotKey = `${accountId}:${chatId}`;
    const cached = automationLineMessageSnapshots.get(snapshotKey);
    const sources = [];
    if (cached && Date.now() - Number(cached.at || 0) <= 30000 && Array.isArray(cached.rows) && cached.rows.length) {
      sources.push({ source:'activity-cache', rows:cached.rows });
    }

    const bundle = await readReliableLineMessageBundle(target);
    if (bundle) {
      if (Array.isArray(bundle.reduxRows) && bundle.reduxRows.length) sources.push({ source:'explicit-redux', rows:bundle.reduxRows });
      if (Array.isArray(bundle.routeRows) && bundle.routeRows.length) sources.push({ source:'route-redux', rows:bundle.routeRows });
      if (Array.isArray(bundle.domRows) && bundle.domRows.length) sources.push({ source:'route-dom', rows:bundle.domRows });
    }

    // Compatibility path if a future/older preload does not expose the bundle.
    if (!sources.some(item => item.source === 'explicit-redux')) {
      try {
        const explicitRows = await callLineBridgeForAccount(accountId, 'getMessagesForChatId', chatId, 100);
        if (Array.isArray(explicitRows) && explicitRows.length) sources.push({ source:'explicit-redux', rows:explicitRows });
      } catch {}
    }
    if (!sources.length) {
      try {
        const legacyRows = await callLineBridgeForAccount(accountId, 'getRecentMessagesDetailed', 100);
        if (Array.isArray(legacyRows) && legacyRows.length) sources.push({ source:'route-redux', rows:legacyRows });
      } catch (error) {
        if (!isExpectedLineExecutionCancellation(error)) {
          automationLogger.write('auto-gpt-line-read-error', {
            platform:'line', accountId, targetHash:automationTargetHash(target),
            error:String(error?.message || error).slice(0,500)
          });
        }
      }
    }

    const localHistoryRows = lineLocalChatHistoryRows(target, 140);
    if (localHistoryRows.length) sources.push({ source:'local-history', rows:localHistoryRows });
    const previewRows = lineAggregatePreviewRows(target);
    if (previewRows.length) sources.push({ source:'aggregate-preview', rows:previewRows });

    const selected = chooseReliableLineRows(sources);
    const unreadMessages = (Array.isArray(bundle?.unreadMessages) ? bundle.unreadMessages : [])
      .map(v => String(v || '').replace(/\r\n/g,'\n').trim().slice(0,4000)).filter(Boolean).slice(-40);
    const previousUnread = (cached && Date.now() - Number(cached.at || 0) <= 15000 && Array.isArray(cached.unreadMessages))
      ? cached.unreadMessages : [];
    const effectiveUnread = unreadMessages.length ? unreadMessages : previousUnread;
    if (selected.rows.length || effectiveUnread.length) {
      automationLineMessageSnapshots.set(snapshotKey, {
        rows:selected.rows,
        unreadMessages:effectiveUnread,
        at:Date.now(),
        signature:String(cached?.signature || ''),
        source:selected.source
      });
    }

    automationLogger.write('line-message-extract', {
      platform:'line', accountId, targetHash:automationTargetHash(target),
      source:selected.source, rowCount:selected.rows.length,
      unreadCount:effectiveUnread.length,
      sourceCount:sources.length,
      routeMatched:!bundle || !bundle.routeChatId || String(bundle.routeChatId) === chatId
    });
    const normalized=selected.rows.slice(-100);
    if(normalized.length)gptStage5RememberSnapshot(target,normalized,`line:${selected.source||'snapshot'}`);
    return normalized;
  }
  if(String(target.platform||'').toLowerCase()==='telegram'){
    const accountId=String(target.accountId||'').trim();
    const targetName=normalizeCrmText(target.displayName,180);
    const targetHandle=normalizeCrmText(target.handle,180).replace(/^@/,'');
    for(const delay of [0,120,220]){
      if(delay)await waitMs(delay);
      const envelope=await externalRecentMessagesEnvelopeRequest(accountId,1100).catch(()=>null);
      if(!envelope)continue;
      const snapName=normalizeCrmText(envelope?.identity?.name,180);
      const snapHandle=normalizeCrmText(envelope?.identity?.handle,180).replace(/^@/,'');
      const hint=externalNativeChatHints.get(accountId)||null;
      const hintFresh=!!hint&&Date.now()-Number(hint.at||0)<30000;
      const identityCheck=preloadSnapshotMatchesTarget(
        {displayName:targetName,handle:targetHandle},
        {name:snapName,handle:snapHandle},
        {name:hintFresh?normalizeCrmText(hint?.name,180):'',handle:hintFresh?normalizeCrmText(hint?.handle,180).replace(/^@/,''):''}
      );
      if(identityCheck?.verified){
        const rows=Array.isArray(envelope.messages)?envelope.messages:[];
        if(rows.length)return rows;
      }
    }
    return [];
  }
  // External browser surfaces intentionally stay live on the operator path.
  // Do not Stage-5-cache DOM snapshots because selection and page painting are
  // not atomic. This preserves the V1.27.238 behavior for web messengers.
  const externalRows=await externalRecentMessagesRequest(target.accountId, 1800);
  return Array.isArray(externalRows)?externalRows:[];
}

function chatgptComposerRuntimeSource() {
  // V1.27.69: one shared deep locator for every ChatGPT composer action. The
  // public ChatGPT UI can move the real editor behind a wrapper/open shadow root
  // or change contenteditable="true" to another editable form. We score all
  // bottom-area editable candidates instead of relying on one DOM selector.
  return `
    const yokoRead=el=>String((el&&('value'in el)?el.value:(el?.innerText||el?.textContent||''))||'').replace(/\\u200b/g,'').replace(/\\r\\n/g,'\\n');
    const yokoVisible=el=>{if(!el)return false;try{const r=el.getBoundingClientRect(),s=getComputedStyle(el);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0}catch{return false}};
    const yokoRoots=()=>{const out=[document],seen=new Set([document]);let primary=null;try{primary=document.querySelector('#prompt-textarea,[data-testid="prompt-textarea"],[data-testid*="composer-input" i],[data-testid*="prompt" i],div.ProseMirror[contenteditable="true"],[contenteditable="true"][role="textbox"],textarea')}catch{}if(primary)return out;for(let i=0;i<out.length&&i<24;i++){const root=out[i];let nodes=[];try{nodes=Array.from(root.querySelectorAll('*'))}catch{}for(const n of nodes){try{if(n.shadowRoot&&!seen.has(n.shadowRoot)){seen.add(n.shadowRoot);out.push(n.shadowRoot)}}catch{}try{if(String(n.tagName||'').toLowerCase()==='iframe'&&n.contentDocument&&!seen.has(n.contentDocument)){seen.add(n.contentDocument);out.push(n.contentDocument)}}catch{}}}return out};
    const yokoEditable=el=>{if(!el)return false;const tag=String(el.tagName||'').toLowerCase();const type=String(el.getAttribute?.('type')||'').toLowerCase();if(tag==='textarea')return !el.disabled&&!el.readOnly;if(tag==='input')return (!type||['text','search'].includes(type))&&!el.disabled&&!el.readOnly;const ce=String(el.getAttribute?.('contenteditable')||'').toLowerCase();return !!el.isContentEditable||(ce!==''&&ce!=='false')||el.getAttribute?.('role')==='textbox'||el.hasAttribute?.('data-lexical-editor')||el.classList?.contains?.('ProseMirror')};
    const yokoDeepActive=()=>{let a=document.activeElement||null;for(let i=0;i<8&&a;i++){let next=null;try{next=a.shadowRoot?.activeElement||null}catch{}try{if(!next&&String(a.tagName||'').toLowerCase()==='iframe')next=a.contentDocument?.activeElement||null}catch{}if(!next||next===a)break;a=next}return a};
    const yokoFindComposer=()=>{const roots=yokoRoots(),candidates=[],seen=new Set();const push=(el,reason='')=>{if(!el||seen.has(el)||!yokoEditable(el)||!yokoVisible(el))return;seen.add(el);let r;try{r=el.getBoundingClientRect()}catch{return}if(r.bottom<innerHeight*.38)return;const attrs=[el.id,el.className,el.getAttribute?.('data-testid'),el.getAttribute?.('placeholder'),el.getAttribute?.('aria-label'),el.getAttribute?.('aria-placeholder'),el.getAttribute?.('data-placeholder'),reason].map(v=>String(v||'')).join(' ').toLowerCase();let score=(r.bottom/Math.max(1,innerHeight))*120+Math.min(45,r.width/12);if(r.bottom>innerHeight*.72)score+=85;if(r.width>140)score+=35;if(el.closest?.('form'))score+=28;if(el.closest?.('[data-type="unified-composer"],[data-testid*="composer" i],[class*="composer" i]'))score+=55;if(/prompt|composer|message|ask|chatgpt|随便问|有问题|訊息|消息|输入|輸入/.test(attrs))score+=120;if(String(el.tagName||'').toLowerCase()==='textarea')score+=45;if(el.isContentEditable||String(el.getAttribute?.('contenteditable')||'').toLowerCase()!=='')score+=42;if(el.getAttribute?.('role')==='textbox')score+=35;candidates.push({el,score,reason,r})};
      const active=yokoDeepActive();if(active)push(active,'active');
      const selectors=['#prompt-textarea','[data-testid="prompt-textarea"]','[data-testid*="composer-input" i]','[data-testid*="prompt" i]','[contenteditable]:not([contenteditable="false"])','[role="textbox"]','[data-lexical-editor]','.ProseMirror','textarea','input[type="text"]','input:not([type])','[placeholder]','[aria-placeholder]','[data-placeholder]'];
      for(const root of roots){for(const sel of selectors){let nodes=[];try{nodes=Array.from(root.querySelectorAll(sel))}catch{}for(const node of nodes){push(node,sel);if(!yokoEditable(node)){let d=null;try{d=node.querySelector?.('textarea,[contenteditable]:not([contenteditable="false"]),[role="textbox"],[data-lexical-editor],.ProseMirror,input[type="text"]')}catch{}if(d)push(d,sel+' descendant');let p=node.parentElement;for(let i=0;i<5&&p;i++,p=p.parentElement){if(yokoEditable(p)){push(p,sel+' ancestor');break}}}}}}
      candidates.sort((a,b)=>b.score-a.score||b.r.bottom-a.r.bottom);return {el:candidates[0]?.el||null,count:candidates.length,roots:roots.length,score:Number(candidates[0]?.score||0),reason:String(candidates[0]?.reason||'')};};
  `;
}

