// V1.27.263 — serialize Customer→GPT work per customer before any composer
// mutation. Existing V1.27.165 delivery fingerprints remain the final exactly-
// once authority; this coordinator prevents unrelated same-customer workflows
// from racing them and exposes one recoverable operation journal.
async function stageCurrentCustomerTurnToChatgpt(options = {}) {
  const source=String(options?.source||'manual');
  const manualExplicit=source.startsWith('manual');
  const target=options?.workflowResolvedTarget?.ok
    ? options.workflowResolvedTarget
    : (manualExplicit
      ? await resolveLiveChatgptExplicitTarget({expectedTarget:chatgptWorkbenchPendingExplicitSelectionTarget,attempts:7,requireConsecutive:2})
      : await resolveChatgptWorkbenchTarget({allowTransient:true}));
  if(!target?.ok)return {ok:false,error:target?.error||'请先打开客户聊天。'};
  const targetKey=chatgptWorkflowTargetKey(target);
  const contentFingerprint=String(options?.expectedDeliveryFingerprint||'').trim()
    || (Array.isArray(options?.messagesOverride)&&options.messagesOverride.length
      ? automationFingerprint(options.messagesOverride.map(v=>String(v||'').trim()).filter(Boolean))
      : '');
  const idempotencyKey=contentFingerprint
    ? automationFingerprint({kind:'customer-to-gpt',targetKey,source:manualExplicit?'manual':'auto',contentFingerprint})
    : '';
  return workflowStability.enqueue({
    targetKey,
    kind:manualExplicit?'gpt-manual-draft':'gpt-customer-turn',
    idempotencyKey,
    startState:WORKFLOW_STATES.TURN_STAGING,
    successState:manualExplicit?WORKFLOW_STATES.REVIEW_READY:WORKFLOW_STATES.GPT_WAITING,
    recentSuccessMs:manualExplicit?500:5000,
    task:()=>_stageCurrentCustomerTurnToChatgptCore({...options,workflowResolvedTarget:target})
  });
}

function normalizeAppCenterAccount(raw = {}) {
  const platform = String(raw.platform || '').trim().toLowerCase();
  if (!APP_CENTER_PLATFORMS[platform]) return null;
  const id = String(raw.id || crypto.randomUUID());
  const prefix = APP_CENTER_PLATFORMS[platform].short || platform.toUpperCase();
  let normalizedName = String(raw.name || `${prefix}-1`).trim().slice(0, 80) || `${prefix}-1`;
  // V1.20.2 migration: TikTok abbreviation is TK, not TT.
  if (platform === 'tiktok' && /^TT-(\d+)$/i.test(normalizedName)) normalizedName = normalizedName.replace(/^TT-/i, 'TK-');
  return {
    id,
    platform,
    name: normalizedName,
    remark: String(raw.remark || '').trim().slice(0, 80),
    phoneNumber: String(raw.phoneNumber || '').trim().slice(0, 40),
    createdAt: Math.max(0, Number(raw.createdAt || Date.now()) || Date.now()),
    lastOpenedAt: Math.max(0, Number(raw.lastOpenedAt || 0) || 0),
    proxy: {
      enabled: raw.proxy?.enabled === true,
      protocol: String(raw.proxy?.protocol || 'socks5'),
      host: String(raw.proxy?.host || ''),
      port: Math.max(0, Number(raw.proxy?.port || 0) || 0),
      auth: raw.proxy?.auth === true,
      username: String(raw.proxy?.username || ''),
      password: String(raw.proxy?.password || '')
    }
  };
}

function appCenterAccounts() {
  if (!config.appCenter || typeof config.appCenter !== 'object') config.appCenter = { accounts: [], installedPlatforms: [] };
  const normalized = (Array.isArray(config.appCenter.accounts) ? config.appCenter.accounts : [])
    .map(normalizeAppCenterAccount).filter(Boolean);
  config.appCenter.accounts = normalized;
  return normalized;
}

function appCenterAccountById(id) {
  id = String(id || '').trim();
  return appCenterAccounts().find(item => item.id === id) || null;
}

function nextAppCenterAccountName(platform) {
  const def = APP_CENTER_PLATFORMS[platform];
  if (!def) return 'APP-1';
  const used = new Set(appCenterAccounts().filter(a => a.platform === platform).map(a => String(a.name || '').toLowerCase()));
  for (let i = 1; i < 10000; i += 1) {
    const candidate = `${def.short}-${i}`;
    if (!used.has(candidate.toLowerCase())) return candidate;
  }
  return `${def.short}-${Date.now()}`;
}

function safeAppProfileSegment(value) {
  return String(value || '').replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120) || 'default';
}

function appCenterProfilePath(account) {
  const root = path.join(app.getPath('sessionData'), 'app-profiles', safeAppProfileSegment(account.platform));
  fs.mkdirSync(root, { recursive: true });
  const profile = path.join(root, safeAppProfileSegment(account.id));
  fs.mkdirSync(profile, { recursive: true });
  return profile;
}

function appCenterSession(account) {
  return session.fromPath(appCenterProfilePath(account), { cache: true });
}

function appCenterInstalledPlatforms() {
  if (!config.appCenter || typeof config.appCenter !== 'object') config.appCenter = { accounts: [], installedPlatforms: [] };
  const raw = Array.isArray(config.appCenter.installedPlatforms) ? config.appCenter.installedPlatforms : [];
  const seen = new Set();
  const normalized = [];
  for (const value of raw) {
    const id = String(value || '').trim().toLowerCase();
    if (!id || seen.has(id)) continue;
    if (id !== 'line' && !APP_CENTER_PLATFORMS[id]) continue;
    seen.add(id);
    normalized.push(id);
  }
  config.appCenter.installedPlatforms = normalized;
  return normalized;
}

function installAppCenterPlatform(platform) {
  platform = String(platform || '').trim().toLowerCase();
  if (platform !== 'line' && !APP_CENTER_PLATFORMS[platform]) throw new Error('不支持的应用平台。');
  const installed = appCenterInstalledPlatforms();
  if (!installed.includes(platform)) installed.push(platform);
  config.appCenter.installedPlatforms = installed;
  saveConfig(config);
  sendAppCenterUpdated();
  return { ok: true, installedPlatforms: [...installed] };
}

async function removeAppCenterPlatform(platform) {
  platform = String(platform || '').trim().toLowerCase();
  if (platform !== 'line' && !APP_CENTER_PLATFORMS[platform]) throw new Error('不支持的应用平台。');
  if (platform !== 'line') {
    const ids = appCenterAccounts().filter(a => a.platform === platform).map(a => a.id);
    for (const id of ids) await closeAppCenterAccountRuntime(id).catch(() => {});
  }
  const installed = appCenterInstalledPlatforms().filter(id => id !== platform);
  config.appCenter.installedPlatforms = installed;
  saveConfig(config);
  if (platform !== 'line' && activeAppCenterAccountId) {
    const active = appCenterAccountById(activeAppCenterAccountId);
    if (active?.platform === platform) {
      activeAppCenterAccountId = '';
      if (shellSurfaceMode === 'external') shellSurfaceMode = 'app-center';
    }
  }
  if (platform === 'line' && shellSurfaceMode === 'line') shellSurfaceMode = 'app-center';
  layoutViews({ raiseActive: true });
  sendAppCenterUpdated();
  return { ok: true, installedPlatforms: [...installed] };
}

function appCenterPublicState() {
  const accounts = appCenterAccounts();
  const platforms = Object.values(APP_CENTER_PLATFORMS).map(def => {
    const list = accounts.filter(a => a.platform === def.id);
    return {
      ...def,
      accountCount: list.length,
      openCount: list.filter(a => appCenterRuntime.has(a.id)).length
    };
  });
  return {
    platforms,
    installedPlatforms: [...appCenterInstalledPlatforms()],
    activeAccountId: activeAppCenterAccountId,
    shellSurface: shellSurfaceMode,
    externalWorkspaceMode: externalWorkspaceLayoutMode,
    externalWorkspacePlatform: externalWorkspaceLayoutPlatform,
    accounts: accounts.map(account => ({
      id: account.id,
      platform: account.platform,
      name: account.name,
      remark: String(account.remark || ''),
      phoneNumber: String(account.phoneNumber || ''),
      createdAt: account.createdAt,
      lastOpenedAt: account.lastOpenedAt,
      isOpen: appCenterRuntime.has(account.id),
      proxy: { ...(account.proxy || {}) }
    }))
  };
}

// V1.23.31 — independent local chat-history archive.
// This module is deliberately separate from the speech library. It snapshots
// text + visible media from the currently opened one-to-one conversation and
// stores records per customer under userData/chat-history.
const CHAT_HISTORY_VERSION = 1;
