    displayName:String(meta.displayName || ''), handle:String(meta.handle || ''), firstAt:String(meta.firstAt || ''),
    updatedAt:String(meta.updatedAt || ''), messageCount:Number(meta.messageCount || 0), mediaCount:Number(meta.mediaCount || 0),
