ipcMain.handle('app-auth-login',async(event,payload={})=>{
  if(!appAuthSenderAllowed(event))throw Error('unauthorized-window');
  const username=String(payload?.username||'').trim();
  const password=String(payload?.password||'');
  if(!username||!password)throw Error('请输入软件账号和密码。');
  const user=appAuthReadUsers().find(row=>String(row?.username||'').toLowerCase()===username.toLowerCase());
  if(!user||user.enabled===false)throw Error('账号或密码错误。');
  const actual=Buffer.from(appAuthHash(password,user.salt),'hex');
  const expected=Buffer.from(String(user.passwordHash||''),'hex');
  if(actual.length!==expected.length||!crypto.timingSafeEqual(actual,expected))throw Error('账号或密码错误。');
  appLoginSession={authenticated:true,user:appAuthPublic(user)};
  sendUI('app-auth-updated',appAuthPublicState());
  if(appLoginWindow&&!appLoginWindow.isDestroyed()){
    try{appLoginWindow.close();}catch{}
    appLoginWindow=null;
  }
  if(mainWindow&&!mainWindow.isDestroyed()){
    try{mainWindow.show();mainWindow.focus();}catch{}
  }
  return appAuthPublicState();
});
ipcMain.handle('app-auth-logout',async(event)=>{
  if(!appAuthSenderAllowed(event))throw Error('unauthorized-window');
  appLoginSession={authenticated:false,user:null};
  sendUI('app-auth-updated',appAuthPublicState());
  return appAuthPublicState();
});
function officialApiBaseUrl(value=''){
  const url=String(value||'').trim().replace(/\/+$/,'');
  if(!/^https:\/\/[^\s/?#]+(?::\d+)?$/i.test(url)&&!/^http:\/\/(?:127\.0\.0\.1|localhost)(?::\d+)?$/i.test(url))throw new Error('请输入 HTTPS VPS 地址（本机调试可用 localhost）。');
  return url;
}
function officialApiAuthPublic(){
  return {ok:true,authenticated:!!officialApiSession.token,user:officialApiUserPublic(officialApiSession.user),serverUrl:officialApiSession.baseUrl||String(config?.teamSync?.serverUrl||'')};
}
ipcMain.handle('official-api-auth-status',async(event)=>{
  if(!mainWindow||mainWindow.isDestroyed()||event.sender!==mainWindow.webContents)throw Error('unauthorized-window');
  return officialApiAuthPublic();
});
ipcMain.handle('official-api-login',async(event,payload={})=>{
  if(!mainWindow||mainWindow.isDestroyed()||event.sender!==mainWindow.webContents)throw Error('unauthorized-window');
  const baseUrl=officialApiBaseUrl(payload?.serverUrl||config?.teamSync?.serverUrl||'https://team.dalongvpn.cc.cd');
  const username=String(payload?.username||'').trim();const password=String(payload?.password||'');
  if(!username||!password)throw Error('请输入 VPS 用户名和密码。');
  const client=new AiServiceClient(baseUrl);
  const user=await client.login(username,password);
  if(officialApiSession.token){try{await new AiServiceClient(officialApiSession.baseUrl).logout();}catch{}}
  officialApiSession={baseUrl,token:String(client.token||''),user:officialApiUserPublic(user)};
  ensureNativeApiRealtimeStream({restart:true});
  sendUI('official-api-auth-updated',officialApiAuthPublic());
  return officialApiAuthPublic();
});
ipcMain.handle('official-api-logout',async(event)=>{
  if(!mainWindow||mainWindow.isDestroyed()||event.sender!==mainWindow.webContents)throw Error('unauthorized-window');
  if(officialApiSession.token){try{const client=new AiServiceClient(officialApiSession.baseUrl);client.token=officialApiSession.token;await client.logout();}catch{}}
  officialApiSession={baseUrl:'',token:'',user:null};
  try{delete config.teamSync?.sessionToken;delete config.teamSync?.officialApiSessionToken;}catch{}
  stopNativeApiRealtimeStream();
  sendUI('official-api-auth-updated',officialApiAuthPublic());
  return officialApiAuthPublic();
});
function openAiAccountWindow() {
  if (aiAccountWindow && !aiAccountWindow.isDestroyed()) { aiAccountWindow.show(); aiAccountWindow.focus(); return; }
  aiAccountWindow = new BrowserWindow({
    width:1100,height:770,minWidth:850,minHeight:600,show:false,
    title:'Yoko SCRM · AI 接待与账户管理',backgroundColor:'#f4f7fa',
    parent:mainWindow && !mainWindow.isDestroyed() ? mainWindow : undefined,
    webPreferences:{preload:path.join(__dirname,'ai-accounts-preload.js'),contextIsolation:true,nodeIntegration:false,sandbox:true}
  });
  aiAccountWindow.setMenuBarVisibility(false);
  aiAccountWindow.loadFile(path.join(__dirname,'ai-accounts.html'));
  aiAccountWindow.once('ready-to-show',()=>{if(aiAccountWindow&&!aiAccountWindow.isDestroyed())aiAccountWindow.show();});
  aiAccountWindow.on('closed',()=>{aiAccountWindow=null; if(aiAccountClient){aiAccountClient.token='';aiAccountClient=null;}});
}
// Only the purpose-built local window may invoke the AI session. Never expose team API keys.
ipcMain.handle('yoko-ai-accounts-action',async(event,action,payload={})=>{
  if(!aiAccountWindow||aiAccountWindow.isDestroyed()||event.sender!==aiAccountWindow.webContents||!aiAccountAllowedActions.has(action)) throw Error('unauthorized-window');
  if(!payload || typeof payload!=='object'||Array.isArray(payload))throw Error('invalid-payload');
  if(action==='connect'){
    const url=String(payload.url||'').trim().replace(/\/$/,'');
    if(!/^https:\/\/[^\s/?#]+(?::\d+)?$/i.test(url)&&!/^http:\/\/(?:127\.0\.0\.1|localhost)(?::\d+)?$/i.test(url))throw Error('Use HTTPS VPS address, or local HTTP loopback');
    aiAccountClient=new AiServiceClient(url);return {ok:true};
  }
  if(!aiAccountClient)throw Error('Please connect to VPS first');
  if(action==='login')return {ok:true,user:await aiAccountClient.login(payload.username,payload.password)};
  if(action==='logout'){await aiAccountClient.logout();return {ok:true};}
  if(action==='me')return aiAccountClient.me();
  if(action==='users')return aiAccountClient.users();
  if(action==='createUser')return aiAccountClient.createUser(payload);
  if(action==='manageUser')return aiAccountClient.manageUser(payload.userId,payload.action,payload.fields||{});
  if(action==='accountAudit')return aiAccountClient.accountAudit(payload.limit);
  if(action==='inbox')return aiAccountClient.metaInboxPreview(payload.limit,payload.pageId||'');
  if(action==='pages')return aiAccountClient.metaPages();
  if(action==='customers')return aiAccountClient.metaCustomers(payload.pageId,payload.offset||0);
  if(action==='providerSettings')return aiAccountClient.providerSettings();
  if(action==='saveProviderSettings')return aiAccountClient.saveProviderSettings(payload);
  if(action==='testProvider')return aiAccountClient.testProvider();
  if(action==='simulateReception')return aiAccountClient.simulateReception(payload.pageId,payload.turns);
  if(action==='getReceptionFlow')return aiAccountClient.getReceptionFlow(payload.pageId);
  if(action==='saveReceptionFlow')return aiAccountClient.saveReceptionFlow(payload);
  if(action==='setPageMode')return aiAccountClient.setPageMode(payload.pageId,payload.mode,payload.expectedRevision);
  if(action==='processInbox')return aiAccountClient.processMetaInbox(payload.limit,{locale:payload.locale||'auto',useAi:payload.useAi===true,pageId:payload.pageId||''});
  if(action==='getCustomerMode')return aiAccountClient.getCustomerMode(String(payload.customerId||'').slice(0,150));
  if(action==='setCustomerMode')return aiAccountClient.setCustomerMode(String(payload.customerId||'').slice(0,150),payload.mode,payload.expectedRevision);
  if(action==='readyDeliveries')return aiAccountClient.readyDeliveryQueue(payload.limit);
  if(action==='reconcileDeliveries')return aiAccountClient.reconcileDeliveryQueue(payload.limit);
  if(action==='deliveryStatus')return aiAccountClient.deliveryStatus(String(payload.interactionId||'').slice(0,100));
  if(action==='dispatchApproved')return aiAccountClient.dispatchApprovedAnswer(String(payload.interactionId||'').slice(0,100));
  if(action==='daemonStatus')return aiAccountClient.daemonStatus();
  if(action==='healthSummary')return aiAccountClient.healthSummary();
  if(action==='usageSummary')return aiAccountClient.usageSummary(Math.max(1,Math.min(50,Number(payload.limit)||10)));
  if(action==='daemonHistory')return aiAccountClient.daemonHistory(Math.max(1,Math.min(100,Number(payload.limit)||25)));
  if(action==='answers')return aiAccountClient.listAnswers(payload);
  if(action==='approve')return aiAccountClient.approveAnswer(payload.id);
  if(action==='reject')return aiAccountClient.rejectAnswer(payload.id);
  if(action==='batchReview')return aiAccountClient.batchReviewAnswers(payload.ids,payload.status);
  if(action==='qaAudit')return aiAccountClient.qaAudit(payload.limit);
  if(action==='handoffs')return aiAccountClient.handoffs();
  if(action==='claimHandoff')return aiAccountClient.claimHandoff(payload.id,payload.action);
  if(action==='handoffHistory')return aiAccountClient.handoffHistory(payload.limit);
  if(action==='resolve')return aiAccountClient.resolveHandoff(payload.id,payload.answer);
  if(action==='state')return aiAccountClient.getWorkspaceState(payload.key||'inbox');
  if(action==='saveState')return aiAccountClient.putWorkspaceState(payload.key||'inbox',payload.value,payload.expectedRevision);
  throw Error('unsupported-action');
});

