  ipcMain.handle('server-pretranslate-incoming-batch', async (event, payload = {}) => {
    const t=config.translation||{};
    if(t.serverPreTranslationV127133===false||!translationGatewayConfigured())return {ok:false,disabled:true,queued:0};
    const accountId=String(webContentsToAccount.get(event.sender.id)||'').trim();
    const account=appCenterAccountById(accountId);
    const platform=String(payload?.platform||account?.platform||'external').trim().toLowerCase().slice(0,40)||'external';
    const rows=(Array.isArray(payload?.items)?payload.items:[]).slice(0,128).map((row,index)=>({
      id:String(row?.id||row?.messageId||`${platform}-${index}-${Date.now()}`).slice(0,120),
      platform,
      direction:'incoming',
      text:String(row?.text||'').trim().slice(0,12000),
      source:String(row?.source||t.inlineSource||'auto').slice(0,20),
      target:String(row?.target||t.inlineTarget||'zh').slice(0,20),
      timestampMs:Number(row?.timestampMs||Date.now())||Date.now()
    })).filter(row=>row.text);
    if(!rows.length)return {ok:true,queued:0};
    try{return await gatewayPretranslateBatch(translationGatewaySettings(),rows,platform,requestJson);}
    catch(error){return {ok:false,queued:0,error:String(error?.message||error)};}
  });
  ipcMain.handle('external-inline-translation-cache-batch', async (event, payload = {}) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    const account = appCenterAccountById(accountId);
    const t = config.translation || {};
    if (!account || t.inlineEnabled === false) return { ok:false, disabled:true, items:[] };
    try { return await lookupInlineTranslationCacheBatch(payload?.items, accountId, { preferSpeed:payload?.preferSpeed === true }); }
    catch (error) { return { ok:false, error:String(error?.message || error), items:[] }; }
  });
  ipcMain.handle('external-inline-translate', async (event, payload = {}) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    const account = appCenterAccountById(accountId);
    const t = config.translation || {};
    const providerReady = translationProviderReady();
    if (!account || t.inlineEnabled === false || !providerReady) {
      return { ok: false, disabled: true, providerReady };
    }
    const text = String(payload?.text || '').trim();
    const direction = String(payload?.direction || 'incoming').toLowerCase();
    if (direction !== 'incoming' && direction !== 'outgoing') return { ok:false, disabled:true, invalidDirection:true };
    if (direction === 'outgoing' && t.ollamaTranslateOutgoing === false) return { ok:false, disabled:true, outgoingSkipped:true };
    if (!text) return { ok: false };
    try {
      const translated = direction === 'outgoing'
        ? await translateOutgoingJapaneseLocalOnly({ text, context:Array.isArray(payload?.context)?payload.context:[], bypassCache:payload?.force===true })
        : await translateText({
        text,
        direction:'incoming',
        source: String(payload?.source || t.inlineSource || 'auto'),
        target: String(payload?.target || t.inlineTarget || 'zh'),
        accountId,
        context: Array.isArray(payload?.context) ? payload.context : [],
        bypassCache: payload?.force === true,
        skipSharedCache: payload?.skipSharedCache === true,
        inlineFast: true
      });
      return { ok: true, translated, target: t.inlineTarget || 'zh' };
    } catch (error) {
      const message = String(error?.message || error);
      try {
        mainWindow?.webContents?.send('translation-status', {
          ok: false,
          accountId,
          platform: account.platform,
          engine: t.engine || 'none',
          providerLabel: aiProviderLabel(t.engine),
          error: message,
          at: Date.now()
        });
      } catch {}
      return { ok: false, error: message };
    }
  });
