  ipcMain.handle('reorder-app-center-accounts', async (_event, platform, orderedIds) => {
    platform = String(platform || '').trim().toLowerCase();
    if (!APP_CENTER_PLATFORMS[platform]) throw new Error('不支持的应用平台。');
    const ids = Array.isArray(orderedIds) ? orderedIds.map(id => String(id || '').trim()).filter(Boolean) : [];
    const current = appCenterAccounts().filter(account => account.platform === platform);
    const currentIds = current.map(account => account.id);
    if (ids.length !== currentIds.length || new Set(ids).size !== ids.length || currentIds.some(id => !ids.includes(id))) {
      throw new Error('应用账号排序数据无效。');
    }
    const byId = new Map(current.map(account => [account.id, account]));
    const reordered = ids.map(id => byId.get(id));
    const otherAccounts = appCenterAccounts().filter(account => account.platform !== platform);
    config.appCenter.accounts = [...otherAccounts, ...reordered];
    saveConfig(config);
    sendAppCenterUpdated();
    return reordered.map(account => ({ ...account, isOpen: appCenterRuntime.has(account.id) }));
  });
