  ipcMain.handle('run-conversion-diagnostics', async (_event, payload = {}) => {
    const platform = conversionDiagClean(payload?.platform || 'tiktok', 40).toLowerCase();
    const accountId = conversionDiagClean(payload?.accountId || activeAppCenterAccountId, 128);
    traceConversion('manual-diagnostic.start', { platform, accountId }, { dedupeMs:0 });
    const results = [];
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        const info = await currentPlatformChatCrm({ platform, accountId, conversionDiagnostic:true });
        results.push({ attempt:attempt + 1, ok:!!info?.ok, chatId:info?.chatId || '', displayName:info?.displayName || '', handle:info?.handle || '', identitySource:info?.identitySource || '', observedThreadId:info?.observedThreadId || '', contactKey:info?.contactKey || '', contact:conversionDiagnosticContact(info?.contact || {}) });
      } catch (error) {
        results.push({ attempt:attempt + 1, ok:false, error:String(error?.message || error) });
      }
      if (attempt < 2) await waitMs(280);
    }
    traceConversion('manual-diagnostic.end', { platform, accountId, results }, { dedupeMs:0 });
    const report = {
      product:`Yoko SCRM V${APP_VERSION}`,
      generatedAt:new Date().toISOString(),
      purpose:'TikTok LINE conversion terminal diagnostics',
      note:'仅包含转换链元数据和明确LINE转换候选的短文本片段；不包含普通聊天全文、密码、Cookie、代理密码或API Key。',
      request:{ platform, accountId },
      results,
      trace:conversionDiagnosticSnapshot(180)
    };
    const text = JSON.stringify(report, null, 2);
    try { clipboard.writeText(text); } catch {}
    return { ok:true, copied:true, chars:text.length, latest:results[results.length - 1] || null };
  });
