  ipcMain.handle('set-layout-metrics', async (_event, metrics = {}) => {
    const sidebar = Number(metrics?.aggregateSidebarWidth);
    const crm = Number(metrics?.crmPanelWidth);
    const externalCrm = Number(metrics?.externalCrmWidth);
    const rail = Number(metrics?.platformRailWidth);
    const externalToolbar = Number(metrics?.externalToolbarHeight);
    const externalSidebar = Number(metrics?.externalSidebarWidth);
    const externalSidebarCollapsed = Number(metrics?.externalSidebarCollapsedWidth);
    const externalAggregateSidebar = Number(metrics?.externalAggregateSidebarWidth);
    const externalAggregateSidebarCollapsed = Number(metrics?.externalAggregateSidebarCollapsedWidth);
    if (Number.isFinite(sidebar)) aggregateCustomerSidebarWidth = Math.max(230, Math.min(340, Math.round(sidebar)));
    if (Number.isFinite(crm)) crmPanelWidth = Math.max(0, Math.min(390, Math.round(crm)));
    if (Number.isFinite(externalCrm)) externalCrmPanelWidth = Math.max(0, Math.min(390, Math.round(externalCrm)));
    if (Number.isFinite(rail)) platformRailWidth = Math.max(44, Math.min(62, Math.round(rail)));
    if (Number.isFinite(externalToolbar)) externalToolbarHeight = Math.max(72, Math.min(92, Math.round(externalToolbar)));
    if (Number.isFinite(externalSidebar)) externalAccountSidebarWidth = Math.max(190, Math.min(228, Math.round(externalSidebar)));
    if (Number.isFinite(externalSidebarCollapsed)) externalAccountSidebarCollapsedWidth = Math.max(68, Math.min(86, Math.round(externalSidebarCollapsed)));
    if (Number.isFinite(externalAggregateSidebar)) externalAggregateSidebarWidth = Math.max(228, Math.min(310, Math.round(externalAggregateSidebar)));
    if (Number.isFinite(externalAggregateSidebarCollapsed)) externalAggregateSidebarCollapsedWidth = Math.max(102, Math.min(132, Math.round(externalAggregateSidebarCollapsed)));
    if (workspaceLayoutMode === 'aggregate') lineViewLeftOffset = aggregateCustomerSidebarWidth;
    layoutViews({ raiseActive: true });
    return { aggregateSidebarWidth: aggregateCustomerSidebarWidth, crmPanelWidth, externalCrmWidth: externalCrmPanelWidth, platformRailWidth, externalToolbarHeight, externalSidebarWidth: externalAccountSidebarWidth, externalSidebarCollapsedWidth: externalAccountSidebarCollapsedWidth, externalAggregateSidebarWidth, externalAggregateSidebarCollapsedWidth };
  });

  ipcMain.handle('set-workspace-mode', async (_event, mode) => {
    const transitionSeq = ++workspaceModeSeq;
    // Invalidate every older aggregate customer-open request immediately.
    ++aggregateOpenRequestSeq;

    workspaceLayoutMode = mode === 'aggregate' ? 'aggregate' : 'line';
    if (workspaceLayoutMode !== 'aggregate') clearAggregateWarmStandby({ relayout: false });
    lineViewLeftOffset = workspaceLayoutMode === 'aggregate'
      ? aggregateCustomerSidebarWidth
      : (lineAccountSidebarCollapsed ? LINE_VIEW_LEFT_COLLAPSED : LINE_VIEW_LEFT_EXPANDED);
    lineViewsSuppressed = false;

    const focusEnabled = workspaceLayoutMode === 'aggregate';
    const activeId = String(config.activeAccountId || '');

    // V1.15.15: clear/apply focus on the visible LINE first. In particular,
    // setAggregateFocusMode(false) now cancels any pending aggregate switch
    // overlay, so LINE mode never remains stuck on “正在打开…”. Use a bounded
    // wait so an unresponsive renderer cannot freeze the mode button.
    if (activeId && runtime.has(activeId) && getAccount(activeId)?.isOpen !== false) {
      await callLineBridgeForAccountBounded(activeId, 'setAggregateFocusMode', 320, focusEnabled).catch(() => null);
    }

    if (transitionSeq !== workspaceModeSeq) {
      return { mode: workspaceLayoutMode, left: lineViewLeftOffset, superseded: true };
    }

    // Move the native LINE view immediately; background accounts do not get to
    // delay what the operator sees.
    layoutViews({ raiseActive: true });

    for (const [accountId] of runtime.entries()) {
      if (accountId === activeId || getAccount(accountId)?.isOpen === false) continue;
      callLineBridgeForAccount(accountId, 'setAggregateFocusMode', focusEnabled).catch(error => {
        console.debug('[Yoko workspace focus background sync skipped]', accountId, error?.message || error);
      });
    }

    // LINE React can remount shortly after mode changes. One delayed pass keeps
    // hidden columns/overlays from leaking across modes without blocking UI.
    setTimeout(() => {
      if (transitionSeq !== workspaceModeSeq) return;
      for (const [accountId] of runtime.entries()) {
        if (getAccount(accountId)?.isOpen === false) continue;
        callLineBridgeForAccount(accountId, 'setAggregateFocusMode', focusEnabled).catch(() => null);
      }
      layoutViews({ raiseActive: true });
    }, focusEnabled ? 120 : 90);

    return { mode: workspaceLayoutMode, left: lineViewLeftOffset };
  });

  ipcMain.handle('set-account-sidebar-collapsed', async (_event, collapsed) => {
    lineAccountSidebarCollapsed = !!collapsed;
    if (workspaceLayoutMode !== 'aggregate') {
      lineViewLeftOffset = lineAccountSidebarCollapsed ? LINE_VIEW_LEFT_COLLAPSED : LINE_VIEW_LEFT_EXPANDED;
    }
    layoutViews({ raiseActive: true });
    return { collapsed: lineAccountSidebarCollapsed, left: lineViewLeftOffset };
  });

  // V1.14.1 LINE media/file download bridge. LINE Chrome 3.7.2 uses
  // chrome.downloads after it has already fetched/decrypted a media File into a
  // blob: URL. Electron does not officially support chrome.downloads for loaded
  // extensions, so the preload polyfill asks the main process only for a safe
  // destination path; the authenticated renderer then streams the blob directly
  // to disk and emits Chrome-compatible onChanged completion events.
  ipcMain.handle('line-download-choose-path', async (event, payload = {}) => {
    try {
      const rawName = String(payload?.filename || `LINE_${Date.now()}`).trim();
      const safeName = (path.basename(rawName) || `LINE_${Date.now()}`)
        .replace(/[<>:\"/\|?*\x00-\x1F]/g, '_')
        .slice(0, 180);
      const downloadsDir = app.getPath('downloads');
      const desired = path.join(downloadsDir, safeName);
      let targetPath = desired;

      if (payload?.saveAs) {
        const owner = BrowserWindow.fromWebContents(event.sender) || mainWindow || undefined;
        const result = await dialog.showSaveDialog(owner, {
          title: '保存 LINE 文件',
          defaultPath: desired,
          buttonLabel: '保存'
        });
        if (result.canceled || !result.filePath) return { ok: false, canceled: true };
        targetPath = result.filePath;
      } else {
        const parsed = path.parse(desired);
        let index = 1;
        while (fs.existsSync(targetPath)) {
          targetPath = path.join(parsed.dir, `${parsed.name} (${index++})${parsed.ext}`);
        }
      }

      fs.mkdirSync(path.dirname(targetPath), { recursive: true });
      return { ok: true, path: targetPath };
    } catch (error) {
      return { ok: false, error: String(error?.message || error) };
    }
  });

  ipcMain.handle('line-download-open-path', async (_event, rawPath) => {
    const target = String(rawPath || '');
    if (!target || !fs.existsSync(target)) return { ok: false, error: '文件不存在。' };
    const error = await shell.openPath(target);
    return error ? { ok: false, error } : { ok: true };
  });

