  ipcMain.handle('chatgpt-copy-latest-state', async () => {
    const state = await chatgptLatestReplyState();
    const target = chatgptWorkbenchStableTarget?.ok ? chatgptWorkbenchStableTarget : null;
    const binding = target ? chatgptBindingForTarget(target) : null;
    let currentUrl=''; try { currentUrl=String(chatgptWorkbenchWindow?.webContents?.getURL?.() || ''); } catch {}
    let routeMatched = !!(binding?.url && chatgptWorkbenchDestinationMatches(currentUrl, binding.url, binding));
    // Overlay polls this state frequently. Only run the SPA DOM/canonical probe
    // when Electron's native URL is not already enough to prove the binding.
    if (binding?.url && !routeMatched) {
      currentUrl = await currentChatgptConversationUrl(chatgptWorkbenchWindow).catch(() => currentUrl);
      routeMatched = !!chatgptWorkbenchDestinationMatches(currentUrl, binding.url, binding);
    }
    const pendingSelection = normalizeChatgptExpectedSelectionTarget(chatgptWorkbenchPendingExplicitSelectionTarget);
    const selectionSettled = !pendingSelection || (!!target && chatgptTargetsRepresentSameCustomer(target, pendingSelection));
    const canAutoBind = selectionSettled && !!target?.ok && !binding?.url && isChatgptConversationUrl(currentUrl) && String(chatgptWorkbenchFreshConversationOwnerKey || '') === String(target.targetKey || speechLibraryTargetKey(target) || '') && Date.now() - Number(chatgptWorkbenchFreshConversationOwnerAt || 0) < 10 * 60 * 1000;
    // V1.27.146: Customer→GPT stays a manual review draft. The operator can
    // press ChatGPT's Send button after editing our "补充：" fields, so the
    // overlay poll is also a recovery point that converts the observed manual
    // send into the existing exactly-once delivery + reply-freshness locks.
    if (target?.ok && binding?.url && routeMatched && chatgptManualCustomerDraftRecord(target)) {
      await finalizeChatgptManualCustomerDraftIfSent(target,binding,chatgptWorkbenchWindow).catch(()=>null);
    }
    const replyFreshness = target?.ok && binding?.url && routeMatched ? chatgptReplyFreshnessStatus(target,binding,state) : {ok:true,pending:false,tracked:false,version:CHATGPT_REPLY_FRESHNESS_VERSION};
    const freshnessPending=!!replyFreshness?.pending;
    const japaneseState = target?.ok && binding?.url && routeMatched && !freshnessPending ? await chatgptLatestJapaneseReplyState().catch(()=>({ready:false,text:''})) : {ready:false,text:''};
    const replyDirectSend = target?.ok && binding?.url && routeMatched && japaneseState?.ready && !freshnessPending ? chatgptReplyDirectSendCandidate(target,binding,japaneseState) : null;
    const queuedSend = target?.ok && binding?.url ? chatgptQueuedJapaneseSendIntent(target,binding) : null;
    return {
      ready:!!japaneseState?.ready,
      label:String(freshnessPending ? '等待本轮GPT新回复…' : (japaneseState?.label || '等待GPT回复…')),
      reason:String(freshnessPending ? 'stale-reply' : (japaneseState?.reason || '')),
      targetName:String(target?.displayName || pendingSelection?.displayName || ''),
      bound:!!binding?.url,
      routeMatched,
      canAutoBind,
      replyAlreadySent:!!replyDirectSend?.alreadySent,
      replyDirectSendVersion:CHATGPT_REPLY_DIRECT_SEND_VERSION,
      replyFreshnessPending:freshnessPending,
      replyFreshnessVersion:CHATGPT_REPLY_FRESHNESS_VERSION,
      sendQueued:!!queuedSend,
      sendQueuedAt:Number(queuedSend?.queuedAt||0),
      oneClickSendVersion:CHATGPT_ONE_CLICK_SEND_VERSION,
      replyCompletionVersion:CHATGPT_REPLY_COMPLETION_VERSION,
      sendReady:!!japaneseState?.ready && !freshnessPending && selectionSettled && !!binding?.url && routeMatched
    };
  });
  ipcMain.handle('chatgpt-copy-latest-reply', async () => {
    const state = await chatgptLatestReplyState();
    const text = String(state?.text || '').replace(/\r\n/g,'\n').trim();
    if (!state?.ready || !text) return { ok:false, error:String(state?.label || '暂无可复制的 GPT 回复。') };
    try {
      clipboard.writeText(text);
      let confirmed = String(clipboard.readText() || '').replace(/\r\n/g,'\n');
      if (confirmed !== text) {
        try { clipboard.clear(); } catch {}
        clipboard.writeText(text);
        confirmed = String(clipboard.readText() || '').replace(/\r\n/g,'\n');
      }
      if (confirmed !== text) return { ok:false, error:'GPT 回复已识别，但 Windows 剪贴板没有保存完整正文，请再点一次复制。' };
      return { ok:true, length:text.length, verifiedClipboard:true };
    } catch (error) { return { ok:false, error:String(error?.message || error) }; }
  });

  ipcMain.handle('chatgpt-stage-latest-reply-to-customer-draft', async () => {
    const target=await resolveLiveChatgptExplicitTarget({
      expectedTarget:chatgptWorkbenchPendingExplicitSelectionTarget,
      attempts:5,
      requireConsecutive:2
    });
    if(!target?.ok)return target;
    noteChatgptWorkflowSelection(target,'reply-draft-selection-v124');
    const mutationLease=await acquireChatgptMutationLease(target,'reply-to-customer-draft');
    if(!mutationLease)return {ok:false,targetChanged:true,error:'客户已经切换，GPT 回复回填已取消。'};
    const guard=phase=>assertChatgptMutationLease(mutationLease,target,phase);
    try{
      let checked=guard('reply-draft-read-gpt');
      if(!checked.ok)return checked;
      const state=await chatgptLatestReplyState();
      const text=String(state?.text||'').replace(/\r\n/g,'\n').trim();
      if(!state?.ready||!text)return {ok:false,error:state?.error||state?.label||'没有识别到可回填的 GPT 回复正文。'};
      const binding=chatgptBindingForTarget(target);
      if(!binding?.url)return {ok:false,unbound:true,error:'当前客户还没有绑定 GPT，对话没有通过身份验证，已停止回填。'};
      let currentUrl=await currentChatgptConversationUrl(chatgptWorkbenchWindow).catch(()=> '');
      if(!chatgptWorkbenchDestinationMatches(currentUrl,binding.url,binding))return {ok:false,targetChanged:true,error:'当前 GPT 对话和客户绑定不一致，为避免把回复填给错误客户，本次已停止。'};
      // V1.27.146 recovery: if the operator manually submitted the editable
      // Customer→GPT draft, finalize that turn before deciding whether the
      // visible assistant reply is fresh enough to return to this customer.
      if(chatgptManualCustomerDraftRecord(target))await finalizeChatgptManualCustomerDraftIfSent(target,binding,chatgptWorkbenchWindow).catch(()=>null);
      const replyFreshness=chatgptReplyFreshnessStatus(target,binding,state);
      if(replyFreshness?.pending){
        pushChatgptStabilityEvent('gpt-reply-customer-draft-stale-blocked-v126',{targetKey:chatgptWorkflowTargetKey(target),conversationRef:chatgptBoundConversationRef(binding),userAdvanced:!!replyFreshness.userAdvanced,assistantAdvanced:!!replyFreshness.assistantAdvanced});
        return {ok:false,freshnessPending:true,staleReply:true,sent:false,freshnessVersion:CHATGPT_REPLY_FRESHNESS_VERSION,error:'这条是上一轮 GPT 回复。当前客户的新消息已经送进 GPT，但本轮新回复还没有生成完成；已停止回填。'};
      }
      const replyDelivery=chatgptReplyDeliveryCandidate(target,binding,state);
      if(replyDelivery.alreadyDelivered){
        pushChatgptStabilityEvent('gpt-reply-customer-draft-deduped-v125',{targetKey:chatgptWorkflowTargetKey(target),conversationRef:replyDelivery.conversationRef,replyIdentity:replyDelivery.replyIdentity});
        return {ok:true,deduped:true,alreadyDrafted:true,drafted:false,sent:false,receiptVersion:CHATGPT_REPLY_DELIVERY_RECEIPT_VERSION,message:'这条 GPT 回复已经成功回填过当前客户，本次没有重复写入。'};
      }
      checked=guard('reply-draft-before-customer-composer');
      if(!checked.ok)return checked;
      const result=await stageChatgptReplyToCustomerDraft(target,text,guard);
      if(result?.ok){
        const receipt=rememberChatgptReplyDelivery(target,binding,replyDelivery,{method:result.method,alreadyExact:!!result.alreadyExact});
        pushChatgptStabilityEvent('gpt-reply-customer-draft-ready-v125',{targetKey:chatgptWorkflowTargetKey(target),textLength:text.length,method:String(result.method||''),replyFingerprint:String(receipt?.replyFingerprint||'').slice(0,16)});
        return {...result,receiptVersion:CHATGPT_REPLY_DELIVERY_RECEIPT_VERSION,replyFingerprint:String(receipt?.replyFingerprint||'')};
      }
      return result;
    }finally{
      finishChatgptMutationLease(mutationLease,'reply-to-customer-draft-finished-v125');
    }
  });


  async function waitForFreshChatgptJapaneseSendState(target,binding,{timeoutMs=9000}={}){
    const started=Date.now();
    let lastState=null,lastFreshness=null;
    while(Date.now()-started<Math.max(1200,Number(timeoutMs||9000))){
      lastState=await chatgptLatestJapaneseReplyState(target);
      if(chatgptManualCustomerDraftRecord(target))await finalizeChatgptManualCustomerDraftIfSent(target,binding,chatgptWorkbenchWindow).catch(()=>null);
      lastFreshness=lastState?.ready?chatgptReplyFreshnessStatus(target,binding,lastState):null;
      if(lastState?.ready&&!lastFreshness?.pending)return {ok:true,state:lastState,freshness:lastFreshness,waitedMs:Date.now()-started};
      const reason=String(lastState?.reason||'');
      const transient=lastFreshness?.pending||['generating','loading','empty','waiting','no-japanese-direct-reply'].includes(reason);
      if(!transient)return {ok:false,state:lastState,freshness:lastFreshness,waitedMs:Date.now()-started,error:lastState?.error||'GPT 回复尚未就绪。'};
      await waitMs(240);
    }
    return {ok:false,pending:true,state:lastState,freshness:lastFreshness,waitedMs:Date.now()-started,error:lastFreshness?.pending?'本轮 GPT 新回复还在生成，请稍等后再点发送。':'GPT 正在生成回复，请稍等后再点发送。'};
  }

  function chatgptQueuedJapaneseSendKey(target = {}, binding = null){
    const targetKey=chatgptWorkflowTargetKey(target),conversationRef=chatgptBoundConversationRef(binding);
    return targetKey&&conversationRef?`${targetKey}::${conversationRef}`:'';
  }

  function chatgptQueuedJapaneseSendIntent(target = {}, binding = null){
    const key=chatgptQueuedJapaneseSendKey(target,binding);
    const token=key?chatgptQueuedJapaneseSendIntents.get(key):null;
    if(!token||token.cancelled)return null;
    return token;
  }

  function finishChatgptQueuedJapaneseSend(token,resultType='completed',extra={}){
    if(!token)return;
    const current=chatgptQueuedJapaneseSendIntents.get(token.key);
    if(current===token)chatgptQueuedJapaneseSendIntents.delete(token.key);
    token.cancelled=true;
    token.finishedAt=Date.now();
    const targetKey=String(token.targetKey||'');
    if(resultType==='completed')chatgptQueuedJapaneseSendState.completedCount+=1;
    else if(resultType==='cancelled')chatgptQueuedJapaneseSendState.cancelledCount+=1;
    else if(resultType==='expired')chatgptQueuedJapaneseSendState.expiredCount+=1;
    else if(resultType==='deduped')chatgptQueuedJapaneseSendState.dedupedCount+=1;
    else if(resultType==='failed')chatgptQueuedJapaneseSendState.failedCount+=1;
    chatgptQueuedJapaneseSendState.last={at:Date.now(),type:resultType,targetKey,waitedMs:Date.now()-Number(token.queuedAt||Date.now()),...extra};
    pushChatgptStabilityEvent(`gpt-one-click-send-${resultType}-v166`,{version:CHATGPT_ONE_CLICK_SEND_VERSION,targetKey,conversationRef:String(token.conversationRef||''),waitedMs:Date.now()-Number(token.queuedAt||Date.now()),...extra});
    try{sendChatgptWorkbenchUpdated(token.target)}catch{}
  }

  async function _deliverReadyChatgptJapaneseReplyCore(target,binding,state,{queued=false}={}){
    const candidate=chatgptReplyDirectSendCandidate(target,binding,state);
    if(candidate.alreadySent){
      pushChatgptStabilityEvent('gpt-japanese-direct-send-deduped-v146',{targetKey:chatgptWorkflowTargetKey(target),conversationRef:candidate.conversationRef,replyIdentity:candidate.replyIdentity,queued:!!queued});
      return {ok:true,deduped:true,alreadySent:true,sent:false,sendVersion:CHATGPT_REPLY_DIRECT_SEND_VERSION,message:'这条日语回复已经发送给当前客户，本次没有重复发送。'};
    }
    const japaneseText=String(state.text||'').replace(/\r\n/g,'\n').trim().slice(0,12000);
    if(!japaneseText)return {ok:false,emptyDraft:true,error:'没有识别到可安全发送的日语正文。'};
    try { workflowStability.setState(chatgptWorkflowTargetKey(target),WORKFLOW_STATES.CUSTOMER_SENDING,{reason:'chatgpt-japanese-direct-send'}); } catch {}
    const sent=await sendSpeechLibraryMessage({text:japaneseText,targetKey:chatgptWorkflowTargetKey(target),expectedTarget:{...target},source:'chatgpt-japanese-only-direct-send',salutationEnabled:false});
    if(!sent?.ok){try { workflowStability.setState(chatgptWorkflowTargetKey(target),WORKFLOW_STATES.ERROR,{reason:'customer-send-failed'}); } catch {} return {...sent,ok:false,error:String(sent?.error||'日语回复发送失败。')};}
    const receipt=rememberChatgptReplyDirectSend(target,binding,candidate,{method:String(sent?.method||sent?.verified||'platform-send')});
    chatgptWorkbenchStableTarget={...target};chatgptWorkbenchStableTargetAt=Date.now();chatgptWorkbenchNoTargetSince=0;sendChatgptWorkbenchUpdated(target);
    chatgptInteractionTransactionState.last={at:Date.now(),type:'send-success',targetKey:chatgptWorkflowTargetKey(target),method:String(sent?.method||''),queued:!!queued};
    try { workflowStability.setState(chatgptWorkflowTargetKey(target),WORKFLOW_STATES.COMPLETED,{reason:'customer-send-complete'}); } catch {}
    pushChatgptStabilityEvent('gpt-japanese-direct-send-success-v146',{targetKey:chatgptWorkflowTargetKey(target),conversationRef:candidate.conversationRef,textLength:japaneseText.length,sendFingerprint:String(receipt?.sendFingerprint||'').slice(0,16),queued:!!queued});
    return {...sent,ok:true,sent:true,japaneseOnly:true,sentTextLength:japaneseText.length,sendVersion:CHATGPT_REPLY_DIRECT_SEND_VERSION,message:'已只发送日语正文给当前客户。'};
  }


  async function deliverReadyChatgptJapaneseReply(target,binding,state,{queued=false}={}){
    const targetKey=chatgptWorkflowTargetKey(target);
    if(!targetKey)return _deliverReadyChatgptJapaneseReplyCore(target,binding,state,{queued});
    const candidate=chatgptReplyDirectSendCandidate(target,binding,state);
    const idempotencyKey=candidate?.sendFingerprint
      ? automationFingerprint({kind:'customer-send',targetKey,conversationRef:String(candidate.conversationRef||''),sendFingerprint:String(candidate.sendFingerprint||'')})
      : '';
    return workflowStability.enqueue({
      targetKey,
      kind:'customer-send',
      idempotencyKey,
      startState:WORKFLOW_STATES.CUSTOMER_SENDING,
      successState:WORKFLOW_STATES.COMPLETED,
      recentSuccessMs:5000,
      task:()=>_deliverReadyChatgptJapaneseReplyCore(target,binding,state,{queued})
    });
  }

  function queueChatgptJapaneseSendIntent(target,binding,{reason='gpt-generating'}={}){
    const key=chatgptQueuedJapaneseSendKey(target,binding);
    if(!key)return {ok:false,error:'当前客户 GPT 绑定不完整，无法排队发送。'};
    const existing=chatgptQueuedJapaneseSendIntents.get(key);
    if(existing&&!existing.cancelled){
      return {ok:true,queued:true,pending:true,generationBusy:true,queueVersion:CHATGPT_ONE_CLICK_SEND_VERSION,message:'已在等待 GPT 本轮回复，完成后会自动发送给当前客户。'};
    }
    const token={key,target:{...target},targetKey:chatgptWorkflowTargetKey(target),conversationRef:chatgptBoundConversationRef(binding),bindingUrl:String(binding?.url||''),queuedAt:Date.now(),reason:String(reason||'gpt-generating'),cancelled:false};
    chatgptQueuedJapaneseSendIntents.set(key,token);
    chatgptQueuedJapaneseSendState.queuedCount+=1;
    chatgptQueuedJapaneseSendState.last={at:Date.now(),type:'queued',targetKey:token.targetKey,conversationRef:token.conversationRef,reason:token.reason};
    pushChatgptStabilityEvent('gpt-one-click-send-queued-v166',{version:CHATGPT_ONE_CLICK_SEND_VERSION,targetKey:token.targetKey,conversationRef:token.conversationRef,reason:token.reason});
    try{sendChatgptWorkbenchUpdated(target)}catch{}
    setTimeout(()=>{
      (async()=>{
        const deadline=token.queuedAt+CHATGPT_ONE_CLICK_SEND_MAX_MS;
        while(!token.cancelled&&Date.now()<deadline){
          const live=await currentSpeechLibraryTarget().catch(()=>null);
          if(!live?.ok||!chatgptTargetsRepresentSameCustomer(token.target,live)){
            finishChatgptQueuedJapaneseSend(token,'cancelled',{reason:'customer-changed'});
            return;
          }
          const liveBinding=chatgptBindingForTarget(live);
          if(!liveBinding?.url||chatgptBoundConversationRef(liveBinding)!==token.conversationRef){
            finishChatgptQueuedJapaneseSend(token,'cancelled',{reason:'binding-changed'});
            return;
          }
          let currentUrl='';try{currentUrl=String(chatgptWorkbenchWindow?.webContents?.getURL?.()||'')}catch{}
          if(!chatgptWorkbenchDestinationMatches(currentUrl,liveBinding.url,liveBinding)){
            const repair=await ensureChatgptStageDestinationFast(ensureChatgptWorkbenchWindow(),live,liveBinding,3200).catch(()=>null);
            if(!repair?.ok){await waitMs(CHATGPT_ONE_CLICK_SEND_POLL_MS);continue;}
            chatgptInteractionTransactionState.sendRouteRepairCount+=1;
          }
          const state=await chatgptLatestJapaneseReplyState(live).catch(()=>({ready:false,reason:'error',text:''}));
          if(chatgptManualCustomerDraftRecord(live))await finalizeChatgptManualCustomerDraftIfSent(live,liveBinding,chatgptWorkbenchWindow).catch(()=>null);
          const freshness=state?.ready?chatgptReplyFreshnessStatus(live,liveBinding,state):null;
          if(state?.ready&&!freshness?.pending){
            const lease=await acquireChatgptMutationLease(live,'japanese-direct-send-queued-v166');
            if(!lease){await waitMs(CHATGPT_ONE_CLICK_SEND_POLL_MS);continue;}
            try{
              const checked=assertChatgptMutationLease(lease,live,'queued-japanese-direct-send');
              if(!checked?.ok){finishChatgptQueuedJapaneseSend(token,'cancelled',{reason:'target-changed-before-send'});return;}
              const recheck=await currentSpeechLibraryTarget().catch(()=>null);
              if(!recheck?.ok||!chatgptTargetsRepresentSameCustomer(live,recheck)){finishChatgptQueuedJapaneseSend(token,'cancelled',{reason:'customer-changed-before-send'});return;}
              const finalBinding=chatgptBindingForTarget(recheck);
              if(!finalBinding?.url||chatgptBoundConversationRef(finalBinding)!==token.conversationRef){finishChatgptQueuedJapaneseSend(token,'cancelled',{reason:'binding-changed-before-send'});return;}
              const finalState=await chatgptLatestJapaneseReplyState(recheck).catch(()=>({ready:false,reason:'error',text:''}));
              const finalFreshness=finalState?.ready?chatgptReplyFreshnessStatus(recheck,finalBinding,finalState):null;
              if(!finalState?.ready||finalFreshness?.pending){await waitMs(CHATGPT_ONE_CLICK_SEND_POLL_MS);continue;}
              const delivered=await deliverReadyChatgptJapaneseReply(recheck,finalBinding,finalState,{queued:true});
              if(delivered?.alreadySent){finishChatgptQueuedJapaneseSend(token,'deduped',{reason:'already-sent'});return;}
              if(delivered?.ok){finishChatgptQueuedJapaneseSend(token,'completed',{textLength:Number(delivered?.sentTextLength||0),method:String(delivered?.method||'')});return;}
              finishChatgptQueuedJapaneseSend(token,'failed',{reason:'platform-send-failed',error:String(delivered?.error||'').slice(0,220)});return;
            }finally{finishChatgptMutationLease(lease,'japanese-direct-send-queued-finished-v166');}
          }
          await waitMs(CHATGPT_ONE_CLICK_SEND_POLL_MS);
        }
        if(!token.cancelled)finishChatgptQueuedJapaneseSend(token,'expired',{reason:'reply-timeout'});
      })().catch(error=>{if(!token.cancelled)finishChatgptQueuedJapaneseSend(token,'failed',{reason:'worker-error',error:String(error?.message||error).slice(0,220)});});
    },0);
    return {ok:true,queued:true,pending:true,generationBusy:true,queueVersion:CHATGPT_ONE_CLICK_SEND_VERSION,message:'GPT 正在生成。本次发送已排队，回复完成后会自动发送给当前客户。'};
  }

  ipcMain.handle('chatgpt-send-latest-reply', async () => {
    const target = await resolveLiveChatgptExplicitTarget({
      expectedTarget:chatgptWorkbenchPendingExplicitSelectionTarget,
      attempts:7,
      requireConsecutive:2
    });
    if (!target?.ok) return target;
    noteChatgptWorkflowSelection(target,'japanese-direct-send-selection-v146');
    const mutationLease=await acquireChatgptMutationLease(target,'japanese-direct-send-v146');
    if (!mutationLease) return {ok:false,targetChanged:true,error:'客户已经切换，GPT 日语发送已取消。'};
    const guard=(phase)=>assertChatgptMutationLease(mutationLease,target,phase);
    const fail=(result={})=>{
      chatgptInteractionTransactionState.sendFailureCount+=1;
      chatgptInteractionTransactionState.last={at:Date.now(),type:'send-failure',targetKey:chatgptWorkflowTargetKey(target),phase:String(result?.phase||''),error:String(result?.error||'').slice(0,220)};
      pushChatgptStabilityEvent('gpt-interaction-send-failed-v163',{targetKey:chatgptWorkflowTargetKey(target),phase:String(result?.phase||''),error:String(result?.error||'').slice(0,220),pending:!!result?.pending});
      return result;
    };
    try {
      let checked=guard('japanese-direct-binding');
      if (!checked.ok) return checked;
      const binding = chatgptBindingForTarget(target);
      if (!binding?.url) return fail({ok:false,unbound:true,phase:'binding',error:'当前客户还没有绑定 GPT。为避免发错客户，已停止发送。'});

      let currentUrl = await currentChatgptConversationUrl(chatgptWorkbenchWindow).catch(() => '');
      if (!chatgptWorkbenchDestinationMatches(currentUrl,binding.url,binding)) {
        const view=ensureChatgptWorkbenchWindow();
        const repair=await ensureChatgptStageDestinationFast(view,target,binding,4600).catch(error=>({ok:false,error:String(error?.message||error)}));
        if(!repair?.ok)return fail({ok:false,targetChanged:true,phase:'route-repair',error:'当前 GPT 页面和客户绑定不一致，自动恢复没有成功。为避免发错客户，本次没有发送。'});
        chatgptInteractionTransactionState.sendRouteRepairCount+=1;
        chatgptInteractionTransactionState.last={at:Date.now(),type:'send-route-repaired',targetKey:chatgptWorkflowTargetKey(target),elapsedMs:Number(repair?.elapsedMs||0)};
        pushChatgptStabilityEvent('gpt-interaction-send-route-repaired-v163',{targetKey:chatgptWorkflowTargetKey(target),elapsedMs:Number(repair?.elapsedMs||0),conversationRef:chatgptBoundConversationRef(binding)});
      }

      const existingQueued=chatgptQueuedJapaneseSendIntent(target,binding);
      if(existingQueued)return {ok:true,queued:true,pending:true,generationBusy:true,queueVersion:CHATGPT_ONE_CLICK_SEND_VERSION,message:'已经排队等待 GPT 本轮回复，完成后会自动发送给当前客户。'};

      checked=guard('japanese-direct-wait-reply');
      if(!checked.ok)return checked;
      // V1.27.166: one click must never turn into "wait 9 seconds and do nothing".
      // Give an already-finished response a very short fast path; otherwise
      // persist the send intent and let the background worker finish it once.
      const ready=await waitForFreshChatgptJapaneseSendState(target,binding,{timeoutMs:1300});
      if(Number(ready?.waitedMs||0)>350){
        chatgptInteractionTransactionState.sendWaitCount+=1;
        chatgptInteractionTransactionState.last={at:Date.now(),type:'send-waited-reply',targetKey:chatgptWorkflowTargetKey(target),waitedMs:Number(ready.waitedMs||0)};
      }
      if(!ready?.ok){
        const reason=String(ready?.state?.reason||'');
        const transient=!!ready?.pending||!!ready?.freshness?.pending||['generating','loading','empty','waiting','no-japanese-direct-reply'].includes(reason);
        if(transient)return queueChatgptJapaneseSendIntent(target,binding,{reason:ready?.freshness?.pending?'fresh-reply-pending':(reason||'gpt-generating')});
        return fail({ok:false,emptyDraft:true,phase:'reply-read',error:ready?.error||ready?.state?.error||'没有识别到可安全发送的日语正文。'});
      }
      checked=guard('japanese-direct-before-customer-send');
      if(!checked.ok)return checked;
      const delivered=await deliverReadyChatgptJapaneseReply(target,binding,ready.state,{queued:false});
      if(!delivered?.ok)return fail({...delivered,phase:'customer-send',error:String(delivered?.error||'日语回复发送失败。')});
      return delivered;
    } finally {
      finishChatgptMutationLease(mutationLease,'japanese-direct-send-finished-v146');
    }
  });
