        pushChatgptStabilityEvent(initResult?.ok?'gpt-auto-bootstrap-rules-ok-v127256':'gpt-auto-bootstrap-rules-failed-v127256',{version:CHATGPT_REPLY_RULES_VERSION,targetKey:chatgptWorkflowTargetKey(pinnedSelection),bound:!!initResult?.bound,pending:!!initResult?.pending,error:String(initResult?.error||'').slice(0,220)});
