  ipcMain.handle('aggregate-send-message', async (_event, payload = {}) => {
    const accountId = String(payload?.accountId || '').trim();
    const chatId = String(payload?.chatId || '').trim();
    const text = String(payload?.text || '').trim();
    const originalText = String(payload?.originalText || '').trim();
    if (!text) return { ok: false, error: '发送内容为空。' };
    try {
      await prepareAggregateConversation(accountId, chatId);
      const setResult = await callLineBridgeForAccount(accountId, 'setInputText', text);
      if (setResult?.ok === false) throw new Error(setResult?.error || '无法写入 LINE 输入框。');
      if (originalText && originalText !== text) {
        await callLineBridgeForAccount(accountId, 'queueOutgoingOriginal', originalText, text).catch(() => null);
      }
      const expected = text.replace(/\s+/g, ' ').trim();
      let matchingBefore = 0;
      try {
        const beforeRows = await callLineBridgeForAccount(accountId, 'getRecentMessagesDetailed', 12);
        matchingBefore = Array.isArray(beforeRows) ? beforeRows.filter(row =>
          String(row?.role || '') === 'me' &&
          String(row?.text || '').replace(/\s+/g, ' ').trim() === expected
        ).length : 0;
      } catch {}

      const sendResult = await callLineBridgeForAccount(accountId, 'sendCurrent');
      if (sendResult?.ok === false) throw new Error(sendResult?.error || 'LINE 未确认发送。');

      let verified = false;
      for (const delay of [120, 260]) {
        await waitMs(delay);
        try {
          const recent = await callLineBridgeForAccount(accountId, 'getRecentMessagesDetailed', 12);
          const matchingAfter = Array.isArray(recent) ? recent.filter(row =>
            String(row?.role || '') === 'me' &&
            String(row?.text || '').replace(/\s+/g, ' ').trim() === expected
          ).length : 0;
          verified = matchingAfter > matchingBefore;
        } catch {}
        if (verified) break;
      }
      return {
        ok: true,
        verified,
        status: verified ? 'confirmed' : 'pending',
        accountId,
        chatId,
        method: sendResult?.method || 'enter'
      };
    } catch (error) {
      return { ok: false, accountId, chatId, error: String(error?.message || error) };
    }
  });

  function lineCustomerDayStateForSelection(accountId = '', chatId = '', displayName = '', now = Date.now()) {
    const account = String(accountId || '').trim();
    const chat = String(chatId || '').trim();
    const name = String(displayName || '').trim();
    const cached = (aggregateConversationCache.get(account)?.conversations || []).find(row => String(row?.chatId || '') === chat) || {};
    return customerDayPublicState('line', account, { ...cached, chatId:chat, displayName:name || cached?.displayName || '' }, now);
  }
  function sendLineCustomerDayState(webContents, accountId = '', chatId = '', displayName = '') {
    if (!webContents || webContents.isDestroyed?.()) return null;
    const state = lineCustomerDayStateForSelection(accountId, chatId, displayName, Date.now());
    try { webContents.send('line-customer-day-state', state); } catch {}
    return state;
  }

  // V1.27.276: manual day calibration in the native LINE header.  This is
  // deliberately independent from GPT bindings and the retired GPT Day flow.
  ipcMain.on('line-customer-day-calibrate', (event, payload = {}) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    if (!accountId) return;
    const selectedHint = lineSelectedChatHints.get(accountId) || {};
    const chatId = String(payload?.chatId || selectedHint?.chatId || '').trim();
    const displayName = String(payload?.displayName || selectedHint?.displayName || '').trim();
    if (!chatId && !displayName) return;
    // A stale popup from a previously selected customer may never rewrite the
    // current customer's day anchor.
    if (selectedHint?.chatId && chatId && String(selectedHint.chatId) !== chatId) {
      sendLineCustomerDayState(event.sender, accountId, selectedHint.chatId, selectedHint.displayName || '');
      return;
    }
    const result = setCustomerDayCalibration({ platform:'line', accountId, chatId, displayName, day:Number(payload?.day||0)||0 }, Date.now());
    const state = lineCustomerDayStateForSelection(accountId, chatId, displayName, Date.now());
    try { event.sender.send('line-customer-day-state', { ...state, saveOk:result?.ok!==false, saveError:String(result?.error||'') }); } catch {}
    try { sendUI('aggregate-updated', publicAggregateInbox()); } catch {}
  });

  ipcMain.on('line-customer-day-refresh', (event, payload = {}) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    if (!accountId) return;
    const selectedHint = lineSelectedChatHints.get(accountId) || {};
    const chatId = String(payload?.chatId || selectedHint?.chatId || '').trim();
    const displayName = String(payload?.displayName || selectedHint?.displayName || '').trim();
    if (!chatId && !displayName) return;
    if (selectedHint?.chatId && chatId && String(selectedHint.chatId) !== chatId) return;
    sendLineCustomerDayState(event.sender, accountId, chatId, displayName);
  });

  // V1.23.15: native LINE customer switches must immediately refresh an
  // already-open speech library window. The sender webContents identifies the
  // owning account, so background LINE accounts cannot steal the target.
  ipcMain.on('line-current-chat-changed', (event, payload) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    if (!accountId || accountId !== String(config.activeAccountId || '').trim() || shellSurfaceMode !== 'line') return;
    const selectedChatId = String(payload?.chatId || '').trim();
    const selectedDisplayName = String(payload?.displayName || payload?.routeDisplayName || payload?.visibleDisplayName || '').trim();
    if (selectedChatId) {
      lineNoChatSelectedHints.delete(accountId);
      const cachedConversation = (aggregateConversationCache.get(accountId)?.conversations || []).find(row => String(row?.chatId || '') === selectedChatId) || {};
      const unreadCount = Math.max(0, Number(payload?.unreadCount ?? cachedConversation?.unreadCount ?? 0) || 0);
      lineSelectedChatHints.set(accountId, { chatId:selectedChatId, displayName:selectedDisplayName, unreadCount, at:Date.now() });
      automationLineSelectionHints.set(`${accountId}:${selectedChatId}`, { unreadCount, at:Date.now() });
      // Force the next sync to compare against the exact newly selected target,
      // not a bridge result that may still be one React tick behind.
      if (chatgptWorkbenchVisible) chatgptWorkbenchTargetKey = '';
      sendLineCustomerDayState(event.sender, accountId, selectedChatId, selectedDisplayName);
    } else {
      // V1.23.47: leaving the conversation must invalidate the previous customer
      // immediately. LINE's bridge may keep the old route for a few React ticks.
      lineSelectedChatHints.delete(accountId);
      lineNoChatSelectedHints.set(accountId, { at:Date.now() });
      for (const key of [...automationLineSelectionHints.keys()]) {
        if (key.startsWith(`${accountId}:`)) automationLineSelectionHints.delete(key);
      }
      automationGptMonitorState.currentTargetKey = '';
      automationGptMonitorState.pending = null;
      if (chatgptWorkbenchVisible) resetChatgptWorkbenchForNoCustomer({ focus:false }).catch(() => {});
      try { event.sender.send('line-customer-day-state', { ok:true, accountId, chatId:'', displayName:'', day:0, rawDay:0, group:'', label:'未选择', calibrated:false, calibration:null, boundaryHourJst:5 }); } catch {}
    }
    if (speechLibraryWindow && !speechLibraryWindow.isDestroyed()) {
      try { speechLibraryWindow.webContents.send('speech-library-refresh-target', { accountId, chatId:String(payload?.chatId || '') }); } catch {}
    }
    // V1.27.250: LINE customer clicks only update GPT target identity. They no
    // longer reveal/create ChatGPT. If GPT is already open manually, keep it
    // synchronized to the selected customer.
    if (selectedChatId || selectedDisplayName) {
      const expectedGptTarget = rememberChatgptExpectedSelectionTarget({ platform:'line', accountId, chatId:selectedChatId, displayName:selectedDisplayName });
      if (chatgptWorkbenchVisible) {
        setTimeout(() => {
          if (chatgptWorkbenchVisible) showChatgptWorkbenchForCustomerSelection({ attempts:7, expectedTarget:expectedGptTarget }).catch(() => {});
        }, 35);
      }
    }
  });

  ipcMain.on('yoko-gpt-recent-messages-response', (event, payload = {}) => {
    const requestId = String(payload?.requestId || '');
    const callback = chatgptRecentMessageRequests.get(requestId);
    if (!callback) return;
    const accountId = String(webContentsToAccount.get(event.sender.id) || '');
    const appEntry = [...appCenterRuntime.values()].find(entry => entry?.view?.webContents?.id === event.sender.id);
    callback({ ...payload, accountId:accountId || appEntry?.account?.id || '' });
  });

  ipcMain.on('yoko-history-snapshot-response', (event, payload = {}) => {
    const requestId = String(payload?.requestId || '');
    const callback = chatHistoryExternalRequests.get(requestId);
    if (!callback) return;
    const appEntry = [...appCenterRuntime.values()].find(entry => entry?.view?.webContents?.id === event.sender.id);
    callback({ ...payload, accountId:String(appEntry?.account?.id || '') });
  });

  // V1.23.45: LINE preload emits a privacy-safe activity hint whenever the
  // selected chat's message turn changes. Wake the GPT monitor immediately
  // instead of relying only on the 1.2s polling loop. The monitor re-reads and
  // re-locks the active account/customer before sending anything to ChatGPT.
  ipcMain.on('line-gpt-message-activity', (event, payload = {}) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    if (!accountId || accountId !== String(config.activeAccountId || '').trim()) return;
    if (shellSurfaceMode !== 'line') return;
    const chatId = String(payload?.chatId || '').trim();
    const latestRole = String(payload?.latestRole || '');
    const rows = (Array.isArray(payload?.messages) ? payload.messages : [])
      .map((row,index) => ({
        role:String(row?.role || ''), text:String(row?.text || '').replace(/\r\n/g,'\n').trim().slice(0,4000),
        delivered:Number(row?.delivered || row?.timestamp || 0) || 0, id:String(row?.id || ''), index
      }))
      .filter(row => row.text && (row.role === 'customer' || row.role === 'me'))
      .slice(-60);
    const unreadMessages = (Array.isArray(payload?.unreadMessages) ? payload.unreadMessages : [])
      .map(v => String(v || '').replace(/\r\n/g,'\n').trim().slice(0,4000)).filter(Boolean).slice(-40);
    if (chatId && rows.length) {
      automationLineMessageSnapshots.set(`${accountId}:${chatId}`, {
        rows,
        unreadMessages,
        at:Date.now(),
        signature:String(payload?.signature || '')
      });
      // Bound memory across many LINE accounts/chats.
      if (automationLineMessageSnapshots.size > 120) {
        const oldest = [...automationLineMessageSnapshots.entries()].sort((a,b) => Number(a[1]?.at||0)-Number(b[1]?.at||0)).slice(0,30);
        for (const [key] of oldest) automationLineMessageSnapshots.delete(key);
      }
    }
    automationLogger.write('auto-gpt-line-activity', {
      platform:'line',
      accountId,
      targetHash:automationFingerprint(`${accountId}:${chatId}`).slice(0,16),
      messageCount:Math.max(0, Number(payload?.messageCount || rows.length || 0) || 0),
      latestRole
    });
    wakeAutomationGptMonitor(latestRole === 'customer' ? 70 : 160);
  });

  ipcMain.on('line-aggregate-snapshot', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    try {
      setAggregateSnapshot(accountId, payload || {});
    } catch (error) {
      console.debug('[Yoko aggregate snapshot skipped]', error?.message || error);
    }
  });

  // V1.15.15: preload resolves pending customer switches asynchronously.
  // Forward only the owning account + exact MID to the UI so loading status can
  // finish without polling or guessing.
  ipcMain.on('line-aggregate-chat-ready', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    sendUI('aggregate-chat-switch', {
      status: 'ready',
      accountId,
      chatId: String(payload?.chatId || ''),
      displayName: String(payload?.displayName || ''),
      method: String(payload?.method || ''),
      latencyMs: Math.max(0, Number(payload?.latencyMs || 0) || 0),
      interactiveReady: payload?.interactiveReady === true
    });
  });

  ipcMain.on('line-aggregate-chat-failed', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    sendUI('aggregate-chat-switch', {
      status: 'failed',
      accountId,
      chatId: String(payload?.chatId || ''),
      displayName: String(payload?.displayName || ''),
      latencyMs: Math.max(0, Number(payload?.latencyMs || 0) || 0),
      error: String(payload?.error || 'LINE 聊天加载超时')
    });
  });

  // V1.15.19: Tab / Shift+Tab pressed inside the native LINE composer cannot
  // be observed by the shell renderer because LINE lives in a WebContentsView.
  // Forward only the direction while Aggregate Mode is active; the shell owns
  // list order/filtering and therefore remains the single source of truth for
  // which customer should be selected next.
  ipcMain.on('line-aggregate-keyboard-nav', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId) || workspaceLayoutMode !== 'aggregate') return;
    const direction = Number(payload?.direction || 0) < 0 ? -1 : 1;
    sendUI('aggregate-keyboard-nav', {
      direction,
      accountId,
      source: String(payload?.shortcut || '') === 'ctrl-tab' ? 'line-ctrl-tab' : 'line-tab',
      at: Date.now()
    });
  });

  // Exact total unread-message count comes from LINE's own React state. The
  // bundled LINE 3.7.2 resource already exposes the computed chat unread total
  // through window._onUnreadCount; line-preload forwards it here.
  ipcMain.on('line-account-unread', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    const unreadCount = Math.max(0, Math.min(99999, Number(payload?.count || 0) || 0));
    const live = accountLiveState.get(accountId) || {};
    if (Number(live.unreadCount || 0) === unreadCount) return;
    accountLiveState.set(accountId, { ...live, unreadCount });
    emitAccountOverview(accountId);
  });

  ipcMain.on('line-account-profile', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    updateLineAccountProfile(accountId, payload || {}).catch(error => {
      console.debug('[Yoko LINE profile sync skipped]', error?.message || error);
    });
  });

  ipcMain.on('line-account-presence', (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    const live = accountLiveState.get(accountId) || {};
    const online = payload?.online === true;
    const next = { ...live, online, loginRequired:online ? false : !!live.loginRequired, loginState:online ? 'authenticated' : String(live.loginState || 'unknown') };
    if (live.online === next.online && live.loginRequired === next.loginRequired && live.loginState === next.loginState) return;
    accountLiveState.set(accountId, next);
    emitAccountOverview(accountId);
    scheduleTeamNodeCapabilitySync(120);
    if (online) {
      updateLineOperationalState(accountId, { status:'online', lastError:'' });
      checkpointLineLoginState(accountId, { force:true });
      const entry = runtime.get(accountId);
      const startupMs = Math.max(0, Date.now() - Number(entry?.startupStartedAt || Date.now()));
      sendUI('account-status', {
        accountId,
        status: 'auth-ready',
        startupMs,
        message: `LINE 登录恢复完成 · ${(startupMs / 1000).toFixed(1)}s`
      });
    }
  });

  ipcMain.on('line-account-login-state', (event, payload = {}) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId || !getAccount(accountId)) return;
    const state = String(payload?.state || 'unknown');
    const live = accountLiveState.get(accountId) || {};
    if (state === 'login-required') {
      accountLiveState.set(accountId, { ...live, online:false, loginRequired:true, loginState:'login-required' });
      updateLineOperationalState(accountId, { status:'login-required', lastError:'' });
      emitAccountOverview(accountId);
      scheduleTeamNodeCapabilitySync(120);
      sendUI('account-status', { accountId, status:'login-required', message:'LINE 需要重新登录/扫码' });
    } else if (state === 'authenticated') {
      accountLiveState.set(accountId, { ...live, online:true, loginRequired:false, loginState:'authenticated' });
      updateLineOperationalState(accountId, { status:'online', lastError:'' });
      emitAccountOverview(accountId);
      scheduleTeamNodeCapabilitySync(120);
      checkpointLineLoginState(accountId, { force:true });
    }
  });

  ipcMain.handle('choose-line-extension', async () => {
    const result = await dialog.showOpenDialog(mainWindow, {
      title: '选择官方 LINE Chrome 扩展目录',
      properties: ['openDirectory']
    });
    if (result.canceled || !result.filePaths[0]) return '';

    const selected = result.filePaths[0];
    manifestInfo(selected);
    if (!isLineExtensionPathValid(selected)) {
      throw new Error('所选目录无法识别为 LINE 扩展。请选择直接包含 manifest.json 的 LINE 版本目录。');
    }
    config.lineExtensionPath = selected;
    saveConfig(config);
    return selected;
  });

