  ipcMain.handle('save-settings', async (_event, newSettings) => {
    if (Object.prototype.hasOwnProperty.call(newSettings || {}, 'lineExtensionPath')) {
      config.lineExtensionPath = String(newSettings?.lineExtensionPath || '');
    }
    if (newSettings?.translation && typeof newSettings.translation === 'object') {
      if (Object.prototype.hasOwnProperty.call(newSettings.translation, 'openaiTranslationApiKey')) updateOpenaiTranslationApiKey(newSettings.translation.openaiTranslationApiKey);
      const previousProvider = config.translation?.incomingTranslationProvider || 'deepl';
      const nextProvider = newSettings.translation.incomingTranslationProvider === 'openai' ? 'openai' : 'deepl';
      const nextModel = String(newSettings.translation.openaiTranslationModel || config.translation?.openaiTranslationModel || 'gpt-4o-mini').trim();
      if (!/^[-a-zA-Z0-9_.]{2,80}$/.test(nextModel)) throw new Error('GPT 模型名称不正确。');
      if (nextProvider === 'openai' && !openaiTranslationApiKey()) throw new Error('请先填写 OpenAI API Key。');
      // V1.27.280: preserve provider/model-separated results across setting changes.
      config.translation = {
        incomingTranslationProvider: nextProvider,
        openaiTranslationModel: nextModel,
        engine: 'ollama',
        ollamaUrl: String(newSettings?.translation?.ollamaUrl || OLLAMA_DEFAULT_URL),
        ollamaModel: String(newSettings?.translation?.ollamaModel ?? config.translation?.ollamaModel ?? ''),
        ollamaModelMode: normalizeOllamaModelMode(newSettings?.translation?.ollamaModelMode ?? config.translation?.ollamaModelMode),
        gatewayPrimaryV127130: true,
        translateIncomingOnlyV127130: true,
        ollamaTranslateOutgoing: newSettings?.translation?.ollamaTranslateOutgoing !== false,
        outgoingLocalOnlyV127170: true,
        localFallbackEnabledV127133: newSettings?.translation?.localFallbackEnabledV127133 !== false,
        serverPreTranslationV127133: true,
        aiContextMessages: Math.max(0, Math.min(12, Number(newSettings?.translation?.aiContextMessages ?? 4))),
        optimizedV193: true,
        cacheEnabled: newSettings?.translation?.cacheEnabled !== false,
        inlineEnabled: newSettings?.translation?.inlineEnabled !== false,
        inlineSource: String(newSettings?.translation?.inlineSource || 'auto'),
        inlineTarget: String(newSettings?.translation?.inlineTarget || 'zh'),
        inlineDisplayMode: String(newSettings?.translation?.inlineDisplayMode || 'bilingual'),
        vpsGatewayEnabled: true,
        migratedV141: true,
        localProviderOnlyV127112: true
      };
    }
    if (newSettings?.updates && typeof newSettings.updates === 'object') {
      config.updates = {
        autoCheck: newSettings.updates.autoCheck !== false,
        autoDownload: newSettings.updates.autoDownload === true,
        checkIntervalHours: Math.max(1, Math.min(48, Number(newSettings.updates.checkIntervalHours ?? 6)))
      };
    }
    config.updates = config.updates || { autoCheck:true, autoDownload:false, checkIntervalHours:6 };
    if (autoUpdater) autoUpdater.autoDownload = config.updates.autoDownload;
    saveConfig(config);

    // Only translation saves need to push new translation settings into every renderer.
    if (newSettings?.translation && typeof newSettings.translation === 'object') {
      broadcastGlobalTranslationSettings();
    }

    return config;
  });


  ipcMain.handle('add-account', async (_event, raw) => {
    // Resolve/import the LINE extension BEFORE persisting a new account. This
    // prevents a broken half-created account when loadExtension() fails.
    const extensionPath = resolveLineExtensionPath({ autoImportDetected: true });
    if (!extensionPath) {
      throw new Error(
        '当前安装中没有可用的 LINE 扩展。请重新安装完整版，或打开“设置”使用自动检测/手动导入作为备用。'
      );
    }

    const account = normalizeAccount(raw || {});
    const previousActiveAccountId = config.activeAccountId;
    config.accounts.push(account);
    config.activeAccountId = account.id;

    try {
      await selectAccount(account.id);
      saveConfig(config);
      return account;
    } catch (error) {
      await closeAccountRuntime(account.id, false).catch(() => {});
      try {
        const ses = sessionForAccount(account.id);
        await ses.clearStorageData();
        await ses.clearCache();
        ses.flushStorageData();
      } catch {}
      config.accounts = config.accounts.filter(a => a.id !== account.id);
      config.activeAccountId = previousActiveAccountId || config.accounts[0]?.id || '';
      saveConfig(config);
      throw new Error(friendlyExtensionLoadError(error, extensionPath));
    }
  });

  ipcMain.handle('update-account', async (_event, raw) => {
    const idx = config.accounts.findIndex(a => a.id === raw?.id);
    if (idx < 0) throw new Error('账号不存在。');

    const old = config.accounts[idx];
    config.accounts[idx] = normalizeAccount({
      ...old,
      ...raw,
      id: old.id,
      proxy: { ...old.proxy, ...(raw.proxy || {}) }
    });
    saveConfig(config);

    // Proxy changes should take effect immediately.
    const entry = runtime.get(old.id);
    if (entry) {
      await applyProxy(entry.ses, config.accounts[idx]);
      entry.account = config.accounts[idx];
      await entry.view.webContents.reload();
    }

    return config.accounts[idx];
  });

  ipcMain.handle('update-account-remark', async (_event, accountId, remark) => {
    accountId = String(accountId || '');
    const idx = config.accounts.findIndex(a => a.id === accountId);
    if (idx < 0) throw new Error('账号不存在。');

    config.accounts[idx].remark = String(remark || '').trim().slice(0, 80);
    saveConfig(config);
    return config.accounts[idx];
  });

  ipcMain.handle('update-account-display-name', async (_event, accountId, displayName) => {
    accountId = String(accountId || '');
    const idx = config.accounts.findIndex(a => a.id === accountId);
    if (idx < 0) throw new Error('账号不存在。');

    // This is a local display override only. It must not touch the LINE profile
    // or reload the LINE renderer, otherwise a simple rename could interrupt chat.
    config.accounts[idx].displayNameOverride = String(displayName || '').trim().slice(0, 80);
    saveConfig(config);
    return config.accounts[idx];
  });

  ipcMain.handle('reorder-accounts', async (_event, orderedIds) => {
    const ids = Array.isArray(orderedIds)
      ? orderedIds.map(id => String(id || '')).filter(Boolean)
      : [];
    const currentIds = config.accounts.map(account => account.id);

    if (
      ids.length !== currentIds.length ||
      new Set(ids).size !== ids.length ||
      currentIds.some(id => !ids.includes(id))
    ) {
      throw new Error('账号排序数据无效。');
    }

    const byId = new Map(config.accounts.map(account => [account.id, account]));
    config.accounts = ids.map(id => byId.get(id)).filter(Boolean);
    saveConfig(config);
    return config.accounts;
  });

