  ipcMain.handle('delete-account', async (_event, accountId) => {
    accountId = String(accountId || '');
    const account = getAccount(accountId);
    if (!account) throw new Error('账号不存在。');

    // Deleting is intentionally different from merely closing a LINE window:
    // clear the Chromium profile/session first so login data is not retained.
    const entry = runtime.get(accountId);
    if (entry) {
      try {
        await entry.ses.clearStorageData();
        await entry.ses.clearCache();
        entry.ses.flushStorageData();
      } catch {}
    } else {
      try {
        const ses = sessionForAccount(accountId);
        await ses.clearStorageData();
        await ses.clearCache();
        ses.flushStorageData();
      } catch {}
    }

    await closeAccountRuntime(accountId, false).catch(() => {});

    // Remove both the legacy V1.15.25 vault and V1.15.35's single-cookie
    // bootstrap vault when the user explicitly deletes the LINE account.
    for (const vault of [legacySessionVaultPath(accountId), lineBootstrapCookieVaultPath(accountId)]) {
      try { if (fs.existsSync(vault)) fs.unlinkSync(vault); } catch {}
    }

    // Remove CRM contacts bound to this LINE account; global quick replies remain.
    const crm = ensureCrmConfig();
    for (const [key, contact] of Object.entries(crm.contacts || {})) {
      if (String(contact?.accountId || '') === accountId) {
        delete crm.contacts[key];
      }
    }

    accountLiveState.delete(accountId);
    removeAvatarCacheRecord(accountId);
    avatarRefreshInFlight.delete(accountId);
    for (const key of [...profileFetchInFlight.keys()]) {
      if (key.startsWith(accountId + '|')) profileFetchInFlight.delete(key);
    }
    config.accounts = config.accounts.filter(a => a.id !== accountId);
    removeAggregateCacheRecord(accountId);
    if (config.activeAccountId === accountId) {
      config.activeAccountId = config.accounts.find(a => a.isOpen !== false)?.id || config.accounts[0]?.id || '';
    }
    saveConfig(config);

    if (config.activeAccountId) {
      const next = getAccount(config.activeAccountId);
      if (next?.isOpen === false) {
        layoutViews();
      } else {
        await selectAccount(config.activeAccountId);
      }
    } else {
      layoutViews();
    }

    return true;
  });

  registerLatencyGuardedIpcHandle('select-account', {category:'customer-switch',operation:'account-switch',detail:args=>({accountId:String(args?.[0]||'')})}, async (_event, accountId) => {
    await selectAccount(accountId);
    return true;
  });

