  ipcMain.handle('line-inline-translation-cache-batch', async (event, payload = {}) => {
    const accountId = String(webContentsToAccount.get(event.sender.id) || '').trim();
    const account = getAccount(accountId);
    const t = config.translation || {};
    if (!account || t.inlineEnabled === false) return { ok:false, disabled:true, items:[] };
    try { return await lookupInlineTranslationCacheBatch(payload?.items, accountId, { preferSpeed:payload?.preferSpeed === true }); }
    catch (error) { return { ok:false, error:String(error?.message || error), items:[] }; }
  });

  ipcMain.handle('line-inline-translate', async (event, payload) => {
    const accountId = webContentsToAccount.get(event.sender.id);
    if (!accountId) return { ok: false, disabled: true };

    const t = config.translation || {};
    const role = String(payload?.role || '');

    // V1.27.170: incoming/customer stays on the existing DeepL/VPS-first lane.
    // Outgoing/operator Japanese is allowed only through local Ollama.
    if (role !== 'incoming' && role !== 'outgoing') {
      return { ok:false, disabled:true, invalidRole:true };
    }
    if (role === 'outgoing' && t.ollamaTranslateOutgoing === false) {
      return { ok:false, disabled:true, outgoingSkipped:true };
    }
    const account = getAccount(accountId);
    const providerReady = translationProviderReady();

    // V1.27.190: a configured VPS/DeepL gateway is itself a valid incoming
    // translation provider. Do not reject the LINE renderer merely because the
    // local-engine selector is `none`; Official API already uses the same
    // gateway successfully in that state. providerReady is the single source
    // of truth for incoming/customer translation availability.
    if (
      !account ||
      t.inlineEnabled === false ||
      !providerReady
    ) {
      return {
        ok: false,
        disabled: true,
        providerReady
      };
    }

    const text = String(payload?.text || '').trim();
    if (!text) return { ok: false };

    try {
      const translated = role === 'outgoing'
        ? await translateOutgoingJapaneseLocalOnly({ text, context:Array.isArray(payload?.context)?payload.context:[], bypassCache:payload?.force===true })
        : await translateText({
        text,
        direction:'incoming',
        source: t.inlineSource || 'auto',
        target: t.inlineTarget || 'zh',
        accountId,
        context: Array.isArray(payload?.context) ? payload.context : [],
        bypassCache: payload?.force === true,
        skipSharedCache: String(t.engine || '').toLowerCase() !== 'ollama',
        inlineFast: true
      });

      return {
        ok: true,
        translated,
        target: t.inlineTarget || 'zh'
      };
    } catch (error) {
      const message = String(error?.message || error);
      try {
        mainWindow?.webContents?.send('translation-status', {
          ok: false,
          accountId,
          engine: t.engine || 'none',
          providerLabel: aiProviderLabel(t.engine),
          error: message,
          at: Date.now()
        });
      } catch {}
      return {
        ok: false,
        error: message
      };
    }
  });

  ipcMain.handle('translate', async (_event, payload) => {
    const request = { ...(payload || {}), accountId:payload?.accountId || config.activeAccountId || '' };
    if (String(request.direction || '').toLowerCase() === 'outgoing' && request.localOnly === true) {
      return translateOutgoingJapaneseLocalOnly(request);
    }
    return translateText(request);
  });

